-- BEGIN data/learning-owned/learning-content.json#sections.jlas_compiled_book_n5 SHA256 71129aa3a17c11dc3cb7e2219a0b9a6cca5ff33134c4ca615431d48306b5a423
-- [JLAS-W0108] D3-04 (owner 2026-10-24): J-LAS N5 compiled book — every book of the level merged per skill,
-- deduplicated, easy → hard. Learning-owned rows only; source books, dictionary entries and Kanji are read, never changed
-- (a word missing from the dictionary is added as a DRAFT textbook entry). Generated: do not hand-edit.
DELIMITER $$
DROP PROCEDURE IF EXISTS jlas_assert_compiled_n5$$
CREATE PROCEDURE jlas_assert_compiled_n5()
BEGIN
  IF EXISTS (SELECT 1 FROM textbook WHERE id=5000000000 AND source_code<>'LP-OWNED-JLAS-N5-COMPILED') THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Compiled N5 textbook id collision';
  END IF;
  IF (SELECT COUNT(*) FROM lesson l JOIN unit u ON u.id=l.unit_id WHERE u.textbook_id=1
      AND l.lesson_type='CURRICULUM') <> 25 THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Dialogue source book of N5 changed its chapter count';
  END IF;
END$$
DELIMITER ;
CALL jlas_assert_compiled_n5();
DROP PROCEDURE jlas_assert_compiled_n5;
DROP TEMPORARY TABLE IF EXISTS jlas_compiled_word_n5;
DROP TEMPORARY TABLE IF EXISTS jlas_compiled_variant_n5;
CREATE TEMPORARY TABLE jlas_compiled_word_n5 (item_id BIGINT NOT NULL PRIMARY KEY, section_id BIGINT NOT NULL, order_index INT NOT NULL, expression VARCHAR(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL, reading VARCHAR(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL, normalized_expression VARCHAR(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_as_cs NOT NULL, normalized_reading VARCHAR(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_as_cs NOT NULL, meaning TEXT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL, example_ja TEXT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci, example_vi TEXT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci, vocab_id BIGINT UNSIGNED);
CREATE TEMPORARY TABLE jlas_compiled_variant_n5 (item_id BIGINT NOT NULL, rank_no INT NOT NULL, normalized_expression VARCHAR(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_as_cs NOT NULL, normalized_reading VARCHAR(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_as_cs NOT NULL, PRIMARY KEY (item_id, rank_no));
START TRANSACTION;
SET @compiled_n5_tag=(SELECT id FROM tag WHERE code='LP-OWNED-JLAS-N5-COMPILED' LIMIT 1);
UPDATE content_item SET section_id=5000029999,order_index=1000000+(id-5100000000) WHERE id BETWEEN 5100000000 AND 5199999999 AND section_id IN (SELECT s.id FROM lesson_section s JOIN lesson l ON l.id=s.lesson_id JOIN unit u ON u.id=l.unit_id WHERE u.textbook_id=5000000000);
UPDATE grammar_point SET lesson_id=5000002999,order_index=1000000+(id-5200000000) WHERE id BETWEEN 5200000000 AND 5299999999 AND lesson_id IN (SELECT l.id FROM lesson l JOIN unit u ON u.id=l.unit_id WHERE u.textbook_id=5000000000);
UPDATE lesson_kanji SET lesson_id=5000002999 WHERE id BETWEEN 5300000000 AND 5399999999 AND lesson_id IN (SELECT l.id FROM lesson l JOIN unit u ON u.id=l.unit_id WHERE u.textbook_id=5000000000);
UPDATE jlas_compiled_word_n5 w SET w.vocab_id=(SELECT e.id FROM jlas_compiled_variant_n5 v JOIN vocabulary_entry e ON e.normalized_expression=v.normalized_expression AND e.normalized_reading=v.normalized_reading WHERE v.item_id=w.item_id ORDER BY v.rank_no LIMIT 1) WHERE w.item_id>0;
DELETE cv FROM content_vocabulary cv JOIN jlas_compiled_word_n5 w ON w.item_id=cv.content_item_id WHERE cv.vocabulary_id<>w.vocab_id;
SET @dialogue_src_n5=(SELECT l.id FROM lesson l JOIN unit u ON u.id=l.unit_id WHERE u.textbook_id=1 AND l.lesson_type='CURRICULUM' AND (u.order_index-1)*5+l.order_index=1 LIMIT 1);
-- COMPREHENSION LP-OWNED-JLAS-N5-C01-READ-P1 <- LP-OWNED-MINNA-N5-L01-READ-P001
-- COMPREHENSION LP-OWNED-JLAS-N5-C01-READ-P2 <- LP-OWNED-SPEED-N5-L13-READ-P1
-- COMPREHENSION LP-OWNED-JLAS-N5-C01-LISTEN-P1 <- LP-OWNED-MINNA-N5-L01-LISTEN-c4
