-- COMPREHENSION LP-OWNED-JLAS-N5-C01-LISTEN-P4 <- LP-OWNED-MINNA-N5-L01-LISTEN-c3
SET @dialogue_src_n5=(SELECT l.id FROM lesson l JOIN unit u ON u.id=l.unit_id WHERE u.textbook_id=1 AND l.lesson_type='CURRICULUM' AND (u.order_index-1)*5+l.order_index=2 LIMIT 1);
-- COMPREHENSION LP-OWNED-JLAS-N5-C02-READ-P1 <- LP-OWNED-SPEED-N5-L13-READ-P2
-- COMPREHENSION LP-OWNED-JLAS-N5-C02-READ-P2 <- LP-OWNED-MINNA-N5-L02-READ-P002
-- COMPREHENSION LP-OWNED-JLAS-N5-C02-LISTEN-P1 <- LP-OWNED-MINNA-N5-L02-LISTEN-c3
