-- COMPREHENSION LP-OWNED-JLAS-N5-C03-LISTEN-P3 <- LP-OWNED-MINNA-N5-L03-LISTEN-c3
-- COMPREHENSION LP-OWNED-JLAS-N5-C03-LISTEN-P4 <- LP-OWNED-MINNA-N5-L03-LISTEN-c4
SET @dialogue_src_n5=(SELECT l.id FROM lesson l JOIN unit u ON u.id=l.unit_id WHERE u.textbook_id=1 AND l.lesson_type='CURRICULUM' AND (u.order_index-1)*5+l.order_index=4 LIMIT 1);
-- COMPREHENSION LP-OWNED-JLAS-N5-C04-READ-P1 <- LP-OWNED-MINNA-N5-L04-READ-P005
-- COMPREHENSION LP-OWNED-JLAS-N5-C04-READ-P2 <- LP-OWNED-MINNA-N5-L04-READ-P004
