INSERT INTO `jpath_grammar` (`code`, `level`, `unit_no`, `sort_order`, `priority`, `pattern`, `pattern_variants_json`, `family_key`, `meaning_vi`, `formation`, `usage_vi`, `nuance_vi`, `common_mistakes_vi`, `related_codes_json`, `parent_code`, `status`, `authored`, `seed_version`) VALUES
('JG-0007a9b1b6', 'N5', 13, 317, 317, 'Ở đâu cũng', '[]', 'Ở đâu cũng', 'ở đâu cũng; bất cứ đâu', 'どこでも + V / どこでも + いい', 'どこでも + câu khẳng định: ở đâu cũng … (どこでも買うことができます), hay gặp trong どこでもいいです (đâu cũng được). Với động từ di chuyển nói どこへでも行きます. Muốn nói "không ở đâu cả" thì dùng どこにも + phủ định.', 'Không giới hạn nơi chốn; thường đi với khẳng định.', 'Hay nhầm với どこも + phủ định (không nơi nào).', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-011e7d2936', 'N5', 6, 224, 224, 'Sau đó...', '[]', 'Sau đó...', 'sau đó; rồi thì; à còn nữa', 'Câu 1。それから、Câu 2', 'Đặt đầu câu sau (hoặc sau thể て) để kể việc làm tiếp theo theo thứ tự: 朝ごはんを食べました。それから、学校へ行きました. Cũng dùng để thêm một thứ khi liệt kê: コーヒーを ください。それから、ケーキも. Không dùng cho quan hệ lý do (dùng だから) hay trái ngược (dùng でも).', 'Trung tính; nối thêm việc tiếp theo hoặc điều bổ sung.', 'Hay dùng それから để nối hai vế trái ngược; muốn nói “nhưng” thì dùng でも.', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-0289294bcc', 'N5', 9, 230, 230, 'Vì vậy...', '[]', 'Vì vậy...', 'vì vậy; cho nên', 'Câu 1。だから・ですから、Câu 2', 'Câu 1 nêu lý do。だから、câu 2 nêu kết quả hay việc sẽ làm: 雨です。だから、出かけません. だから thân mật; nói lịch sự dùng ですから. Kết quả phải hợp với lý do.', 'だから thân mật, ですから lịch sự.', 'Hay dùng だから với người trên; lịch sự phải dùng ですから.', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-02a877e02e', 'N5', 12, 64, 64, 'だった・でした', '[]', 'だった・でした', 'đã là … (quá khứ của だ và です với danh từ và tính từ な)', 'N / Aな + だった (thân mật) / でした (lịch sự)', 'Dùng khi nói về một việc, một trạng thái trong quá khứ: hôm qua là chủ nhật, trước đây rất yên tĩnh.', 'でした là lịch sự, だった là thân mật.', 'Hay dùng でした cho tính từ い (sai: 寒いでした); quá khứ của tính từ い là 寒かったです. Cũng không nói 静かなでした, phải bỏ な.', '[]', NULL, 'AI_CHECKED', 1, '3c5bc58917e7'),
('JG-03edea15cd', 'N5', 3, 140, 140, 'ここ/そこ/あそこ は N です', '[]', 'ここ/そこ/あそこ は N', 'chỗ này; chỗ đó; chỗ kia (chỉ một chỗ và gọi tên chỗ đó)', 'ここ・そこ・あそこ + は + N + です', 'Đứng một mình làm chủ đề để chỉ nơi chốn: ここは教室です. Chọn ここ khi ở ngay chỗ đó, そこ khi chỗ gần người nghe, あそこ khi xa cả hai; muốn kèm danh từ thì dùng この／その／あの hoặc ここの店.', 'Trung tính; dạng lịch sự là こちら, そちら, あちら.', 'Hay dùng これ, それ cho nơi chốn (sai: これは教室です khi đang đứng trong lớp); nói về nơi chốn phải dùng ここ.', '["JG-10ce1e439d"]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-041fbf92aa', 'N5', 16, 87, 87, '〜て (Adjectives and Nouns)', '[]', 'て (Adjectives and Nouns)', '… và … (nối tính từ hoặc danh từ với vế sau)', 'Aい bỏ い + くて / Aな + で / N + で', 'Dùng để nối hai tính chất của cùng một người, vật, hoặc nối danh từ với vế sau thành một câu.', 'Trung tính; hai tính chất nối bằng て thường cùng chiều (cùng tốt hoặc cùng xấu).', 'Hay nối tính từ い bằng で (sai: 安いで) hoặc tính từ な bằng くて (sai: 静かくて). Muốn nối hai ý trái ngược (rẻ nhưng không ngon) thì nên dùng が.', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-05140f76f9', 'N5', 16, 150, 150, 'Adjで〜 – Nối câu với tính từ な', '[]', 'Adjで〜 – Nối câu với tính từ な', '… và …; vì … nên … (nối câu bằng tính từ な)', 'Aな + で、…', 'Aな bỏ な thêm で để nối sang vế sau: 静かできれいです (yên tĩnh và sạch đẹp). Cũng nêu lý do nhẹ: 有名で、いつも人が多いです. Không giữ な (静かなで) và không dùng くて (静かくて).', 'Trung tính; nối các tính chất cùng chiều hoặc nêu hoàn cảnh nhẹ cho vế sau.', 'Hay giữ な (sai: 静かなで) hoặc dùng くて (sai: 静かくて); đúng là 静かで.', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-054fc1320d', 'N5', 5, 315, 315, 'Không ở đâu cả', '[]', 'Không ở đâu cả', 'không … ở đâu cả', 'どこにも + Vない (ありません・いません・行きません)', 'どこにも + phủ định: không có, không thấy ở đâu cả (どこにもありません, どこにもいません) hoặc không đi đâu cả (どこにも行きません). Đồ vật dùng ありません, người và con vật dùng いません.', 'Phủ định toàn bộ về nơi chốn.', 'Hay dùng với câu khẳng định; どこにも luôn đi với phủ định.', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-05589d014f', 'N5', 17, 320, 320, '〜なければ なりませんか / 〜は いりますか', '[]', 'なければ なりませんか / 〜は いりますか', 'Hỏi có phải làm không\nThêm か vào cuối; hỏi đồ vật cần hay không thì dùng いりますか.', 'Vない bỏ い + ければなりませんか / N + は + いりますか', 'Đáp không cần thì nói なくても いいです, đừng đáp trống một chữ いいえ.', 'Lịch sự; câu trả lời phủ định thường dùng 〜なくてもいいです.', 'Không cần làm thì hay đáp いいえ、なければなりません; đúng là いいえ、〜なくてもいいです.', '["JG-f02a27e408","JG-a3abb234e6"]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-06ccdf06d7', 'N5', 1, 1, 1, '〜も', '[]', 'も', 'cũng', 'N + も', 'Đặt も ngay sau danh từ để nói người hoặc vật đó cũng giống điều vừa nêu: 私も学生です (tôi cũng là học sinh). も đứng thay vào chỗ của は, が, を; còn với に, で, へ thì giữ trợ từ rồi thêm も phía sau (日本にも).', 'Trung tính, dùng được cả khi nói lẫn khi viết; も đứng thay hẳn vào chỗ của は, が, を.', 'Người Việt hay nói 私はも hoặc 本をも; đúng là bỏ は/が/を và chỉ để も: 私も, 本も. Riêng に, で, へ thì giữ lại rồi thêm も phía sau: 日本にも.', '[]', NULL, 'AI_CHECKED', 1, '3c5bc58917e7'),
('JG-06ffc763fd', 'N5', 22, 165, 165, '〜の・〜が', '[]', 'の・〜が', 'Chỉ chủ thể của cụm từ bổ nghĩa', 'N + が・の + V + N (母が作った料理, 母の作った料理)', 'Trong cụm bổ nghĩa đứng trước danh từ, chủ ngữ của cụm đó được đánh dấu bằng が hoặc の.', 'の nghe mềm và hơi trang trọng; が phổ biến hơn trong hội thoại.', 'Hay dùng は trong cụm bổ nghĩa (sai: 母は作った料理); chủ ngữ trong cụm bổ nghĩa không dùng は.', '["JG-be2024a8f0"]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-072b546f77', 'N5', 19, 348, 348, 'V たり V たり します', '[]', 'V たり V たり し', 'Kể vài việc làm không theo thứ tự\nKể vài việc tiêu biểu, ý là còn làm cả thứ khác nữa: よんだり きいたり します.', 'V1た + り、V2た + り + します', 'Khác với đuôi て nối câu: đuôi て là làm lần lượt, たり là kể ví dụ vài việc.', 'Trung tính; kể vài việc tiêu biểu, ngầm hiểu còn việc khác.', 'Hay quên する ở cuối mẫu (読んだり、見たり。✗ → 読んだり、見たりします). Thì của câu chỉ đặt ở します / しました cuối câu.', '["JG-f20250fe9e","JG-6b3810a528"]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-074c1eba29', 'N5', 1, 118, 118, 'N1 は N2 ですか', '[]', 'N1 は N2 ですか', 'có phải là … không? (N1 có phải là N2 không)', 'N1 + は + N2 + ですか', 'Thêm か vào cuối câu khẳng định để hỏi, giữ nguyên trật tự từ: あの人は先生ですか. Trả lời đồng ý: はい、そうです; không đúng: いいえ、ちがいます hoặc いいえ、〜じゃありません.', 'Lịch sự; trả lời はい、そうです hoặc いいえ、そうじゃありません.', 'Hay chỉ lên giọng hoặc thêm dấu ? mà quên か. Khi trả lời “không”, người Việt hay nói いいえ、そうです; đúng là いいえ、そうじゃありません.', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-0a27275d17', 'N5', 23, 394, 394, 'V た とき', '[]', 'V た とき', 'Lúc việc kia đã xong\nDùng đuôi た khi việc trước đã xong rồi mới tới việc sau: えきに ついた とき でんわします.', 'Vた + とき、…', 'Vる とき (行くとき: lúc đang trên đường đi, trước khi tới) khác hẳn Vた とき (行ったとき: khi đã tới nơi) — đây là chỗ hay nhầm nhất.', 'Việc ở vế とき đã xong rồi mới xảy ra việc sau.', 'Hay dùng thể từ điển cho việc đã xong (sai: 日本へ行くとき、すしを食べました với nghĩa “khi đã đến Nhật”); phải là 行ったとき.', '["JG-1455934d05"]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-0bfff36769', 'N5', 14, 78, 78, '〜て (Conjunction)', '[]', 'て (Conjunction)', '… rồi … (dạng て nối các hành động)', 'V1-て、V2', 'Dùng thể て của động từ đứng trước để nối các hành động liền nhau: 朝起きて、シャワーを浴びます (dậy rồi tắm). Cách đổi sang thể て: く → いて, ぐ → いで, う・つ・る → って, む・ぶ・ぬ → んで, す → して; riêng 行く → 行って.', 'Trung tính; thì của cả câu do động từ ở cuối câu quyết định.', 'Hay chia thì ở cả hai vế (sai: 起きました、シャワーを浴びました) khi muốn nối; vế trước chỉ cần thể て. Hay chia sai thể て: 書きて → 書いて, 待ちて → 待って, 行いて → 行って.', '[]', NULL, 'AI_CHECKED', 1, '3c5bc58917e7'),
('JG-0cadcd9e02', 'N5', 20, 203, 203, 'Tuy... nhưng...', '[]', 'Tuy... nhưng...', 'tuy … nhưng …; nối hai vế trái ngược (cách nói thân mật)', 'Câu 1 (thể thường / です・ます) + けど、Câu 2', 'Câu 1 + けど、câu 2 trái ý: 高いけど、買います. Tính từ い và động từ nối thẳng (高いけど, 行きたいけど); danh từ và tính từ な thêm だ (雨だけど, 静かだけど). Lịch sự thì nói ですけど hoặc dùng が.', 'Thân mật, dùng khi nói; lịch sự hơn thì dùng が hoặc けれども.', 'Với danh từ, tính từ な phải có だ trước けど (sai: 雨けど); đúng là 雨だけど.', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-0e17041b0c', 'N5', 15, 375, 375, 'もう〜た・まだ〜ていない', '[]', 'もう〜た・まだ〜ていない', 'đã … rồi (もう); vẫn chưa … (まだ)', 'もう + V-ました / まだ + V-ていません', 'Hỏi việc đã làm chưa: もう + Vましたか. Đã làm: はい、もうVました. Chưa làm: いいえ、まだVていません (hoặc ngắn gọn いいえ、まだです).', 'Trung tính; hỏi và trả lời về việc đã định làm.', 'Chưa làm thì hay đáp いいえ、〜ませんでした; đúng là いいえ、まだ〜ていません.', '["JG-a6edafd1b9","JG-13a8dada5f"]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-0e97cffd1d', 'N5', 19, 147, 147, 'Adjくします – Làm cho trở nên (tính từ い)', '[]', 'Adjくします – Làm cho trở nên (tính từ い)', 'làm cho … trở nên …; chủ động thay đổi trạng thái (tính từ い)', 'N + を + Aい bỏ い + く + します', 'Dùng N を Aく します khi chính mình tác động làm vật đó thay đổi: 部屋を明るくします, 音を小さくします. Nhờ người khác thì nói 〜くしてください: もう少し短くしてください. Riêng いい → よくします.', 'Diễn tả sự thay đổi do người làm chủ động tạo ra, khác với なります là tự thay đổi.', 'Hay nhầm với くなります: 部屋が明るくなります là phòng tự sáng lên, 部屋を明るくします là mình làm cho phòng sáng. Nhớ dùng を với くします.', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-0eeeecf6ed', 'N5', 8, 148, 148, 'Adjくない – Phủ định tính từ い', '[]', 'Adjくない – Phủ định tính từ い', 'không …; phủ định của tính từ い', 'Aい bỏ い + くない(です)', 'Aい bỏ い thêm くない: 高い → 高くない. Lịch sự nói 〜くないです hoặc 〜くありません. Hay đi với あまり (không … lắm) và ぜんぜん (hoàn toàn không). Riêng いい → よくない.', 'くない là thân mật; lịch sự là くないです hoặc くありません.', 'Hay dùng じゃない cho tính từ い (sai: 高いじゃない). いい đổi thành よくない.', '["JG-dad75c9be2","JG-af886f1233","JG-aecc9e94e2"]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-0ef56ff856', 'N5', 9, 217, 217, '〜ません / 〜じゃ ありません', '[]', 'ません / 〜じゃ ありません', 'Nói không thích, không có\nĐộng từ đổi đuôi thành ません; tính từ loại な dùng じゃ ありません.', 'V-ます bỏ ます + ません / Aな・N + じゃありません', 'ぜんぜん ～ません là không chút nào, あまり ～ません là không mấy.', 'Lịch sự.', 'Hay dùng じゃありません với động từ (sai: 行くじゃありません); động từ phải chia ません.', '["JG-b003a8c5af","JG-d78721df11"]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-1075a293a5', 'N5', 3, 225, 225, 'Thế nhé...', '[]', 'Thế nhé...', 'thế thì; vậy thì; thế nhé (chào tạm biệt)', 'じゃ、+ Câu', 'Đặt じゃ ở đầu câu khi đưa ra quyết định, đề nghị dựa trên điều vừa nghe: 「もう五時ですね。」「じゃ、帰りましょう。」. Cũng dùng để chào khi chia tay: じゃ、また明日. じゃ thân mật; lịch sự hơn dùng では.', 'Thân mật; lịch sự hơn là では.', 'Hay dùng じゃ với người trên trong dịp trang trọng; khi đó nên dùng では.', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-10ce1e439d', 'N5', 3, 15, 15, 'ここ', '[]', 'ここ', 'chỗ này; ở đây (nơi người nói đang ở)', 'ここ + は + N + です / ここ + に・で + V', 'Dùng để chỉ chỗ mình đang đứng hoặc chỗ ở ngay gần mình.', 'Trung tính; nói lịch sự (tiếp khách, trong cửa hàng) thì dùng こちら.', 'Không đặt danh từ ngay sau ここ (sai: ここ部屋); muốn kèm danh từ thì dùng この部屋. Nói “ở đây có …” phải thêm に: ここに本があります.', '["JG-03edea15cd"]', NULL, 'AI_CHECKED', 1, '3c5bc58917e7'),
('JG-10eece2be0', 'N5', 13, 76, 76, '〜に行(い)く', '[]', 'に行(い)く', 'đi để làm … (chỉ mục đích của việc di chuyển)', 'V-ます bỏ ます / N(hoạt động) + に + 行く・来る・帰る', 'Dùng để nói đi đâu với mục đích gì, ví dụ đi mua đồ, đi ăn, đi chụp ảnh.', 'Trung tính; nơi đến đi với へ hoặc に, mục đích đi với に.', 'Hay dùng thể từ điển trước に (sai: 買うに行きます); đúng là 買いに行きます. Nơi đến và mục đích có thể cùng xuất hiện: デパートへ買い物に行きます.', '[]', NULL, 'AI_CHECKED', 1, '3c5bc58917e7'),
('JG-115382d155', 'N5', 10, 293, 293, 'Không ai cả', '[]', 'Không ai cả', 'không ai; không một ai', 'だれも + Vない / Vません', 'だれも + phủ định = không ai. Khi có trợ từ khác thì đặt trước も: だれにも (không … với/cho ai cả), だれとも (không … cùng ai cả). Ở N5, だれも không đi với câu khẳng định.', 'Phủ định toàn bộ về người.', 'Hay dùng だれも với câu khẳng định (sai: だれも来ました); だれも luôn đi với phủ định.', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-1186ed0175', 'N5', 23, 396, 396, 'どうすると 〜か / いつ 〜か', '[]', 'どうすると 〜か / いつ 〜か', 'Hỏi cách làm, hỏi lúc nào\nHỏi thao tác thì どうすると, hỏi thời điểm thì いつ.', 'どうすると + Câu + か / いつ + Câu + か', 'Đáp どうすると nên đáp bằng cả vế と cho rõ, đừng đáp mỗi tên nút.', 'Trung tính.', 'Hay thêm に sau いつ (sai: いつに降りますか).', '["JG-9b200447f7","JG-d5f6d866ef","JG-171c3a58eb"]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-1268d009b9', 'N5', 4, 156, 156, '〜ます/〜ますか', '[]', 'ます/〜ますか', 'Nói việc mình làm và hỏi lại người khác\nĐuôi ます dùng cho việc thường ngày và việc sắp làm.', 'V-ます / V-ますか', 'Hỏi thì thêm か vào cuối, giọng hơi lên ở chữ cuối.', 'Lịch sự, dùng với người mới quen, người trên; ます vừa chỉ thói quen vừa chỉ việc sẽ làm.', 'Hay dùng ます để nói việc đang làm ngay lúc nói (sai: 今食べます với nghĩa đang ăn); đang làm phải là 食べています.', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-127e14e7aa', 'N5', 2, 12, 12, 'あの', '[]', 'あの', '… kia (đứng trước danh từ chỉ người hoặc vật ở xa cả hai người)', 'あの + N', 'Đặt trước danh từ để chỉ người hoặc vật ở xa cả người nói lẫn người nghe, ví dụ あの人 (người kia).', 'Trung tính; nói về người lạ thì あの方 lịch sự hơn あの人.', 'Hay để あの đứng một mình như あれ; あの bắt buộc có danh từ theo sau. Đừng nhầm あの (… kia) với あのう (ừm, xin lỗi) dùng khi bắt chuyện.', '[]', NULL, 'AI_CHECKED', 1, '3c5bc58917e7'),
('JG-12f3c42e79', 'N5', 17, 325, 325, '〜ないでください', '[]', 'ないでください', 'xin đừng …; đừng … nhé', 'Vない + でください', 'Dùng để nhờ hoặc yêu cầu người khác đừng làm một việc gì đó.', 'Lịch sự; với người trên có thể nói 〜ないでくださいませんか cho mềm hơn.', 'Hay quên で (sai: 食べないください).', '["JG-1fe5b4d961","JG-71898a4777","JG-b707f36b01"]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-138a37b3bb', 'N5', 9, 343, 343, 'Tại sao', '[]', 'Tại sao', 'tại sao (thân mật); bằng gì', 'なんで + Câu + か・の', 'なんで có hai nghĩa: hỏi lý do (thân mật, hay đi với 〜んですか: なんで来なかったんですか) và hỏi phương tiện (なんで行きますか — バスで行きます). Nhìn câu trả lời để phân biệt. Hỏi lý do với người trên thì dùng どうして.', 'Thân mật, dùng với bạn bè; lịch sự hơn là どうして.', 'Hay dùng なんで với người trên; nên dùng どうして. Cũng đừng nhầm với なんで mang nghĩa “bằng gì” (なんで行きますか).', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-13a8dada5f', 'N5', 7, 193, 193, 'もう 〜ました / まだです', '[]', 'もう 〜ました / まだ', 'Đã xong rồi hay vẫn chưa\nXong rồi thì もう + đuôi ました; chưa thì đáp gọn まだです.', 'もう + V-ました / まだです / まだ + V-ていません', 'Đáp まだです là chưa nhưng sẽ làm. Nói ません là không làm — hai ý khác hẳn nhau.', 'Trung tính; まだです là câu trả lời ngắn, tự nhiên.', 'Chưa làm thì hay đáp いいえ、〜ませんでした; đúng là いいえ、まだです.', '["JG-a6edafd1b9","JG-0e17041b0c"]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-13b031cef2', 'N5', 11, 243, 243, 'いくつ / なんまい / なんにん / なんぼん / なんかい ですか', '[]', 'いくつ / なんまい / なんにん / なんぼん / なんかい ですか', 'Hỏi bao nhiêu\nĐổi số thành なん rồi giữ nguyên đuôi đếm: なんまい · なんにん · なんだい.', 'いくつ / なん + đơn vị đếm (なんまい, なんにん, なんぼん, なんかい) + ですか', 'Hỏi vật chung chung thì dùng いくつ, không cần đuôi đếm.', 'Trung tính; いくつ dùng cho vật đếm bằng 〜つ và còn dùng để hỏi tuổi lịch sự (おいくつ).', 'Hay đọc なんほん; đúng là なんぼん. Hỏi số người phải dùng なんにん, không dùng いくつ.', '["JG-5a67a7a6d3"]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-13fef2ce63', 'N5', 7, 385, 385, 'Nhận từ (ai đó, nguồn)', '[]', 'Nhận từ (ai đó, nguồn)', 'nhận (từ ai hoặc từ nơi nào)', 'N(người, tổ chức) + から + N + を + もらいます', 'N + から + N + を もらいます: nhận cái gì từ một người hoặc một nơi (学校から, 会社から, 店から). Với người cụ thể dùng に hay から đều được; với trường học, công ty, cửa hàng thì dùng から.', 'Nhấn vào nguồn cho; với trường học, công ty thì dùng から tự nhiên hơn に.', 'Hay dùng に với tổ chức (学校にもらいました nghe không tự nhiên); nên dùng から.', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-1455934d05', 'N5', 10, 163, 163, '〜たとえば', '[]', 'たとえば', 'ví dụ; chẳng hạn như', 'たとえば、N1 や N2 (など)…', 'Đặt trước phần ví dụ để nêu vài trường hợp cụ thể minh họa cho điều vừa nói.', 'Trung tính; thường đi cùng や, など.', 'Hay đặt たとえば ở cuối câu như “chẳng hạn” trong tiếng Việt; たとえば luôn đứng trước phần ví dụ. Sau たとえば nên dùng や, など chứ không dùng と để kể hết.', '["JG-0a27275d17"]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-14e46cf9f2', 'N5', 7, 363, 363, 'Nhận từ (ai đó)', '[]', 'Nhận từ (ai đó)', 'nhận (từ ai); được cho', 'N1(người cho) + に・から + N2 + を + もらいます', 'N1 に / から N2 を もらいます: nhận N2 từ N1 (người cho đứng trước に hoặc から). Câu nhìn từ phía người nhận, thường là "tôi". Người cho là tổ chức thì hay dùng から: 会社から手紙をもらいました.', 'Nhìn sự việc từ phía người nhận; người nhận thường là người nói.', 'Hay đặt người nhận trước に như với あげます; với もらいます, trước に là người cho.', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-15239d5b3e', 'N5', 19, 347, 347, 'V た ことが ありません', '[]', 'V た ことが ありません', 'Nói chưa từng làm\nChỉ đổi cuối câu thành ありません.', 'Vた + ことがありません', 'Thêm いちども cho ý chưa lần nào, thêm まだ cho ý chưa nhưng sẽ có dịp.', 'Trung tính; nói chưa từng trải qua.', 'Hay dùng thể ない (sai: 食べないことがあります) để nói chưa từng; đúng là 食べたことがありません.', '["JG-788cfc687d","JG-4f10b05b40","JG-afacd1b137"]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-1552483f27', 'N5', 12, 68, 68, 'より', '[]', 'より', 'hơn … (より đánh dấu mốc để so sánh)', 'N1 + は + N2 + より + A', 'Đặt sau thứ được đem ra làm mốc để nói N1 hơn N2 về một tính chất nào đó.', 'Trung tính; より đứng sau mốc so sánh, tức là thứ kém hơn.', 'Hay đặt より nhầm chỗ theo kiểu “A hơn B” trong tiếng Việt; nhớ より luôn gắn sau B: 日本はベトナムより寒いです. Không cần thêm もっと.', '["JG-1a68a64c14"]', NULL, 'AI_CHECKED', 1, '3c5bc58917e7'),
('JG-15e5fd833e', 'N5', 4, 27, 27, 'Noun + まで', '[]', 'Noun + まで', 'đến … (điểm kết thúc về thời gian hoặc nơi chốn)', 'N + まで', 'Đặt sau danh từ chỉ giờ giấc hay nơi chốn để nói mốc kết thúc; thường đi cặp với から.', 'Trung tính; chỉ giới hạn cuối, hành động kéo dài liên tục đến mốc đó.', 'Hay nhầm まで với までに: まで là làm liên tục cho đến lúc đó, までに là hạn chót phải xong trước lúc đó.', '["JG-eeda3e983e"]', NULL, 'AI_CHECKED', 1, '3c5bc58917e7'),
('JG-16a9facc20', 'N5', 12, 255, 255, '〜くなかったです / 〜じゃ ありませんでした', '[]', 'くなかったです / 〜じゃ ありませんでした', 'Nói chuyện đã qua mà không phải vậy\nGhép hai bước: trước hết chuyển sang phủ định, rồi mới chuyển sang đã qua.', 'Aい bỏ い + くなかったです / Aな・N + じゃありませんでした', 'あまり và ぜんぜん vẫn bắt buộc đi với đuôi phủ định như thường.', 'Lịch sự; dùng khi kể chuyện đã qua mà không phải như vậy.', 'Hay nói くないでした, じゃなかったでした; đúng là くなかったです, じゃありませんでした.', '["JG-dad75c9be2","JG-af886f1233","JG-0eeeecf6ed"]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-171c3a58eb', 'N5', 16, 308, 308, 'どうやって 〜か / なにを してから 〜か', '[]', 'どうやって 〜か / なにを してから 〜か', 'Hỏi cách làm, hỏi thứ tự\nどうやって hỏi đi bằng cách nào, làm bằng cách nào.', 'どうやって + V + か / なにを + してから + V + か', 'Đáp どうやって thì kể cả chuỗi việc, đừng đáp mỗi tên phương tiện.', 'Trung tính.', 'Hay dùng どう thay cho どうやって khi hỏi cách làm; どう là hỏi cảm nhận.', '["JG-9b200447f7","JG-d5f6d866ef","JG-39f20e102c"]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-180021545a', 'N5', 10, 234, 234, 'N に N が います', '[]', 'N に N が い', 'Ở chỗ đó có ai, có con gì\nNgười và con vật dùng います, đồ vật dùng あります. Cấu trúc giống hệt nhau.', 'N(nơi chốn) + に + N(người, con vật) + が + います', 'Cây cối là vật, nên vẫn dùng あります dù nó sống.', 'Trung tính.', 'Hay dùng あります cho người và con vật.', '["JG-66a6ede168"]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-18049507fb', 'N5', 4, 21, 21, 'る-Verb (Negative)', '[]', 'る-Verb (Negative)', 'không … (dạng phủ định thân mật của động từ nhóm II)', 'Vる bỏ る + ない (食べる → 食べない)', 'Dùng để nói mình không làm việc gì khi nói chuyện thân mật; nói lịch sự thì dùng 〜ません.', 'Thân mật; với người lạ hay người trên nên dùng ません.', 'Hay áp quy tắc nhóm I thành 食べらない; nhóm II chỉ bỏ る rồi thêm ない. Ngược lại, động từ nhóm I đuôi る như 帰る phải thành 帰らない.', '[]', NULL, 'AI_CHECKED', 1, '3c5bc58917e7'),
('JG-182def4e9c', 'N5', 11, 355, 355, '〜ぐらい・くらい', '[]', 'ぐらい・くらい', 'khoảng; chừng', 'Số lượng + ぐらい・くらい', 'Đặt sau con số chỉ lượng, thời gian, giá tiền để nói con số đó chỉ gần đúng.', 'Trung tính; ぐらい và くらい dùng như nhau.', 'Hay dùng với mốc thời điểm; mốc thời điểm thì ごろ tự nhiên hơn.', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-195ce8feed', 'N5', 10, 59, 59, 'や', '[]', 'や', 'và; như là (liệt kê vài ví dụ tiêu biểu không nêu hết)', 'N1 + や + N2 (+ など)', 'Dùng để nêu vài thứ tiêu biểu trong nhiều thứ, ngầm hiểu vẫn còn những thứ khác nữa.', 'Trung tính; hay đi với など ở cuối để nhấn ý “vân vân”.', 'Hay dùng や khi đã kể đủ hết (lúc đó dùng と). や chỉ nối danh từ, không nối động từ; nối động từ thì dùng 〜たり〜たり.', '[]', NULL, 'AI_CHECKED', 1, '3c5bc58917e7'),
('JG-19c95ea4c6', 'N5', 4, 26, 26, 'う-Verb (Negative-Past)', '[]', 'う-Verb (Negative-Past)', 'đã không … (dạng phủ định quá khứ thân mật của động từ nhóm I)', 'Vう: âm hàng う → âm hàng あ + なかった (書く → 書かなかった)', 'Dùng khi kể việc đã không làm trong quá khứ với người thân quen; nói lịch sự thì dùng 〜ませんでした.', 'Thân mật; nghĩa giống ませんでした.', 'Hay nói 行かないでした; đúng là 行かなかった (thân mật) hoặc 行きませんでした (lịch sự).', '[]', NULL, 'AI_CHECKED', 1, '3c5bc58917e7'),
('JG-1a68a64c14', 'N5', 12, 70, 70, 'より〜の方(ほう)が', '[]', 'より〜の方(ほう)が', '… hơn … (nhấn vào thứ được chọn khi so sánh hai thứ)', 'N1 + より + N2 + のほうが + A', 'Dùng để trả lời câu hỏi どちら, hoặc để nói rõ trong hai thứ thì N2 là thứ hơn.', 'Nhấn vào thứ đứng trước の方が; phần N1より có thể lược nếu đã rõ.', 'Hay quên の hoặc が (sai: 魚方が); đúng là 魚の方が. Không dùng mẫu này để so sánh từ ba thứ trở lên.', '["JG-1552483f27"]', NULL, 'AI_CHECKED', 1, '3c5bc58917e7'),
('JG-1b0d6dd1ca', 'N5', 7, 342, 342, 'Nói thế nào', '[]', 'Nói thế nào', 'nói thế nào; gọi là gì', 'N + は + (ngôn ngữ) + で + 何と・どう + 言いますか', 'Hỏi cách nói một từ, một câu trong ngôn ngữ khác: N は + ngôn ngữ + で + どう言いますか / 何と言いますか. Trả lời: 「…」と言います. Ngôn ngữ đi với で; hỏi cách đọc chữ thì dùng 何と読みますか.', 'Trung tính; 何と hỏi nói là gì, どう hỏi nói bằng cách nào.', 'Hay dùng どうやって cho câu hỏi cách nói; với cách diễn đạt chỉ cần どう言いますか.', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-1bd140cb75', 'N5', 18, 309, 309, '〜が見える・聞こえる', '[]', 'が見える・聞こえる', 'Biểu thị hình ảnh hay âm thanh đập vào mắt, vào tai một cách tự nhiên.', 'N + が + 見える・聞こえる', 'Dùng khi hình ảnh hay âm thanh tự nhiên lọt vào mắt, vào tai mà mình không cần cố ý.', 'Khác với 見る, 聞く là chủ động nhìn, nghe.', 'Hay dùng を (sai: 海を見えます); đúng là 海が見えます.', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-1cb080df09', 'N5', 13, 74, 74, 'が欲(ほ)しい', '[]', 'が欲(ほ)しい', 'muốn có (thứ gì)', 'N + が + ほしい(です)', 'Dùng để nói người nói muốn có một đồ vật hay một điều gì; hỏi người nghe thì dùng 何がほしいですか.', 'Nói thẳng mong muốn của mình; nói với người trên dễ nghe như đòi hỏi nên cần chú ý.', 'Hay dùng を (sai: 車をほしい) hoặc dùng ほしい cho hành động; muốn làm việc gì thì dùng 〜たい. Không dùng ほしい để nói mong muốn của người thứ ba.', '[]', NULL, 'AI_CHECKED', 1, '3c5bc58917e7'),
('JG-1d1d997bc7', 'N5', 9, 55, 55, '大体(だいたい)', '[]', '大体(だいたい)', 'đại khái; khoảng chừng; phần lớn', 'だいたい + V / だいたい + số lượng', 'Dùng để nói số lượng, thời gian xấp xỉ, hoặc nói đã hiểu, đã làm được phần lớn.', 'Trung tính, hay dùng trong hội thoại; だいたい分かります là hiểu gần hết chứ không phải hiểu hoàn toàn.', 'Hay dùng だいたい như “rất”; nó chỉ mang nghĩa xấp xỉ, phần lớn. Với một mốc giờ cụ thể thì ごろ tự nhiên hơn (3時ごろ).', '[]', NULL, 'AI_CHECKED', 1, '3c5bc58917e7'),
('JG-1e244bf9f2', 'N5', 1, 122, 122, 'Chủ đề của câu', '[]', 'Chủ đề của câu', 'nêu chủ đề của câu (… thì)', 'N + は + (phần nói về N)', 'Đặt は sau danh từ để nêu điều sẽ nói đến, phần sau は là thông tin về nó: 私はベトナム人です. Khi hai vế có は đặt cạnh nhau, は tạo ý so sánh tương phản: 肉は食べますが、魚は食べません. Sau nơi chốn có thể dùng では: 日本では…. は viết là は nhưng đọc là “wa”.', 'Trung tính; は làm nền cho câu và có thể ngầm so sánh với những thứ khác.', 'Người Việt hay nghĩ は luôn là chủ ngữ nên dùng nhầm cho thông tin mới hoặc sau từ để hỏi (sai: だれは来ましたか); những chỗ đó cần が.', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-1eb30f0391', 'N5', 22, 377, 377, 'V ない + N', '[]', 'V ない + N', 'Tả bằng việc không làm\nDùng đuôi ない: しらない ことば là từ mình không biết.', 'Vない + N', 'Đây là cụm tả, không phải câu — đừng thêm です vào giữa.', 'Trung tính.', 'Hay dùng thể ません trước danh từ (sai: 使いません物); phải dùng thể ない.', '["JG-1fe5b4d961","JG-71898a4777","JG-b707f36b01"]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-1f5761145b', 'N5', 23, 360, 360, 'Khi, lúc', '[]', 'Khi, lúc', 'khi …; lúc …', 'Vる・Vた / Aい / Aな + な / N + の + とき', 'Đặt とき sau mệnh đề để chỉ thời điểm: Vる / Vた + とき, Aい + とき, Aな + な + とき, N + の + とき. Vる とき: việc chính xảy ra trước hoặc trong lúc làm V (日本へ行くとき、パスポートを持っていきます); Vた とき: việc chính xảy ra sau khi V xong (日本へ行ったとき、すしを食べました).', 'Trung tính.', 'Hay quên な với tính từ な (sai: ひまとき).', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-1f7078c096', 'N5', 24, 399, 399, 'N が V-て くれます', '[]', 'N が V-て くれ', 'Người khác làm cho tôi\nNgười ra tay đứng đầu và đi với が: たなかさんが てつだって くれました.', 'N(người giúp) + が + V-て + くれます', 'くれます luôn hướng về phía mình — không dùng cho việc người này làm cho người kia.', 'Thể hiện sự biết ơn với người giúp mình.', 'Hay dùng に cho người giúp (sai: 母に作ってくれました); với くれる phải dùng が.', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-1faa5326a0', 'N5', 2, 137, 137, 'これ/それ/あれ は N です', '[]', 'これ/それ/あれ は N', 'cái này; cái đó; cái kia (chỉ đồ vật và gọi tên nó)', 'これ・それ・あれ + は + N + です', 'Đứng một mình làm chủ đề để chỉ đồ vật: これは本です. Chọn これ khi đồ ở gần mình, それ khi ở gần người nghe, あれ khi ở xa cả hai; không gắn thêm danh từ ngay sau (sai: これ本).', 'Trung tính; ba từ này chỉ dùng cho đồ vật.', 'Hay dùng これ để giới thiệu người đang đứng đó (sai: これは私の母です); với người phải dùng こちら.', '["JG-364904155e"]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-1fe5b4d961', 'N5', 17, 90, 90, '〜ないで', '["ないで"]', 'ないで', 'không … mà … (làm việc sau trong lúc không làm việc trước)', 'Vない + で + V2', 'Dùng để nói làm việc thứ hai trong lúc không làm việc thứ nhất, ví dụ ra ngoài mà không mang ô.', 'Trung tính; nhấn rằng việc lẽ ra thường làm đã không được làm.', 'Hay dùng なくて thay cho ないで (sai: 朝ごはんを食べなくて出かけました); nói “làm B mà không làm A” phải dùng ないで. Đừng nhầm với 〜ないでください là lời nhờ đừng làm.', '["JG-71898a4777","JG-b707f36b01","JG-12f3c42e79"]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-20044b7380', 'N5', 3, 138, 138, 'N は いくら ですか', '[]', 'N は いくら ですか', 'bao nhiêu tiền (hỏi giá)', 'N + は + いくら + ですか', 'Dùng Nはいくらですか để hỏi giá; thường thêm この／その／あの trước món đồ: このシャツはいくらですか. Trả lời bằng số tiền + 円: 三百円です. Hỏi tổng cộng: 全部でいくらですか.', 'Trung tính, dùng khi mua bán; lịch sự hơn có thể nói おいくらですか.', 'Hay hỏi giá bằng なんえん hay どのくらい; tự nhiên nhất là いくらですか. Đọc giá cần nhớ: さんびゃく (300), ろっぴゃく (600), はっぴゃく (800).', '["JG-dbcd98f1dc"]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-20d5ded708', 'N5', 15, 298, 298, '〜ても いいですか / 〜て いますか', '[]', 'ても いいですか / 〜て いますか', 'Hỏi xin phép, hỏi tình trạng\nXin phép thì thêm か vào sau いいです; hỏi tình trạng thì thêm か sau います.', 'V-て + もいいですか / V-て + いますか', 'Hỏi chuyện riêng (lập gia đình chưa, sống với ai) chỉ nên hỏi khi đã thân.', 'Lịch sự; một câu để xin phép, một câu để hỏi tình trạng.', 'Hay trả lời câu xin phép bằng はい、いいです nghe cụt; tự nhiên hơn là はい、どうぞ.', '["JG-315e3a8560","JG-9d12efd7d2","JG-a412adf097"]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-219bf7903d', 'N5', 15, 301, 301, 'V-て います (tình trạng)', '[]', 'V-て います (tình trạng)', 'Kể chỗ ở, nghề, chuyện đã thành nếp\nKhác với bài trước: đây không phải đang làm dở, mà là tình trạng đang duy trì — とうきょうに すんで います.', 'V-て + います (tình trạng: 持っている, かけている, 結婚している)', 'V-ています còn dùng cho tình trạng đang duy trì, không phải việc đang làm dở: chỗ ở (東京にすんでいます), nghề nghiệp (先生をしています), đã kết hôn (結婚しています), sở hữu (車を持っています), đeo/mặc (めがねをかけています). Riêng 知っています (biết): phủ định nói 知りません, không nói 知っていません.', 'Không phải đang làm dở mà là trạng thái đang được duy trì.', 'Hay dùng 持ちます để nói “có” (sai: 車を持ちます); nói đang sở hữu phải là 持っています.', '["JG-b2976be48a","JG-4bf259bc32","JG-72a02e9fe6"]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-223df589a9', 'N5', 2, 10, 10, 'この', '[]', 'この', '… này (đứng trước danh từ chỉ người hoặc vật ở gần người nói)', 'この + N', 'Đặt ngay trước danh từ để chỉ người hoặc vật ở gần mình, ví dụ この本 (quyển sách này).', 'Trung tính; nói về người thì この方 lịch sự hơn この人.', 'Hay để この đứng một mình (sai: このはいくらですか); この luôn cần danh từ theo sau, đứng một mình thì dùng これ. Thứ tự cũng ngược tiếng Việt: “sách này” là この本.', '["JG-2e4c8d4494"]', NULL, 'AI_CHECKED', 1, '3c5bc58917e7'),
('JG-2530ce1e3f', 'N5', 8, 49, 49, 'が', '[]', 'が', 'nhưng (nối hai vế trái ngược)', 'Câu 1 (です・ます) + が、Câu 2', 'Đặt が sau vế thứ nhất (thường kết thúc bằng です hoặc ます) để nối với vế sau mang ý trái ngược: この部屋は広いですが、高いです (phòng này rộng nhưng đắt). Hai vế phải có ý đối lập.', 'Lịch sự, hay đi với です・ます; nói thân mật thì dùng けど. Đôi khi が chỉ để mở lời nhẹ nhàng: すみませんが、….', 'Hay dùng が để nối hai ý cùng chiều (sai: 親切ですが、やさしいです); ý cùng chiều thì nối bằng て/で: 親切で、やさしいです. Cũng đừng nhầm với trợ từ が chỉ chủ ngữ (猫がいます).', '[]', NULL, 'AI_CHECKED', 1, '3c5bc58917e7'),
('JG-25a1d2bbc3', 'N5', 21, 366, 366, '〜と いいました', '[]', 'と いいました', 'Thuật lại lời người khác\nCũng để vế trước ở lối thân mật rồi thêm と いいました.', 'Câu (thể thường) + と言いました / 「Lời nguyên văn」 + と言いました', 'Người nói đứng đầu câu và đi với は: たなかさんは ～と いいました.', 'Trung tính; dùng để thuật lại lời người khác.', 'Khi thuật gián tiếp hay để vế trích ở thể lịch sự; trích nguyên văn thì đặt lời nói trong 「」.', '["JG-30023f2c1d"]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-25b6c4e2da', 'N5', 12, 72, 72, 'の中(なか)で〜が一番(いちばん)', '[]', 'の中(なか)で〜が一番(いちばん)', 'trong số … thì … là nhất', 'N(nhóm) + の中で + N + が + 一番 + A', 'Dùng để nói hoặc hỏi trong một nhóm thì người, vật nào đứng đầu về một mặt nào đó.', 'Trung tính; câu hỏi dùng 何, どれ, だれ, いつ, どこ + が一番.', 'Hay dùng は sau thứ đứng nhất (sai: りんごは一番好きです); đúng là りんごが一番好きです. Hỏi trong nhóm từ ba thứ trở lên thì không dùng どちら.', '["JG-c9a23c6309"]', NULL, 'AI_CHECKED', 1, '3c5bc58917e7'),
('JG-2642696f51', 'N5', 8, 162, 162, '〜あまり〜ない', '[]', 'あまり〜ない', 'không … lắm; ít khi …', 'あまり + Vない / Aくない / Aな じゃない', 'Dùng để nói mức độ hay tần suất không cao; luôn đi với dạng phủ định.', 'Nhẹ nhàng, tế nhị hơn phủ định thẳng; hay dùng khi từ chối hoặc chê khéo.', 'Hay dùng あまり với câu khẳng định (sai: あまり好きです). Đừng nhầm với ぜんぜん〜ない là hoàn toàn không.', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-264c82053a', 'N5', 7, 338, 338, 'Gọi là gì nhỉ', '[]', 'Gọi là gì nhỉ', 'gọi là gì; nói thế nào (bằng tiếng …)', 'N + は + (ngôn ngữ) + で + 何と言いますか', 'Hỏi một từ trong ngôn ngữ khác gọi là gì: N は + ngôn ngữ + で + 何と言いますか (これは日本語で何と言いますか). と là trợ từ trích dẫn, ngôn ngữ đi với で. Hỏi cách đọc chữ thì dùng 何と読みますか.', 'Trung tính, rất hay dùng khi học ngoại ngữ.', 'Hay quên と (sai: 何言いますか) hoặc dùng を (sai: 何を言いますか với nghĩa hỏi tên gọi).', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-26c3235df7', 'N5', 12, 327, 327, '〜は〜より', '[]', 'は〜より', '… hơn …; so với …', 'N1 + は + N2 + より + A', 'Dùng để so sánh chủ đề N1 với N2, nói N1 hơn N2 về một mặt nào đó.', 'Trung tính; より đứng sau mốc so sánh.', 'Hay đặt より sau thứ hơn theo kiểu tiếng Việt; より luôn gắn sau thứ đem ra so.', '["JG-31bd9a3cc4"]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-26e3b52ff4', 'N5', 16, 149, 149, 'Adjて – Nối câu với tính từ い', '[]', 'Adjて – Nối câu với tính từ い', '… và …; vì … nên … (nối câu bằng tính từ い)', 'Aい bỏ い + くて、…', 'Aい bỏ い thêm くて để nối sang vế sau: 安くておいしい (rẻ và ngon). Cũng dùng để nêu lý do nhẹ cho cảm xúc, trạng thái: 頭が痛くて、休みました. Riêng いい → よくて. Trước câu nhờ vả, mệnh lệnh không dùng くて để nêu lý do mà dùng から.', 'Trung tính; nối các tính chất cùng chiều, hoặc nêu lý do nhẹ cho vế sau.', 'Hay viết 安いて hoặc 安いで; đúng là 安くて. いい đổi thành よくて.', '["JG-b2976be48a","JG-4bf259bc32","JG-72a02e9fe6"]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-27ad6cf551', 'N5', 13, 273, 273, 'N が ほしいです', '[]', 'N が ほしい', 'Nói muốn có thứ gì\nThứ mình muốn đi với が: あたらしい くるまが ほしいです.', 'N + が + ほしいです', 'ほしい nói về mình. Nói người khác muốn gì thì phải thêm cách nói khác, chưa học ở bài này.', 'Nói thẳng mong muốn của bản thân.', 'Hay dùng を (sai: 車をほしいです) hoặc dùng cho người thứ ba.', '["JG-b9ff41658f"]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-27ca66f6c8', 'N5', 15, 261, 261, '〜他動詞てある', '[]', '他動詞てある', 'Biểu thị trạng thái kết quả hành động của ai đó còn được lưu lại.', 'N + が + V(tha động từ)-て + ある (窓が開けてある)', 'Dùng để nói trạng thái đang thấy là kết quả của việc ai đó đã cố ý làm từ trước, thường là để chuẩn bị.', 'Nhấn vào kết quả còn lại và ý định của người làm, nhưng không nói ai làm.', 'Hay nhầm với tự động từ + ている: 窓が開いている chỉ tả trạng thái, 窓が開けてある ngầm có người cố ý mở. Với てある vật thường đi với が chứ không đi với を.', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-2839471ebc', 'N5', 9, 271, 271, 'Hoàn toàn không', '[]', 'Hoàn toàn không', 'hoàn toàn không; chẳng … chút nào', 'ぜんぜん + Vない / Aくない', 'ぜんぜん đứng trước động từ hay tính từ ở dạng phủ định: ぜんぜんわかりません, ぜんぜん高くないです. Mạnh hơn あまり〜ない (không … lắm). Ở N5 luôn dùng ぜんぜん với phủ định.', 'Mạnh, phủ định hoàn toàn.', 'Hay dùng ぜんぜん với câu khẳng định; ở N5 hãy luôn dùng với phủ định.', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-28af0261e7', 'N5', 6, 183, 183, 'N を V ます', '[]', 'N を V', 'Nói mình làm gì với vật gì\nVật bị tác động đứng trước を, rồi mới tới động từ: ごはんを たべます.', 'N + を + V-ます', 'Trợ từ を chỉ viết chữ を, nhưng đọc là お.', 'Trung tính; を luôn đứng ngay trước động từ chỉ hành động.', 'Hay dùng を với ある, 分かる, 好き (những từ này đi với が). を đọc là “o”.', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-28b044ef5f', 'N5', 17, 349, 349, '〜なくてはいけない', '[]', 'なくてはいけない', 'Biểu thị sự cần thiết hoặc là nghĩa vụ phải làm như thế.', 'Vない bỏ い + くてはいけない (いけません)', 'Dùng để nói một việc cần thiết hoặc bắt buộc phải làm.', 'Nghĩa gần như なければならない; hay dùng hơn khi nói chuyện.', 'Hay quên bỏ い (sai: 起きないくては).', '["JG-af79a30b59","JG-a08d454bb7"]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-294efa3571', 'N5', 13, 280, 280, 'なにが ほしいですか / なにを 〜たいですか', '[]', 'なにが ほしいですか / なにを 〜たいですか', 'Hỏi muốn gì, muốn làm gì\nHỏi vật thì なにが, hỏi việc thì なにを, hỏi nơi thì どこへ.', 'なにが + ほしいですか / なにを + V-ます bỏ ます + たいですか', 'Hỏi thẳng người trên rằng họ muốn gì nghe hơi sỗ — với sếp nên hỏi vòng hơn.', 'Trung tính; hỏi người trên thì nên tránh 〜たいですか.', 'Hay dùng なにを với ほしい (sai: なにをほしいですか); ほしい đi với が.', '["JG-c0e847d3fa","JG-a788659d89"]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-2a84407399', 'N5', 4, 206, 206, '〜ごろ', '[]', 'ごろ', 'Chỉ khoảng thời gian được giới hạn một cách đại khái', 'N(thời điểm) + ごろ', 'Đặt sau mốc thời gian (giờ, ngày, tháng) để nói thời điểm đó chỉ là khoảng chừng.', 'Trung tính; chỉ dùng cho thời điểm, không dùng cho lượng thời gian.', 'Hay dùng ごろ cho lượng thời gian (sai: 3時間ごろ); lượng thời gian phải dùng ぐらい: 3時間ぐらい.', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-2aad5619c3', 'N5', 3, 316, 316, 'Ở đâu', '[]', 'Ở đâu', 'ở đâu; chỗ nào; nơi nào', 'どこ + に・で・へ・から / どこの + N', 'どこ hỏi nơi chốn. Trợ từ đi theo động từ: どこにありますか / いますか (ở đâu), どこで + hành động (làm ở đâu), どこへ行きますか (đi đâu), どこから (từ đâu). どこの + N hỏi xuất xứ, hãng: どこの国, どこのカメラ.', 'Trung tính; どちら lịch sự hơn.', 'Hay dùng どこに khi hỏi nơi làm việc gì; phải dùng どこで.', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-2ba558d1c8', 'N5', 23, 107, 107, '時(とき)', '[]', '時(とき)', 'khi …; lúc … (thời điểm xảy ra việc ở vế sau)', 'Vる・Vた / Aい / Aな + な / N + の + とき', 'Dùng để nói vào lúc nào thì làm việc gì hoặc xảy ra việc gì.', 'Trung tính; thể từ điển chỉ lúc việc chưa xảy ra, thể た chỉ lúc việc đã xong.', 'Hay quên の với danh từ (sai: 子どもとき) hoặc な với tính từ な (sai: ひまとき); đúng là 子どものとき, ひまなとき.', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-2bcfe2ce46', 'N5', 3, 13, 13, '〜ね', '[]', 'ね', 'nhỉ; nhé (cuối câu để tìm sự đồng tình hoặc xác nhận lại)', 'Câu + ね', 'Đặt cuối câu khi muốn người nghe đồng ý với cảm nhận của mình, hoặc khi xác nhận lại một thông tin cả hai cùng biết.', 'Thân thiện, làm câu mềm hơn, giống “nhỉ”, “nhé” trong tiếng Việt; không mang ý báo tin mới.', 'Hay dùng ね khi báo cho người nghe điều họ chưa biết; trường hợp đó phải dùng よ. Thêm ね vào mọi câu cũng làm lời nói kém tự nhiên.', '[]', NULL, 'AI_CHECKED', 1, '3c5bc58917e7'),
('JG-2bed9c60a6', 'N5', 8, 371, 371, '〜どんな', '[]', 'どんな', '… như thế nào; loại … nào', 'どんな + N', 'Dùng để hỏi về loại, kiểu hoặc tính chất của người, vật, sự việc.', 'Trung tính.', 'Hay dùng どう trước danh từ (sai: どう本).', '["JG-9da239be95"]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-2c477bb863', 'N5', 7, 184, 184, 'V ましょう', '[]', 'V ましょう', 'Chốt lại: cùng làm thôi\nDùng khi cả hai đã đồng ý, chốt việc sẽ làm.', 'V-ます bỏ ます + ましょう', 'ませんか là hỏi ý, ましょう là đã thống nhất rồi.', 'Chủ động, thân thiện; dùng khi cả hai đã đồng ý với nhau.', 'Hay dùng để mời ngay từ đầu khi chưa biết ý người kia; lúc đó nên hỏi bằng ませんか trước.', '["JG-5ab8fbc241","JG-38e03685b6","JG-77640b61e7"]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-2e129556cf', 'N5', 9, 51, 51, 'が有(あ)る', '[]', 'が有(あ)る', 'có (đồ vật hoặc sự việc không có sự sống)', 'N(nơi chốn) + に + N + が + ある (あります)', 'Dùng để nói ở đâu có đồ vật gì, hoặc mình có thứ gì, có việc gì (có thời gian, có bài kiểm tra).', 'Trung tính; lịch sự là あります, phủ định là ない hoặc ありません.', 'Hay dùng ある cho người và con vật (sai: 犬があります); người, động vật phải dùng いる. Phủ định thân mật của ある là ない, không phải あらない.', '[]', NULL, 'AI_CHECKED', 1, '3c5bc58917e7'),
('JG-2e4c8d4494', 'N5', 2, 136, 136, 'この/その/あの N は ...', '[]', 'この/その/あの N は ...', '… này; … đó; … kia (đứng trước danh từ để chỉ đồ vật)', 'この・その・あの + N + は + …です', 'Đặt この, その, あの ngay trước danh từ để vừa chỉ vừa gọi tên đồ vật; chọn theo khoảng cách như これ, それ, あれ: この本 (gần mình), その本 (gần người nghe), あの本 (xa cả hai).', 'Trung tính; chọn この, その, あの theo khoảng cách giống như これ, それ, あれ.', 'Hay dùng これ + danh từ (sai: これ本は) hoặc để この đứng một mình. この, その, あの bắt buộc có danh từ theo sau.', '["JG-223df589a9"]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-2ee7b1e330', 'N5', 20, 227, 227, 'Tuy nhiên...', '[]', 'Tuy nhiên...', 'tuy nhiên; nhưng', 'Câu 1。けれども、Câu 2 / Câu 1 + けれども、Câu 2', 'Đặt けれども ở đầu câu sau để nói ý trái với câu trước: 安いです。けれども、遠いです. Cũng có thể gắn cuối vế trước: 安いですけれども、遠いです. Lịch sự hơn けど, mềm hơn しかし; hai vế phải thật sự trái ngược.', 'Lịch sự hơn けど, mềm hơn しかし.', 'Hay dùng けれども khi hai vế không hề trái ngược nhau; muốn nối ý thêm thì dùng そして.', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-30023f2c1d', 'N5', 5, 168, 168, 'N と いきます', '[]', 'N と いき', 'Nói đi với ai\nNgười đi cùng đứng trước と; đi một mình thì nói ひとりで, không dùng と.', 'N(người) + と + 行きます / 一人で + 行きます', 'Hỏi ai đi cùng thì だれと いきますか.', 'Trung tính; と chỉ người cùng đi.', 'Đi một mình hay nói nhầm 一人と; đúng là 一人で. Hỏi “đi với ai” là だれと行きますか.', '["JG-25a1d2bbc3"]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-315e3a8560', 'N5', 15, 81, 81, '〜てもいい (Verb)', '[]', 'てもいい (Verb)', '… cũng được (cho phép hoặc xin phép)', 'V-て + もいい(です) / V-て + もいいですか', 'Dùng để cho phép người khác làm gì; thêm か ở cuối để xin phép.', 'Lịch sự vừa phải; xin phép người trên bằng 〜てもいいですか là đủ lịch sự ở trình độ N5.', 'Hay dùng thể từ điển (sai: 座るもいいです); phải dùng thể て: 座ってもいいです. Khi từ chối, tránh nói thẳng だめです với người trên, nên nói すみません、ちょっと….', '["JG-9d12efd7d2","JG-a412adf097","JG-cce238d8ca"]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-31ab3fdc1d', 'N5', 24, 109, 109, '〜てあげる', '[]', 'てあげる', 'làm … cho (người khác)', 'N(người được giúp) + に + V-て + あげる', 'Dùng khi người nói hoặc ai đó làm một việc có ích cho người khác.', 'Có thể nghe như kể công; nói trực tiếp với người trên (先生、持ってあげます) là thất lễ, nên dùng 〜ましょうか.', 'Hay dùng khi người khác làm cho mình; trường hợp đó phải dùng 〜てくれる. Khi việc giúp tác động lên đồ của người kia thì dùng の: 母の荷物を持ってあげます.', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-31bd9a3cc4', 'N5', 12, 259, 259, 'N1 は N2 より Aです / N1 の ほうが Aです', '[]', 'N1 は N2 より Aです / N1 の ほうが A', 'Nói cái này hơn cái kia\nThứ được cho là hơn đứng đầu câu, thứ đem ra so đứng trước より.', 'N1 + は + N2 + より + A です / N1 + のほうが + A です', 'より đứng SAU thứ bị so — ngược với tiếng Việt nói "hơn" ở giữa.', 'Trung tính; のほうが nhấn mạnh thứ được chọn.', 'Hay đặt より sau thứ hơn hoặc quên の trước ほう.', '["JG-26c3235df7"]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-322570640d', 'N5', 8, 211, 211, 'N は Aな です', '[]', 'N は Aな', 'Khen chê bằng tính từ đuôi な\nLoại này rụng な khi đứng cuối câu: しずかな → へやは しずかです.', 'N + は + Aな bỏ な + です', 'きれい và ゆうめい tuy kết thúc bằng い nhưng thuộc loại な — học thuộc riêng.', 'Lịch sự; tính từ な đứng cuối câu thì bỏ な.', 'Hay giữ な ở cuối câu (sai: 静かなです).', '["JG-aee65c5570","JG-d61be94fc2","JG-fc410c25b4"]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-3246983f8f', 'N5', 16, 356, 356, 'Bằng cách nào', '[]', 'Bằng cách nào', 'bằng cách nào; làm thế nào', 'どうやって + V + か', 'どうやって + động từ hỏi cách làm, cách đi: どうやって行きますか, どうやって使いますか. Trả lời bằng cách thức: バスで行きます, 歩いて行きます. Hỏi chung "thấy thế nào" thì dùng どう.', 'Hỏi quy trình, phương tiện hoặc cách thức.', 'Hay dùng どう thay cho どうやって khi hỏi cách làm.', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-326a048921', 'N5', 12, 257, 257, 'N の なかで N が いちばん Aです', '[]', 'N の なかで N が いちばん A', 'Nói cái nào nhất trong nhóm\nNhóm đứng trước なかで, thứ đứng nhất đi với が: くだものの なかで りんごが いちばん おいしいです.', 'N(nhóm) + の中で + N + が + いちばん + A + です', 'Nhóm là nơi chốn thì bỏ なか, chỉ cần で: クラスで いちばん.', 'Trung tính.', 'Hay dùng は thay が sau thứ đứng nhất, hoặc quên で sau の中.', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-32a5b094ae', 'N5', 3, 14, 14, '〜よ', '[]', 'よ', 'đấy; đó (cuối câu để báo điều người nghe chưa biết hoặc nhấn mạnh ý mình)', 'Câu + よ', 'Đặt cuối câu khi muốn cho người nghe biết một thông tin mới, hoặc khi khuyên nhủ, nhắc nhở.', 'Mang tính khẳng định, giống “đấy”, “đó” trong tiếng Việt; dùng quá nhiều với người trên dễ nghe như lên lớp.', 'Hay nhầm với ね: よ là mình báo điều người nghe chưa biết, ね là mong người nghe đồng tình. Nói よ mạnh giọng với người lớn tuổi dễ bị coi là thiếu lễ phép.', '[]', NULL, 'AI_CHECKED', 1, '3c5bc58917e7'),
('JG-32d156182e', 'N5', 3, 141, 141, 'こちら/そちら/あちら は N です', '[]', 'こちら/そちら/あちら は N', 'Nói chỗ theo lối lịch sự\nDùng khi tiếp khách, nói với người trên, hoặc khi mình là người của cửa hàng.', 'こちら・そちら・あちら + は + N + です', 'Cùng nghĩa với ここ／そこ／あそこ nhưng nghe trang trọng hơn hẳn.', 'Lịch sự hơn ここ, そこ, あそこ; こちら còn dùng để giới thiệu người.', 'Hay dùng これ để giới thiệu người với người khác; lịch sự phải nói こちらは〜さんです.', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-33b8b7d970', 'N5', 12, 205, 205, '〜がいちばん', '[]', 'がいちばん', 'Biểu thị mức độ cao nhất trong một vài đồ vật.', '(N の中で) + N + が + いちばん + A', 'Dùng để nói trong một nhóm thì người, vật nào là nhất về một mặt nào đó.', 'Trung tính; いちばん đứng ngay trước tính từ hoặc động từ.', 'Khi trả lời câu hỏi “cái nào nhất” hay dùng は (sai: りんごはいちばん好きです); phải dùng が. Không dùng より chung với いちばん.', '["JG-f67982a10e"]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-352c73f66e', 'N5', 1, 319, 319, 'Vị nào (lịch sự)', '[]', 'Vị nào (lịch sự)', 'ai (lịch sự); vị nào', 'N + は + どなたですか / どなた + が・の …', 'どなた là cách nói lịch sự của だれ, dùng với khách, người lạ, người trên: あの方はどなたですか. Đi với trợ từ giống だれ: どなたが, どなたに, どなたの + N. どなたか = vị nào đó, どなたでも = vị nào cũng.', 'Lịch sự hơn だれ; dùng với khách, người lạ, người trên.', 'Hay dùng だれ với khách hàng hay người trên, nghe thiếu lịch sự.', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-364904155e', 'N5', 2, 7, 7, 'これ', '[]', 'これ', 'cái này (đồ vật ở gần người nói)', 'これ + は + N + です', 'Dùng để chỉ đồ vật ở gần mình (đang cầm, đang ở trước mặt mình) mà không cần nêu tên vật đó.', 'Dùng cho đồ vật; khi giới thiệu người thì lịch sự là dùng こちら.', 'Không đặt danh từ ngay sau これ (sai: これ本は…); muốn kèm danh từ thì dùng この本. Cũng không dùng これ để chỉ người đang đứng trước mặt.', '["JG-1faa5326a0"]', NULL, 'AI_CHECKED', 1, '3c5bc58917e7'),
('JG-36665dbce6', 'N5', 9, 218, 218, 'N が じょうず/へたです', '[]', 'N が じょうず/へた', 'Nói giỏi hay kém việc gì\nCũng đi với が: ギターが じょうずです.', 'N + が + じょうず・へた + です', 'Người Nhật ít tự khen mình じょうず — nói về mình thì dùng すき hoặc ちょっと できます cho khiêm tốn.', 'じょうず dùng để khen người khác; nói về mình nên khiêm tốn, dùng まだへたです.', 'Hay dùng を (sai: 料理をじょうずです), và hay tự khen mình bằng じょうず, nghe thiếu khiêm tốn.', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-36c7185f86', 'N5', 1, 3, 3, '〜です', '["です"]', 'です', 'là (kết thúc câu danh từ một cách lịch sự)', 'N + です', 'Đặt ở cuối câu danh từ để nói “là …” một cách lịch sự. Dùng khi giới thiệu bản thân, nói nghề nghiệp, quốc tịch hoặc gọi tên đồ vật.', 'Lịch sự, dùng với người mới quen và người trên; nói thân mật thì thay bằng だ hoặc bỏ hẳn.', 'Người Việt hay đặt “là” vào giữa câu theo thói quen tiếng Việt; です luôn đứng cuối câu. Sau động từ đuôi ます không thêm です (sai: 行きますです).', '["JG-fcc3af75f6"]', NULL, 'AI_CHECKED', 1, '3c5bc58917e7'),
('JG-374aef0ff3', 'N5', 4, 127, 127, 'Nơi chốn, thời điểm, mục đích', '[]', 'Nơi chốn, thời điểm, mục đích', 'lúc (thời điểm cụ thể); ở (nơi tồn tại); để (mục đích khi đi lại)', 'N(nơi chốn) + に + ある・いる / N(thời điểm) + に + V / V-ます bỏ ます + に + 行く', 'に chỉ một điểm cụ thể: mốc thời gian có số (七時に起きます, 日曜日に), nơi người hoặc vật tồn tại (机の上に本があります), mục đích khi đi lại (買い物に行きます). に còn chỉ người nhận (友だちに手紙を書きます) và kết quả thay đổi (先生になります). Các từ thời gian tương đối như 今日, 明日, 毎日 không đi với に.', 'Trung tính; に chỉ một điểm cụ thể: điểm đến, chỗ tồn tại hoặc mốc thời gian.', 'Hay gắn に sau các từ thời gian tương đối như 今日, 明日, 毎日 (sai: 明日に行きます); những từ này không cần に. Thứ, ngày, giờ cụ thể thì cần に: 7時に.', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-377d5ee6df', 'N5', 4, 390, 390, '〜から・〜まで', '[]', 'から・〜まで', 'từ … đến …', 'N1 + から + N2 + まで', 'Dùng để nói phạm vi về thời gian, không gian hoặc số lượng: từ … đến ….', 'Trung tính.', 'Hay nhầm まで (đến lúc đó) với までに (trước hạn đó).', '["JG-9985533827","JG-ae13357418"]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-38e03685b6', 'N5', 7, 36, 36, '〜ましょうか', '[]', 'ましょうか', 'để tôi … nhé? (đề nghị làm giúp người nghe)', 'V-ます bỏ ます + ましょうか', 'Dùng khi muốn ngỏ ý làm giúp người nghe (Để tôi … nhé?), hoặc khi hỏi ý người nghe để cùng quyết định.', 'Lịch sự, chu đáo, để người nghe quyết định có nhận sự giúp đỡ hay không.', 'Hay nhầm với ませんか: ましょうか là mình làm cho người kia, ませんか là rủ người kia cùng làm. Nhận lời thì đáp ええ、お願いします.', '["JG-5ab8fbc241","JG-2c477bb863","JG-77640b61e7"]', NULL, 'AI_CHECKED', 1, '3c5bc58917e7'),
('JG-3976c1fc65', 'N5', 17, 89, 89, '〜たら', '["たら"]', 'たら', 'nếu … thì; khi … xong thì', 'Vた + ら / Aい bỏ い + かったら / Aな・N + だったら', 'Gắn ら vào thể た để nêu điều kiện hoặc mốc: khi (hoặc nếu) việc ở vế trước xảy ra thì làm việc ở vế sau: 駅に着いたら、電話してください (đến ga thì gọi điện nhé). Tính từ い: 安かったら; tính từ な và danh từ: ひまだったら, 雨だったら.', 'Trung tính, rất hay dùng trong hội thoại; vế sau có thể là mong muốn, lời nhờ hay lời rủ.', 'Hay ghép ら vào gốc ます (sai: 行きたら); phải dựa trên thể た: 行ったら. Người Việt cũng hay chỉ thêm もし mà quên ら ở cuối vế điều kiện.', '["JG-bff0e28443","JG-f539f37a62"]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-3981bfcd17', 'N5', 1, 116, 116, 'N1 は N2 じゃ ありません', '[]', 'N1 は N2 じゃ ありません', 'không phải là (N1 không phải là N2)', 'N1 + は + N2 + じゃありません (ではありません)', 'Phủ định của N1はN2です: thay です bằng じゃありません: 私は先生じゃありません. Khi nói hằng ngày dùng じゃありません, khi viết hoặc dịp trang trọng dùng ではありません.', 'じゃありません dùng khi nói, ではありません trang trọng hơn khi viết; じゃないです là cách nói mềm hơn.', 'Hay nói じゃないありません hoặc じゃありませんです; dạng đúng chỉ là じゃありません. Người Việt cũng hay quên は sau N1.', '["JG-71edb25a43","JG-45fa70fbca"]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-39f20e102c', 'N5', 21, 369, 369, 'どう おもいますか / なんと いいましたか', '[]', 'どう おもいますか / なんと いいましたか', 'Hỏi ý nghĩ, hỏi lời người khác\nHỏi ý kiến thì どう おもいますか, hỏi người ta nói gì thì なんと いいましたか.', 'N + を + どう思いますか / N + は + 何と言いましたか', 'Hỏi ý kiến: N を どう思いますか (この町をどう思いますか); trả lời 〜と思います. Hỏi người khác đã nói gì: N は何と言いましたか; trả lời 〜と言いました.', 'Trung tính; dùng để hỏi ý kiến hoặc hỏi người khác đã nói gì.', 'Hay hỏi どんな思いますか; hỏi ý kiến phải dùng どう思いますか.', '["JG-9b200447f7","JG-d5f6d866ef","JG-171c3a58eb"]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-3a44727b3b', 'N5', 16, 237, 237, '〜かた', '[]', 'かた', 'Hậu tố chỉ phương pháp để tiến hành một hành động nào đó.', 'V-ます bỏ ます + かた (使い方, 作り方)', 'Vます bỏ ます + かた tạo danh từ "cách làm": 読みます → 読み方 (cách đọc), 使います → 使い方 (cách dùng). Vì là danh từ nên đối tượng đi với の: 漢字の読み方, カメラの使い方; hay đi với 教えてください, わかりません.', 'Trung tính; tạo thành danh từ nên đi với の: 漢字の読み方.', 'Hay dùng を trước かた (sai: 漢字を読み方); phải dùng の: 漢字の読み方.', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-3b2e79bc71', 'N5', 2, 6, 6, '〜の', '["〜のだ"]', 'の', 'của (nối hai danh từ); cái của … (thay cho danh từ đã rõ)', 'N1 + の + N2 / N + の (thay cho danh từ đã rõ)', 'Đặt の giữa hai danh từ: danh từ trước bổ nghĩa cho danh từ sau (sở hữu, xuất xứ, nội dung): 私の本, 日本の車, 日本語の本. Khi danh từ sau đã rõ thì bỏ đi, chỉ giữ N の: これは私のです (cái này là của tôi).', 'Trung tính; khi danh từ phía sau đã rõ thì có thể bỏ đi và chỉ để lại の với nghĩa “cái của …”.', 'Hay đảo thứ tự theo tiếng Việt “sách của tôi” thành 本の私; đúng là 私の本, người sở hữu luôn đứng trước の.', '[]', NULL, 'AI_CHECKED', 1, '3c5bc58917e7'),
('JG-3b32c0a804', 'N5', 2, 9, 9, 'あれ', '[]', 'あれ', 'cái kia (đồ vật ở xa cả người nói lẫn người nghe)', 'あれ + は + N + です', 'Dùng để chỉ đồ vật ở xa cả hai người, ví dụ tòa nhà hay chiếc xe ở phía xa.', 'Trung tính; trong hội thoại あれ còn chỉ chuyện mà cả hai cùng biết từ trước.', 'Hay nhầm あれ với それ khi vật ở hơi xa; chỉ dùng あれ khi vật xa cả mình lẫn người nghe. Muốn kèm danh từ thì dùng あの.', '[]', NULL, 'AI_CHECKED', 1, '3c5bc58917e7'),
('JG-3b896a5cec', 'N5', 19, 384, 384, 'Liệt kê hành động', '[]', 'Liệt kê hành động', 'lúc thì … lúc thì …; làm những việc như …', 'V1た + り、V2た + り + する', 'V1た + り、V2た + り + します: kể vài việc tiêu biểu (không phải tất cả), không theo thứ tự. Thì của câu đặt ở します / しました cuối câu: 週末は映画を見たり、友だちと遊んだりします.', 'Trung tính; kể vài việc tiêu biểu, không phải tất cả.', 'Hay quên する ở cuối mẫu (見たり、遊んだり。✗ → 見たり、遊んだりします) hoặc dùng thể て trước り (見てり ✗).', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-3e35ef8495', 'N5', 13, 336, 336, 'Cái gì cũng', '[]', 'Cái gì cũng', 'cái gì cũng; bất cứ cái gì', 'なんでも + V / なんでも + A', 'なんでも + câu khẳng định: cái gì cũng … (なんでも食べます, なんでも知っています). なんでもいいです = gì cũng được. Riêng なんでもないです là cụm cố định = không có gì đâu. "Không … gì cả" thì dùng 何も + phủ định.', 'Bao trùm mọi thứ, thường đi với khẳng định.', 'Hay nhầm với 何も + phủ định: なんでも食べます (ăn gì cũng được) khác 何も食べません (không ăn gì).', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-3ebc789296', 'N5', 14, 195, 195, 'Đang, thói quen', '[]', 'Đang, thói quen', 'đang …; thói quen (thường làm)', 'V-て + います', 'V-て + います nói việc đang diễn ra lúc nói (今、手紙を書いています) hoặc việc làm đều đặn trong một thời gian (毎朝、新聞を読んでいます). Câu hỏi "đang làm gì?" là 何をしていますか. Câu chỉ có 〜ます thì là thói quen hoặc việc sẽ làm, không phải "đang".', 'Trung tính; vừa chỉ việc đang diễn ra, vừa chỉ thói quen lặp lại.', 'Hay dùng 〜ます cho việc đang diễn ra (sai: 今テレビを見ます với nghĩa đang xem).', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-41469914b4', 'N5', 4, 158, 158, 'N の N (giờ của việc)', '[]', 'N の N (giờ của việc)', 'Gắn giờ giấc với việc\nきんようびの よる là tối thứ sáu, ごごの かいぎ là cuộc họp buổi chiều.', 'N(thời gian) + の + N(sự việc)', 'Thứ tự là cái lớn trước cái nhỏ sau: thứ rồi mới tới buổi.', 'Trung tính; danh từ thời gian đứng trước の để nói việc đó diễn ra vào lúc nào.', 'Hay đảo thứ tự theo tiếng Việt “cuộc họp buổi chiều” thành 会議の午後; đúng là 午後の会議.', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-41595b514a', 'N5', 14, 285, 285, 'V-て ください', '["V-て くださいます"]', 'V-て ください', 'Nhờ người khác làm giúp\nĐộng từ chuyển sang đuôi て rồi thêm ください: まちます → まって ください.', 'V-て + ください', 'Đây là câu nhờ lịch sự nhưng vẫn là câu sai bảo — với người trên nên mở đầu bằng すみませんが.', 'Lịch sự; muốn nhẹ nhàng hơn thì dùng 〜てくださいませんか.', 'Hay chia sai thể て của nhóm I (待ちます → 待って, không phải 待ちて).', '["JG-a96e6873a8","JG-8e21283b46","JG-b4ac2012bf"]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-41b9467416', 'N5', 5, 30, 30, '来(く)る', '[]', '来(く)る', 'đến; tới (di chuyển về phía người nói)', 'N(nơi chốn) + へ・に + 来る (来ます・来ない・来た)', 'Dùng khi ai đó di chuyển về phía chỗ người nói đang ở, ví dụ bạn đến nhà mình.', 'Trung tính; hướng về phía người nói, ngược với 行く là đi ra xa.', 'Người Việt hay nói “tôi đến chỗ bạn” bằng 来る; tiếng Nhật lúc đó dùng 行く. 来る chia bất quy tắc: 来ない đọc là こない, 来た đọc là きた.', '[]', NULL, 'AI_CHECKED', 1, '3c5bc58917e7'),
('JG-4275662606', 'N5', 4, 28, 28, '〜と', '["と"]', 'と', 'và (nối danh từ với danh từ)', 'N1 + と + N2', 'Đặt と giữa các danh từ để liệt kê đầy đủ: パンと牛乳 (bánh mì và sữa). Trợ từ của cả cụm đứng sau danh từ cuối: 本とノートがあります. と chỉ nối danh từ, không nối động từ hay tính từ.', 'Trung tính; liệt kê đầy đủ, ngầm hiểu chỉ có đúng những thứ được nêu.', 'Không dùng と để nối hai động từ hay hai câu như chữ “và” trong tiếng Việt (sai: 食べますと飲みます); と chỉ nối danh từ với danh từ.', '[]', NULL, 'AI_CHECKED', 1, '3c5bc58917e7'),
('JG-42bc2d09e3', 'N5', 5, 153, 153, 'Đi đến...', '[]', 'Đi đến...', 'đi; đi đến (nơi nào đó để làm gì)', 'N(nơi chốn) + へ・に + 行きます / V-ます bỏ ます + に + 行きます', 'Nơi đến + へ/に + 行きます: 学校へ行きます. Đi để làm gì: Vます bỏ ます + に + 行きます (見に行きます) hoặc danh từ hoạt động + に (買い物に行きます). Dùng khi đi ra xa chỗ người nói.', 'Trung tính; hướng đi ra xa người nói.', 'Hay dùng を với nơi đến (sai: 学校を行きます). Thể て và た của 行く là ngoại lệ: 行って, 行った.', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-449cdc24f6', 'N5', 13, 310, 310, 'Bất kỳ cái nào', '[]', 'Bất kỳ cái nào', 'cái nào cũng; bất kỳ cái nào', 'どれでも + いい・V', 'どれでも dùng khi chọn trong một số thứ đang có: cái nào cũng được (どれでもいいです). Có danh từ theo sau thì nói どの + N + でも (どの色でもいいです). Nói về người dùng だれでも, về nơi chốn dùng どこでも.', 'Không phân biệt giữa các lựa chọn đang có.', 'Hay nhầm với どれも + phủ định (cái nào cũng không).', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-44aa9cb2be', 'N5', 10, 124, 124, 'Có (vật, địa điểm)', '[]', 'Có (vật, địa điểm)', 'có; ở (あります cho đồ vật và います cho người hoặc động vật)', 'N(nơi chốn) + に + N + が + あります・います', 'Nói ở đâu có gì: [nơi chốn] に [vật hoặc người] が あります／います. あります dùng cho đồ vật, cây cối, sự kiện; います dùng cho người và động vật. Hỏi vị trí của thứ đã biết: 〜はどこにありますか (người: どこにいますか).', 'Trung tính; あります dùng cho đồ vật, sự kiện, います dùng cho người và con vật.', 'Hay dùng あります cho người hay con vật. Khi nói vị trí của một vật đã biết thì đổi trật tự: 本は机の上にあります.', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-44d752abd1', 'N5', 8, 44, 44, 'な-Adjective + だ (Predicate)', '[]', 'な-Adjective + だ (Predicate)', 'tính từ な + だ làm vị ngữ (lối nói thân mật)', 'N + は + Aな bỏ な + だ (静かだ)', 'Dùng khi nói chuyện thân mật hoặc khi viết nhật ký để nói người, vật có tính chất gì.', 'Thân mật hoặc văn viết trung tính; lịch sự thì thay だ bằng です.', 'Hay nói 静かなだ; đúng là 静かだ, không giữ な. Câu hỏi thân mật không dùng だか, chỉ cần lên giọng: 静か？', '[]', NULL, 'AI_CHECKED', 1, '3c5bc58917e7'),
('JG-44ec000d19', 'N5', 20, 352, 352, 'V た / A かった / N だった', '[]', 'V た / A かった / N だった', 'Nói thân mật về chuyện đã qua\nĐộng từ dùng đuôi た; tính từ đuôi い thành かった; danh từ thành だった.', 'Vた / Aい bỏ い + かった / Aな・N + だった', 'でした thân mật hoá thành だった, không phải でした trơn bỏ đuôi.', 'Thân mật; dùng với bạn bè, người nhà.', 'Hay dùng だった cho tính từ い (sai: おもしろいだった); đúng là おもしろかった.', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-4547ba63f0', 'N5', 7, 192, 192, 'だれに 〜ますか / なにを 〜ますか', '[]', 'だれに 〜ますか / なにを 〜ますか', 'Hỏi cho ai, hỏi nhận gì\nHỏi người thì thay chỗ người bằng だれ, hỏi vật thì thay bằng なに, phần còn lại giữ nguyên.', 'だれに + V-ますか / なにを + V-ますか', 'Hỏi người nhận là だれに, hỏi người sở hữu là だれの — đừng lẫn hai cái.', 'Trung tính; giữ nguyên trợ từ như câu khẳng định, chỉ thay chỗ bằng từ để hỏi.', 'Hay quên trợ từ に sau だれ (sai: だれあげますか).', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-45fa70fbca', 'N5', 4, 160, 160, 'N は 〜じ 〜ふん です', '[]', 'N は 〜じ 〜ふん', 'Nói giờ\nGiờ đứng trước, phút đứng sau, đọc liền một mạch: しちじ じゅっぷん.', 'N + は + 〜時 + 〜分 + です', 'Rưỡi thì nói はん thay cho さんじゅっぷん, nghe tự nhiên hơn.', 'Trung tính; 30 phút thường nói là 半 (はん).', 'Hay đọc sai số phút: いっぷん (1 phút), さんぷん (3 phút), じゅっぷん (10 phút). Giờ cũng có cách đọc riêng: よじ (4 giờ), しちじ (7 giờ), くじ (9 giờ).', '["JG-3981bfcd17","JG-71edb25a43"]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-461391b18a', 'N5', 8, 46, 46, 'な-Adjective + (Noun)', '[]', 'な-Adjective + (Noun)', 'tính từ な đứng trước danh từ (giữ な để nối)', 'Aな + N (静か + な + 町 → 静かな町)', 'Dùng khi đặt tính từ な ngay trước danh từ để miêu tả danh từ đó.', 'Trung tính; な là cầu nối bắt buộc giữa tính từ và danh từ.', 'Hay bỏ な (sai: 有名店) hoặc dùng の (sai: 静かの町). 好き, 嫌い đứng trước danh từ cũng phải có な: 好きな食べ物.', '[]', NULL, 'AI_CHECKED', 1, '3c5bc58917e7'),
('JG-48b0a20a91', 'N5', 16, 247, 247, 'Cấu trúc mô tả đặc điểm', '[]', 'Cấu trúc mô tả đặc điểm', 'tả đặc điểm của người hay vật; chủ đề thì có bộ phận như thế nào', 'N1 + は + N2 + が + A', 'N1 は N2 が A: N1 là chủ đề, N2 là bộ phận hay mặt được tả: 姉は髪が長いです (chị tôi tóc dài), この町は公園が多いです. Hay dùng với cơ thể (背が高い, 目が大きい) và với 好き, 上手 (私は猫が好きです).', 'N1 là chủ đề, N2 là bộ phận hay đặc điểm được miêu tả.', 'Hay dùng hai は hoặc bỏ が (sai: 姉は髪は長いです khi chỉ muốn tả); khi miêu tả đặc điểm của N1 hãy dùng N1はN2が〜.', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-4974e22f04', 'N5', 6, 339, 339, 'Không gì cả', '[]', 'Không gì cả', 'không … gì cả', '何も + Vない / Vません', '何も + phủ định = không … gì cả: 何も食べません, 何もありません. Không thêm を hay が sau 何も. Không dùng với câu khẳng định.', 'Phủ định hoàn toàn về sự vật.', 'Hay dùng 何も với khẳng định (sai: 何も食べました).', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-4a1beb4a86', 'N5', 8, 209, 209, 'Aい N / Aな N', '[]', 'Aい N / Aな N', 'Đặt lời khen ngay trước danh từ\nĐứng trước danh từ thì đuôi い giữ nguyên, còn loại な phải trả lại な: たかい やま · ゆうめいな やま.', 'Aい + N / Aな + な + N', 'Đây là chỗ hay quên な nhất, vì khi đứng cuối câu thì lại không có な.', 'Trung tính; tính từ đứng trước danh từ để miêu tả.', 'Hay quên な với tính từ な (sai: 有名レストラン) hoặc thêm な cho tính từ い (sai: 高いな山).', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-4bf259bc32', 'N5', 15, 83, 83, '〜ている 2', '[]', 'ている 2', 'đang ở trạng thái … (kết quả của hành động vẫn còn kéo dài)', 'V-て + いる (結婚している, 住んでいる, 知っている)', 'Dùng với các động từ chỉ sự thay đổi như kết hôn, sống ở, biết, mở, đóng để nói trạng thái sau khi việc đó xảy ra vẫn còn.', 'Trung tính; không phải đang làm dở mà là tình trạng đang được duy trì.', 'Người Việt hay nói 結婚しました để nói “tôi đã có gia đình”; câu đó chỉ kể việc đã cưới, nói tình trạng phải là 結婚しています. Phủ định của 知っています là 知りません, không phải 知っていません.', '["JG-b2976be48a","JG-72a02e9fe6","JG-26e3b52ff4"]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-4cf620a411', 'N5', 11, 241, 241, 'N を 〜つ ください', '[]', 'N を 〜つ ください', 'Xin bao nhiêu cái\nSố đếm đứng SAU tên vật, không đứng trước: りんごを ふたつ ください.', 'N + を + số (〜つ) + ください', 'Dãy ひとつ・ふたつ・みっつ dùng cho vật chung chung, đếm tới とお (mười) thì hết.', 'Lịch sự, dùng khi mua hàng hoặc gọi món.', 'Người Việt hay đặt số trước tên vật như “hai quả táo” (sai: 二つりんごをください); số đếm đứng sau を: りんごを二つください. Từ 10 trở lên không dùng 〜つ nữa.', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-4d02b61077', 'N5', 2, 334, 334, 'Cái gì', '[]', 'Cái gì', 'cái gì; gì', '何 + を・が・に … (đọc なに) / 何 + です・の・đơn vị đếm (đọc なん)', '何 hỏi vật, việc. Đọc なに trước を, が (何を食べますか, 何がありますか); đọc なん trước です, の và đơn vị đếm (何ですか, 何の本, 何時, 何人). 何の + N hỏi N thuộc loại gì, về cái gì.', 'Trung tính.', 'Hay đọc sai なに và なん: trước です, の và đơn vị đếm thì đọc なん.', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-4f00564020', 'N5', 5, 128, 128, 'Nơi diễn ra hành động, phương tiện', '[]', 'Nơi diễn ra hành động, phương tiện', 'ở (nơi diễn ra hành động); bằng (phương tiện hoặc công cụ)', 'N(nơi chốn) + で + V / N(phương tiện, công cụ) + で + V', 'Đặt で sau danh từ nơi chốn để chỉ chỗ hành động diễn ra (家で勉強します), hoặc sau phương tiện, công cụ, ngôn ngữ để chỉ cách làm (バスで, はしで, 日本語で). で còn chỉ nguyên nhân (かぜで休みました), số người cùng làm (三人で) và khoảng thời gian, giá cả (一時間で, 三つで五百円).', 'Trung tính; で chỉ chỗ hành động diễn ra hoặc cách thức, công cụ để làm.', 'Hay dùng に cho nơi diễn ra hành động (sai: 公園に遊びます); nơi làm việc gì phải dùng で. Đi bộ thì nói 歩いて, không nói 足で.', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-4f10b05b40', 'N5', 19, 344, 344, '〜た ことが ありますか / なにを したり しますか', '[]', 'た ことが ありますか / なにを したり しますか', 'Hỏi từng làm chưa, hỏi hay làm gì\nThêm か vào cuối như thường.', 'Vた + ことがありますか / なにを + したり + しますか', 'Đáp chưa từng thì nên nói thêm một câu (まだです、こんど いきたいです) cho đỡ cụt.', 'Trung tính; hỏi về trải nghiệm hoặc những việc hay làm.', 'Trả lời “chưa từng” hay nói いいえ、しませんでした; đúng là いいえ、〜たことがありません.', '["JG-788cfc687d","JG-15239d5b3e","JG-afacd1b137"]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-4f77fc0d0b', 'N5', 23, 253, 253, '〜が+自動詞', '[]', 'が+自動詞', 'Tự động từ: Động từ không đòi hỏi bổ ngữ (đi với「～を」).', 'N + が + tự động từ (開く, 閉まる, つく, 消える)', 'Dùng để miêu tả sự việc tự xảy ra hoặc trạng thái thay đổi mà không nói ai làm.', 'Khách quan, nhấn vào sự thay đổi của vật.', 'Hay dùng を với tự động từ (sai: ドアを開きます); tự động từ đi với が: ドアが開きます.', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-502bf03194', 'N5', 1, 117, 117, 'N1 は N2 です', '[]', 'N1 は N2', 'là (N1 là N2)', 'N1 + は + N2 + です', 'Câu khẳng định cơ bản: N1 là thứ đang nói tới (chủ đề, đánh dấu bằng は), N2 là điều muốn nói về nó, です ở cuối làm câu lịch sự: 私は学生です. は ở vị trí này đọc là “wa”.', 'Lịch sự, dùng khi giới thiệu bản thân hoặc nói với người mới gặp.', 'Người Việt hay đọc は là “ha”; khi làm trợ từ phải đọc là “wa”. Cũng hay bỏ quên です ở cuối, khiến câu cụt và thiếu lịch sự.', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-520ce6127b', 'N5', 11, 62, 62, '〜だけ', '["だけ"]', 'だけ', 'chỉ; chỉ có (giới hạn ở bấy nhiêu)', 'N / số lượng + だけ', 'Đặt だけ ngay sau danh từ hoặc số lượng để giới hạn, chỉ có thế chứ không hơn: 一つだけあります (chỉ có một cái), コーヒーだけ飲みます (chỉ uống cà phê).', 'Trung tính; nhấn vào giới hạn, không hơn.', 'Hay nhầm だけ với しか: だけ đi với khẳng định, しか phải đi với phủ định (一つしかありません). Không đặt だけ trước danh từ như chữ “chỉ” (sai: だけ水をください).', '[]', NULL, 'AI_CHECKED', 1, '3c5bc58917e7'),
('JG-53e50fc60e', 'N5', 5, 314, 314, 'Không nơi nào', '[]', 'Không nơi nào', 'không nơi nào (với phủ định); nơi nào cũng (với khẳng định)', 'どこも + Vない / どこも + A', 'どこも + phủ định = không chỗ nào … (店はどこもあいていません). どこも + khẳng định = chỗ nào cũng … (どこも人が多いです). Muốn nói "không đi đâu cả" với động từ di chuyển thì dùng どこへも / どこにも.', 'Với phủ định là “không nơi nào”, với khẳng định là “nơi nào cũng”.', 'Hay nhầm どこも với どこか (nơi nào đó).', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-5465ba55d3', 'N5', 8, 48, 48, '余(あま)り〜ない', '[]', '余(あま)り〜ない', 'không … lắm; ít khi (đi với phủ định)', 'あまり + Vない / Aくない / Aな じゃない', 'Dùng để nói mức độ không cao hoặc ít khi làm việc gì; luôn đi với dạng phủ định.', 'Nhẹ nhàng, khéo hơn phủ định thẳng; hay dùng để từ chối hoặc chê một cách tế nhị.', 'Hay dùng あまり với câu khẳng định để nói “rất” (sai: あまり高いです); khẳng định phải dùng とても. Đừng nhầm với ぜんぜん〜ない là hoàn toàn không.', '[]', NULL, 'AI_CHECKED', 1, '3c5bc58917e7'),
('JG-5549d02710', 'N5', 11, 392, 392, '〜どのぐらい', '[]', 'どのぐらい', 'khoảng bao lâu; khoảng bao nhiêu', 'どのぐらい・どのくらい + V / どのぐらい + かかりますか', 'Dùng để hỏi về lượng, thời gian, khoảng cách hoặc mức độ: bao lâu, bao nhiêu.', 'Trung tính; どのぐらい và どのくらい dùng như nhau.', 'Hay dùng いくら để hỏi thời gian; いくら chỉ dùng để hỏi giá tiền.', '["JG-a344ddcd6a"]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-5598dd5ba9', 'N5', 2, 129, 129, 'Sở hữu, bổ nghĩa', '[]', 'Sở hữu, bổ nghĩa', 'của (nối danh từ với danh từ); cái … (thay cho danh từ đã rõ)', 'N1 + の + N2 / N + の (thay cho danh từ đã rõ)', 'Đặt の giữa hai danh từ để nối: danh từ trước bổ nghĩa cho danh từ sau (sở hữu, xuất xứ, nội dung): 私の本, 日本の車, 車の本. Khi danh từ sau đã rõ thì có thể bỏ, chỉ giữ の: このかさは先生のです; tính từ い + の = cái …: 大きいのをください.', 'Trung tính; の liên kết hai danh từ với nhiều quan hệ: của ai, về cái gì, ở đâu.', 'Hay đảo thứ tự theo tiếng Việt; danh từ chính luôn đứng sau の: 日本の車 (ô tô của Nhật). Tính từ い đứng trước danh từ không cần の.', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-55b2903768', 'N5', 3, 386, 386, 'Phía đó / bạn / ở đó', '[]', 'Phía đó / bạn / ở đó', 'phía đó (bên bạn); ở đó (lịch sự)', 'そちら + は・へ・の …', 'そちら là cách nói lịch sự chỉ phía người nghe: nơi người nghe đang ở (そちらの天気はどうですか), công ty, nhà của người nghe, hoặc người ở đầu dây điện thoại (そちらは田中さんですか). Bộ đi cùng: こちら (phía tôi) – そちら (phía bạn) – あちら (phía kia) – どちら.', 'Lịch sự; dùng nhiều khi gọi điện hoặc nói với khách về phía người nghe.', 'Hay dùng そこ khi nói chuyện điện thoại với người lạ; lịch sự phải dùng そちら.', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-55c6751f24', 'N5', 18, 330, 330, 'V る ことが できません', '[]', 'V る ことが できません', 'Nói không làm được\nChỉ đổi cuối câu thành できません, phần trước giữ nguyên.', 'Vる + ことができません', 'Thêm ぜんぜん cho ý hoàn toàn không, thêm あまり cho ý không được mấy.', 'Lịch sự; nói không có khả năng hoặc không được phép.', 'Hay chia phủ định ở động từ trước こと (sai: 泳がないことができます); chỉ đổi cuối câu thành できません.', '["JG-627cff76d9"]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-57056c3bb2', 'N5', 8, 275, 275, 'Tạm được, bình thường', '[]', 'Tạm được, bình thường', 'tạm được; tàm tạm; cũng khá', 'まあまあ + です / まあまあ + A', 'まあまあです / まあまあでした: trả lời "cũng tạm" khi được hỏi どうですか. まあまあ + tính từ: cũng khá … (まあまあおいしい). Dùng khi nói khiêm tốn về mình; nhận xét đồ người khác làm, tặng thì nên tránh.', 'Đánh giá ở mức trung bình hoặc nói khiêm tốn về mình.', 'Hay dùng まあまあ để nhận xét món người khác nấu hay quà người khác tặng, dễ làm họ phật lòng.', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-586dbef68f', 'N5', 24, 401, 401, 'N に V-て もらいます', '[]', 'N に V-て もらい', 'Tôi nhờ được người ta làm\nCũng là người ta làm, nhưng nhìn từ phía mình đi nhờ: せんせいに おしえて もらいました.', 'N(người giúp) + に + V-て + もらいます', 'N に V-てもらいます: được N làm giúp việc gì, câu nhìn từ phía người nhận (thường là tôi): 先生に教えてもらいました. Cùng việc đó nói từ phía người làm là 先生が教えてくれました. Hay dùng khi chính mình nhờ người khác làm.', 'Nhìn từ phía người được giúp, thể hiện sự biết ơn.', 'Hay dùng が cho người giúp (sai: 兄が見てもらいました); với もらう, người giúp đi với に.', '["JG-81dd99afed"]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-589f4356b8', 'N5', 3, 229, 229, 'Vậy thì...', '[]', 'Vậy thì...', 'vậy thì; thế thì (lịch sự)', 'では、+ Câu', 'Đặt では ở đầu câu để chuyển sang việc tiếp theo, mở đầu hoặc kết thúc một phần, nhất là ở lớp học, cuộc họp: では、始めましょう. Cũng dùng khi chào: では、また来週. Lịch sự hơn じゃ; đừng nhầm với では trong ではありません.', 'Lịch sự, hơi trang trọng; hay dùng khi mở đầu hoặc chuyển sang phần khác.', 'Hay nhầm では đứng đầu câu (vậy thì) với では trong ではありません.', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-5955bb3d5c', 'N5', 10, 383, 383, 'Có (vật vô tri)', '[]', 'Có (vật vô tri)', 'có (đồ vật); có (sự kiện)', 'N(nơi chốn) + に + N(vật) + が + あります', 'Nơi chốn + に + N + が あります: ở đâu có cái gì (つくえの上にペンがあります). Cũng dùng cho sự kiện: あしたテストがあります. Phủ định là ありません. Người và con vật thì dùng います.', 'Trung tính; dùng cho đồ vật, cây cối, sự kiện.', 'Hay dùng あります cho người và động vật; những trường hợp đó dùng います.', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-59919d4a3a', 'N5', 13, 178, 178, 'Muốn có gì', '[]', 'Muốn có gì', 'muốn có …', 'N + が + ほしい(です)', 'N が ほしいです: nói thứ mình muốn có. Hỏi người nghe: 何がほしいですか. ほしい là tính từ い nên phủ định ほしくない, quá khứ ほしかった. Muốn làm gì thì dùng Vたい; không dùng ほしい để nói mong muốn của người khác.', 'Nói thẳng mong muốn của mình; không dùng ほしい để nói mong muốn của người khác.', 'Hay dùng を (sai: 時計をほしい). ほしい là tính từ い nên phủ định là ほしくない.', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-5a67a7a6d3', 'N5', 8, 208, 208, 'Aい → 〜くないです / Aな → 〜じゃ ありません', '[]', 'Aい → 〜くないです / Aな → 〜じゃ ありません', 'Nói không phải như vậy\nĐuôi い đổi thành くない; loại な dùng じゃ ありません như câu danh từ.', 'Aい bỏ い + くないです / Aな + じゃありません', 'いい là ngoại lệ, chê thì nói よくないです chứ không phải いくないです.', 'Lịch sự; くありません cũng là cách nói lịch sự của tính từ い.', 'Hay dùng じゃありません cho tính từ い (sai: 高いじゃありません) hoặc くない cho tính từ な (sai: 静かくない).', '["JG-13b031cef2"]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-5ab8fbc241', 'N5', 7, 35, 35, '〜ましょう', '[]', 'ましょう', 'cùng … nào; … đi (rủ rê hoặc hô hào cùng làm)', 'V-ます bỏ ます + ましょう', 'Dùng để rủ người nghe cùng làm khi đã biết họ sẵn lòng, hoặc để hô hào, hướng dẫn cả nhóm cùng làm.', 'Chủ động và dứt khoát hơn ませんか; không hợp để mời người trên ngay từ đầu.', 'Hay dùng ましょう để mời ngay khi chưa biết ý người kia, nghe hơi ép; lúc đó nên hỏi bằng ませんか trước.', '["JG-38e03685b6","JG-2c477bb863","JG-77640b61e7"]', NULL, 'AI_CHECKED', 1, '3c5bc58917e7'),
('JG-5bf934a3f4', 'N5', 4, 132, 132, 'Và, cùng với, trích dẫn', '[]', 'Và, cùng với, trích dẫn', 'và (liệt kê đủ); cùng với (người cùng làm); trích dẫn lời nói', 'N1 + と + N2 / N(người) + と + V / Câu + と + 言う・思う', 'と nối danh từ khi kể đủ: ペンとノート. Sau người, と nghĩa là cùng với: 母と買い物をします (thường thêm いっしょに). Sau lời nói trong ngoặc, と đánh dấu trích dẫn: 「ありがとう」と言いました.', 'Trung tính; と dùng để liệt kê đầy đủ, chỉ người cùng làm, hoặc đánh dấu lời trích dẫn.', 'Hay dùng と để nối hai động từ hoặc hai câu (sai: 食べますと寝ます). Làm một mình thì nói 一人で, không nói 一人と.', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-5c86076657', 'N5', 9, 382, 382, 'Bởi vì...', '[]', 'Bởi vì...', 'vì …; đó là vì …', 'Câu (lý do, thể thường) + からです', 'Câu lý do (thể thường) + からです dùng để trả lời câu hỏi どうして, hoặc đứng sau một câu để giải thích: 早く帰ります。用事があるからです. Danh từ và tính từ な thêm だ: 雨だからです, 好きだからです.', 'Dùng để trả lời trực tiếp cho câu hỏi どうして.', 'Với danh từ, tính từ な phải thêm だ: 好きだからです, 雨だからです.', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-5d07042dbe', 'N5', 3, 17, 17, 'あそこ', '[]', 'あそこ', 'chỗ kia (nơi ở xa cả người nói lẫn người nghe)', 'あそこ + は + N + です / あそこ + に・で + V', 'Dùng để chỉ chỗ ở xa cả mình và người nghe, thường vừa nói vừa chỉ tay.', 'Trung tính; dạng lịch sự là あちら.', 'Hay nhầm あそこ với あれ: あそこ chỉ nơi chốn, あれ chỉ đồ vật (sai: あれに銀行があります). Muốn kèm danh từ thì dùng あの hoặc あそこの: あそこの店.', '[]', NULL, 'AI_CHECKED', 1, '3c5bc58917e7'),
('JG-5d2f0a6c47', 'N5', 2, 115, 115, 'N1 の N2', '[]', 'N1 の N2', 'của (nối hai danh từ N1 の N2)', 'N1 + の + N2', 'Đặt の giữa hai danh từ; danh từ sau là cái đang nói tới, danh từ trước bổ nghĩa cho nó (sở hữu, xuất xứ, nội dung, nơi làm việc): 私の本, 日本の車, 日本語の先生 (giáo viên dạy tiếng Nhật), 会社の友だち.', 'Trung tính; の có thể chỉ sở hữu, nguồn gốc, nội dung hay thuộc tính tùy hai danh từ.', 'Người Việt hay đảo thứ tự theo tiếng Việt “sách tiếng Nhật” thành 本の日本語; đúng là 日本語の本, danh từ chính đứng sau. Giữa tính từ い và danh từ thì không chèn の (sai: 高いの本).', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-5d8cfb7459', 'N5', 8, 388, 388, 'Rất vất vả, khó khăn', '[]', 'Rất vất vả, khó khăn', 'vất vả; khó khăn; rất (lịch sự)', 'N + は + たいへんです / たいへんな + N', 'たいへん là tính từ な: N はたいへんです (vất vả, khó khăn), たいへんな + N. V のはたいへんです = làm V thật vất vả. たいへんですね dùng để tỏ ra thông cảm. Làm phó từ, たいへん = rất (lịch sự): たいへんつかれました.', 'Lịch sự; là tính từ な nghĩa “vất vả, khó khăn”, cũng làm phó từ nghĩa “rất”.', 'Hay dùng たいへん để nói chuyện vui; khi là tính từ nó mang nghĩa vất vả, khó khăn.', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-5dfba295d9', 'N5', 10, 123, 123, 'Chủ ngữ, đối tượng nhấn mạnh', '[]', 'Chủ ngữ, đối tượng nhấn mạnh', 'trợ từ chỉ chủ ngữ (nhấn vào người hoặc vật được nói tới)', 'N + が + V / A (ある・いる・好き・分かる…)', 'Đặt が sau danh từ làm chủ ngữ khi nêu thông tin mới hoặc trả lời từ để hỏi: だれが来ましたか → 田中さんが来ました. が còn đánh dấu đối tượng của あります・います, 好き・きらい, 上手・下手, わかる: 日本語がわかります.', 'Nhấn vào danh từ đứng trước が, thường là thông tin mới với người nghe.', 'Hay dùng を với 好き, 分かる, 上手 (sai: 日本語を分かります); những từ này đi với が.', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-5e7542917e', 'N5', 11, 240, 240, 'N が 〜にん います', '[]', 'N が 〜にん い', 'Đếm người\nTừ ba người trở lên là số + にん: さんにん.', 'N + が + số người + います (ひとり, ふたり, 〜にん)', 'Một người và hai người đọc riêng: ひとり · ふたり, không phải いちにん · みにん.', 'Trung tính.', 'Hay nói いちにん, ににん; 1 người là ひとり, 2 người là ふたり, từ 3 người mới là số + にん. 4 người đọc là よにん.', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-5eef0723bd', 'N5', 23, 254, 254, '〜を+他動詞', '[]', 'を+他動詞', 'Tha động từ: Động từ đòi hỏi bổ ngữ (「～を」).', 'N + を + tha động từ (開ける, 閉める, つける, 消す)', 'Dùng khi có người chủ động làm một việc tác động lên vật.', 'Nhấn vào người làm và hành động của họ.', 'Hay nhầm cặp tự/tha động từ: 開く–開ける, 閉まる–閉める, 消える–消す; tha động từ mới đi với を.', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-5f945f18ef', 'N5', 10, 58, 58, '〜に', '["に"]', 'に', 'một cách … (tính từ な + に làm trạng từ)', 'Aな (bỏ な) + に + V (きれいに書く)', 'Đổi tính từ な thành từ bổ nghĩa cho động từ bằng cách thay な bằng に: 静かな → 静かに話します (nói nhỏ nhẹ), きれいな → きれいに書きます (viết cho đẹp). Tính từ い thì đổi い thành く: 早く起きます.', 'Trung tính; に biến tính từ な thành từ chỉ cách làm, giống “một cách …” trong tiếng Việt.', 'Hay giữ な trước động từ (sai: きれいな書きます); phải là きれいに書きます. Tính từ い thì đổi い thành く, không dùng に (はやく, không phải はやいに).', '[]', NULL, 'AI_CHECKED', 1, '3c5bc58917e7'),
('JG-5febe6d4d1', 'N5', 4, 22, 22, 'る-Verb (Negative-Past)', '[]', 'る-Verb (Negative-Past)', 'đã không … (dạng phủ định quá khứ thân mật của động từ nhóm II)', 'Vる bỏ る + なかった (食べる → 食べなかった)', 'Dùng khi kể việc đã không làm trong quá khứ với người thân quen; nói lịch sự thì dùng 〜ませんでした.', 'Thân mật; nghĩa giống ませんでした.', 'Hay nói 食べないでした hoặc 食べなかったでした; thân mật là 食べなかった, lịch sự là 食べませんでした.', '[]', NULL, 'AI_CHECKED', 1, '3c5bc58917e7'),
('JG-6058cc3992', 'N5', 7, 189, 189, 'N で V ます', '[]', 'N で V', 'Làm bằng cái gì, nói bằng tiếng gì\nDụng cụ hay thứ tiếng dùng để làm việc đó đứng trước で: はしで たべます, にほんごで かきます.', 'N(dụng cụ, ngôn ngữ) + で + V-ます', 'Cùng chữ で nhưng khác bài trước: bài trước là nơi diễn ra việc, bài này là thứ mình dùng.', 'Trung tính; で chỉ công cụ hay thứ tiếng dùng để làm việc đó.', 'Hay dùng を hoặc と cho dụng cụ (sai: はしを食べます); dụng cụ đi với で.', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-60d337caf7', 'N5', 6, 340, 340, 'Làm sao bây giờ', '[]', 'Làm sao bây giờ', 'làm thế nào; tính sao', 'N + は + どうしますか / どうしよう', 'N は どうしますか hỏi người nghe định làm gì, chọn gì với N (飲み物はどうしますか). Trả lời bằng việc mình sẽ làm: コーヒーにします, うちで食べます. Khác どうですか (hỏi thấy thế nào). どうしよう là lời tự hỏi khi lúng túng.', 'Trung tính; どうしよう là lời tự hỏi khi lúng túng.', 'Hay nhầm どうしますか (sẽ làm thế nào, chọn gì) với どうですか (thấy thế nào).', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-6109692e9e', 'N5', 18, 408, 408, '〜あとで・〜あとに', '[]', 'あとで・〜あとに', 'sau khi …; sau (N の あとで)', 'Vた + あとで / N + の + あとで', 'Dùng để nói việc ở vế sau xảy ra sau khi việc ở vế trước đã xong.', 'Nhấn thứ tự thời gian; あとで nhấn hành động tiếp theo, あとに nhấn thời điểm.', 'Hay dùng thể từ điển trước あとで (sai: 食べるあとで); phải dùng thể た: 食べたあとで. Với danh từ phải có の.', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-61efcda0b5', 'N5', 7, 37, 37, 'あげる', '[]', 'あげる', 'cho; tặng (mình hoặc ai đó đưa vật cho người khác)', 'N1(người nhận) + に + N2(vật) + を + あげる', 'Dùng khi người nói hoặc người khác cho, tặng đồ cho một người khác; chiều cho đi là từ phía mình ra ngoài.', 'Trung tính với bạn bè, người nhà; nói trực tiếp với người trên thì nghe hơi kẻ cả.', 'Hay dùng あげる khi người khác cho mình (sai: 友だちが私にあげました); trường hợp đó phải dùng くれる.', '[]', NULL, 'AI_CHECKED', 1, '3c5bc58917e7'),
('JG-6206aa1bf1', 'N5', 8, 213, 213, 'とても / ちょっと / あまり 〜ない', '[]', 'とても / ちょっと / あまり 〜ない', 'Nói mức độ nhiều ít\nとても là rất, ちょっと／すこし là hơi, あまり là không ... lắm.', 'とても・ちょっと + A / あまり + Aくない・Vない', 'あまり bắt buộc đi với đuôi phủ định ở cuối câu, không đứng một mình được.', 'ちょっと còn dùng để nói giảm hoặc từ chối khéo.', 'Hay dùng あまり với câu khẳng định; あまり bắt buộc đi với phủ định.', '["JG-9e64c1e419"]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-6268a8d03a', 'N5', 8, 228, 228, 'Và rồi...', '[]', 'Và rồi...', 'và; và rồi; hơn nữa', 'Câu 1。そして、Câu 2', 'Đặt そして ở đầu câu sau để thêm một ý cùng chiều (広いです。そして、明るいです) hoặc kể việc xảy ra tiếp theo (起きました。そして、シャワーを浴びました). Không dùng để nối hai danh từ (dùng と) hay hai ý trái ngược (dùng でも).', 'Trung tính, hơi trang trọng; hay dùng khi viết.', 'Hay dùng そして để nối hai danh từ (sai: 本そしてノート); nối danh từ phải dùng と.', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-627cff76d9', 'N5', 18, 329, 329, 'V る ことが できます', '[]', 'V る ことが でき', 'Nói làm được việc gì\nĐộng từ để ở dạng gốc (thể từ điển) rồi thêm ことが できます: およぐ ことが できます.', 'Vる + ことができます', 'Chỗ này KHÔNG dùng đuôi ます — nói およぎます ことが できます là sai.', 'Hơi trang trọng; nói khả năng của người hoặc điều kiện của nơi chốn.', 'Hay dùng thể ます trước こと (sai: 話しますことができます).', '["JG-55c6751f24"]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-63b38d7919', 'N5', 14, 295, 295, 'Ngay lập tức', '[]', 'Ngay lập tức', 'ngay; ngay lập tức; liền', 'すぐ(に) + V', 'すぐ(に) đứng trước động từ để nói làm ngay, không chờ: すぐに行きます, 帰って、すぐに寝ます. Nói chỗ rất gần thì dùng すぐ (không có に): すぐ近く, すぐそこ.', 'Trung tính; nhấn hành động xảy ra ngay, không chờ đợi.', 'Hay đặt すぐに ở cuối câu như “ngay” trong tiếng Việt; すぐに đứng trước động từ.', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-65004b9f67', 'N5', 11, 267, 267, 'Chỉ, duy nhất', '[]', 'Chỉ, duy nhất', 'chỉ; chỉ có', 'N / số lượng + だけ', 'Đặt だけ sau danh từ hay số lượng để giới hạn: 水だけ (chỉ nước), 二時間だけ (chỉ hai tiếng). Câu vẫn ở dạng khẳng định. Sau だけ có thể thêm が, を (私だけが, 水だけを), không thêm に trước động từ. しか thì phải đi với phủ định.', 'Trung tính; nhấn vào giới hạn.', 'Hay nhầm だけ với しか; しか phải đi với phủ định (二時間しか寝ませんでした).', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-65d0ae98d3', 'N5', 4, 294, 294, 'Lúc nãy', '[]', 'Lúc nãy', 'lúc nãy; vừa nãy', 'さっき + V-た / V-ました', 'さっき chỉ thời điểm vừa qua không lâu, thường đi với quá khứ: さっき会いました. さっきから + V-ています = từ lúc nãy đến giờ vẫn …; さっきまで = cho đến lúc nãy; さっきの + N = N lúc nãy.', 'Thân mật, dùng khi nói; trang trọng hơn là 先ほど.', 'Hay dùng さっき cho chuyện từ hôm qua; さっき chỉ dùng cho lúc rất gần, vài phút hay vài giờ trước.', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-664fd40c03', 'N5', 7, 38, 38, '貰(もら)う', '[]', '貰(もら)う', 'nhận (người nói hoặc ai đó nhận vật từ người khác)', 'N1(người cho) + に・から + N2(vật) + を + もらう', 'Dùng khi kể mình nhận quà, nhận đồ từ ai; người cho đứng trước に hoặc から.', 'Trung tính; nhìn sự việc từ phía người nhận.', 'Hay đặt người nhận trước に như với あげる; với もらう thì đứng trước に là người cho. Nhận từ công ty, trường học thì nên dùng から.', '[]', NULL, 'AI_CHECKED', 1, '3c5bc58917e7'),
('JG-66a6ede168', 'N5', 10, 233, 233, 'N に N が あります', '[]', 'N に N が あり', 'Ở chỗ đó có đồ vật gì\nChỗ đứng trước に, vật đứng trước が: だいどころに れいぞうこが あります.', 'N(nơi chốn) + に + N(vật) + が + あります', 'Câu này giới thiệu vật mới, nên vật đi với が chứ không phải は.', 'Trung tính; dùng khi nói ở một chỗ có thứ gì.', 'Hay dùng は thay が khi nói đến vật mới (sai: 部屋に机はあります).', '["JG-180021545a"]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-672d99428b', 'N5', 11, 242, 242, 'N を 〜まい/〜ほん/〜さつ/〜だい', '[]', 'N を 〜まい/〜ほん/〜さつ/〜だい', 'Đếm theo hình dạng của vật\nVật mỏng dùng まい, vật dài dùng ほん, sách vở dùng さつ, máy móc dùng だい.', 'N + を + số + まい・ほん・さつ・だい + V', 'Số đọc chệch ở vài chỗ: いっぽん・さんぼん・さんばい — nghe quen dần chứ đừng học vẹt.', 'Trung tính; chọn đơn vị đếm theo hình dạng của vật.', 'Hay đọc sai âm biến: いっぽん, さんぼん, ろっぽん; いっさつ, はっさつ. Số và đơn vị đếm đứng sau を, không đứng trước danh từ.', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-68aa27602e', 'N5', 19, 174, 174, 'Adjになります – Trở nên (tính từ な)', '[]', 'Adjになります – Trở nên (tính từ な)', 'trở nên …; chỉ sự thay đổi trạng thái của tính từ な', 'Aな / N + に + なります', 'Aな bỏ な + に なります để nói trạng thái tự thay đổi: 元気になりました (đã khỏe lại), 上手になりました (đã giỏi lên). Danh từ cũng dùng に なります. Tính từ い thì dùng 〜くなります; tự mình làm cho thay đổi thì dùng 〜にします.', 'Diễn tả sự thay đổi tự nhiên, khách quan.', 'Hay dùng く như tính từ い (sai: 元気くなります); tính từ な phải dùng に: 元気になります.', '["JG-7a14565753","JG-dbad118de2"]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-68ed805b7c', 'N5', 8, 341, 341, 'Như thế nào', '[]', 'Như thế nào', '… như thế nào; loại … nào', 'どんな + N', 'どんな luôn đứng trước danh từ để hỏi tính chất, loại: どんな人, どんな町, どんな映画. Không dùng どんな một mình; hỏi "thấy thế nào" về một thứ đã biết thì dùng どうですか.', 'Trung tính; hỏi về loại, tính chất.', 'Hay dùng どう trước danh từ (sai: どう町ですか); trước danh từ phải dùng どんな.', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-6988891eb2', 'N5', 12, 65, 65, 'じゃなかった', '[]', 'じゃなかった', 'đã không phải là … (quá khứ phủ định thân mật của danh từ và tính từ な)', 'N / Aな + じゃなかった (lịch sự: じゃありませんでした)', 'Dùng để nói trong quá khứ không phải như vậy, khi nói chuyện thân mật.', 'Thân mật; lịch sự thì dùng じゃありませんでした hoặc じゃなかったです.', 'Hay nói じゃないでした; đúng là じゃなかったです hoặc じゃありませんでした. Tính từ い không dùng mẫu này mà dùng くなかった.', '["JG-8924280459","JG-7c63ce580f"]', NULL, 'AI_CHECKED', 1, '3c5bc58917e7'),
('JG-69eb1f4796', 'N5', 24, 380, 380, 'Ai đó cho tôi', '[]', 'Ai đó cho tôi', 'cho (tôi); tặng (tôi)', 'N(người cho) + が + 私に + N(vật) + を + くれます', 'N (người cho) が 私に N (vật) を くれます: người khác cho, tặng tôi (hoặc người nhà tôi). Người nhận là tôi thường được lược: 友だちがプレゼントをくれました. Tôi cho người khác thì dùng あげます.', 'Thể hiện sự biết ơn; người nhận là người nói hoặc người trong nhà mình.', 'Hay dùng あげます trong trường hợp này (sai: 姉が私にあげました).', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-6b3810a528', 'N5', 19, 287, 287, '〜たり〜たるする', '[]', 'たり〜たるする', 'Cách nêu một vài ví dụ tiêu biểu trong nhiều hành động.', 'V1た + り、V2た + り + する', 'Dùng để kể vài việc tiêu biểu trong nhiều việc đã làm hoặc thường làm, không theo thứ tự.', 'Trung tính; ngầm hiểu còn những việc khác nữa.', 'Hay quên する ở cuối mẫu (読んだり、見たり。✗ → 読んだり、見たりします). Thì của cả câu chỉ đặt ở する cuối câu: 〜たりしました là việc đã làm.', '["JG-f20250fe9e","JG-072b546f77"]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-6b3f5d5c75', 'N5', 6, 372, 372, '〜疑問詞で〜ない', '[]', '疑問詞で〜ない', 'không … gì cả; không … ai cả; không … đâu cả', 'Từ để hỏi + も + Vない (何も, だれも, どこへも)', 'Dùng để phủ định hoàn toàn: không có gì, không có ai, không đi đâu.', 'Phủ định mạnh, bao trùm toàn bộ.', 'Hay dùng với câu khẳng định (sai: だれもいます). Cũng hay nhầm với từ để hỏi + でも (bất cứ … cũng).', '["JG-7df651c4ab","JG-a5087b5e0b"]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-6b9a7c8a3d', 'N5', 8, 196, 196, 'Dù... nhưng...', '[]', 'Dù... nhưng...', 'tuy … nhưng …; nối hai vế trái ngược (が)', 'Câu 1 + が、Câu 2', 'Câu 1 (thường kết thúc bằng です, ます) + が、câu 2 trái ý với câu 1: 雨ですが、出かけます (trời mưa nhưng vẫn đi). Cũng dùng để mở lời trước khi hỏi, nhờ: すみませんが、…. Khi hai vế là nguyên nhân – kết quả thì dùng から, không dùng が.', 'Lịch sự hơn けど; cũng dùng để mở lời trước khi hỏi, nhờ (すみませんが…).', 'Hay nhầm が nối câu với が chỉ chủ ngữ; が nối câu đứng sau cả một câu hoàn chỉnh, thường sau です, ます.', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-6bbd0fc52e', 'N5', 3, 333, 333, '(〜に〜を)ください', '[]', '(〜に〜を)ください', 'Cách yêu cầu người khác đưa cái gì cho mình.', 'N + を + ください / (私に) + N + を + ください', 'Dùng để xin hoặc yêu cầu người khác đưa cho mình một vật, hay dùng khi mua hàng, gọi món.', 'Lịch sự vừa phải; với người trên lịch sự hơn là 〜をいただけますか.', 'Hay nhầm hai mẫu: xin đồ vật là Nをください, nhờ làm việc là V-てください.', '["JG-cf2d62eca8","JG-ea84df0587","JG-af373390ef"]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-6da47b0eeb', 'N5', 4, 23, 23, 'う-Verb (Dictionary)', '[]', 'う-Verb (Dictionary)', 'thể từ điển (dạng gốc) của động từ nhóm I', 'V-ます: âm hàng い trước ます → âm hàng う (書きます → 書く, 飲みます → 飲む)', 'Dùng trong lối nói thân mật ở hiện tại hoặc tương lai, và để ghép với các mẫu như ことができる, まえに.', 'Thân mật; với người trên dùng dạng ます.', 'Hay quên đổi âm, nói 書きる thay vì 書く. Nhớ các cặp: 行きます → 行く, 待ちます → 待つ, 話します → 話す.', '[]', NULL, 'AI_CHECKED', 1, '3c5bc58917e7'),
('JG-701e98a1b5', 'N5', 5, 170, 170, 'どこへ いきますか / いつ いきますか', '[]', 'どこへ いきますか / いつ いきますか', 'Hỏi đi đâu\nHỏi nơi đến thì đổi chỗ nơi đến thành どこ, phần còn lại giữ nguyên.', 'どこへ + 行きますか / いつ + 行きますか', 'Hỏi nơi đến dùng どこへ, hỏi thời điểm dùng いつ (không thêm に). Không đi đâu cả thì đáp どこ(へ)も 行きません.', 'Trung tính; いつ không cần thêm trợ từ に.', 'Hay thêm に sau いつ (sai: いつに行きますか). Không đi đâu thì đáp どこへも行きません.', '["JG-7b9ca26686"]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-70bcaae2f1', 'N5', 9, 221, 221, 'N が わかります/あります', '[]', 'N が わかります/あり', 'Nói hiểu được, có sẵn\nHai động từ này cũng lấy が chứ không lấy を: かんじが わかります · じかんが あります.', 'N + が + わかります・あります', 'あります dùng cho đồ vật và sự việc. Người và con vật thì dùng います.', 'Trung tính.', 'Hay dùng を (sai: 時間をあります). Phủ định là わかりません, ありません.', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-7115d3bc5c', 'N5', 9, 54, 54, 'そんな', '[]', 'そんな', 'như thế; như vậy (đứng trước danh từ chỉ thứ giống điều vừa được nói tới)', 'そんな + N', 'Đặt trước danh từ để nói về thứ kiểu như điều người kia vừa nhắc tới; hay dùng khi ngạc nhiên hoặc phản bác.', 'Thường mang ý ngạc nhiên hoặc phủ nhận nhẹ; そんなことないです là cách khiêm tốn đáp lại lời khen.', 'Không để そんな đứng một mình; luôn cần danh từ theo sau (そんな人, そんなこと). Đừng nhầm với そう: そう đi với động từ (そう思います), そんな đi với danh từ.', '[]', NULL, 'AI_CHECKED', 1, '3c5bc58917e7'),
('JG-7121d4b204', 'N5', 22, 374, 374, '〜連体修飾', '[]', '連体修飾', 'Cách bổ nghĩa cho danh từ bằng mệnh đề quan hệ.', 'V(thể thường) / Aい / Aな + な + N', 'Đặt cả một cụm có động từ hoặc tính từ ngay trước danh từ để miêu tả danh từ đó.', 'Tiếng Nhật không có từ nối kiểu “mà, người mà” như tiếng Việt.', 'Hay đặt cụm bổ nghĩa sau danh từ hoặc chèn の (sai: 読んでいるの人).', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-71898a4777', 'N5', 21, 105, 105, 'ないと', '[]', 'ないと', 'phải … (cách nói tắt thân mật của ないといけない)', 'Vない + と (いけない)', 'Dùng trong hội thoại thân mật để nói mình phải làm việc gì, thường bỏ lửng phần いけない phía sau.', 'Thân mật, dùng khi tự nhủ hoặc nói với bạn bè; với người trên dùng 〜なければなりません.', 'Hay hiểu là “nếu không …” rồi chờ vế sau; khi đứng cuối câu, 〜ないと mang nghĩa “phải …”. Không dùng trong văn viết trang trọng.', '["JG-1fe5b4d961","JG-b707f36b01","JG-12f3c42e79"]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-718c796354', 'N5', 19, 345, 345, 'A く なります / N に なります', '[]', 'A く なります / N に なり', 'Nói cái gì đổi khác đi\nTính từ đuôi い đổi い thành く; tính từ đuôi な và danh từ thì thêm に.', 'Aい bỏ い + く + なります / Aな・N + に + なります', 'いい là ngoại lệ: khá lên thì nói よく なります.', 'Trung tính.', 'Hay dùng に với tính từ い (sai: 暑いになります).', '["JG-dad75c9be2","JG-af886f1233","JG-0eeeecf6ed"]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-7193124c6e', 'N5', 19, 173, 173, 'Adjにします – Làm cho trở nên (tính từ な)', '[]', 'Adjにします – Làm cho trở nên (tính từ な)', 'làm cho … trở nên …; chủ động thay đổi trạng thái (tính từ な)', 'N + を + Aな + に + します', 'Dùng N を Aな bỏ な + に します khi chính mình làm vật đó thay đổi: 部屋をきれいにします (dọn phòng cho sạch). Nhờ người khác: 静かにしてください (hãy giữ yên lặng). Tính từ い thì dùng 〜くします.', 'Diễn tả việc mình chủ động làm thay đổi trạng thái của vật.', 'Hay quên に (sai: きれいします) hoặc dùng く như tính từ い (sai: きれいくします).', '["JG-9965cb922d"]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-71b02d4467', 'N5', 22, 378, 378, 'V る / V-て いる + N', '[]', 'V る / V-て いる + N', 'Đặt cả một việc trước danh từ để tả\nCụm tả đứng TRƯỚC danh từ, không có の ở giữa: よく いく みせ.', 'Vる / V-ている + N', 'Trong cụm tả, chủ ngữ đi với が chứ không đi với は: ははが つくった りょうり.', 'Trung tính; cụm miêu tả đứng ngay trước danh từ.', 'Hay chèn の giữa cụm và danh từ (sai: よく行くの店).', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-71edb25a43', 'N5', 1, 121, 121, 'はじめまして ... どうぞ よろしく', '[]', 'はじめまして ... どうぞ よろしく', 'lời chào khi gặp lần đầu (khung câu tự giới thiệu)', 'はじめまして。+ 私は N です。+ どうぞよろしく(お願いします)。', 'Khung cố định khi tự giới thiệu lần đầu: mở đầu bằng はじめまして, xưng tên (私は〜です) và vài thông tin như quê quán, nghề nghiệp, rồi kết bằng どうぞよろしく (お願いします). Người nghe đáp lại: こちらこそ、どうぞよろしく.', 'Lịch sự, chỉ dùng ở lần gặp đầu tiên; thêm お願いします thì lịch sự hơn.', 'Hay dùng はじめまして khi gặp lại người đã quen; câu này chỉ dùng lần đầu gặp. Khi xưng tên không gắn さん vào tên mình.', '["JG-3981bfcd17","JG-45fa70fbca"]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-72a02e9fe6', 'N5', 15, 84, 84, '〜ている 3', '[]', 'ている 3', 'thường xuyên … (thói quen lặp lại hoặc nghề nghiệp)', 'V-て + いる (毎日〜ている, 〜で働いている)', 'Dùng để nói một việc lặp đi lặp lại trong thời gian dài như thói quen, nghề nghiệp, nơi làm việc.', 'Nhấn tính liên tục, kéo dài hơn so với thể ます đơn thuần.', 'Hay dùng 〜ます để nói công việc hiện tại (銀行で働きます nghe như “sẽ làm”); nói việc đang làm hằng ngày tự nhiên hơn là 銀行で働いています.', '["JG-b2976be48a","JG-4bf259bc32","JG-26e3b52ff4"]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-72aca41796', 'N5', 13, 278, 278, 'V たいです', '[]', 'V たい', 'Nói muốn làm việc gì\nBỏ ます rồi thêm たいです: いきます → いきたいです.', 'V-ます bỏ ます + たいです', 'Tân ngữ đi với を hoặc が đều được: すしを食べたいです / すしが食べたいです. Chỉ dùng để nói mong muốn của mình hoặc hỏi người nghe.', 'Nói mong muốn của bản thân một cách lịch sự.', 'Hay dùng cho người thứ ba hoặc ghép vào thể từ điển (sai: 買うたいです).', '["JG-819bac9f6d"]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-73190d3ca9', 'N5', 9, 144, 144, '〜よく・ときどき・あまり〜ない・ぜんぜん〜ない', '[]', 'よく・ときどき・あまり〜ない・ぜんぜん〜ない', 'Trạng thái chỉ mức độ thường xuyên của một hành động.', 'よく・ときどき + V / あまり・ぜんぜん + Vない', 'Dùng để nói một việc được làm thường xuyên đến mức nào: hay, thỉnh thoảng, ít khi, hoàn toàn không.', 'よく và ときどき đi với khẳng định; あまり và ぜんぜん bắt buộc đi với phủ định.', 'Hay dùng あまり hoặc ぜんぜん với câu khẳng định (sai: あまり見ます). Thứ tự tần suất: よく > ときどき > あまり〜ない > ぜんぜん〜ない.', '["JG-e7d401dccb"]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-73a902e219', 'N5', 5, 29, 29, 'へ行(い)く', '[]', 'へ行(い)く', 'đi đến … (へ chỉ hướng hoặc nơi đến)', 'N(nơi chốn) + へ + 行く', 'Dùng để nói đi đến một nơi nào đó; へ đánh dấu hướng đi hoặc điểm đến.', 'Trung tính; へ nhấn vào hướng đi, có thể thay bằng に mà nghĩa gần như không đổi.', 'Hay đọc へ là “he”; khi làm trợ từ phải đọc là “e”. Người Việt cũng hay dùng nhầm を (sai: 学校を行きます).', '[]', NULL, 'AI_CHECKED', 1, '3c5bc58917e7'),
('JG-741c8e687a', 'N5', 18, 251, 251, 'Trước khi...', '[]', 'Trước khi...', 'trước khi …; làm việc B trước việc A', 'Vる + 前に / N + の前に', 'Vる (thể từ điển) + まえに / N + の + まえに, rồi nói việc làm trước: 寝る前に本を読みます, 食事の前に手を洗います. Động từ trước まえに luôn ở thể từ điển, kể cả khi cả câu ở quá khứ (日本へ来る前に勉強しました). Với giờ nói 3時前に (không cần の).', 'Trung tính; động từ trước 前に luôn ở thể từ điển.', 'Hay dùng thể た hoặc thể ます trước 前に (sai: 寝た前に, 寝ます前に).', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-74e81139eb', 'N5', 16, 373, 373, '〜ながら', '[]', 'ながら', 'Biểu thị 2 hành động xảy ra đồng thời. Hành động đứng sau là hành động chính.', 'V-ます bỏ ます + ながら、V2', 'V1 (bỏ ます) + ながら + V2: vừa V1 vừa V2, hai việc do cùng một người làm cùng lúc. Việc chính đặt ở cuối câu (V2): 音楽を聞きながら勉強します (việc chính là học). Cũng dùng cho hai việc song song lâu dài: 働きながら日本語を勉強しています.', 'Hành động chính là V2 ở cuối câu; hai hành động do cùng một người làm.', 'Hay gắn ながら vào hành động chính; hành động phụ mới đi với ながら. Không dùng khi hai việc do hai người khác nhau làm.', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-762fd6d05d', 'N5', 15, 302, 302, 'まだ 〜て いません / しりません', '[]', 'まだ 〜て いません / しりません', 'Nói chưa, nói không có\nChưa làm thì まだ + て いません; không mang theo thì もって いません.', 'まだ + V-ていません / 知りません', 'まだ mang nghĩa chưa nhưng rồi sẽ, khác hẳn với ません là không làm.', 'Trung tính.', 'Phủ định của 知っています là 知りません, không phải 知っていません.', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-76a5b1d0e4', 'N5', 15, 300, 300, 'V ても いいです', '[]', 'V ても いい', 'Xin phép và cho phép\nĐuôi て rồi thêm も いいです: すわっても いいですか là tôi ngồi được không.', 'V-て + もいいです', 'Đáp cho phép thì nói はい、いいですよ hoặc どうぞ, đừng đáp trống một chữ はい.', 'Lịch sự vừa phải; dùng để cho phép.', 'Hay quên も hoặc chia sai thể て (sai: 休みてもいいです; đúng là 休んでもいいです).', '["JG-315e3a8560","JG-9d12efd7d2","JG-a412adf097"]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-76f889e316', 'N5', 2, 335, 335, 'Cái gì (dạng biến thể)', '[]', 'Cái gì (dạng biến thể)', 'cái gì; mấy (đi với đơn vị đếm)', '何(なん) + です・の・đơn vị đếm (何時, 何月, 何人)', '何 đọc なん trước です, の và phần lớn đơn vị đếm: なんですか, なんの本, なんじ, なんにん, なんがい, なんこ. Trước を, が thì đọc なに: なにを食べますか.', 'Trung tính; なん là cách đọc của 何 trước một số âm và đơn vị đếm.', 'Hay đọc 何月 thành なにがつ; đúng là なんがつ.', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-773b73376f', 'N5', 13, 77, 77, '何(なに) + か', '[]', '何(なに) + か', 'cái gì đó (một thứ không xác định)', '何か + V / 何か + N…', 'Dùng khi nói đến một thứ không xác định, thường để hỏi “có … gì không” hoặc nói “muốn … gì đó”.', 'Nhẹ nhàng; câu hỏi 何か〜ますか chỉ cần trả lời はい hoặc いいえ.', 'Hay nhầm 何か với 何: 何を食べますか là hỏi ăn gì, còn 何か食べますか là hỏi có ăn gì không. Sau 何か thường bỏ を và が.', '[]', NULL, 'AI_CHECKED', 1, '3c5bc58917e7'),
('JG-77640b61e7', 'N5', 7, 283, 283, 'V ましょうか / V ませんか', '[]', 'V ましょうか / V ませんか', 'Mời và ngỏ ý giúp\nましょうか là ngỏ ý làm giúp, ませんか là rủ cùng làm.', 'V-ます bỏ ます + ましょうか (ngỏ ý giúp) / ませんか (rủ cùng làm)', 'Hai câu này nghe nhẹ hơn ください nhiều — muốn lịch sự thì chọn chúng.', 'Cả hai đều lịch sự; ましょうか hướng về việc mình làm cho người nghe, ませんか hướng về việc cùng làm.', 'Hay nhầm hai mẫu: muốn xách đồ giúp thì nói 持ちましょうか, muốn rủ đi chơi thì nói 行きませんか.', '["JG-5ab8fbc241","JG-38e03685b6","JG-2c477bb863"]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-786d7f35b0', 'N5', 12, 311, 311, 'Bên nào', '[]', 'Bên nào', 'bên nào; cái nào (giữa hai thứ); đâu (lịch sự)', 'どちら + が・に … / N + は + どちらですか', 'どちら hỏi chọn giữa hai thứ: AとBと、どちらが〜ですか. Cũng là cách hỏi lịch sự thay cho どこ: トイレはどちらですか, お国はどちらですか. Đứng trước danh từ thì dùng どちらの + N.', 'Lịch sự; dùng cho lựa chọn giữa hai thứ hoặc để hỏi phương hướng, nơi chốn.', 'Hay dùng どれ cho hai thứ; hai thứ phải dùng どちら.', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-788cfc687d', 'N5', 19, 98, 98, '〜たことがある', '[]', 'たことがある', 'đã từng … (kinh nghiệm trong quá khứ)', 'Vた + ことがある (ことがあります)', 'Gắn ことがあります vào thể た của động từ để nói về trải nghiệm đã có trong đời: 日本へ行ったことがあります (tôi đã từng đến Nhật). Hỏi bằng 〜たことがありますか; chưa từng thì nói 〜たことがありません, nhấn mạnh bằng 一度も.', 'Trung tính; nói về trải nghiệm trong đời, không dùng cho việc vừa mới làm hôm qua.', 'Hay dùng cho việc gần đây (sai: 昨日すしを食べたことがあります); việc vừa xảy ra chỉ cần nói 食べました. Phủ định là 〜たことがありません, không phải 〜なかったことがあります.', '["JG-15239d5b3e","JG-4f10b05b40","JG-afacd1b137"]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-7a14565753', 'N5', 19, 100, 100, 'になる・くなる', '[]', 'になる・くなる', 'trở nên …; trở thành … (nói về sự thay đổi)', 'Aい bỏ い + くなる / Aな・N + になる', 'Dùng để nói trạng thái, tính chất thay đổi theo thời gian, hoặc một người trở thành nghề gì, đến tuổi nào.', 'Trung tính, diễn tả sự thay đổi tự nhiên, không do ai cố ý tạo ra.', 'Hay dùng に với tính từ い (sai: 寒いになる) hoặc く với tính từ な (sai: 静かくなる). Đúng là 寒くなる, 静かになる, 先生になる.', '["JG-dbad118de2","JG-68aa27602e"]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-7ac543f4e0', 'N5', 4, 20, 20, 'る-Verb (Past)', '[]', 'る-Verb (Past)', 'đã … (dạng quá khứ thân mật của động từ nhóm II)', 'Vる bỏ る + た (食べる → 食べた)', 'Dùng khi kể việc đã xảy ra với bạn bè, người nhà; nói lịch sự thì dùng 〜ました.', 'Thân mật; nghĩa giống dạng ました nhưng không dùng với người trên.', 'Hay chia theo kiểu nhóm I thành 食べった, 見った; nhóm II chỉ cần bỏ る rồi thêm た: 食べた, 見た.', '[]', NULL, 'AI_CHECKED', 1, '3c5bc58917e7'),
('JG-7b07dc0c88', 'N5', 3, 226, 226, 'Thế thì...', '[]', 'Thế thì...', 'thế thì; vậy thì (dựa vào điều vừa nói)', 'それじゃ、+ Câu', 'Đặt それじゃ ở đầu câu đáp, dựa vào điều người kia vừa nói để đưa ra đề nghị, quyết định: 「バスがありません。」「それじゃ、歩いて行きましょう。」. Cũng dùng khi chào tạm biệt: それじゃ、また. Thân mật như じゃ; lịch sự hơn là それでは.', 'Thân mật; それでは lịch sự hơn.', 'Hay dùng それじゃ khi chưa có thông tin gì trước đó; nó phải dựa vào điều vừa được nói.', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-7b9ca26686', 'N5', 3, 18, 18, 'どこ', '[]', 'どこ', 'ở đâu; chỗ nào (từ dùng để hỏi nơi chốn)', 'N + は + どこ + ですか / どこ + に・で・へ + V', 'Dùng để hỏi vị trí của người, vật hoặc nơi diễn ra một việc gì đó.', 'Trung tính; nói lịch sự với khách hoặc người trên thì dùng どちら.', 'Hay đặt どこ lên đầu kèm は (sai: どこはトイレですか); đúng là トイレはどこですか. Hỏi nơi làm việc gì thì phải thêm で: どこで食べますか.', '["JG-701e98a1b5"]', NULL, 'AI_CHECKED', 1, '3c5bc58917e7'),
('JG-7c63ce580f', 'N5', 8, 172, 172, 'Adjじゃない(ではない) – Phủ định tính từ な', '[]', 'Adjじゃない(ではない) – Phủ định tính từ な', 'không …; phủ định của tính từ な (và danh từ)', 'Aな + じゃない(です) / ではない', 'Aな bỏ な rồi thêm じゃない: 静か → 静かじゃない. Lịch sự nói 〜じゃないです hoặc 〜じゃありません; ではありません trang trọng hơn. Danh từ phủ định cũng vậy: 学生じゃありません. Tính từ い thì dùng 〜くない.', 'じゃない dùng khi nói, ではない trang trọng hơn; thêm です để lịch sự.', 'Hay giữ な trước じゃない (sai: 静かなじゃない). Tính từ い không dùng じゃない (sai: 高いじゃない).', '["JG-8924280459","JG-6988891eb2"]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-7cbd428d1f', 'N5', 5, 142, 142, '〜へ・〜に', '[]', 'へ・〜に', 'Trợ từ chỉ phương hướng di chuyển. Thường được sử dụng với những động từ chỉ sự di chuyển như 「行く」「帰る」「来る」', 'N(nơi chốn) + へ・に + 行く・来る・帰る', 'Đặt sau nơi chốn để chỉ hướng đi hoặc điểm đến khi đi, đến, về.', 'へ nhấn hướng đi, に nhấn điểm đến; với 行く, 来る, 帰る hai trợ từ dùng gần như nhau.', 'Hay đọc へ là “he”; khi làm trợ từ phải đọc là “e”. Không dùng を với các động từ này (sai: 学校を行きます).', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-7ceb56c66d', 'N5', 5, 155, 155, 'Trở về...', '[]', 'Trở về...', 'về; trở về nơi mình thuộc về (nhà; nước mình)', 'N(nơi chốn) + へ・に + 帰る (帰ります)', 'Nơi về + へ/に + 帰ります: うちへ帰ります, 国に帰ります. Chỉ dùng cho nơi mình thuộc về (nhà, quê, nước mình); đi học, đi làm thì dùng 行きます, quay lại chỗ vừa rời thì dùng 戻ります.', 'Trung tính; dùng khi về nơi mình thuộc về: nhà, quê, nước mình.', '帰る là động từ nhóm I dù tận cùng る: 帰らない, 帰って (không phải 帰ない, 帰て). Đừng nhầm với 戻る là quay lại chỗ vừa rời.', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-7d37fd371c', 'N5', 8, 40, 40, 'い-Adjective', '[]', 'い-Adjective', 'tính từ đuôi い (từ chỉ tính chất tận cùng bằng い)', 'Aい (高い, 大きい); Aい + N; Aい + です', 'Dùng để miêu tả tính chất, trạng thái của người và vật; có thể đứng trước danh từ hoặc ở cuối câu.', 'Đứng cuối câu một mình là thân mật; thêm です là lịch sự.', 'Hay thêm な trước danh từ (sai: 高いな山); tính từ い đi thẳng với danh từ: 高い山. Lưu ý きれい, きらい tuy tận cùng い nhưng là tính từ な.', '[]', NULL, 'AI_CHECKED', 1, '3c5bc58917e7'),
('JG-7df651c4ab', 'N5', 13, 282, 282, '〜疑問詞でも', '[]', '疑問詞でも', 'bất cứ … nào cũng; gì cũng; ai cũng', 'Từ để hỏi (何・いつ・どこ・だれ) + でも', 'Gắn でも sau từ để hỏi để nói không giới hạn: 何でも (gì cũng), だれでも (ai cũng), どこでも (đâu cũng), いつでも (lúc nào cũng). Thường đi với câu khẳng định, hay gặp trong 〜でもいいです (… cũng được).', 'Mang ý “bất cứ … cũng được”, thường đi với câu khẳng định.', 'Hay nhầm với từ để hỏi + も đi với phủ định: 何でも食べます (ăn gì cũng được) khác hẳn 何も食べません (không ăn gì).', '["JG-a5087b5e0b","JG-6b3f5d5c75"]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-7e2b2860b7', 'N5', 18, 95, 95, 'ことが出来(でき)る', '[]', 'ことが出来(でき)る', 'có thể …; biết … (khả năng hoặc điều kiện cho phép)', 'Vる + ことができる (ことができます)', 'Dùng để nói ai đó có khả năng làm gì, hoặc ở nơi nào đó có thể làm gì.', 'Hơi trang trọng hơn thể khả năng (書ける); hay dùng khi viết hoặc khi nói lịch sự.', 'Hay dùng thể ます trước こと (sai: 泳ぎますことができます); phải dùng thể từ điển: 泳ぐことができます. Với danh từ thì dùng thẳng Nができる: 日本語ができます.', '["JG-b37786c8d4"]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-7f92b5d0f6', 'N5', 13, 337, 337, 'Cái gì đó', '[]', 'Cái gì đó', 'cái gì đó; thứ gì đó', '何か + V / 何か + N…', '何か chỉ một thứ không xác định: 何か食べたいです. Câu hỏi 何かありますか hỏi có gì không, đáp はい / いいえ trước. Hay đi với tính từ + もの: 何かつめたいもの. Muốn nói "không … gì cả" thì dùng 何も + phủ định.', 'Không xác định; câu hỏi chỉ cần trả lời はい hoặc いいえ.', 'Hay nhầm với 何: 何が入っていますか hỏi có cái gì, 何か入っていますか hỏi có gì không.', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-819bac9f6d', 'N5', 13, 75, 75, '〜たい', '["たい"]', 'たい', 'muốn … (mong muốn làm việc gì của người nói)', 'V-ます bỏ ます + たい(です)', 'Dùng để nói người nói muốn làm việc gì, hoặc hỏi người nghe muốn làm gì.', 'Nói thẳng mong muốn của bản thân; không dùng để mời người trên (sai: 先生、コーヒーを飲みたいですか).', 'Hay dùng 〜たい cho người thứ ba (sai: 母は日本へ行きたいです). Phủ định là 〜たくない, không phải 〜たいない.', '["JG-72aca41796"]', NULL, 'AI_CHECKED', 1, '3c5bc58917e7'),
('JG-81dd99afed', 'N5', 24, 400, 400, 'N に V-て あげます', '[]', 'N に V-て あげ', 'Tôi làm giúp người khác\nNgười được giúp đứng trước に: リンさんに おしえて あげました.', 'N(người được giúp) + に + V-て + あげます', 'Nói thẳng あげます với người trên nghe như kể công — với sếp nên bỏ đi, chỉ nói việc mình làm.', 'Có thể nghe như kể công; không nói trực tiếp với người trên.', 'Hay dùng khi người khác giúp mình; trường hợp đó phải dùng 〜てくれます.', '["JG-586dbef68f"]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-82d5f66b93', 'N5', 8, 45, 45, 'い-Adjective + (Noun)', '[]', 'い-Adjective + (Noun)', 'tính từ い đứng trước để bổ nghĩa cho danh từ', 'Aい + N (高い山)', 'Đặt tính từ い ngay trước danh từ để nói danh từ đó có tính chất gì.', 'Trung tính; tính từ giữ nguyên đuôi い, không cần thêm gì ở giữa.', 'Người Việt hay đặt tính từ sau danh từ theo thói quen “núi cao” (sai: 山高い); đúng là 高い山. Cũng không chèn の hay な vào giữa (sai: 高いの山).', '[]', NULL, 'AI_CHECKED', 1, '3c5bc58917e7'),
('JG-84ba76b207', 'N5', 16, 201, 201, 'Sau khi...', '[]', 'Sau khi...', 'sau khi … rồi mới …; làm xong V1 rồi mới làm V2', 'V1-て + から、V2', 'V1-て + から、V2: nhấn rõ V1 phải xong trước rồi mới tới V2: 手を洗ってから、食べます. Chỉ có một から sau thể て. Khác V1-て、V2 (chỉ nối hành động), てから nhấn mạnh thứ tự "sau khi".', 'Trung tính; nhấn rõ thứ tự: làm xong V1 rồi mới làm V2.', 'Hay dùng thể từ điển hoặc thể た trước から (sai: 食べたから) – khi đó から lại mang nghĩa “vì”.', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-851fd247f1', 'N5', 2, 134, 134, 'N は だれ の N ですか', '[]', 'N は だれ の N ですか', 'của ai? (hỏi chủ sở hữu của đồ vật)', 'N + は + だれの + N + ですか (lịch sự: どなたの)', 'Dùng だれの + danh từ để hỏi chủ của đồ vật, nhất là khi nhặt được đồ hoặc thấy đồ lạ: これはだれのかさですか. Có thể lược danh từ: このかさはだれのですか. Trả lời bằng tên người + の: 山田さんのです.', 'Trung tính; muốn lịch sự hơn thì dùng どなたの.', 'Hay quên の sau だれ (sai: だれ本ですか). Khi trả lời có thể lược danh từ: 先生のです.', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-85cefa2875', 'N5', 16, 305, 305, 'N を わたって / N へ まがって / あるいて', '[]', 'N を わたって / N へ まがって / あるいて', 'Chỉ đường bằng chuỗi việc\nChỉ đường thực chất là nối nhiều việc: みちを わたって、まっすぐ いきます.', 'N + を + わたって / N(hướng) + へ + まがって / まっすぐ + あるいて', 'Hướng rẽ đi với へ, chỗ băng qua đi với を.', 'Trung tính, dùng khi chỉ đường bằng chuỗi việc nối bằng thể て.', 'Hay dùng に với 渡る (sai: 橋に渡る); nơi đi qua dùng を. Chỉ việc cuối mới chia ます.', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-870b8730ba', 'N5', 21, 104, 104, '〜でも', '["でも"]', 'でも', 'dù … cũng (điều kiện ở vế trước không làm thay đổi kết quả)', 'V-て + も / Aい bỏ い + くても / Aな・N + でも', 'Gắn でも sau danh từ (hoặc tính từ な bỏ な) để nói dù trong điều kiện đó thì kết quả vẫn không đổi: 雨でも、サッカーをします (dù mưa vẫn đá bóng). Với động từ dùng thể て + も (飲んでも), với tính từ い dùng くても (寒くても).', 'Trung tính; nhấn rằng điều kiện ở vế trước không làm thay đổi kết quả ở vế sau.', 'Hay nhầm với でも đứng đầu câu (nghĩa là “nhưng”). Với tính từ い phải là くても (sai: 寒いでも).', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-87638f52db', 'N5', 9, 133, 133, '〜がすき・きらい', '[]', 'がすき・きらい', 'thích; ghét (người hoặc vật đứng trước が)', 'N + が + すき・きらい(です)', 'Dùng để nói mình thích hay ghét người, vật, việc gì; muốn hỏi thì thêm か ở cuối.', 'きらい khá mạnh; muốn nói khéo thì dùng あまりすきじゃないです.', 'Hay dùng を trước すき (sai: 犬をすきです). すき và きらい là tính từ な nên phủ định là すきじゃない, きらいじゃない.', '["JG-e4333f73fe","JG-ffae1ad9ba"]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-88d77e396b', 'N5', 13, 187, 187, '〜い行く・〜に来る', '[]', 'い行く・〜に来る', 'Biểu thị mục đích di chuyển. Ngoài 「行く」ra, còn có thể sử dụng cùng với những động từ chỉ sự di chuyển như 「帰る」「出る」「戻る」', 'V-ます bỏ ます + に + 行く・来る・帰る', 'Dùng để nói mục đích của việc đi, đến, về: đi để mua, đến để gặp, về để ăn.', 'Trung tính; mục đích đi với に, nơi đến đi với へ hoặc に.', 'Hay dùng thể từ điển trước に (sai: 会うに来ました); phải bỏ ます: 会いに来ました.', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-8924280459', 'N5', 1, 5, 5, 'じゃない', '[]', 'じゃない', 'không phải là … (lối nói thân mật)', 'N / Aな + じゃない', 'Dùng để phủ định câu danh từ hoặc tính từ な khi nói chuyện với bạn bè, người nhà. Muốn lịch sự hơn thì nói じゃないです hoặc じゃありません.', 'Thân mật, dùng trong văn nói; khi viết hoặc dịp trang trọng thì dùng ではない, ではありません.', 'Không dùng じゃない để phủ định tính từ い (sai: 高いじゃない); phải nói 高くない. Cũng đừng nhầm với じゃないですか lên giọng, nghĩa là “chẳng phải là … sao”.', '["JG-6988891eb2","JG-7c63ce580f"]', NULL, 'AI_CHECKED', 1, '3c5bc58917e7'),
('JG-894fbb47aa', 'N5', 10, 236, 236, 'N は どこに ありますか / に なにが ありますか', '[]', 'N は どこに ありますか / に なにが ありますか', 'Hỏi ở đâu, hỏi có gì\nHỏi chỗ thì どこに, hỏi vật thì なにが, hỏi người thì だれが.', 'N + は + どこに + ありますか / N(nơi chốn) + に + なにが + ありますか', 'Người ta hỏi どこ thì đáp bằng chỗ, đừng đáp bằng tên đồ vật.', 'Trung tính; hỏi người thì thay なにが bằng だれが và dùng いますか.', 'Hay dùng なには (sai: 箱の中になにはありますか); từ để hỏi làm chủ ngữ phải đi với が.', '["JG-d604d684d2","JG-e99ec187f7"]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-897e453cbf', 'N5', 25, 407, 407, 'V ても / A くても / N でも', '[]', 'V ても / A くても / N でも', 'Dù thế nào vẫn làm\nTừ đuôi て thêm も: ふって → ふっても; tính từ đuôi い thành くても.', 'V-て + も / Aい bỏ い + くても / Aな・N + でも', 'Vế sau phải là chuyện đi NGƯỢC với vế trước, không thì nghe kỳ.', 'Trung tính; nhấn rằng kết quả không đổi dù điều kiện ở vế trước xảy ra.', 'Với tính từ い hay viết 寒いでも; đúng là 寒くても.', '["JG-315e3a8560","JG-9d12efd7d2","JG-a412adf097"]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-899f898e99', 'N5', 7, 350, 350, '(〜に〜を)もらう', '[]', '(〜に〜を)もらう', 'nhận (từ ai); được cho', 'N1(người cho) + に・から + N2 + を + もらう', 'Dùng khi người nói hoặc ai đó nhận một vật từ người khác; người cho đứng trước に hoặc から.', 'Nhìn sự việc từ phía người nhận.', 'Hay đặt người nhận trước に; đứng trước に là người cho.', '["JG-cf2d62eca8","JG-ea84df0587","JG-af373390ef"]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-89c33f369d', 'N5', 10, 126, 126, 'Liệt kê không đầy đủ', '[]', 'Liệt kê không đầy đủ', '… và … vân vân (liệt kê vài ví dụ không nêu hết)', 'N1 + や + N2 + (など)', 'Nối các danh từ bằng や để nêu vài ví dụ tiêu biểu, ngầm hiểu còn thứ khác; thường thêm など sau danh từ cuối: 本やノートなどがあります. Muốn kể đủ hết thì dùng と.', 'Mềm, ngầm hiểu còn những thứ khác; khác với と là kể đủ.', 'Hay dùng や khi đã nêu hết mọi thứ; khi đó phải dùng と. や không nối động từ hay tính từ.', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-8a7d6f9279', 'N5', 22, 106, 106, '〜た + (Noun)', '[]', 'た + (Noun)', 'danh từ đã … (động từ thể た bổ nghĩa cho danh từ)', 'Vた + N (昨日買った本)', 'Đặt cả cụm có động từ thể た ngay trước danh từ để nói danh từ đó gắn với một việc đã xảy ra.', 'Trung tính; người làm việc đó trong cụm bổ nghĩa đi với が hoặc の.', 'Người Việt hay đặt cụm bổ nghĩa sau danh từ như tiếng Việt “cái cặp đã mua hôm qua”; tiếng Nhật phải là 昨日買ったかばん. Không chèn の giữa động từ và danh từ (sai: 買ったの本).', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-8c2a3a12a2', 'N5', 2, 11, 11, 'その', '[]', 'その', '… đó (đứng trước danh từ chỉ vật ở gần người nghe)', 'その + N', 'Đặt trước danh từ để chỉ vật ở gần người nghe, hoặc người, vật vừa được nhắc đến.', 'Trung tính; cũng dùng để nhắc lại người, vật đã nói ở câu trước.', 'Không để その đứng một mình (sai: そのは何ですか); phải nói それは何ですか hoặc その本は何ですか.', '[]', NULL, 'AI_CHECKED', 1, '3c5bc58917e7'),
('JG-8c8827052d', 'N5', 18, 326, 326, '〜前に', '[]', '前に', 'trước khi …; trước (N の前に)', 'Vる + 前に / N + の前に', 'Dùng để nói làm việc gì trước khi làm một việc khác hoặc trước một sự kiện.', 'Trung tính; động từ trước 前に luôn ở thể từ điển.', 'Hay dùng thể た trước 前に vì câu nói chuyện đã qua (sai: 行った前に); vẫn phải là 行く前に.', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-8cc885626c', 'N5', 3, 16, 16, 'そこ', '[]', 'そこ', 'chỗ đó (nơi ở gần người nghe)', 'そこ + は + N + です / そこ + に・で + V', 'Dùng để chỉ chỗ người nghe đang ở hoặc chỗ gần người nghe; cũng dùng để chỉ lại nơi vừa được nhắc tới.', 'Trung tính; dạng lịch sự là そちら.', 'Hay dùng そこ cho chỗ ở xa cả hai người; chỗ đó phải dùng あそこ.', '[]', NULL, 'AI_CHECKED', 1, '3c5bc58917e7'),
('JG-8d067fe6bd', 'N5', 4, 131, 131, 'Từ... đến...', '[]', 'Từ... đến...', 'từ … đến … (phạm vi thời gian hoặc nơi chốn)', 'N1 + から + N2 + まで', 'Đặt から sau mốc bắt đầu và まで sau mốc kết thúc để nói khoảng thời gian hoặc quãng đường: 九時から五時まで働きます, 家から駅まで歩きます. Muốn bổ nghĩa cho danh từ thì thêm の: 東京から大阪までの切符.', 'Trung tính; dùng được cho cả thời gian lẫn nơi chốn.', 'Hay dùng までに thay cho まで khi nói khoảng thời gian liên tục. Câu nói giờ làm việc có thể kết thúc bằng です: 9時から5時までです.', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-8d5ac2aa76', 'N5', 1, 125, 125, 'Cũng, giống như', '[]', 'Cũng, giống như', 'cũng; cả … lẫn … (AもBも); không … nào cả (từ để hỏi + も + phủ định)', 'N + も / N1 も N2 も + V', 'も thay cho は, が, を để nói “cũng”: 私も行きます. AもBも = cả A lẫn B. Từ để hỏi + も + phủ định = không … gì, ai, đâu cả: 何も食べません, だれもいません, どこへも行きません. Số lượng + も nhấn ý nhiều hơn mong đợi: 三つも食べました (ăn những ba cái).', 'Trung tính; も đứng thay vào chỗ は, が, を; đi sau số lượng thì mang ý “đến tận …”.', 'Hay giữ nguyên trợ từ cũ (sai: 私はも, 水をも). Với に, で, へ thì giữ lại rồi thêm も: 日本にも行きました.', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-8e21283b46', 'N5', 14, 264, 264, '〜てください', '[]', 'てください', 'Cách yêu cầu, khuyến khích hoặc mệnh lệnh.', 'V-て + ください', 'Dùng để nhờ, yêu cầu, hướng dẫn hoặc mời người khác làm gì một cách lịch sự.', 'Lịch sự nhưng vẫn là yêu cầu; どうぞ + 〜てください là lời mời.', 'Hay gắn ください vào thể ます (sai: 読みますください).', '["JG-a96e6873a8","JG-41595b514a","JG-b4ac2012bf"]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-8e2914f807', 'N5', 23, 393, 393, 'N の とき / A い とき / V る とき', '[]', 'N の とき / A い とき / V る とき', 'Nói lúc nào thì làm gì\nVế trước とき để ở dạng gốc: ひまな とき · でかける とき.', 'N + の + とき / Aい + とき / Aな + な + とき / Vる + とき', 'Danh từ phải có の: こどもの とき, không nói こども とき.', 'Trung tính.', 'Hay quên の với danh từ (sai: 子どもとき) hoặc な với tính từ な.', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-8f27747a07', 'N5', 9, 277, 277, 'Thường, đa số', '[]', 'Thường, đa số', 'thường; phần lớn (thói quen)', 'たいてい + V', 'たいてい + câu nói thói quen: phần lớn các lần đều như vậy (たいてい6時に起きます). Mạnh hơn よく, yếu hơn いつも. Không dùng cho một việc chỉ xảy ra một lần hay một ngày cụ thể.', 'Chỉ thói quen chung, phần lớn các lần.', 'Hay dùng たいてい cho một việc chỉ xảy ra một lần; nó chỉ dùng cho thói quen lặp lại.', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-8fbcf1634b', 'N5', 7, 291, 291, 'Đã, rồi', '[]', 'Đã, rồi', 'đã … rồi; không … nữa; thêm … nữa', 'もう + V-ました', 'もう + Vました: việc đã xong (もう食べました). Hỏi もう〜ましたか = đã … chưa; chưa làm thì đáp いいえ、まだです. もう + phủ định = không … nữa. もう + số lượng (もう一度, もう少し, もう一つ) = thêm.', 'Trung tính; nhấn việc đã hoàn thành trước thời điểm nói.', 'Được hỏi もう〜ましたか mà chưa làm thì đáp いいえ、まだです, không đáp いいえ、〜ませんでした.', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-907910f5d7', 'N5', 14, 284, 284, 'V-て います', '[]', 'V-て い', 'Nói đang làm dở việc gì\nCũng dùng đuôi て, nhưng thêm います: たべて います là đang ăn.', 'V-て + います', 'Với việc làm lâu dài (nghề nghiệp, chỗ ở) thì nó mang nghĩa hiện đang như vậy chứ không phải đang làm ngay lúc này.', 'Trung tính; diễn tả việc đang làm dở ngay lúc nói.', 'Hay dùng 〜ます cho việc đang diễn ra; đang làm phải dùng 〜ています.', '["JG-b2976be48a","JG-4bf259bc32","JG-72a02e9fe6"]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-90c7979425', 'N5', 22, 376, 376, 'V た + N', '[]', 'V た + N', 'Tả bằng việc đã xảy ra\nDùng đuôi た cho việc đã rồi: きのう かった ほん.', 'Vた + N', 'Thì của cụm tả độc lập với thì của cả câu — cụm để た mà câu vẫn có thể là hiện tại.', 'Trung tính; người làm việc đó đi với が.', 'Hay chèn の giữa động từ và danh từ (sai: 作ったのケーキ).', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-918af04099', 'N5', 4, 25, 25, 'う-Verb (Negative)', '[]', 'う-Verb (Negative)', 'không … (dạng phủ định thân mật của động từ nhóm I)', 'Vう: âm hàng う → âm hàng あ + ない (書く → 書かない, 買う → 買わない)', 'Dùng để nói không làm việc gì trong lối nói thân mật; nói lịch sự thì dùng 〜ません.', 'Thân mật, dùng với bạn bè, người nhà.', 'Động từ tận cùng う phải đổi thành わ chứ không phải あ (買う → 買わない, không phải 買あない). Ngoại lệ: ある → ない.', '[]', NULL, 'AI_CHECKED', 1, '3c5bc58917e7'),
('JG-91a0ff6ec4', 'N5', 8, 381, 381, 'Bạn thấy thế nào?', '[]', 'Bạn thấy thế nào?', 'thế nào ạ (lịch sự); mời dùng … nhé', 'N + は + いかがですか', 'いかがですか là cách nói lịch sự của どうですか: dùng để mời (コーヒーはいかがですか) hoặc hỏi cảm nhận, tình trạng (おからだはいかがですか). Hỏi về việc đã qua dùng いかがでしたか. Với bạn thân chỉ cần どう？', 'Lịch sự hơn どうですか; dùng để mời hoặc hỏi ý kiến khách, người trên.', 'Hay dùng với bạn thân, nghe khách sáo; với bạn bè chỉ cần どう？', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-91b5b5d193', 'N5', 20, 353, 353, 'V ない / N じゃ ない', '[]', 'V ない / N じゃ ない', 'Nói thân mật kiểu phủ định\nĐộng từ dùng đuôi ない; danh từ và tính từ đuôi な dùng じゃ ない.', 'Vない / Aな・N + じゃない', 'ありません thân mật hoá thành ない, không nói あらない.', 'Thân mật.', 'Hay dùng じゃない với động từ (sai: 食べるじゃない); động từ phủ định là 食べない.', '["JG-1fe5b4d961","JG-71898a4777","JG-b707f36b01"]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-9348e6acbe', 'N5', 4, 252, 252, 'Vào khoảng (thời điểm)', '[]', 'Vào khoảng (thời điểm)', 'vào khoảng (thời điểm)', 'N(thời điểm) + ごろ (+ に)', 'Mốc thời gian (giờ, ngày, tháng) + ごろ để nói thời điểm xấp xỉ: 3時ごろ, 7月ごろ; có thể thêm に, から, まで (10時ごろに, 3時ごろまで). Hỏi: いつごろ, なんじごろ. Lượng thời gian hay số lượng thì dùng ぐらい, không dùng ごろ.', 'Trung tính; chỉ thời điểm xấp xỉ.', 'Hay dùng ごろ cho lượng thời gian (sai: 2時間ごろ); lượng thời gian dùng ぐらい.', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-9397da0ccd', 'N5', 10, 235, 235, 'N は N の うえ/した/なか/まえ/うしろ/となり/ちかく/あいだ に あります', '[]', 'N は N の うえ/した/なか/まえ/うしろ/となり/ちかく/あいだ に あり', 'Nói rõ thứ đó nằm chỗ nào\nĐã biết vật rồi, muốn chỉ chỗ thì vật đi với は: かばんは いすの したに あります.', 'N1 + は + N2 + の + うえ・した・なか・まえ・うしろ・となり・ちかく・あいだ + に + あります・います', 'Chữ chỉ chỗ (うえ・した・なか) luôn có の đứng trước nó.', 'Trung tính; N1 là vật đã biết, câu cho biết vị trí của nó.', 'Hay đảo thứ tự theo tiếng Việt “trên bàn” thành うえの机; đúng là 机のうえ.', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-94b35187d4', 'N5', 18, 97, 97, '中々(なかなか)', '[]', '中々(なかなか)', 'mãi mà không …; khó mà … (đi với phủ định); khá là … (đi với khẳng định)', 'なかなか + Vない / なかなか + Aい・Aな', 'Đi với phủ định để nói việc gì đó mãi không xảy ra như mong đợi; đi với khẳng định để khen là “khá …, hơn mình nghĩ”.', 'Với phủ định thể hiện sự sốt ruột; với khẳng định là lời khen nhẹ, không dùng để khen người trên.', 'Hay hiểu なかなか〜ない là “không … lắm” giống あまり〜ない; thật ra nó là “mãi không …, khó mà …”.', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-97308f3bca', 'N5', 18, 331, 331, 'V る まえに / N の まえに', '[]', 'V る まえに / N の まえに', 'Nói trước khi làm gì\nVế trước まえに luôn để dạng gốc, dù cả câu nói chuyện đã qua.', 'Vる + まえに / N + の + まえに', 'Danh từ thì phải có の: しょくじの まえに, không nói しょくじ まえに.', 'Trung tính.', 'Hay dùng thể た trước まえに, hoặc quên の sau danh từ (sai: テストまえに).', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-9757baa776', 'N5', 7, 197, 197, 'Hãy cùng làm', '[]', 'Hãy cùng làm', 'hãy cùng …; chúng ta … nào', 'V-ます bỏ ます + ましょう', 'Vます bỏ ます + ましょう để hô hào, rủ mọi người cùng làm, nhất là khi đã thống nhất: さあ、始めましょう. Hay đi với いっしょに, みんなで. Hỏi ý người nghe trước thì dùng 〜ませんか; đề nghị làm giúp thì dùng 〜ましょうか.', 'Hô hào, rủ rê cả nhóm; hay dùng trong lớp học.', 'Hay dùng ましょう để mời người trên ngay từ đầu, nghe hơi ép; lúc đó nên dùng ませんか.', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-981512c9b7', 'N5', 20, 351, 351, '〜? (lên giọng cuối câu)', '[]', '? (lên giọng cuối câu)', 'Hỏi kiểu thân mật\nBỏ luôn chữ か, chỉ lên giọng ở cuối: いく？ · たべた？', 'Câu thể thường + ？ (lên giọng ở cuối)', 'Câu danh từ thì bỏ cả だ khi hỏi: あした ひま？ chứ không nói ひまだ？', 'Rất thân mật, chỉ dùng với bạn bè, người nhà.', 'Hay dùng với người trên hoặc người lạ, nghe thiếu lịch sự. Khi viết nhớ thêm dấu ？ để người đọc hiểu đó là câu hỏi.', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-98aa8c57ac', 'N5', 6, 32, 32, '〜を', '["を"]', 'を', 'trợ từ chỉ đối tượng của hành động', 'N + を + V (tha động từ)', 'Đặt sau danh từ là đối tượng chịu tác động trực tiếp của hành động như ăn, uống, đọc, mua. を đọc giống お (“o”).', 'Trung tính; を luôn đứng ngay sau đối tượng và trước động từ.', 'Hay dùng を với 好き, 分かる, ある (sai: 日本語を分かります); những từ này đi với が. Cũng hay viết nhầm を thành お.', '[]', NULL, 'AI_CHECKED', 1, '3c5bc58917e7'),
('JG-98f65ef756', 'N5', 11, 357, 357, 'Bao nhiêu (cái, tuổi)', '[]', 'Bao nhiêu (cái, tuổi)', 'mấy cái; bao nhiêu tuổi', 'N + を・が + いくつ + V', 'いくつ hỏi số lượng đồ vật đếm bằng 〜つ (りんごはいくつありますか — 五つあります) và hỏi tuổi (おいくつですか là cách hỏi lịch sự). Hỏi giá thì dùng いくら, hỏi số người dùng 何人.', 'Hỏi số lượng vật đếm bằng 〜つ.', 'Hay dùng いくつ cho người; hỏi số người phải dùng 何人.', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-9965cb922d', 'N5', 13, 171, 171, '〜にします', '[]', 'にし', 'chọn …; quyết định lấy …', 'N + に + します', 'N に します: chọn, chốt một thứ trong nhiều thứ, hay dùng khi gọi món, chọn đồ, chốt ngày giờ: コーヒーにします, 会議は三時にします. Hỏi: 何にしますか (chọn gì?).', 'Trung tính, hay dùng khi gọi món, chọn đồ hoặc chốt ngày giờ.', 'Hay nói Nをします khi gọi món; chốt lựa chọn tự nhiên nhất là Nにします.', '["JG-7193124c6e"]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-9985533827', 'N5', 18, 94, 94, '〜から', '[]', 'から', 'từ (điểm xuất phát về nơi chốn hoặc thời gian)', 'N(nơi chốn / thời điểm) + から', 'Đặt sau danh từ chỉ nơi chốn hoặc thời điểm để nói điểm bắt đầu: đến từ đâu, bắt đầu từ lúc nào.', 'Trung tính; hay đi cặp với まで.', 'Hay nhầm から chỉ điểm xuất phát (sau danh từ) với から chỉ lý do (sau cả câu: 雨ですから). Khi nói quê quán đừng quên から: ベトナムから来ました.', '["JG-ae13357418","JG-377d5ee6df"]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-9a0666f2d9', 'N5', 14, 198, 198, 'Hãy làm...', '[]', 'Hãy làm...', 'hãy …; xin vui lòng … (nhờ người nghe làm)', 'V-て + ください', 'V-て + ください để nhờ, yêu cầu lịch sự: ここに名前を書いてください. Thêm すみませんが ở đầu cho mềm hơn. Không muốn người kia làm thì dùng Vないでください. Với danh từ: N を ください (cho tôi N).', 'Lịch sự, nhưng vẫn là lời yêu cầu.', 'Hay gắn ください vào thể ます hay thể từ điển (sai: 読みますください); phải dùng thể て: 読んでください.', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-9b200447f7', 'N5', 9, 222, 222, 'どうして 〜か', '[]', 'どうして 〜か', 'Hỏi vì sao\nĐặt どうして ở đầu câu hỏi; người trả lời đáp bằng vế có から.', 'どうして + Câu + か / どうして + 〜んですか', 'Hỏi どうして nhiều lần nghe gắt — trong công việc thường hỏi nhẹ hơn.', 'Trung tính; なぜ trang trọng hơn, なんで thân mật hơn.', 'Khi trả lời hay quên から ở cuối; nêu lý do nên kết thúc bằng 〜からです.', '["JG-d5f6d866ef","JG-171c3a58eb","JG-39f20e102c"]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-9b6265598a', 'N5', 3, 387, 387, 'Phía này / tôi / ở đây', '[]', 'Phía này / tôi / ở đây', 'phía này; vị này; bên chúng tôi (lịch sự)', 'こちら + は + N + です / N + は + こちらです', 'こちら là cách nói lịch sự của ここ / これ / この人: chỉ đường (お手洗いはこちらです), giới thiệu người (こちらは山田さんです), tự xưng bên mình trên điện thoại (こちらは田中です). Mời đi lối này: こちらへどうぞ.', 'Lịch sự; dùng để chỉ đường, giới thiệu người hoặc nói về phía mình.', 'Hay dùng これ để giới thiệu người; với người phải dùng こちら.', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-9b6cb8d29e', 'N5', 7, 194, 194, 'Cùng làm nhé?', '[]', 'Cùng làm nhé?', '… không?; lời mời lịch sự rủ người nghe cùng làm', 'V-ます bỏ ます + ませんか', 'Vます bỏ ます + ませんか để mời: 映画を見ませんか (đi xem phim không?). Thường thêm いっしょに. Nhận lời: ええ、いいですね / 〜ましょう; từ chối khéo: すみません、ちょっと…. Muốn đề nghị làm giúp người kia thì dùng 〜ましょうか, không dùng ませんか.', 'Lịch sự, trọng ý kiến của người nghe.', 'Hay hiểu là câu phủ định rồi trả lời いいえ khi muốn đồng ý.', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-9bb07b6431', 'N5', 6, 182, 182, 'N で N を V ます', '[]', 'N で N を V', 'Nói làm việc gì ở đâu\nChỗ đứng trước で, vật đứng trước を: しょくどうで ごはんを たべます.', 'N(nơi chốn) + で + N + を + V-ます', 'Thứ tự chỗ rồi mới tới vật nghe tự nhiên hơn ngược lại.', 'Trung tính; で chỉ nơi hành động diễn ra.', 'Hay dùng に cho nơi diễn ra hành động (sai: 図書館に本を読みます). Nơi chốn thường đứng trước, vật đứng ngay trước を.', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-9ce4ca1ba3', 'N5', 12, 250, 250, 'So sánh hơn', '[]', 'So sánh hơn', '… hơn …; so sánh hơn (N1 は N2 より)', 'N1 + は + N2 + より + A', 'N1 は N2 より A: N1 hơn N2; より gắn sau cái làm mốc so sánh: 今日は昨日より暑いです. Trả lời câu hỏi どちら thì hay dùng のほうが. "Không … bằng" là N1 は N2 ほど 〜ない.', 'Trung tính; より đứng sau mốc so sánh.', 'Hay đặt より sau thứ hơn hoặc thêm もっと không cần thiết.', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-9d12efd7d2', 'N5', 24, 110, 110, '〜てもらう', '[]', 'てもらう', 'được người khác làm cho … (mình nhận sự giúp đỡ)', 'N(người giúp) + に + V-て + もらう', 'Dùng khi người nói nhờ hoặc được người khác làm giúp một việc, nhìn từ phía người nhận.', 'Thể hiện sự biết ơn; muốn nhờ lịch sự thì dùng 〜てもらえますか.', 'Hay đặt người nhận trước に; đứng trước に là người giúp mình. Cũng hay nhầm với 〜てくれる: てくれる lấy người giúp làm chủ ngữ với が, てもらう lấy mình làm chủ ngữ.', '["JG-315e3a8560","JG-a412adf097","JG-cce238d8ca"]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-9d6ba97c98', 'N5', 18, 175, 175, 'Có thể làm gì', '[]', 'Có thể làm gì', 'có thể …; biết (làm gì)', 'N + が + できる / Vる + ことができる', 'N が できます: biết, làm được việc gì (日本語ができます, テニスができます). Vる + ことが できます: có thể làm, được phép làm (ここで写真をとることができます). Phủ định: できません. Luôn dùng が, không dùng を.', 'Trung tính; ことができる hơi trang trọng hơn thể khả năng.', 'Hay dùng を với できる (sai: 日本語をできます); đúng là 日本語ができます.', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-9da239be95', 'N5', 22, 379, 379, 'どんな N ですか / 〜は だれですか', '[]', 'どんな N ですか / 〜は だれですか', 'Hỏi về thứ được tả\nHỏi loại nào thì どんな, hỏi người thì だれ.', 'どんな + N + ですか / (cụm miêu tả) + N + は + だれですか', 'Đáp どんな nên đáp bằng cả cụm tả, đừng đáp mỗi một tính từ.', 'Trung tính.', 'Hay dùng どう trước danh từ, hoặc dùng なに để hỏi người (phải dùng だれ).', '["JG-2bed9c60a6"]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-9ddc3aa74e', 'N5', 16, 307, 307, 'V-て、V-て、V ます', '[]', 'V-て、V-て、V', 'Nối nhiều việc theo thứ tự\nCác việc giữa câu để đuôi て, chỉ việc CUỐI mới chia đuôi ます.', 'V1-て、V2-て、V3-ます', 'Thì của cả câu nằm ở động từ cuối — muốn kể chuyện hôm qua thì chỉ đổi chữ cuối thành ました.', 'Trung tính; kể các việc theo đúng thứ tự.', 'Hay chia ます ở các việc giữa câu; chỉ việc cuối cùng mới chia ます.', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-9e64c1e419', 'N5', 8, 47, 47, 'とても〜ない', '[]', 'とても〜ない', 'rất (phó từ chỉ mức độ đi với câu khẳng định)', 'とても + Aい / Aな (khẳng định); phủ định dùng あまり / ぜんぜん + 〜ない', 'とても đứng trước tính từ (hoặc 好き, 上手…) để nói mức độ cao: とても高いです (rất đắt). Cùng nhóm phó từ chỉ mức độ: phủ định nhẹ dùng あまり〜ない (không … lắm), phủ định hoàn toàn dùng ぜんぜん〜ない (hoàn toàn không). Ở N5, とても chỉ đi với câu khẳng định.', 'Trung tính, dùng được khi nói lẫn khi viết; とても nhấn mức độ cao, mạnh hơn すこし và ちょっと.', 'Người Việt hay dịch “không … lắm” thành とても〜ない (sai: とても高くないです); đúng là あまり高くないです. Muốn nói hoàn toàn không thì dùng ぜんぜん〜ない.', '["JG-6206aa1bf1"]', NULL, 'AI_CHECKED', 1, '3c5bc58917e7'),
('JG-a032789fb6', 'N5', 7, 202, 202, 'Tôi làm nhé?', '[]', 'Tôi làm nhé?', 'để tôi … nhé?; ngỏ ý làm giúp người nghe', 'V-ます bỏ ます + ましょうか', 'Vます bỏ ます + ましょうか để ngỏ ý làm giúp: 荷物を持ちましょうか (để tôi xách giúp nhé?). Nhận lời: ええ、お願いします; từ chối: いいえ、大丈夫です. Rủ người kia cùng làm thì dùng 〜ませんか.', 'Lịch sự, chu đáo; người nghe có thể nhận (お願いします) hoặc từ chối (いいえ、大丈夫です).', 'Hay nhầm với ませんか: ましょうか là ngỏ ý làm giúp, ませんか là rủ người kia cùng làm.', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-a08d454bb7', 'N5', 17, 322, 322, 'V なくても いいです', '[]', 'V なくても いい', 'Nói không làm cũng được\nĐuôi ない bỏ い rồi thêm くても いいです: こない → こなくても いいです.', 'Vない bỏ い + くてもいいです', 'Khác hẳn ないで ください: đây là được phép bỏ qua, không phải bị cấm.', 'Nhẹ nhàng, giúp người nghe yên tâm rằng việc đó không bắt buộc.', 'Hay quên bỏ い (sai: 行かないくてもいいです); đúng là 行かなくてもいいです.', '["JG-af79a30b59","JG-28b044ef5f"]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-a0cab321e3', 'N5', 10, 57, 57, 'が居(い)る', '[]', 'が居(い)る', 'có; ở (người hoặc động vật)', 'N(nơi chốn) + に + N(người, con vật) + が + いる (います)', 'Dùng để nói ở đâu có người hay con vật, hoặc mình có anh chị em, có bạn bè.', 'Trung tính; lịch sự là います.', 'Hay dùng あります cho người, con vật (sai: 子どもがあります); phải dùng います. Cây cối, đồ vật thì không dùng いる.', '[]', NULL, 'AI_CHECKED', 1, '3c5bc58917e7'),
('JG-a19d16d843', 'N5', 2, 8, 8, 'それ', '[]', 'それ', 'cái đó (đồ vật ở gần người nghe)', 'それ + は + N + です', 'Dùng để chỉ đồ vật ở gần người nghe, hoặc chỉ lại điều người kia vừa nói tới.', 'Trung tính; trong hội thoại それ còn dùng để nhắc lại chuyện vừa được nói.', 'Hay dùng それ cho mọi thứ “đó”, kể cả vật ở xa cả hai người; vật xa cả hai phải dùng あれ. Không nói それ本, phải là その本.', '[]', NULL, 'AI_CHECKED', 1, '3c5bc58917e7'),
('JG-a22c7a81d7', 'N5', 12, 249, 249, 'Là nhất', '[]', 'Là nhất', '… nhất; mức cao nhất trong một nhóm', '(N の中で) + N + が + いちばん + A', '(N の中で / N で) + N が いちばん A: 家族で母がいちばん早く起きます. いちばん đứng ngay trước tính từ hay động từ. Hỏi: どれ/なに/だれ/どこ/いつ + が いちばん 〜ですか. Không dùng より cùng với いちばん.', 'Trung tính; いちばん đứng ngay trước tính từ.', 'Hay dùng より cùng với いちばん, hoặc dùng どちら khi hỏi trong nhóm từ ba thứ trở lên.', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-a26325168e', 'N5', 14, 79, 79, '〜て下(くだ)さい', '[]', 'て下(くだ)さい', 'hãy …; xin hãy … (nhờ hoặc yêu cầu lịch sự)', 'V-て + ください', 'Dùng để nhờ người khác làm gì, chỉ dẫn hoặc mời mọc lịch sự.', 'Lịch sự nhưng vẫn là yêu cầu; với người trên muốn nhẹ hơn thì dùng 〜てくださいませんか.', 'Hay gắn ください vào thể ます (sai: 書きますください) hoặc thể từ điển (sai: 書くください); phải dùng thể て: 書いてください.', '[]', NULL, 'AI_CHECKED', 1, '3c5bc58917e7'),
('JG-a2e54fdcf3', 'N5', 5, 31, 31, '〜で', '["で"]', 'で', 'ở; tại (chỉ nơi diễn ra hành động)', 'N(nơi chốn) + で + V', 'Đặt で sau danh từ nơi chốn để chỉ chỗ hành động diễn ra: 図書館で勉強します (học ở thư viện). で còn chỉ phương tiện, cách thức: バスで (bằng xe buýt), 日本語で (bằng tiếng Nhật).', 'Trung tính; chỉ chỗ hành động diễn ra, không phải chỗ người hay vật đang có mặt.', 'Hay nhầm で với に: nơi diễn ra hành động dùng で (図書館で勉強します), còn nơi có người, vật dùng に (図書館に本があります).', '[]', NULL, 'AI_CHECKED', 1, '3c5bc58917e7'),
('JG-a344ddcd6a', 'N5', 16, 88, 88, 'どの', '[]', 'どの', '… nào (đứng trước danh từ để hỏi chọn một trong nhiều thứ)', 'どの + N', 'Đặt trước danh từ để hỏi người nghe chọn hoặc chỉ ra người, vật nào trong nhiều người, vật.', 'Trung tính; hỏi về người một cách lịch sự thì dùng どの方.', 'Hay để どの đứng một mình (sai: どのですか); đứng một mình phải dùng どれ. Khi どの + N làm chủ ngữ trong câu hỏi thì đi với が, không dùng は.', '["JG-5549d02710"]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-a3abb234e6', 'N5', 17, 323, 323, 'V なければ なりません', '[]', 'V なければ なりません', 'Nói việc buộc phải làm\nChuyển động từ sang đuôi ない, bỏ い rồi thêm ければ なりません: のみます → のまなければ なりません.', 'Vない bỏ い + ければなりません', 'Câu này dài nhưng là một khối — đừng ngắt hơi giữa なければ và なりません.', 'Lịch sự nhưng mạnh, nói việc bắt buộc.', 'Hay quên bỏ い (sai: 出さないければ). Khi chỉ muốn khuyên thì dùng 〜たほうがいいです.', '["JG-f02a27e408","JG-05589d014f"]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-a3ae2367dc', 'N5', 8, 50, 50, 'どれ', '[]', 'どれ', 'cái nào (hỏi chọn một trong ba thứ trở lên)', 'N + は + どれ + ですか / どれ + が + …', 'Dùng để hỏi trong nhiều vật (từ ba thứ trở lên) thì cái nào là cái người nghe nói tới hoặc chọn.', 'Trung tính; chọn giữa hai thứ thì dùng どちら.', 'Hay để danh từ ngay sau どれ (sai: どれ本); muốn kèm danh từ thì dùng どの本. Khi どれ làm chủ ngữ thì đi với が, không dùng は (sai: どれは安いですか).', '[]', NULL, 'AI_CHECKED', 1, '3c5bc58917e7'),
('JG-a412adf097', 'N5', 25, 112, 112, '〜ても・でも', '[]', 'ても・でも', 'dù … cũng …; cho dù …', 'V-て + も / Aい bỏ い + くても / Aな・N + でも', 'Dùng để nói dù vế trước xảy ra thì vế sau vẫn như vậy, ngược với điều người nghe có thể nghĩ.', 'Trung tính; nhấn rằng kết quả không đổi dù hoàn cảnh thế nào.', 'Hay nghĩ でも chỉ là “dù” cho mọi từ; động từ phải đi với thể て + も (sai: 雨が降るでも). Động từ có thể て là で thì thành でも: 飲んでも, 読んでも.', '["JG-315e3a8560","JG-9d12efd7d2","JG-cce238d8ca"]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-a5087b5e0b', 'N5', 13, 281, 281, '〜疑問詞か', '[]', '疑問詞か', 'cái gì đó; ai đó; đâu đó', 'Từ để hỏi (何・だれ・どこ・いつ) + か', 'Gắn か sau từ để hỏi để chỉ một thứ, một người, một nơi hay một lúc không xác định: cái gì đó, ai đó, đâu đó, lúc nào đó.', 'Câu hỏi có 〜か chỉ cần trả lời はい hoặc いいえ trước.', 'Hay trả lời câu hỏi 何か食べましたか bằng tên món ăn ngay; trước hết nên nói はい hoặc いいえ rồi mới nói thêm.', '["JG-7df651c4ab","JG-6b3f5d5c75"]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-a63f4456fb', 'N5', 5, 169, 169, 'N へ いきます/きます/かえります', '[]', 'N へ いきます/きます/かえり', 'Nói đi đâu, đến đâu, về đâu\nNơi đến đứng trước, へ nối vào rồi mới tới động từ.', 'N(nơi chốn) + へ + 行きます・来ます・帰ります', 'Chữ へ ở đây đọc là え, không đọc là へ.', 'Trung tính; へ chỉ hướng di chuyển.', 'Hay đọc へ là “he”; đọc đúng là “e”. Về nhà thì nói うちへ帰ります, không dùng 行きます.', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-a6edafd1b9', 'N5', 7, 39, 39, 'もう', '[]', 'もう', 'đã … rồi (đi với khẳng định); không … nữa (đi với phủ định)', 'もう + Vました / もう + Vません', 'Đặt trước động từ để nói việc đã xong rồi; đi với phủ định thì nghĩa là không còn làm việc đó nữa.', 'Trung tính; trong もう少し, もう一度 thì もう mang nghĩa “thêm”.', 'Được hỏi もう〜ましたか mà chưa làm, người Việt hay đáp いいえ、〜ませんでした; đúng là いいえ、まだです hoặc まだ〜ていません.', '["JG-13a8dada5f","JG-0e17041b0c"]', NULL, 'AI_CHECKED', 1, '3c5bc58917e7'),
('JG-a703e5d7b2', 'N5', 9, 269, 269, 'Hầu như, gần như', '[]', 'Hầu như, gần như', 'gần hết; hầu như không (với phủ định)', 'ほとんど + V (gần hết) / ほとんど + Vない (hầu như không)', 'ほとんど + câu khẳng định: gần hết (ほとんど終わりました). ほとんど + câu phủ định: hầu như không (ほとんど寝ませんでした). Trước danh từ dùng ほとんどの: ほとんどの人 (hầu hết mọi người).', 'Trung tính; nghĩa thay đổi tùy câu khẳng định hay phủ định.', 'Hay nhầm ほとんど〜ない (hầu như không) với ぜんぜん〜ない (hoàn toàn không).', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-a788659d89', 'N5', 14, 286, 286, 'なにを して いますか / どこで 〜て いますか', '[]', 'なにを して いますか / どこで 〜て いますか', 'Hỏi đang làm gì, ở đâu\nGiữ nguyên đuôi て います rồi thêm か.', 'なにを + して + いますか / どこで + V-て + いますか', 'Hỏi nghề nghiệp cũng dùng câu này: どんな しごとを して いますか.', 'Trung tính; hỏi việc đang làm hoặc công việc hằng ngày.', 'Hay hỏi どこに働いていますか; nơi làm việc đi với で: どこで働いていますか.', '["JG-c0e847d3fa","JG-294efa3571"]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-a88b294a8e', 'N5', 13, 289, 289, 'Ai cũng', '[]', 'Ai cũng', 'ai cũng; bất kỳ ai', 'だれでも + V (khẳng định)', 'だれでも đi với câu khẳng định để nói không giới hạn người: ai cũng làm được, ai cũng được phép. Hay đi với できます, わかります, 〜てもいいです. Muốn nói "không ai" thì dùng だれも + phủ định.', 'Nhấn tính bao quát, không phân biệt người nào.', 'Hay nhầm với だれも + phủ định (không ai): だれでもできます là ai cũng làm được, だれもできません là không ai làm được.', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-a96e6873a8', 'N5', 24, 111, 111, '〜てくれる', '[]', 'てくれる', '(người khác) làm … cho tôi', 'N(người giúp) + が + V-て + くれる', 'Dùng khi người khác làm một việc có ích cho người nói hoặc người trong nhóm mình.', 'Thể hiện sự cảm kích; nhờ vả lịch sự thì dùng 〜てくれませんか.', 'Hay dùng khi mình giúp người khác (lúc đó dùng 〜てあげる). Người được giúp là 私 thì thường lược đi, không cần nói 私に.', '["JG-8e21283b46","JG-41595b514a","JG-b4ac2012bf"]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-a9f81eee32', 'N5', 8, 272, 272, 'Không... lắm', '[]', 'Không... lắm', 'không … lắm; không … nhiều', 'あまり + Vない / Aくない', 'あまり + động từ hay tính từ ở dạng phủ định: あまり食べません, あまり高くないです, あまり便利じゃありません. Nhẹ hơn ぜんぜん〜ない. Câu khẳng định không dùng あまり.', 'Nhẹ nhàng, tế nhị.', 'Hay dùng あまり với khẳng định (sai: あまり食べます).', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-aca5cae25e', 'N5', 12, 292, 292, 'Hơn nữa', '[]', 'Hơn nữa', 'hơn nữa; thêm nữa', 'もっと + A / もっと + V', 'もっと đứng trước tính từ, phó từ hoặc động từ để nói mức độ cao hơn hiện tại: もっと大きい, もっとゆっくり, もっと食べてください. Muốn nói "thêm một chút" thì dùng もう少し; thêm một số lượng cụ thể thì dùng もう一度, もう一つ.', 'Trung tính; dùng để yêu cầu hoặc mong muốn mức độ cao hơn hiện tại.', 'Hay dùng もっと với số lượng cụ thể (✗ もっと一度, ✗ もっと一つ); thêm một lần, một cái phải nói もう一度, もう一つ.', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-ace2df3955', 'N5', 12, 69, 69, 'と〜と、どちらが', '[]', 'と〜と、どちらが', 'giữa … và … thì cái nào … hơn? (hỏi so sánh hai thứ)', 'N1 + と + N2 + と、どちらが + A + ですか', 'Dùng để hỏi người nghe trong hai thứ thì thứ nào hơn về một mặt nào đó.', 'Lịch sự, trung tính; trả lời bằng N1の方が〜です.', 'Hay dùng どれ cho hai thứ; so sánh hai thứ phải dùng どちら. Cũng hay dùng は sau どちら (sai: どちらは高いですか); phải là どちらが.', '["JG-e5790e7933","JG-bf7dd08411"]', NULL, 'AI_CHECKED', 1, '3c5bc58917e7'),
('JG-ada36ca505', 'N5', 25, 405, 405, 'N を かえます / ひっこします / かえります', '[]', 'N を かえます / ひっこします / かえり', 'Nói dự định đổi thay\nViệc lớn trong đời thường đi với mốc thời gian: らいねん けっこんします.', 'N + を + かえます / N(nơi chốn) + へ + ひっこします / N + へ + かえります', 'Chuyện chưa chắc thì nên thêm と おもいます cho nhẹ, đừng nói chắc như đinh.', 'Trung tính; hay đi với mốc thời gian như 来年, 来月.', 'Hay nhầm かえます (変える – đổi) với かえります (帰る – về) vì cách đọc gần giống nhau.', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-ae13357418', 'N5', 5, 166, 166, '<nơi> から <nơi> まで', '[]', '<nơi> から <nơi> まで', 'Nói đi từ đâu đến đâu\nGiống mốc giờ bài trước, nhưng lần này là mốc nơi chốn.', 'N(nơi chốn) + から + N(nơi chốn) + まで', 'Hai mốc hay đi cùng câu chỉ phương tiện: うちから えきまで あるいて いきます.', 'Trung tính; hay dùng khi nói đường đi và thời gian di chuyển.', 'Hay dùng へ thay cho まで khi nói phạm vi (sai: 家から駅へ何分ですか); nói khoảng cách dùng まで. Hỏi mất bao lâu thì thêm どのくらいかかりますか.', '["JG-9985533827","JG-377d5ee6df"]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-aecc9e94e2', 'N5', 19, 146, 146, 'Adjく なります – Trở nên (tính từ い)', '[]', 'Adjく なります – Trở nên (tính từ い)', 'trở nên …; chỉ sự thay đổi trạng thái của tính từ い', 'Aい bỏ い + く + なります', 'Aい bỏ い thêm く rồi đặt trước なります để nói một trạng thái tự thay đổi: 暑くなります (trời nóng lên), 高くなりました (đã đắt lên). Hay đi với だんだん, もっと. Riêng いい → よくなります. Nếu chính mình làm cho thay đổi thì dùng N を Aく します.', 'Trung tính; diễn tả sự thay đổi tự nhiên theo thời gian.', 'Hay dùng に (sai: 暑いになります); tính từ い phải đổi い thành く. いい đổi thành よくなります.', '["JG-dad75c9be2","JG-af886f1233","JG-0eeeecf6ed"]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-aed57cd119', 'N5', 20, 304, 304, '〜んです', '[]', 'ん', 'Nói rõ lý do của mình\nNgười ta hỏi rồi thì đáp bằng んです để nêu hoàn cảnh: ねつが あるんです.', 'V・Aい (thể thường) + んです / Aな・N + なんです', 'んです là kể hoàn cảnh, không phải thông báo suông. Nói việc bình thường mà cứ gắn んです thì nghe như lúc nào cũng có uẩn khúc.', 'Dùng để giải thích, nêu hoàn cảnh; dùng quá nhiều có thể nghe như biện hộ.', 'Với danh từ, tính từ な phải là なんです (sai: 雨んです).', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-aee65c5570', 'N5', 1, 114, 114, 'N は なんさい ですか', '[]', 'N は なんさい ですか', 'mấy tuổi (hỏi tuổi)', 'N + は + なんさい + ですか (lịch sự: おいくつですか)', 'Dùng なんさいですか để hỏi tuổi trẻ em hoặc người thân quen: この子はなんさいですか. Trả lời bằng số + さい: 七さいです. Với người lớn hoặc người mới gặp thì hỏi おいくつですか cho lịch sự.', 'なんさい dùng với trẻ em hoặc người thân quen; với người lớn nên hỏi おいくつですか cho lịch sự.', 'Hay hỏi tuổi người lớn tuổi hoặc người mới quen bằng なんさい, nghe thiếu lễ độ. Khi trả lời nhớ cách đọc đặc biệt: いっさい (1 tuổi), はっさい (8 tuổi), はたち (20 tuổi).', '["JG-d61be94fc2","JG-fc410c25b4","JG-322570640d"]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-af373390ef', 'N5', 7, 262, 262, '(〜に〜を)あげる', '[]', '(〜に〜を)あげる', 'cho; tặng (người khác)', 'N1(người nhận) + に + N2 + を + あげる', 'Dùng khi người nói hoặc ai đó cho, tặng vật cho một người khác.', 'Trung tính với bạn bè, người nhà; nói trực tiếp với người trên thì nên tránh.', 'Hay dùng あげる khi người khác cho mình; lúc đó phải dùng くれる.', '["JG-cf2d62eca8","JG-ea84df0587","JG-6bbd0fc52e"]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-af495d8f5e', 'N5', 8, 199, 199, 'Nhưng mà...', '[]', 'Nhưng mà...', 'nhưng …; nối hai ý trái ngược', 'Câu 1 + が、Câu 2 / Câu 1。でも、Câu 2', 'Có hai cách: nối trong một câu bằng が (高いですが、おいしいです) hoặc tách hai câu rồi mở câu sau bằng でも (高いです。でも、おいしいです). Hay dùng để so sánh hai thứ đối lập: にくは好きですが、さかなはきらいです.', 'が lịch sự, gắn cuối vế trước; でも thân mật hơn và đứng đầu câu sau.', 'Hay dùng でも ở cuối vế trước như が; でも luôn đứng đầu câu sau.', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-af79a30b59', 'N5', 17, 92, 92, '〜なくてもいい', '["なくてもいい"]', 'なくてもいい', 'không … cũng được (không cần làm)', 'Vない bỏ い + くてもいい(です)', 'Dùng để nói không làm việc gì cũng được, hoặc cho phép người khác không phải làm.', 'Nhẹ nhàng, giúp người nghe yên tâm; là cách nói ngược lại của なければならない.', 'Hay quên bỏ い (sai: 書かないくてもいい); dạng đúng là 書かなくてもいいです.', '["JG-a08d454bb7","JG-28b044ef5f"]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-af82b6346f', 'N5', 20, 354, 354, 'V る / A い / N だ', '[]', 'V る / A い / N', 'Nói thân mật ở hiện tại\nBỏ ます trả động từ về dạng gốc; tính từ đuôi い bỏ です; danh từ và tính từ đuôi な thay です bằng だ.', 'Vる / Aい / Aな・N + だ', 'Thể thông thường dùng khi nói với bạn bè, người nhà hoặc khi viết nhật ký: động từ ở thể từ điển (行く, 食べる), tính từ い giữ nguyên (寒い), tính từ な và danh từ thêm だ (しずかだ, 休みだ). Với người trên, người lạ vẫn dùng です / ます.', 'Thân mật; cũng là thể dùng trong nhật ký, văn viết thông thường.', 'Hay thêm だ sau tính từ い (sai: 寒いだ).', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-af886f1233', 'N5', 12, 67, 67, 'くなかった', '[]', 'くなかった', 'đã không … (quá khứ phủ định của tính từ い)', 'Aい bỏ い + くなかった(です) (高い → 高くなかった)', 'Dùng để nói trong quá khứ người, vật không có tính chất đó.', 'くなかった là thân mật; lịch sự là くなかったです hoặc くありませんでした.', 'Hay nói 高くないでした; đúng là 高くなかったです. いい đổi thành よくなかった.', '["JG-dad75c9be2","JG-0eeeecf6ed","JG-aecc9e94e2"]', NULL, 'AI_CHECKED', 1, '3c5bc58917e7'),
('JG-afacd1b137', 'N5', 19, 346, 346, 'V た ことが あります', '[]', 'V た ことが あり', 'Nói từng làm việc gì rồi\nĐộng từ để ở đuôi た rồi thêm ことが あります: いった ことが あります.', 'Vた + ことがあります', 'Đây là kể trải nghiệm trong đời, khác với いきました là kể một lần cụ thể.', 'Trung tính; nói về trải nghiệm trong đời.', 'Hay dùng thể từ điển (sai: 行くことがあります – nghĩa khác: thỉnh thoảng có đi).', '["JG-788cfc687d","JG-15239d5b3e","JG-4f10b05b40"]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-b003a8c5af', 'N5', 7, 34, 34, '〜ませんか', '[]', 'ませんか', '… không? (lời mời hoặc rủ rê lịch sự)', 'V-ます bỏ ます + ませんか', 'Gắn ませんか vào gốc ます của động từ để mời hoặc rủ người nghe một cách lịch sự: いっしょに映画を見ませんか (cùng xem phim không?). Người nghe nhận lời bằng ええ、いいですね; từ chối khéo bằng ちょっと….', 'Lịch sự, nhẹ nhàng, để người nghe tự quyết định; mềm hơn ましょう.', 'Người Việt hay hiểu theo mặt chữ là câu phủ định rồi đáp いいえ khi muốn nhận lời; đồng ý thì nói ええ、いいですね, từ chối khéo thì nói ちょっと….', '["JG-d78721df11","JG-0ef56ff856"]', NULL, 'AI_CHECKED', 1, '3c5bc58917e7'),
('JG-b0bf127675', 'N5', 11, 61, 61, 'くらい 1', '[]', 'くらい 1', 'khoảng; chừng (số lượng hoặc thời gian xấp xỉ)', 'Số lượng + くらい・ぐらい', 'Đặt sau con số chỉ lượng, khoảng thời gian, giá tiền để nói con số đó chỉ gần đúng.', 'Trung tính, hay dùng trong hội thoại; くらい và ぐらい dùng như nhau.', 'Với một mốc thời điểm (3時) thì ごろ tự nhiên hơn; くらい hợp với lượng thời gian (3時間くらい) và số lượng.', '[]', NULL, 'AI_CHECKED', 1, '3c5bc58917e7'),
('JG-b11836bb5b', 'N5', 13, 362, 362, 'Một ngày nào đó', '[]', 'Một ngày nào đó', 'một ngày nào đó; một lúc nào đó', 'いつか + V (thường ở tương lai)', 'いつか chỉ một thời điểm không xác định, thường trong tương lai, hay đi với 〜たいです hoặc 〜ましょう: いつか日本へ行きたいです, いつかまた会いましょう. Không dùng để hỏi; hỏi "khi nào" là いつ.', 'Chỉ một thời điểm không xác định, thường mang sắc thái mong ước.', 'Hay nhầm いつか (một lúc nào đó) với いつ (khi nào) và いつも (luôn luôn).', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-b2976be48a', 'N5', 14, 80, 80, '〜ている 1', '[]', 'ている 1', 'đang … (hành động đang diễn ra)', 'V-て + いる (います)', 'Dùng để nói một hành động đang diễn ra ngay lúc nói.', 'Trung tính; khi nói chuyện thân mật âm い thường bị nuốt: 食べてる.', 'Người Việt hay quên ている và nói 今食べます với nghĩa “đang ăn”; 食べます là sẽ ăn hoặc thường ăn, đang ăn phải là 食べています.', '["JG-4bf259bc32","JG-72a02e9fe6","JG-26e3b52ff4"]', NULL, 'AI_CHECKED', 1, '3c5bc58917e7'),
('JG-b355405f7b', 'N5', 7, 279, 279, 'Vẫn còn', '[]', 'Vẫn còn', 'vẫn còn; vẫn chưa (với phủ định)', 'まだ + V-ています / まだ + A', 'まだ + V-ています: vẫn đang … (まだ寝ています). まだ + V-ていません: vẫn chưa … (まだ食べていません); trả lời ngắn: いいえ、まだです. まだ + danh từ: mới chỉ … (まだ五時です). Trái nghĩa với もう (đã … rồi).', 'Trung tính; nhấn rằng trạng thái chưa thay đổi.', 'Hay nhầm まだ (vẫn còn, vẫn chưa) với もう (đã rồi, không còn nữa).', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-b37786c8d4', 'N5', 18, 328, 328, '〜ことが できますか / しゅみは なんですか', '[]', 'ことが できますか / しゅみは なんですか', 'Hỏi làm được không, hỏi sở thích\nThêm か vào cuối như mọi câu hỏi khác.', 'Vる + ことができますか / しゅみは + なんですか', 'Hỏi người mới quen thì hỏi sở thích dễ bắt chuyện hơn hỏi khả năng.', 'Trung tính; hay dùng khi làm quen để hỏi khả năng và sở thích.', 'Hay trả lời câu hỏi sở thích bằng một động từ đơn (sai: しゅみは読みます); phải dùng こと: しゅみは本を読むことです.', '["JG-7e2b2860b7"]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-b3ef186447', 'N5', 9, 268, 268, 'Đại khái, phần lớn', '[]', 'Đại khái, phần lớn', 'khoảng; đại khái; phần lớn', 'だいたい + V / だいたい + số lượng', 'Đặt だいたい trước số lượng để nói con số xấp xỉ (だいたい20分), hoặc trước động từ để nói làm được phần lớn (だいたいわかりました, だいたい終わりました). Không chỉ tần suất (đó là たいてい).', 'Trung tính, hay dùng khi nói.', 'Hay dùng だいたい như “rất”; nó chỉ có nghĩa xấp xỉ, phần lớn.', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-b4ac2012bf', 'N5', 14, 391, 391, '〜てくる', '[]', 'てくる', 'đi … rồi quay lại', 'V-て + くる (きます)', 'V-てきます: đi làm việc gì đó ở chỗ khác rồi quay lại chỗ cũ: ちょっと飲み物を買ってきます. 行ってきます là câu chào khi ra khỏi nhà (người ở nhà đáp いってらっしゃい). Đi mà không quay lại thì không dùng 〜てきます.', 'Thân thiện; 行ってきます là câu chào khi ra khỏi nhà.', 'Hay dùng 〜ていく khi ý là đi làm việc gì rồi quay lại; trường hợp đó dùng 〜てくる.', '["JG-a96e6873a8","JG-8e21283b46","JG-41595b514a"]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-b707f36b01', 'N5', 17, 321, 321, 'V ないで ください', '[]', 'V ないで ください', 'Xin người khác đừng làm\nGiữ nguyên đuôi ない rồi thêm で ください: またないで ください.', 'Vない + でください', 'Nhẹ hơn ては いけません nhiều — đây là lời xin, không phải nội quy.', 'Lịch sự, dùng để nhắc nhở hoặc nhờ người khác đừng làm gì.', 'Hay dùng thể ます (sai: 待ちませんでください); phải dùng thể ない: 待たないでください.', '["JG-1fe5b4d961","JG-71898a4777","JG-12f3c42e79"]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-b8666e3232', 'N5', 17, 204, 204, 'Xin đừng...', '[]', 'Xin đừng...', 'xin đừng …; nhờ người nghe không làm việc gì', 'Vない + でください', 'Vない + でください: 入る → 入らないでください. Dùng để nhắc nhở, nêu quy định một cách lịch sự. Với bạn bè có thể nói gọn 〜ないで. Không dùng 〜なくてください.', 'Lịch sự nhưng rõ ràng; hay dùng trong quy định, lời nhắc nhở.', 'Hay dùng thể ます (sai: 入りませんでください); phải dùng thể ない: 入らないでください.', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-b88ef2c09f', 'N5', 9, 276, 276, 'Thường xuyên', '[]', 'Thường xuyên', 'hay; thường xuyên', 'よく + V', 'よく + động từ: làm thường xuyên (よく公園へ行きます). Cũng có nghĩa "rõ, kỹ": よくわかります (hiểu rõ), よくわかりません (không hiểu rõ). Muốn nói "không hay làm" thì dùng あまり〜ません.', 'Trung tính; tần suất cao hơn ときどき.', 'Hay nhầm よく (hay, thường) với よく trong よく分かります (rõ, kỹ).', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-b8b2c363b5', 'N5', 4, 296, 296, 'Sắp, sắp sửa', '[]', 'Sắp, sắp sửa', 'sắp; sắp sửa', 'もうすぐ + N / V', 'もうすぐ + N です hoặc もうすぐ + Vます để nói việc sắp đến trong thời gian gần: もうすぐ夏休みです, もうすぐ電車が来ます. もうすぐ không đi với quá khứ.', 'Thân mật, nhẹ nhàng; chỉ việc sắp đến rất gần.', 'Hay nhầm もうすぐ (sắp) với もう (đã rồi).', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-b9c46937cc', 'N5', 13, 318, 318, 'Ở đâu đó', '[]', 'Ở đâu đó', 'đâu đó; nơi nào đó', 'どこか + へ・に・で + V', 'どこか chỉ một nơi không xác định. Thêm trợ từ theo động từ: どこかへ行きます, どこかで会いました, どこかに置きました. Câu hỏi どこかへ行きましたか chỉ cần đáp はい / いいえ. Muốn nói "không đi đâu cả" thì dùng どこへも + phủ định.', 'Chỉ một nơi không xác định; câu hỏi chỉ cần trả lời はい hoặc いいえ.', 'Hay nhầm どこか (đâu đó) với どこ (ở đâu): どこへ行きますか hỏi đi đâu, どこかへ行きますか hỏi có đi đâu không.', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-b9ff41658f', 'N5', 13, 402, 402, '〜がほしい', '[]', 'がほしい', 'Biểu thị ý muốn có một cái gì đó.', 'N + が + ほしい(です)', 'Dùng để nói người nói muốn có một vật hay một điều gì; hỏi người nghe thì dùng 何がほしいですか.', 'Nói thẳng mong muốn của bản thân; không dùng để nói mong muốn của người thứ ba.', 'Hay dùng を (sai: 部屋をほしい). ほしい là tính từ い nên quá khứ là ほしかった, phủ định là ほしくない.', '["JG-27ad6cf551"]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-bbb41c1257', 'N5', 5, 152, 152, 'Đến (từ nơi khác)', '[]', 'Đến (từ nơi khác)', 'đến; đến chỗ người nói hoặc nơi đang nói tới', 'N(nơi chốn) + へ・に + 来ます / N + から + 来ます / V-ます bỏ ます + に + 来ます', 'Nơi đến + へ/に + 来ます; nơi xuất phát + から + 来ます; đến để làm gì: Vます bỏ ます + に + 来ます (遊びに来ます). Dùng 来ます khi hướng về phía người nói đang ở; mình đi đến chỗ người nghe thì nói 行きます.', 'Trung tính; hướng về phía người nói hoặc nơi đang được nhắc tới.', 'Hay dùng 来ます khi mình đi đến chỗ người nghe; tiếng Nhật lúc đó dùng 行きます. Quá khứ 来ました đọc là きました.', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-bcf7e368d0', 'N5', 1, 120, 120, 'Tên người + さん', '[]', 'Tên người + さん', 'anh; chị (cách gọi lịch sự gắn sau tên người khác)', 'Họ / tên + さん', 'Gắn さん sau họ hoặc tên của người khác để gọi hoặc nhắc đến họ một cách lịch sự, dùng cho cả nam lẫn nữ: 田中さん, マイさん. Không gắn さん sau tên của chính mình.', 'Lịch sự, trung tính, dùng cho cả nam lẫn nữ; với trẻ em thân thiết có thể dùng くん, ちゃん.', 'Không gắn さん vào tên của chính mình (sai: 私はリンさんです). Gọi giáo viên thì dùng 先生 thay cho さん.', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-bdf7557863', 'N5', 5, 167, 167, 'N で いきます', '[]', 'N で いき', 'Nói đi bằng phương tiện gì\nPhương tiện đứng trước で: でんしゃで、バスで、じてんしゃで.', 'N(phương tiện) + で + 行きます・来ます・帰ります', 'Đi bộ là ngoại lệ, nói あるいて chứ không nói あしで.', 'Trung tính; phương tiện đi lại đứng trước で.', 'Hay nói 足で行きます cho đi bộ; đúng là 歩いて行きます. Lên xe thì dùng に乗ります, không dùng で乗ります.', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-be2024a8f0', 'N5', 18, 215, 215, '〜のがすき・きらい', '[]', 'のがすき・きらい', 'thích hay ghét làm việc gì; giỏi hay kém làm việc gì', 'V(thể từ điển) + のが + すき・きらい・上手・下手', 'Dùng để nói mình thích, ghét, giỏi hay kém một việc làm nào đó; động từ phải được danh từ hóa bằng の trước が.', 'Tự nhiên, dùng nhiều trong hội thoại.', 'Hay bỏ の (sai: 歌うが好き) hoặc dùng thể ます (sai: 歌いますのが好き).', '["JG-06ffc763fd"]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-bf4a4fe660', 'N5', 15, 260, 260, '〜てはいけません', '[]', 'てはいけません', 'không được …; cấm làm việc gì', 'V-て + はいけません', 'Dùng để nói một việc bị cấm, không được làm, thường là quy định hoặc lời răn dạy.', 'Mạnh và cứng; không nên dùng để nói với người trên.', 'Hay nhầm với lời cho phép; 〜てもいいです mới là cho phép, 〜てはいけません là cấm.', '["JG-c048f762e3","JG-c866613c1f"]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-bf7dd08411', 'N5', 12, 258, 258, 'N1 と N2 と どちらが Aですか / どれが いちばん Aですか', '[]', 'N1 と N2 と どちらが Aですか / どれが いちばん Aですか', 'Hỏi cái nào hơn, cái nào nhất\nHai thứ thì dùng どちら, từ ba thứ trở lên thì どれ (người thì だれ).', 'N1 と N2 と どちらが A ですか / (N の中で) どれが いちばん A ですか', 'Hỏi hai thứ mà dùng どれ là sai — どちら mới đúng cho cặp đôi.', 'Hai thứ dùng どちら, từ ba thứ trở lên dùng どれ (người thì だれ, nơi thì どこ).', 'Hay dùng どれ cho hai thứ hoặc どちら cho nhóm nhiều thứ.', '["JG-ace2df3955","JG-e5790e7933"]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-bfd00d52d1', 'N5', 6, 130, 130, 'Tân ngữ, đối tượng hành động', '[]', 'Tân ngữ, đối tượng hành động', 'trợ từ chỉ đối tượng của hành động; chỉ nơi đi qua hoặc nơi rời khỏi', 'N + を + V(tha động từ) / N(nơi chốn) + を + V(di chuyển)', 'Đặt を sau danh từ là đối tượng chịu tác động của hành động: パンを食べます. Với động từ di chuyển, を chỉ nơi đi qua (公園を散歩します, 道を渡ります) hoặc nơi rời khỏi (家を出ます, バスを降ります). Khoảng thời gian (三時間) đứng thẳng trước động từ, không cần を.', 'Trung tính; を với động từ di chuyển chỉ chỗ đi qua hoặc chỗ rời khỏi.', 'Hay dùng で cho nơi đi qua; “đi dạo qua công viên” là 公園を散歩します. Rời khỏi nơi nào cũng dùng を: 家を出ます.', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-bff0e28443', 'N5', 25, 404, 404, '〜たら、どう しますか / いつ 〜か', '[]', 'たら、どう しますか / いつ 〜か', 'Hỏi nếu thế thì tính sao\nĐặt vế điều kiện trước rồi mới hỏi どう しますか.', 'Vた + ら、どうしますか / いつ + V-ますか', 'Đáp nên nhắc lại vế điều kiện cho rõ, đừng đáp trống mỗi một việc.', 'Trung tính; dùng để hỏi dự định trong một tình huống giả định.', 'Hay dùng と thay たら (sai: お金があると、何をしますか); hỏi dự định nên dùng たら.', '["JG-3976c1fc65","JG-f539f37a62"]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-c022d2e5f6', 'N5', 4, 24, 24, 'う-Verb (Past)', '[]', 'う-Verb (Past)', 'đã … (dạng quá khứ thân mật của động từ nhóm I)', 'く → いた, ぐ → いだ, う・つ・る → った, む・ぶ・ぬ → んだ, す → した (書く → 書いた)', 'Dùng khi kể việc đã xảy ra trong lối nói thân mật; nói lịch sự thì dùng 〜ました.', 'Thân mật; nghĩa giống dạng ました.', 'Hay quên ngoại lệ 行く → 行った (không phải 行いた), và chia nhầm 飲む thành 飲った; đúng là 飲んだ.', '[]', NULL, 'AI_CHECKED', 1, '3c5bc58917e7'),
('JG-c048f762e3', 'N5', 15, 82, 82, '〜てはいけない', '[]', 'てはいけない', 'không được … (cấm đoán)', 'V-て + はいけない (はいけません)', 'Gắn はいけません vào thể て của động từ để nói việc bị cấm, hay dùng cho nội quy, biển báo hoặc khi người trên nhắc người dưới: ここでたばこをすってはいけません (không được hút thuốc ở đây). Đáp câu xin phép 〜てもいいですか bằng いいえ、〜てはいけません là từ chối dứt khoát.', 'Mạnh, mang tính cấm đoán; thường dùng cho nội quy, luật lệ hoặc khi người trên nói với người dưới.', 'Hay dùng để từ chối lời xin phép của người trên, nghe rất cứng; với người trên nên nói すみません、ちょっと…. Không dùng thể từ điển trước はいけない (sai: 入るはいけない).', '["JG-bf4a4fe660","JG-c866613c1f"]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-c0e847d3fa', 'N5', 6, 186, 186, 'なにを V ますか / どこで V ますか', '[]', 'なにを V ますか / どこで V ますか', 'Hỏi ăn gì, làm ở đâu\nHỏi vật thì thay chỗ vật bằng なに, hỏi chỗ thì thêm どこで.', 'なにを + V-ますか / どこで + V-ますか', 'Chỗ diễn ra hành động đi với で, khác với へ chỉ nơi đến của bài trước.', 'Trung tính; dùng để hỏi nội dung hoặc nơi chốn của hành động.', 'Hay dùng どこに thay cho どこで khi hỏi nơi làm việc gì. Hỏi “có làm gì không” thì dùng 何か, không phải 何を.', '["JG-294efa3571","JG-a788659d89"]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-c2de063a13', 'N5', 9, 52, 52, '好(す)き', '[]', '好(す)き', 'thích (tính từ な nói về sở thích)', 'N + が + 好き(です) / 好きな + N', 'Dùng để nói mình thích người, vật hay việc gì; thứ được thích đứng trước が.', 'Trung tính; 大好き là rất thích. Nói thẳng 好きです với một người còn có nghĩa là tỏ tình.', 'Hay dùng を (sai: 音楽を好きです); đúng là 音楽が好きです. 好き là tính từ な nên phủ định là 好きじゃないです, không phải 好きくない.', '[]', NULL, 'AI_CHECKED', 1, '3c5bc58917e7'),
('JG-c5b9bc987b', 'N5', 11, 248, 248, 'Khoảng chừng...', '[]', 'Khoảng chừng...', 'khoảng; chừng (số lượng; thời gian)', 'Số lượng + くらい・ぐらい', 'Số lượng hay khoảng thời gian + くらい/ぐらい: 20分くらい, 千円ぐらい, 30人ぐらい. くらい và ぐらい dùng như nhau. Mốc thời điểm (3時, 4月) thì dùng ごろ.', 'Trung tính; くらい và ぐらい dùng như nhau.', 'Hay dùng くらい cho thời điểm; nói thời điểm thì ごろ tự nhiên hơn (3時ごろ).', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-c645b96cd3', 'N5', 20, 101, 101, 'だ', '[]', 'だ', 'là … (dạng thân mật của です)', 'N / Aな + だ', 'Dùng ở cuối câu danh từ hoặc tính từ な khi nói chuyện thân mật, viết nhật ký hoặc văn viết thông thường.', 'Thân mật, có thể nghe cộc với người lạ; khi nói chuyện, nữ giới thường bỏ だ.', 'Hay gắn だ sau tính từ い (sai: 高いだ); tính từ い đứng một mình là đủ: 高い. Câu hỏi thân mật không dùng だか (sai: 学生だか).', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-c6f7a485c1', 'N5', 7, 297, 297, 'Vẫn chưa', '[]', 'Vẫn chưa', 'vẫn chưa; chưa; vẫn còn', 'まだ + V-ていません', 'まだ + V-ていません = vẫn chưa làm (tính đến lúc nói). Đáp ngắn câu hỏi もう〜ましたか: いいえ、まだです. まだ + câu khẳng định = vẫn còn: まだ時間があります, 兄はまだ学生です.', 'Trung tính; ngầm ý việc đó sẽ làm sau.', 'Hay nói まだ〜ません (sai: まだ食べません với nghĩa chưa ăn); đúng là まだ食べていません.', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-c734b6727f', 'N5', 21, 207, 207, '〜とおもう', '[]', 'とおもう', 'Biểu thị cảm nghĩ của người nói.', 'Câu (thể thường) + とおもう (とおもいます)', 'Dùng để nêu suy nghĩ, ý kiến hoặc phỏng đoán của người nói.', 'Làm câu mềm hơn, bớt khẳng định.', 'Hay để vế trước ở thể lịch sự (sai: 来ますとおもいます). Danh từ, tính từ な phải thêm だ: いい天気だとおもいます.', '["JG-e0f65d2af2"]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-c866613c1f', 'N5', 15, 299, 299, 'V ては いけません', '[]', 'V ては いけません', 'Nói việc đó không được làm\nCũng từ đuôi て: たばこを すっては いけません.', 'V-て + はいけません', 'Câu này nặng, thường là nội quy. Từ chối trong đời thường thì nói ちょっと... cho nhẹ.', 'Mạnh, mang tính cấm; hay dùng cho nội quy.', 'Hay dùng để từ chối lời xin phép của người trên, nghe rất cứng.', '["JG-c048f762e3","JG-bf4a4fe660"]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-c8c347b62f', 'N5', 9, 53, 53, '嫌(きら)い', '[]', '嫌(きら)い', 'ghét; không thích (tính từ な)', 'N + が + 嫌い(です) / 嫌いな + N', 'Dùng để nói mình ghét, không ưa người, vật hay việc gì.', 'Khá mạnh; muốn nói nhẹ nhàng thì dùng あまり好きじゃないです.', 'Vì tận cùng bằng い nên hay chia như tính từ い (sai: 嫌くない); 嫌い là tính từ な: 嫌いじゃない, 嫌いな食べ物.', '[]', NULL, 'AI_CHECKED', 1, '3c5bc58917e7'),
('JG-c9090d7d75', 'N5', 10, 403, 403, 'Tổng hợp ngữ pháp N5 dễ nhầm', '[]', 'Tổng hợp ngữ pháp N5 dễ nhầm', 'phân biệt các trợ từ dễ nhầm ở N5', 'は (chủ đề) / が (chủ thể, tồn tại) / に (nơi tồn tại, thời điểm, đích đến) / で (nơi hành động, phương tiện) / を (tân ngữ, nơi rời khỏi)', 'Các trợ từ hay nhầm ở N5: は nêu chủ đề (私は学生です); が đánh dấu chủ thể, đi với từ để hỏi (だれが来ましたか) và với あります / います, 好き, わかる; に chỉ nơi tồn tại, thời điểm, đích đến (教室に先生がいます, 七時に起きます); で chỉ nơi diễn ra hành động và phương tiện (図書館で勉強します, バスで行きます); を chỉ tân ngữ và nơi rời khỏi (パンを食べます, うちを出ます). Học theo cả câu mẫu, không dịch từng chữ từ tiếng Việt.', 'Mỗi cặp có chức năng và sắc thái riêng; phải chọn theo ngữ cảnh chứ không dịch từng chữ từ tiếng Việt.', 'Người Việt hay dịch từng chữ nên nhầm に với で: ✗ 教室で先生がいます → ✓ 教室に先生がいます; ✗ 図書館に勉強します → ✓ 図書館で勉強します. Từ để hỏi làm chủ ngữ đi với が, không đi với は.', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-c9a23c6309', 'N5', 12, 71, 71, 'の中(なか)で', '[]', 'の中(なか)で', 'trong số … (giới hạn phạm vi khi so sánh)', 'N(nhóm) + の中で', 'Đặt sau danh từ chỉ một nhóm (môn thể thao, mùa, đồ ăn…) để nêu phạm vi khi chọn ra cái nhất.', 'Trung tính; thường đi với いちばん.', 'Hay dùng の中に (chỉ vị trí bên trong) khi so sánh; so sánh trong một nhóm phải dùng の中で.', '["JG-25b6c4e2da"]', NULL, 'AI_CHECKED', 1, '3c5bc58917e7'),
('JG-c9d936878e', 'N5', 9, 56, 56, '全然(ぜんぜん)', '[]', '全然(ぜんぜん)', 'hoàn toàn không; chẳng … chút nào (đi với phủ định)', 'ぜんぜん + Vない / Aくない / Aな じゃない', 'Dùng để phủ định hoàn toàn về mức độ hay tần suất: không hiểu chút nào, không bao giờ đi.', 'Mạnh hơn あまり〜ない; giới trẻ đôi khi dùng ぜんぜん với khẳng định nhưng người học N5 nên tránh.', 'Hay dùng với câu khẳng định như chữ “hoàn toàn” trong tiếng Việt (sai: ぜんぜんいいです); ở N5 hãy luôn để ぜんぜん đi với phủ định.', '[]', NULL, 'AI_CHECKED', 1, '3c5bc58917e7'),
('JG-ca33c31154', 'N5', 13, 179, 179, 'Muốn làm gì', '[]', 'Muốn làm gì', 'muốn làm …', 'V-ます bỏ ます + たい(です)', 'Vます bỏ ます + たいです: 行きます → 行きたいです. Tân ngữ dùng を hoặc が đều được (水を/が飲みたい). たい biến đổi như tính từ い: たくない (không muốn), たかった (đã muốn). Chỉ dùng cho mong muốn của mình hoặc để hỏi người nghe.', 'Nói mong muốn chủ quan; hỏi người trên muốn gì thì nên tránh 〜たいですか.', 'Hay ghép たい vào thể từ điển (sai: 行くたい); phải bỏ ます: 行きたい. Phủ định là 〜たくない.', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-ca50c3824a', 'N5', 9, 361, 361, 'Luôn luôn', '[]', 'Luôn luôn', 'luôn luôn; lúc nào cũng', 'いつも + V / いつも + A', 'いつも chỉ thói quen, tần suất rất cao: いつも7時に起きます. いつもは … が、きょうは … = bình thường thì …, nhưng hôm nay …. いつもの + N = N quen thuộc như mọi khi. Khác いつでも (lúc nào cũng được).', 'Chỉ tần suất cao nhất; いつもは dùng để nêu thói quen thường ngày rồi đối lập với hôm nay.', 'Hay nhầm いつも (luôn luôn) với いつでも (lúc nào cũng được).', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-cc187b894c', 'N5', 19, 324, 324, '〜くなる・になる', '[]', 'くなる・になる', 'trở nên …; trở thành …', 'Aい bỏ い + くなる / Aな・N + になる', 'Dùng để nói trạng thái, tính chất thay đổi: trở nên nóng, trở nên yên tĩnh, trở thành sinh viên.', 'Diễn tả sự thay đổi tự nhiên, không do ai cố ý.', 'Hay dùng nhầm く và に giữa hai loại tính từ (sai: 暖かいになる, 静かくなる).', '["JG-dad75c9be2","JG-af886f1233","JG-0eeeecf6ed"]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-cc98d9f7f9', 'N5', 18, 176, 176, 'Danh từ hóa động từ', '[]', 'Danh từ hóa động từ', '～ること danh hóa mệnh đề động từ: “việc …”, “điều …”. Dùng để: Đặt làm chủ ngữ/chủ đề: 食べることは大切です。 Kết hợp tính từ/động từ chỉ đánh giá: ピアノを弾くことが好きです。 Định nghĩa, mô tả quy tắc/ thói quen: 朝早く起きること。 Sắc thái: trang trọng, chung chung/khái quát hơn so với の.', 'Vる + こと + は・が・を …', 'Vる + こと biến cả cụm động từ thành danh từ "việc …", rồi dùng は, が, を như danh từ: 歩くことは体にいいです, 料理を作ることが好きです. Hay gặp trong しゅみは〜ことです và 〜ことができます.', 'Hơi trang trọng hơn の; hay dùng khi viết và trong các mẫu cố định như ことができる, しゅみは〜ことです.', 'Hay dùng thể ます hoặc thể て trước こと (sai: 読みますこと, 読んでこと); trước こと luôn là thể từ điển. Hay quên trợ từ sau こと (sai: 読むこと好きです).', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-cce238d8ca', 'N5', 15, 265, 265, '〜てもいい', '[]', 'てもいい', 'Biểu thị ý nghĩa có thể làm được một việc gì đó hoặc cho phép ai đó làm gì đó.', 'V-て + もいい(です)', 'V-て + もいいです: được phép làm. Thêm か để xin phép: 〜てもいいですか. Đồng ý: ええ、いいですよ / どうぞ; từ chối: すみません、ちょっと…. Cấm thì dùng 〜てはいけません.', 'Lịch sự vừa phải; thêm か để xin phép.', 'Hay quên も hoặc dùng thể từ điển (sai: 使うもいいですか).', '["JG-315e3a8560","JG-9d12efd7d2","JG-a412adf097"]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-cd0810d52a', 'N5', 19, 409, 409, '〜くする・にする', '[]', 'くする・にする', 'Biểu thị tác động với đối tượng để nó chuyển sang một tình trạng khác.', 'N + を + Aい bỏ い + くする / N + を + Aな・N + にする', 'Dùng khi người làm chủ động tác động để vật chuyển sang trạng thái khác.', 'Khác với くなる, になる là thay đổi tự nhiên.', 'Hay dùng が thay cho を, hoặc nhầm く và に giữa hai loại tính từ (sai: 静かくする).', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-ce2a3e0a24', 'N5', 6, 33, 33, 'する', '[]', 'する', 'làm (động từ nhóm III hay ghép với danh từ chỉ hoạt động)', 'N + を + する / N + する (勉強する); します・しない・した', 'Dùng để nói làm một việc gì: chơi thể thao, làm bài tập, đi mua sắm. Ghép với danh từ như 勉強, 買い物, 散歩 để thành động từ.', 'Trung tính và rất thông dụng; dạng lịch sự là します.', 'する là động từ nhóm III nên chia bất quy tắc: しない, した (không phải すない, すった). Đừng thêm を hai lần (sai: 日本語を勉強をします).', '[]', NULL, 'AI_CHECKED', 1, '3c5bc58917e7'),
('JG-cf2d62eca8', 'N5', 7, 191, 191, 'N1 に N2 を もらいます/かります/ならいます', '[]', 'N1 に N2 を もらいます/かります/ならい', 'Nhận của ai cái gì\nCũng dùng に nhưng chiều ngược lại: người cho đứng trước に, còn mình là người nhận.', 'N1(người cho) + に・から + N2 + を + もらいます・かります・ならいます', 'かります (mượn) và ならいます (học của ai) đi cùng kiểu câu này.', 'Trung tính; nhìn sự việc từ phía người nhận.', 'Hay đặt người nhận trước に; đứng trước に là người cho, người cho mượn hoặc người dạy.', '["JG-ea84df0587","JG-af373390ef","JG-6bbd0fc52e"]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-cf564a194a', 'N5', 13, 266, 266, '〜ほしくないです / 〜たくないです', '[]', 'ほしくないです / 〜たくない', 'Nói không muốn\nCả hai đều là đuôi い nên chuyển thành くない như tính từ.', 'N + は + ほしくないです / V-ます bỏ ます + たくないです', 'Từ chối thẳng bằng たくないです nghe hơi cụt — thêm lý do vào cho nhẹ.', 'Lịch sự; nói thẳng ý không muốn, nên dùng nhẹ nhàng với người trên.', 'Hay nói ほしいじゃない, たいじゃない; ほしい và たい chia như tính từ い: ほしくない, たくない.', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-cfdb9268c3', 'N5', 10, 232, 232, '〜ありません / 〜いません', '[]', 'ありません / 〜いません', 'Nói không có gì, không có ai\nĐổi đuôi ます thành ません như mọi động từ khác.', 'N + は・が + ありません / いません', 'だれも và なにも bắt buộc đi với đuôi phủ định.', 'Lịch sự; là phủ định của あります, います.', 'Hay dùng ありません cho người (sai: 兄弟がありません); với người, con vật phải dùng いません.', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-d017a1430a', 'N5', 1, 270, 270, 'Hoặc... hoặc...', '[]', 'Hoặc... hoặc...', 'hoặc; hay (chọn một)', 'N1 + か + N2 (+ か) / V(thể thường) + か + Vない + か', 'N1 か N2: chọn một trong hai (電車かバスで行きます). V thể thường か Vない か: có … hay không (行くか行かないか、わかりません). Khác と (cả hai) và や (liệt kê vài thứ).', 'Trung tính; nêu các khả năng để chọn.', 'Hay dùng と thay か khi chỉ chọn một; と là cả hai.', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-d0877576b7', 'N5', 8, 145, 145, 'Adjく V – Dạng trạng từ của tính từ い', '[]', 'Adjく V – Dạng trạng từ của tính từ い', 'biến tính từ い thành trạng từ (bỏ い thêm く); làm gì một cách …', 'Aい bỏ い + く + V (早く起きる)', 'Đặt Aく ngay trước động từ để nói hành động được làm thế nào: 早く起きます (dậy sớm), 大きく書きます (viết to), 楽しく遊びます (chơi vui vẻ). Riêng いい đổi thành よく. Tính từ な thì dùng に thay cho く: 静かに話します.', 'Trung tính; く biến tính từ い thành từ chỉ cách làm.', 'Hay giữ nguyên い trước động từ (sai: 早い起きます) hoặc dùng に như tính từ な (sai: 早いに). Riêng いい đổi thành よく.', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-d19a5724f2', 'N5', 8, 43, 43, 'な-Adjective', '[]', 'な-Adjective', 'tính từ đuôi な (cần な khi đứng trước danh từ)', 'Aな + N (静かな部屋); Aな bỏ な + です (静かです)', 'Dùng để miêu tả tính chất như yên tĩnh, nổi tiếng, tiện lợi; đứng trước danh từ thì giữ な, đứng cuối câu thì bỏ な.', 'Cuối câu dùng です là lịch sự, dùng だ là thân mật.', 'Hay quên な trước danh từ (sai: 静か部屋) hoặc giữ な ở cuối câu (sai: 静かなです). きれい, ゆうめい tuy nghe như đuôi い nhưng là tính từ な.', '[]', NULL, 'AI_CHECKED', 1, '3c5bc58917e7'),
('JG-d1a68b3e70', 'N5', 1, 214, 214, '〜たち', '[]', 'たち', 'Dạng số nhiều của danh từ hoặc đại từ chỉ người.', 'N(người) + たち (私たち, 子どもたち)', 'Gắn sau danh từ hoặc đại từ chỉ người để chỉ số nhiều: chúng tôi, các bạn, bọn trẻ.', 'Trung tính; nói lịch sự về người khác thì dùng 〜がた (先生がた).', 'Hay gắn たち vào đồ vật (sai: 本たち). Khi đã có số lượng cụ thể thì thường không cần たち.', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-d3d086fcc7', 'N5', 2, 238, 238, '〜こ・そ・あ・ど', '[]', 'こ・そ・あ・ど', 'Từ chỉ thị. Khi chỉ đồ vật thì sẽ thành「これ・それ・あれ・どれ」, khi chỉ nơi chốn thì sẽ thành「ここ・そこ・あそこ・どこ」, còn khi bổ ngữ cho danh từ thì thành「このN・そのN・あのN・どのN」.', 'こ・そ・あ・ど + れ (vật) / こ (nơi chốn) / の + N / ちら (lịch sự)', 'Dùng để chỉ người, vật, nơi chốn theo khoảng cách: こ gần người nói, そ gần người nghe, あ xa cả hai, ど để hỏi.', 'Nhóm ちら (こちら, そちら, あちら, どちら) là dạng lịch sự.', 'Hay trộn các nhóm, ví dụ dùng これ cho nơi chốn hoặc để この đứng một mình.', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-d5f6d866ef', 'N5', 16, 239, 239, '〜どうやって', '[]', 'どうやって', 'Cách hỏi phương pháp để tiến hành một hành động nào đó.', 'どうやって + V + か', 'Dùng để hỏi cách làm hoặc cách đi: làm bằng cách nào, đi bằng gì.', 'Trung tính; khi trả lời thường dùng thể て nối các bước.', 'Hay nhầm với どう (thấy thế nào); hỏi cách thức phải dùng どうやって.', '["JG-9b200447f7","JG-171c3a58eb","JG-39f20e102c"]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-d604d684d2', 'N5', 3, 139, 139, 'N は どこ ですか / どちら ですか', '[]', 'N は どこ ですか / どちら ですか', 'ở đâu (hỏi nơi chốn và どちら là cách hỏi lịch sự hơn)', 'N + は + どこ・どちら + ですか', 'Nói tên nơi cần tìm trước rồi hỏi: トイレはどこですか. Với khách, người lạ hoặc trong cửa hàng thì dùng どちら cho lịch sự; どちら còn dùng để hỏi lịch sự về nước, công ty: お国はどちらですか.', 'どちら lịch sự hơn どこ, hay dùng với khách hoặc trong cửa hàng.', 'Hay đặt どこ lên đầu câu (sai: どこはトイレですか). Hỏi quê, công ty của người khác một cách lịch sự thì dùng どちら.', '["JG-e99ec187f7","JG-894fbb47aa"]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-d61be94fc2', 'N5', 2, 135, 135, 'N は なん/どれ ですか', '[]', 'N は なん/どれ ですか', 'cái gì; cái nào (hỏi tên hoặc hỏi chọn đồ vật)', 'N + は + なん + ですか / N + は + どれ + ですか', 'Hỏi tên đồ vật: Nはなんですか (… là cái gì). Hỏi chọn một trong nhiều thứ: Nはどれですか (… là cái nào). Câu hỏi này không trả lời bằng はい／いいえ mà bằng tên đồ vật hoặc chỉ ra cái đó.', 'なん hỏi tên đồ vật, どれ hỏi chọn cái nào trong nhiều cái.', 'Hay đọc 何ですか thành なにですか; trước です phải đọc なん. Chỉ có hai thứ thì không dùng どれ mà dùng どちら.', '["JG-aee65c5570","JG-fc410c25b4","JG-322570640d"]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-d78721df11', 'N5', 4, 157, 157, '〜ません/〜ませんでした', '[]', 'ません/〜ませんでした', 'Nói không làm\nBỏ ます thay bằng ません; chuyện đã qua thì ませんでした.', 'V-ます bỏ ます + ません / ませんでした', 'Việc đã làm rồi dùng ました, đừng lẫn với ません.', 'Lịch sự; ません cho hiện tại và tương lai, ませんでした cho quá khứ.', 'Hay nói ませんでしたです hoặc ないでした; dạng đúng chỉ là ませんでした.', '["JG-b003a8c5af","JG-0ef56ff856"]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-d8a07b9cda', 'N5', 9, 365, 365, 'Thỉnh thoảng', '[]', 'Thỉnh thoảng', 'thỉnh thoảng; đôi khi', 'ときどき + V', 'ときどき chỉ tần suất vừa phải (ít hơn よく), đứng đầu câu hoặc trước động từ, không cần trợ từ: ときどき映画を見ます, 私はときどきコーヒーを飲みます. Chữ Hán là 時々.', 'Tần suất trung bình, ít hơn よく.', 'Hay đặt ときどき ở cuối câu như “thỉnh thoảng” trong tiếng Việt; thường đặt ở đầu câu hoặc trước động từ.', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-dad75c9be2', 'N5', 8, 42, 42, 'くない', '[]', 'くない', 'không … (dạng phủ định của tính từ い)', 'Aい bỏ い + くない(です) (高い → 高くない)', 'Dùng để phủ định tính chất của người, vật; thêm です để nói lịch sự.', 'くない là thân mật; くないです hoặc くありません là lịch sự.', 'Hay nói 高いじゃない như với danh từ. Riêng いい phải đổi thành よくない, không phải いくない.', '["JG-af886f1233","JG-0eeeecf6ed","JG-aecc9e94e2"]', NULL, 'AI_CHECKED', 1, '3c5bc58917e7'),
('JG-db85b4b3fa', 'N5', 9, 397, 397, '〜くて', '[]', 'くて', 'Biểu hiện lý do của một cảm giác hoặc một tâm trạng nào đó. Vế sau thường là dạng phủ định của động từ chỉ khả năng.', 'Aい bỏ い + くて、(cảm xúc, kết quả)', 'Dùng để nêu lý do nhẹ cho một cảm giác, trạng thái hoặc việc không làm được ở vế sau.', 'Nhẹ hơn から; vế sau thường không phải mệnh lệnh hay ý muốn.', 'Hay đặt lời nhờ ở vế sau (sai: 暑くて、窓を開けてください); khi đó phải dùng から.', '["JG-f154a7c22d"]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-dbad118de2', 'N5', 8, 151, 151, 'Adjに V – Dạng trạng từ của tính từ な', '[]', 'Adjに V – Dạng trạng từ của tính từ な', 'biến tính từ な thành trạng từ (bỏ な thêm に); làm gì một cách …', 'Aな + に + V (静かに話す)', 'Đặt Aなに ngay trước động từ để nói hành động được làm thế nào: 静かに話します (nói khẽ), きれいに書きます (viết đẹp), 上手に歌います (hát hay). Với します thì là làm cho trở nên: 部屋をきれいにします. Tính từ い thì dùng く: 早く起きます.', 'Trung tính; に biến tính từ な thành từ chỉ cách làm; với する, なる thì chỉ sự thay đổi.', 'Hay giữ な trước động từ (sai: 静かな話してください). Tính từ い thì dùng く, không dùng に.', '["JG-7a14565753","JG-68aa27602e"]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-dbcd98f1dc', 'N5', 8, 210, 210, 'N は Aい です', '[]', 'N は Aい', 'Khen chê bằng tính từ đuôi い\nTính từ đuôi い giữ nguyên rồi thêm です: ほんは やすいです.', 'N + は + Aい + です', 'Đừng bỏ chữ い đi. Nói やすです là sai.', 'Lịch sự; tính từ い giữ nguyên rồi thêm です.', 'Hay chèn だ hoặc な (sai: 安いだ, 安いなです).', '["JG-20044b7380"]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-dc06119c3d', 'N5', 12, 246, 246, 'Cái này hơn cái kia', '[]', 'Cái này hơn cái kia', '… hơn; so sánh nhấn vào thứ hơn (N1 より N2 のほうが)', 'N1 + より + N2 + のほうが + A', 'N1 より N2 の ほうが A: N2 hơn N1 (より gắn sau cái làm mốc). Hay dùng để trả lời câu hỏi どちらが…: バスより電車のほうが速いです. Khi đã rõ thì bỏ N1 より: 電車のほうが速いです.', 'Nhấn vào N2 là thứ hơn.', 'Hay đặt より sau thứ hơn; より luôn gắn sau thứ được đem ra làm mốc.', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-de77c92e70', 'N5', 1, 4, 4, '〜は', '["は"]', 'は', 'trợ từ nêu chủ đề của câu', 'N + は + …', 'Đặt sau danh từ để nêu điều mình sắp nói tới (chủ đề), phần sau mới là thông tin về nó. Viết là は nhưng đọc là “wa”.', 'Trung tính; は làm nền cho câu, còn thông tin quan trọng nằm ở phần đứng sau.', 'Hay đọc nhầm thành “ha” hoặc viết nhầm thành わ. Sau từ để hỏi làm chủ ngữ như だれ, なに phải dùng が, không dùng は (sai: だれは来ましたか).', '[]', NULL, 'AI_CHECKED', 1, '3c5bc58917e7'),
('JG-decc71fc45', 'N5', 12, 245, 245, 'Cái nào hơn?', '[]', 'Cái nào hơn?', 'cái nào … hơn?; hỏi chọn giữa hai thứ (N1 と N2 と どちらが)', 'N1 + と + N2 + と、どちらが + A + ですか', 'N1 と N2 と どちらが A ですか: hỏi cái nào hơn trong hai thứ. Trả lời: N の ほうが A です; như nhau thì どちらも. Với động từ cũng hỏi được: どちらを飲みますか. Ba thứ trở lên thì dùng どれ.', 'Trung tính, lịch sự; câu trả lời dùng のほうが.', 'Hay dùng どれ khi so sánh hai thứ; hai thứ phải dùng どちら.', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-df6a911829', 'N5', 10, 143, 143, '〜や〜(など)', '[]', 'や〜(など)', 'Trợ từ nối danh từ với danh từ khác. Được sử dụng liệt kê một vài thứ trong nhiều thứ.', 'N1 + や + N2 + (など)', 'Dùng để nêu vài thứ tiêu biểu trong nhiều thứ, ngầm hiểu còn những thứ khác nữa.', 'Mềm, không khẳng định đã kể hết; thêm など để nhấn ý “vân vân”.', 'Hay dùng や khi đã kể hết (lúc đó dùng と). や chỉ nối danh từ với danh từ.', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-dfde08df0a', 'N5', 14, 263, 263, '〜ている', '[]', 'ている', 'đang …; trạng thái kéo dài (住んでいる、知っている)', 'V-て + いる', 'V-て + います nói việc đang diễn ra lúc nói: 今、新聞を読んでいます. Với 住む, 知る thì chỉ trạng thái: ハノイに住んでいます (sống ở Hà Nội), 知っています (biết). Câu hỏi: 何をしていますか. Nói thân mật rút gọn 〜てる.', 'Trung tính; khi nói thân mật hay rút gọn thành 〜てる.', 'Hay dùng thể ます cho việc đang diễn ra (sai: 今新聞を読みます với nghĩa đang đọc).', '["JG-b2976be48a","JG-4bf259bc32","JG-72a02e9fe6"]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-e0f65d2af2', 'N5', 21, 367, 367, '〜と おもいます', '[]', 'と おもい', 'Nói ý nghĩ của mình\nVế trước と phải để ở lối nói thân mật (bài trước), rồi mới thêm と おもいます.', 'Câu (thể thường) + と思います', 'Danh từ và tính từ đuôi な cần thêm だ trước と: べんりだと おもいます.', 'Làm câu mềm, bớt khẳng định.', 'Hay để vế trước ở thể lịch sự (sai: 高いですと思います); vế trước phải là thể thường.', '["JG-c734b6727f"]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-e249844251', 'N5', 8, 41, 41, 'い-Adjective + です (Predicate)', '[]', 'い-Adjective + です (Predicate)', 'tính từ い + です làm vị ngữ lịch sự', 'N + は + Aい + です', 'Dùng để nói người, vật có tính chất gì một cách lịch sự, ví dụ この本は高いです (quyển sách này đắt).', 'Lịch sự; bỏ です thì thành lối nói thân mật.', 'Hay chia quá khứ thành 高いでした; đúng là 高かったです. Phủ định cũng không phải 高いじゃないです mà là 高くないです.', '[]', NULL, 'AI_CHECKED', 1, '3c5bc58917e7'),
('JG-e2a6b6adf4', 'N5', 17, 303, 303, '〜ほうがいい', '[]', 'ほうがいい', 'nên …; không nên … thì hơn', 'Vた + ほうがいい / Vない + ほうがいい', 'Dùng để khuyên: Vた + ほうがいいです = nên làm (休んだほうがいいです); Vない + ほうがいいです = không nên làm (行かないほうがいいです). Khi khuyên người nghe thường thêm よ ở cuối.', 'Lời khuyên khá thẳng; với người trên nên thêm と思います cho mềm.', 'Lời khuyên nên làm thường dùng thể た (休んだほうがいい), lời khuyên không nên làm dùng thể ない (行かないほうがいい). Đừng dùng thể ます trước ほう.', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-e323c89bad', 'N5', 13, 290, 290, 'Ai đó', '[]', 'Ai đó', 'ai đó; người nào đó', 'だれか + が・に … / だれか + V', 'だれか chỉ một người không rõ là ai. Dùng trong câu khẳng định (だれかが来ました) hoặc câu hỏi có/không (だれかいますか). Thêm trợ từ theo vai trò: だれかに聞きます, だれかと行きます, だれかの + N. Muốn nói "không ai" thì dùng だれも + phủ định.', 'Chỉ một người không xác định; câu hỏi có だれか chỉ cần trả lời はい hoặc いいえ.', 'Hay nhầm với だれ: だれが来ましたか hỏi ai đã đến, còn だれか来ましたか hỏi có ai đến không.', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-e3a7c47bae', 'N5', 11, 244, 244, 'いっしゅうかんに 〜かい', '[]', 'いっしゅうかんに 〜かい', 'Nói mấy lần trong một khoảng\nKhoảng thời gian đứng trước に, rồi mới tới số lần: いっかげつに にかい.', 'Khoảng thời gian + に + số + 回', 'Chữ に ở đây là trong một khoảng, khác với に chỉ giờ giấc.', 'Trung tính; khoảng thời gian đứng trước に, số lần đứng sau.', 'Hay đảo thứ tự theo tiếng Việt “hai lần một tuần” (sai: 2回に1週間); đúng là 1週間に2回.', '["JG-f2d24d20e7"]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-e420d7285d', 'N5', 4, 19, 19, 'る-Verb (Dictionary)', '[]', 'る-Verb (Dictionary)', 'thể từ điển (dạng gốc) của động từ nhóm II tận cùng bằng る', 'V-ます bỏ ます + る (食べます → 食べる, 見ます → 見る)', 'Dùng khi nói chuyện thân mật ở hiện tại hoặc tương lai, và làm nền để ghép các mẫu như ことができる, まえに.', 'Thân mật, dùng với người ngang hàng; với người trên phải dùng dạng ます.', 'Hay xếp nhầm các động từ nhóm I cũng tận cùng る như 帰る, 入る, 走る vào nhóm II; chúng chia khác (帰らない chứ không phải 帰ない).', '[]', NULL, 'AI_CHECKED', 1, '3c5bc58917e7'),
('JG-e4333f73fe', 'N5', 9, 219, 219, 'N が すき/きらいです', '[]', 'N が すき/きらい', 'Nói thích hay không ưa\nThứ mình thích đứng trước が, không phải を: おんがくが すきです.', 'N + が + すき・きらい + です', 'Nhấn mạnh thì thêm だい: だいすき (rất thích) · だいきらい (rất ghét).', 'Trung tính; きらい khá mạnh, muốn nói nhẹ thì dùng あまりすきじゃありません.', 'Hay dùng を (sai: 夏をすきです). Phủ định là すきじゃありません, không phải すきません.', '["JG-87638f52db","JG-ffae1ad9ba"]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-e5131c2016', 'N5', 24, 398, 398, '〜て もらえますか / だれが 〜て くれましたか', '[]', 'て もらえますか / だれが 〜て くれましたか', 'Nhờ vả và hỏi ai đã giúp\nNhờ lịch sự thì もらえますか, hỏi ai giúp thì だれが ～て くれましたか.', 'V-て + もらえますか / だれが + V-て + くれましたか', 'もらえますか nhẹ hơn ください nhiều — nhờ người chưa thân thì nên dùng.', 'Lịch sự; もらえますか là cách nhờ mềm mỏng.', 'Hay dùng だれに〜てくれましたか; với くれる người giúp đi với が.', '["JG-315e3a8560","JG-9d12efd7d2","JG-a412adf097"]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-e5790e7933', 'N5', 12, 188, 188, '〜と〜とちらが・〜のほうが', '[]', 'と〜とちらが・〜のほうが', 'Cách so sánh giữa hai vật.', 'N1 + と + N2 + と、どちらが + A + ですか / N + のほうが + A', 'Hỏi chọn giữa hai thứ: N1 と N2 と どちらが A ですか. Trả lời bằng N の ほうが A です; như nhau thì nói どちらも. Từ ba thứ trở lên thì hỏi bằng どれ.', 'Trung tính; câu trả lời dùng のほうが.', 'Khi chọn một thứ phải đáp Nのほうが〜, không chỉ nêu tên. Không dùng どれ khi so sánh hai thứ.', '["JG-ace2df3955","JG-bf7dd08411"]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-e5894d1831', 'N5', 5, 154, 154, 'Quay lại...', '[]', 'Quay lại...', 'quay lại; trở lại chỗ vừa rời đi', 'N(nơi chốn) + に・へ + 戻る (戻ります)', 'Nơi quay lại + に/へ + 戻ります: 席に戻ります, 会社へ戻ります. Dùng khi tạm rời một chỗ rồi quay lại; về nhà, về nước sau khi xong việc thì thường nói 帰ります. Câu quen dùng: すぐ戻ります (tôi quay lại ngay).', 'Trung tính; nhấn việc trở lại chỗ vừa rời đi, thường sau một thời gian ngắn.', 'Hay nhầm 戻る với 帰る: 帰る là về nơi mình thuộc về (nhà, nước mình), 戻る là quay lại chỗ vừa ở. 戻る là động từ nhóm I: 戻らない, 戻って.', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-e6abc20999', 'N5', 7, 359, 359, 'Cho (ai đó)', '[]', 'Cho (ai đó)', 'cho; tặng (người khác)', 'N1(người nhận) + に + N2 + を + あげます', 'N1 に N2 を あげます: mình (hoặc người khác) cho, tặng N2 cho N1. Người nhận đi với に, vật cho đi với を. Khi người nhận là "tôi" thì không dùng あげます mà dùng くれます.', 'Trung tính; hướng cho từ phía mình ra người khác.', 'Hay dùng あげます khi người khác cho mình; phải dùng くれます.', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-e6e4e7e1cb', 'N5', 1, 288, 288, 'Ai', '[]', 'Ai', 'ai; người nào', 'だれ + が・を・に・と・の … / N + は + だれですか', 'だれ dùng để hỏi về người. Thêm trợ từ theo vai trò trong câu: だれが (ai làm), だれを, だれに (cho ai), だれと (với ai), だれの + N (N của ai). Hỏi lịch sự hơn thì dùng どなた.', 'Trung tính; lịch sự hơn là どなた.', 'Hay dùng だれは (sai: だれは来ましたか); だれ làm chủ ngữ phải đi với が.', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-e6f26f90c4', 'N5', 10, 60, 60, '等(など)', '[]', '等(など)', 'vân vân; như là … (nêu ví dụ và ngầm hiểu còn thứ khác)', 'N1 + や + N2 + など / N + など', 'Đặt sau danh từ (thường ở cuối chuỗi や) để cho biết đó chỉ là vài ví dụ, vẫn còn thứ khác.', 'Trung tính, làm câu mềm và không khẳng định hết.', 'Hay đặt など ở đầu như chữ “vân vân” trong tiếng Việt; など luôn đứng ngay sau danh từ cuối cùng được kể. Đi với など tự nhiên nhất là chuỗi や.', '[]', NULL, 'AI_CHECKED', 1, '3c5bc58917e7'),
('JG-e742bd6430', 'N5', 20, 102, 102, 'けど', '[]', 'けど', 'nhưng; tuy … nhưng … (nối hai vế trái ngược trong lối nói thân mật)', 'Câu (thể thường / です・ます) + けど、…', 'Dùng để nối hai ý trái ngược nhau, hoặc để mở lời nhẹ nhàng trước khi nhờ vả, hỏi han.', 'Thân mật, dùng khi nói; lịch sự hơn là が hoặc けれども.', 'Nhớ けど gắn vào cuối vế trước (高いけど、買います), không đứng đầu vế sau như chữ “nhưng” tiếng Việt. Với danh từ và tính từ な phải có だ: 雨だけど.', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-e7d401dccb', 'N5', 9, 223, 223, 'よく/だいたい/たくさん/すこし', '[]', 'よく/だいたい/たくさん/すこし', 'Nói mức độ nhiều ít\nMấy từ này đứng trước động từ: よく ききます · すこし わかります.', 'よく・だいたい・たくさん・すこし + V', 'ぜんぜん và あまり bắt buộc đi với đuôi phủ định ở cuối câu.', 'Trung tính; よく còn có nghĩa “rõ, kỹ” (よく分かります).', 'Hay đặt たくさん ngay trước danh từ mà quên の (đúng là たくさんの本), hoặc đặt nó sau động từ.', '["JG-73190d3ca9"]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-e9737e8107', 'N5', 16, 312, 312, 'Cái nào (danh từ)', '[]', 'Cái nào (danh từ)', 'cái … nào (đứng trước danh từ); khoảng bao lâu (どのくらい)', 'どの + N', 'どの luôn đứng trước danh từ: どの人, どの本. Không có danh từ theo sau thì dùng どれ (どれがあなたのですか). どのくらい (どのぐらい) hỏi khoảng bao lâu, bao nhiêu.', 'Trung tính.', 'Hay để どの đứng một mình; đứng một mình phải dùng どれ.', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-e99ec187f7', 'N5', 8, 212, 212, 'N は どうですか / どんな N ですか', '[]', 'N は どうですか / どんな N ですか', 'Hỏi thấy thế nào\nどうですか hỏi cảm nhận chung, どんな hỏi thuộc loại nào, kiểu gì.', 'N + は + どうですか / どんな + N + ですか', 'どうですか đứng một mình; どんな bắt buộc có danh từ theo sau.', 'Trung tính; lịch sự hơn どうですか là いかがですか.', 'Hay dùng どう trước danh từ (sai: どう人ですか); trước danh từ phải dùng どんな.', '["JG-d604d684d2","JG-894fbb47aa"]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-ea54cf6735', 'N5', 13, 358, 358, 'Bất cứ khi nào', '[]', 'Bất cứ khi nào', 'bất cứ lúc nào; lúc nào cũng được', 'いつでも + V / いつでも + いい', 'いつでも + câu khẳng định: lúc nào cũng được (いつでも来てください, いつでもいいですよ). Khác いつも (luôn luôn, thói quen): 私はいつも7時に起きます.', 'Thể hiện sự sẵn lòng, cho phép ở mọi thời điểm.', 'Hay nhầm với いつも (luôn luôn): いつでも là lúc nào cũng được, いつも là lúc nào cũng vậy.', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-ea84df0587', 'N5', 7, 190, 190, 'N1 に N2 を あげます/かします/おしえます/おくります', '[]', 'N1 に N2 を あげます/かします/おしえます/おくり', 'Cho ai, tặng ai cái gì\nNgười nhận đứng trước に, món đồ đứng trước を: ともだちに はなを あげます.', 'N1(người nhận) + に + N2 + を + あげます・かします・おしえます・おくります', 'Người nhận đi với に, đồ vật đi với を: あげます (tặng, cho), かします (cho mượn), おしえます (dạy), おくります (gửi). Người cho làm chủ ngữ; khi mình là người nhận thì không dùng あげます.', 'Trung tính; người nhận luôn đi với に.', 'Hay dùng を cho người nhận (sai: 友だちを教えます với nghĩa dạy bạn). Với あげます, người nhận không được là 私.', '["JG-cf2d62eca8","JG-af373390ef","JG-6bbd0fc52e"]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-ed609c4e15', 'N5', 16, 86, 86, '〜て (Sequence)', '[]', 'て (Sequence)', '… rồi … (nối các hành động theo thứ tự thời gian)', 'V1-て、V2-て、V3', 'Dùng để kể nhiều hành động nối tiếp nhau; các động từ ở giữa câu để thể て, chỉ động từ cuối mới chia thì.', 'Trung tính; các việc được kể đúng theo thứ tự xảy ra.', 'Hay chia ます hoặc ました ở các vế giữa; chỉ vế cuối mới chia thì. Cũng hay chia sai thể て của nhóm I (行く → 行って, không phải 行いて).', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-ed6d5d3884', 'N5', 21, 368, 368, 'そう おもいません / しりません', '[]', 'そう おもいません / しりません', 'Nói không nghĩ vậy, không biết\nPhản đối nhẹ thì nói そう おもいません, không nắm được thì しりません.', 'そう + おもいません / N + を + しりません', 'Người Nhật ít phản đối thẳng — thường mở đầu bằng そうですね rồi mới nói ý khác.', 'そう思いません là phản đối nhẹ; nói với người trên nên thêm あまり hoặc ちょっと cho mềm.', 'Hay nói 知っていません; phủ định đúng của 知っています là 知りません.', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-ed8c4dbd55', 'N5', 11, 63, 63, 'に (Frequency)', '[]', 'に (Frequency)', 'trong (một khoảng thời gian) … lần (chỉ tần suất)', 'Khoảng thời gian + に + số lần (一週間に二回)', 'Dùng để nói trong một khoảng thời gian thì làm việc gì bao nhiêu lần.', 'Trung tính; khoảng thời gian đứng trước に, số lần đứng sau.', 'Hay đảo thứ tự theo tiếng Việt “hai lần một tuần” thành 二回に一週間; đúng là 一週間に二回. Cũng hay quên trợ từ に.', '[]', NULL, 'AI_CHECKED', 1, '3c5bc58917e7'),
('JG-eeda3e983e', 'N5', 17, 93, 93, '〜までに', '["までに"]', 'までに', 'trước … (hạn chót về thời gian)', 'N(thời điểm) / Vる + までに', 'Đặt までに sau danh từ chỉ thời điểm (hoặc động từ thể từ điển) để nêu hạn chót: việc phải xong trước hoặc chậm nhất là lúc đó: 金曜日までに出してください (hãy nộp trước thứ sáu). Động từ ở vế sau là việc làm một lần (帰る, 出す, 返す), không phải việc kéo dài.', 'Trung tính; nhấn vào hạn chót, việc phải xong trước hoặc đúng lúc đó.', 'Hay nhầm với まで: まで là làm liên tục đến lúc đó (5時まで働きます), までに là xong trước lúc đó (5時までに帰ります).', '["JG-15e5fd833e"]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-ef0902c4e5', 'N5', 8, 364, 364, 'Thế nào', '[]', 'Thế nào', 'thế nào; … thì sao (gợi ý)', 'N + は + どうですか', 'N は どうですか hỏi cảm nhận, đánh giá: 日本の生活はどうですか. Cũng dùng để mời, gợi ý: コーヒーはどうですか. Hỏi về việc đã qua dùng どうでしたか. Lịch sự hơn là いかがですか.', 'Trung tính; lịch sự hơn là いかがですか; còn dùng để gợi ý (〜はどうですか).', 'Hay dùng どう trước danh từ (sai: どう料理ですか); trước danh từ phải dùng どんな.', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-ef9ab35cc5', 'N5', 5, 313, 313, 'Không đi đâu cả', '[]', 'Không đi đâu cả', 'không đi đâu cả; không đến đâu cả', 'どこへも + Vない (行きません・出かけません)', 'どこへも + động từ di chuyển ở thể phủ định (行きません, 出かけません) = không đi đâu cả. Nói どこにも行きません cũng cùng nghĩa. Không dùng với câu khẳng định.', 'Phủ định toàn bộ hướng đi.', 'Hay bỏ へ (どこも行きません vẫn được dùng khi nói nhưng chuẩn là どこへも). Không dùng với câu khẳng định.', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-f02a27e408', 'N5', 17, 91, 91, 'なければならない', '[]', 'なければならない', 'phải … (việc bắt buộc phải làm)', 'Vない bỏ い + ければならない (行かなければならない)', 'Dùng để nói một việc cần thiết hoặc bắt buộc phải làm, do quy định hay do hoàn cảnh.', 'Khá mạnh và nghiêm; lịch sự là なければなりません, nói thân mật hay rút gọn thành なきゃ.', 'Hay quên bỏ い (sai: 行かないければ). Người Việt cũng hay dùng mẫu này cho lời khuyên nhẹ; muốn khuyên thì dùng 〜たほうがいいです.', '["JG-05589d014f","JG-a3abb234e6"]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-f0866ae3fd', 'N5', 25, 113, 113, 'もし', '[]', 'もし', 'nếu như … (đặt ở đầu câu điều kiện để nhấn ý giả định)', 'もし + (vế điều kiện)たら・ても', 'Đặt ở đầu vế điều kiện để báo trước rằng mình đang giả định; thường đi với 〜たら.', 'Trung tính; nhấn vào tính giả định, có thể lược mà nghĩa vẫn giữ nhờ たら.', 'Người Việt hay chỉ dùng もし mà quên chia たら ở cuối vế (sai: もし雨が降ります、行きません); もし chỉ là từ báo trước, phần điều kiện vẫn phải là 降ったら.', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-f0cf022426', 'N5', 12, 66, 66, 'い-Adjective (Past)', '[]', 'い-Adjective (Past)', 'đã … (dạng quá khứ của tính từ い)', 'Aい bỏ い + かった(です) (高い → 高かった)', 'Dùng để miêu tả tính chất, cảm nhận trong quá khứ; thêm です để nói lịch sự.', 'かった là thân mật, かったです là lịch sự.', 'Hay nói 高いでした hoặc 高いだった; đúng là 高かったです. いい đổi thành よかった, không phải いかった.', '[]', NULL, 'AI_CHECKED', 1, '3c5bc58917e7'),
('JG-f154a7c22d', 'N5', 16, 370, 370, '〜くて・で', '[]', 'くて・で', '… và … (nối tính từ hoặc danh từ)', 'Aい bỏ い + くて / Aな・N + で', 'Dùng để nối nhiều tính từ hoặc danh từ khi miêu tả, giống chữ “và” trong tiếng Việt.', 'Các tính chất nối với nhau thường cùng chiều.', 'Hay nối tính từ bằng と (sai: やさしいときれい); と chỉ nối danh từ.', '["JG-db85b4b3fa"]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-f17bfc45f7', 'N5', 39, 231, 231, '〜ので', '["ので"]', 'ので', 'vì … nên …; nêu lý do (lịch sự và nhẹ nhàng hơn から)', 'V・Aい (thể thường) + ので / Aな・N + なので', 'Câu lý do (thể thường) + ので、câu kết quả: 頭が痛いので、休みます. Danh từ và tính từ な dùng なので (雨なので). Hay dùng khi xin phép, xin lỗi, giải thích vì nghe mềm hơn から. Không đặt ので ở cuối câu trả lời; trả lời "どうして" thì dùng 〜からです.', 'Lịch sự, khách quan hơn から; hay dùng khi xin phép, giải thích.', 'Với danh từ, tính từ な phải dùng なので (sai: 雨ので).', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-f20250fe9e', 'N5', 19, 99, 99, 'たり〜たりする', '[]', 'たり〜たりする', 'lúc thì … lúc thì …; nào là … nào là … (kể vài việc tiêu biểu)', 'V1た + り、V2た + り + する', 'Dùng để kể vài việc tiêu biểu trong nhiều việc, không theo thứ tự, ví dụ những việc thường làm vào ngày nghỉ.', 'Trung tính; ngầm hiểu còn những việc khác nữa.', 'Hay quên する ở cuối hoặc chỉ dùng たり một lần. Thì của câu nằm ở する: します (thường làm), しました (đã làm).', '["JG-6b3810a528","JG-072b546f77"]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-f2d24d20e7', 'N5', 7, 185, 185, 'いっしょに 〜ませんか', '[]', 'いっしょに 〜ませんか', 'Rủ người khác cùng làm\nNghe như câu phủ định nhưng thật ra là lời mời, giọng nhẹ và lịch sự.', 'いっしょに + V-ます bỏ ます + ませんか', 'Nhận lời thì đáp ええ、いいですね; từ chối thì mở đầu bằng ざんねんですが.', 'Lịch sự, nhẹ nhàng, để người nghe dễ từ chối.', 'Hay đáp いいえ khi muốn nhận lời; đồng ý thì nói ええ、いいですね. Từ chối khéo là すみません、ちょっと….', '["JG-e3a7c47bae"]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-f328aa1f6b', 'N5', 16, 306, 306, 'V てから V', '[]', 'V てから V', 'Xong việc này rồi mới việc kia\nNhấn mạnh thứ tự trước sau: たべてから くすりを のみます.', 'V1-て + から + V2', 'V1-てから V2: làm xong V1 rồi mới làm V2, nhấn thứ tự trước sau. Một câu thường chỉ có một chỗ てから; kể nhiều việc liên tiếp thì nối bằng V-て、V-て.', 'Nhấn thứ tự trước sau: xong V1 rồi mới V2.', 'Hay dùng thể た trước から (sai: 払ったから) – khi đó から lại thành “vì”.', '["JG-f730cc8935"]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-f4bd5342b8', 'N5', 18, 177, 177, 'Danh từ hóa thân mật', '[]', 'Danh từ hóa thân mật', 'việc …; biến động từ thành danh từ (cách nói thân mật)', 'V(thể thường) + の + が・は・を …', 'V thể thường + の biến cụm động từ thành danh từ, rồi thêm が, は, を: 歌うのが好きです, 歩くのは体にいいです. Hay đi với 好き, きらい, 上手, 下手, 楽しい. Mẫu cố định như ことができます, しゅみは〜ことです thì không đổi こと thành の.', 'Tự nhiên, gần gũi, dùng nhiều khi nói; với 好き, 楽しい dùng の hay こと đều được.', 'Hay dùng thể ます trước の (sai: 歌いますの). Trong các mẫu cố định như ことができる thì không thay こと bằng の.', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-f500b3b07c', 'N5', 1, 2, 2, '〜か', '["か"]', 'か', 'hoặc; hay là', 'N1 + か + N2', 'Đặt か giữa hai danh từ để nêu các khả năng, chỉ chọn một trong số đó: コーヒーかお茶 (cà phê hoặc trà). Trợ từ của cả cụm đứng sau danh từ cuối: バスか電車で行きます (đi bằng xe buýt hoặc tàu điện).', 'Trung tính; chỉ đưa ra các khả năng để chọn một, không khẳng định cả hai cùng đúng.', 'Hay nhầm か với と: AとB là cả A lẫn B, còn AかB là chọn một trong hai. Cũng đừng lẫn với か ở cuối câu dùng để hỏi.', '[]', NULL, 'AI_CHECKED', 1, '3c5bc58917e7'),
('JG-f539f37a62', 'N5', 25, 406, 406, 'V たら / A かったら / N だったら', '[]', 'V たら / A かったら / N だったら', 'Nếu như thế thì sẽ thế này\nLấy dạng đuôi た rồi thêm ら: ふった → ふったら · やすかった → やすかったら.', 'Vた + ら / Aい bỏ い + かったら / Aな・N + だったら', 'Khác với と ở bài trước: たら dùng cho chuyện cụ thể chưa chắc xảy ra, と dùng cho quy luật luôn đúng.', 'Trung tính; vế sau có thể là ý muốn, lời nhờ hay lời rủ.', 'Hay ghép ら vào thể từ điển (sai: 安いら); phải dựa trên thể た: 安かったら.', '["JG-3976c1fc65","JG-bff0e28443"]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-f563d8eb9a', 'N5', 19, 180, 180, 'Trở thành...', '[]', 'Trở thành...', 'trở thành …; trở nên …', 'N / Aな + に + なります / Aい bỏ い + く + なります', 'N に なります: trở thành (医者になります), đến mốc thời gian (もう十二時になりました), đến tuổi (二十歳になります). Tính từ な dùng に なります, tính từ い dùng 〜く なります. Danh từ luôn đi với に, không dùng が, を.', 'Trung tính; なります là cách nói lịch sự của なる.', 'Hay nói 先生がなります; đúng là 先生になります, danh từ đi với に.', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-f5ba577956', 'N5', 16, 200, 200, 'Nối hai hành động', '[]', 'Nối hai hành động', '… rồi …; nối các hành động theo thứ tự', 'V1-て、V2', 'V1-て、V2: làm V1 xong rồi làm V2. Có thể nối nhiều hành động: 起きて、顔を洗って、学校へ行きます. Thì của cả câu do động từ cuối quyết định (〜ます hay 〜ました). Muốn nhấn "sau khi" thì dùng 〜てから.', 'Trung tính; thì của câu do động từ cuối quyết định.', 'Hay chia thì ở vế trước; vế trước chỉ cần thể て.', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-f5e430ddca', 'N5', 18, 96, 96, '前(まえ)に', '[]', '前(まえ)に', 'trước khi …; trước …', 'Vる + 前に / N + の前に', 'Dùng để nói làm việc gì trước khi làm một việc khác, hoặc trước một sự kiện, thời điểm.', 'Trung tính; động từ đứng trước 前に luôn để thể từ điển.', 'Hay dùng thể た trước 前に vì việc đã xảy ra (sai: 寝た前に); luôn là 寝る前に. Với danh từ phải có の: 食事の前に.', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-f61f6b2c03', 'N5', 1, 119, 119, 'N1 も N2 です', '[]', 'N1 も N2', 'cũng là (N1 cũng là N2)', 'N1 + も + N2 + です', 'Khi điều vừa nói về một người, vật cũng đúng với người, vật khác thì thay は bằng も: 山田さんは学生です。田中さんも学生です (anh Tanaka cũng là học sinh).', 'Trung tính; も đứng thay hẳn vào chỗ của は.', 'Hay nói 私はも学生です; đúng là 私も学生です, bỏ は đi.', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-f64e5a267e', 'N5', 18, 332, 332, 'しゅみは V る こと です / V る ことが すきです', '[]', 'しゅみは V る こと です / V る ことが すき', 'Nói sở thích\nBiến một việc thành danh từ bằng chữ こと rồi mới nói thích hay là sở thích.', 'しゅみは + Vる + ことです / Vる + ことが + 好きです', 'Người Nhật hay đáp gọn bằng danh từ (おんがくです) — cả hai cách đều dùng được.', 'Trung tính; cách nói thường dùng khi giới thiệu bản thân.', 'Hay bỏ こと (sai: しゅみは写真をとります); động từ phải được danh từ hóa bằng こと: しゅみは写真をとることです.', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-f67982a10e', 'N5', 10, 181, 181, '〜がいる・〜がある', '[]', 'がいる・〜がある', 'có …; chỉ người hoặc vật nào đó tồn tại', 'N + が + いる (người, con vật) / N + が + ある (đồ vật)', 'Dùng để nói có người, con vật hay đồ vật nào đó; nơi chốn đặt phía trước kèm に.', 'Trung tính; lịch sự là います, あります.', 'Hay nhầm いる với ある; người và động vật dùng いる, đồ vật và cây cối dùng ある.', '["JG-33b8b7d970"]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-f721ef2f45', 'N5', 13, 274, 274, 'N へ N/V ます に いきます', '[]', 'N へ N/V ます に いき', 'Nói đi đâu để làm gì\nViệc định làm đứng trước に: デパートへ かいものに いきます.', 'N(nơi chốn) + へ + N(hoạt động) / V-ます bỏ ます + に + 行きます', 'Động từ thì bỏ ます rồi mới thêm に: みます → みに いきます.', 'Trung tính; nơi đến đi với へ, mục đích đi với に.', 'Hay dùng thể từ điển trước に (sai: 泳ぐに行きます); đúng là 泳ぎに行きます.', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-f730cc8935', 'N5', 13, 73, 73, '〜てから', '[]', 'てから', '… rồi mới … (sau khi làm xong việc trước)', 'V1-て + から + V2', 'Dùng để nói làm xong việc thứ nhất rồi mới làm việc thứ hai, nhấn vào thứ tự trước sau.', 'Trung tính; nhấn rằng việc trước phải xong rồi mới bắt đầu việc sau, rõ hơn khi chỉ nối bằng て.', 'Hay dùng thể từ điển trước から (sai: 食べるから) – lúc đó から lại thành nghĩa “vì”. Phải dùng thể て: 食べてから.', '["JG-f328aa1f6b"]', NULL, 'AI_CHECKED', 1, '3c5bc58917e7'),
('JG-f85a7639c4', 'N5', 21, 103, 103, 'と思(おも)う', '[]', 'と思(おも)う', 'tôi nghĩ là … (nêu ý kiến hoặc phỏng đoán của người nói)', 'Câu (thể thường) + と思う (と思います)', 'Dùng để nêu suy nghĩ, ý kiến hoặc phỏng đoán của bản thân một cách nhẹ nhàng.', 'Làm câu mềm, bớt khẳng định; rất hay dùng khi nói ý kiến với người khác.', 'Hay để vế trước ở thể lịch sự (sai: 雨が降りますと思います); vế trước phải là thể thường: 雨が降ると思います. Với danh từ, tính từ な phải thêm だ: 静かだと思います.', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-f8a97297c8', 'N5', 10, 164, 164, '〜にある・いる', '[]', 'にある・いる', 'Chỉ nơi chốn tồn tại.', 'N + は + N(nơi chốn) + に + ある・いる', 'Dùng để nói một người, vật đã biết đang ở đâu; nơi chốn đứng trước に.', 'Trung tính; đồ vật dùng ある, người và con vật dùng いる.', 'Hay dùng で thay cho に (sai: 銀行は駅の前であります); chỉ chỗ tồn tại phải dùng に.', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-fb31c8c0a0', 'N5', 16, 85, 85, '〜でしょう', '[]', 'でしょう', 'có lẽ …; chắc là … (phỏng đoán chưa chắc chắn)', 'V(thể thường) / Aい / Aな・N + でしょう', 'Đặt でしょう sau thể thường của động từ, tính từ い, hoặc sau tính từ な và danh từ (không có だ) để đoán một việc chưa chắc: あしたは雨が降るでしょう (ngày mai có lẽ mưa). Hay đi với たぶん. Lên giọng cuối (でしょう？) thì thành câu hỏi để người nghe xác nhận.', 'Lịch sự, phỏng đoán chưa chắc chắn; thân mật là だろう, lên giọng でしょう？ thì là hỏi để xác nhận.', 'Hay gắn だ trước でしょう (sai: 雨だでしょう); danh từ và tính từ な gắn thẳng: 雨でしょう. Với tính từ い cũng không thêm です (sai: 寒いですでしょう).', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-fc22da9584', 'N5', 23, 395, 395, 'V る と、〜', '[]', 'V る と、', 'Hễ làm thế này thì thế kia\nDùng cho quy luật luôn đúng: máy móc, đường đi, thời tiết theo mùa.', 'Vる + と、Câu (kết quả)', 'Vế sau KHÔNG được là lời nhờ hay lời rủ — không nói ボタンを おすと、おして ください.', 'Dùng cho quy luật tự nhiên, máy móc, chỉ đường; vế sau không phải ý muốn hay lời nhờ.', 'Hay đặt lời nhờ, lời mời ở vế sau (sai: 駅に着くと、電話してください); trường hợp đó dùng たら.', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-fc410c25b4', 'N5', 4, 161, 161, 'N は なんじ ですか / なんようび ですか', '[]', 'N は なんじ ですか / なんようび ですか', 'Hỏi mấy giờ\nHỏi giờ của một việc: cuộc họp, buổi học, giờ nghỉ trưa.', 'N + は + なんじ・なんようび + ですか', 'Hỏi khoảng thời gian thì thêm から／まで: なんじから なんじまでですか.', 'Trung tính; hỏi giờ hiện tại thì nói 今、何時ですか.', 'Hay đọc 何時 thành なにじ; đúng là なんじ. Khi trả lời thứ trong tuần nhớ đuôi ようび: げつようび, かようび.', '["JG-aee65c5570","JG-d61be94fc2","JG-322570640d"]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-fc83704d96', 'N5', 9, 389, 389, 'Vì... nên...', '[]', 'Vì... nên...', 'vì … nên …', 'Câu (lý do) + から、Câu (kết quả)', 'Câu lý do + から、câu kết quả: vế lý do đứng trước (時間がないから、タクシーで行きます). Dùng được cả khi vế sau là lời đề nghị, nhờ vả (さむいですから、まどをしめてください). Danh từ và tính từ な thêm だ: 雨だから, しずかだから.', 'Nêu lý do chủ quan, trực tiếp; dùng được với mệnh lệnh, lời mời.', 'Hay đặt vế lý do sau vế kết quả như tiếng Việt; tiếng Nhật vế lý do + から đứng trước.', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-fcc3af75f6', 'N5', 9, 216, 216, '〜ですから、〜 / 〜ますから、〜', '[]', 'ですから、〜 / 〜ますから、', 'Nói lý do rồi mới nói việc\nVế lý do đứng trước, gắn から vào cuối rồi mới tới vế việc làm.', 'Câu (lý do) + から、Câu (kết quả)', 'から đứng SAU lý do, ngược với tiếng Việt nói "vì" ở đầu câu.', 'から nêu lý do một cách chủ quan, trực tiếp; dùng được với lời nhờ, lời mời.', 'Người Việt hay nói kết quả trước rồi mới nói lý do như “… vì …”; tiếng Nhật đặt vế lý do + から ở trước.', '["JG-36c7185f86"]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-fccb688324', 'N5', 24, 108, 108, 'くれる', '[]', 'くれる', '(người khác) cho tôi (đồ vật đi về phía người nói)', 'N(người cho) + が + 私に + N(vật) + を + くれる', 'Dùng khi người khác cho, tặng người nói (hoặc người trong nhà mình) một thứ gì đó.', 'Thể hiện sự biết ơn của người nhận; người nhận thường là 私 nên hay được lược.', 'Hay dùng くれる khi mình cho người khác (sai: 私は友だちにくれました); lúc đó phải dùng あげる. Với くれる, người cho đi với が, không phải に.', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-fd2a61da26', 'N5', 12, 256, 256, 'Aい → 〜かったです / Aな・N → 〜でした', '[]', 'Aい → 〜かったです / Aな・N → 〜でした', 'Kể chuyện đã qua\nĐuôi い đổi thành かった rồi thêm です; loại な và danh từ thì でした.', 'Aい bỏ い + かったです / Aな・N + でした', 'いい là ngoại lệ: đã tốt thì nói よかったです.', 'Lịch sự; kể về tính chất, trạng thái trong quá khứ.', 'Hay dùng でした cho tính từ い (sai: 楽しいでした); đúng là 楽しかったです.', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-fddadcb610', 'N5', 4, 159, 159, 'N は 〜から 〜まで です', '[]', 'N は 〜から 〜まで', 'Nói từ mấy giờ đến mấy giờ\nから là mốc mở đầu, まで là mốc kết thúc, hai cái hay đi cùng nhau.', 'N + は + (giờ) + から + (giờ) + までです', 'Chỉ có mốc mở thì bỏ まで: みせは じゅうじからです.', 'Trung tính; dùng khi nói giờ mở cửa, giờ làm việc, giờ học.', 'Hay nhầm まで với までに. Đọc giờ cần nhớ: 4時 là よじ, 9時 là くじ, không phải よんじ, きゅうじ.', '[]', NULL, 'HOLD', 1, '3c5bc58917e7'),
('JG-ffae1ad9ba', 'N5', 9, 220, 220, 'N が すきですか / N が わかりますか', '[]', 'N が すきですか / N が わかりますか', 'Hỏi thích không, hiểu không\nGiữ nguyên が rồi thêm か ở cuối: スポーツが じょうずですか.', 'N + が + すきですか・わかりますか', 'Đáp gọn thì nhắc lại chính thứ được hỏi, đừng đáp trống một chữ はい.', 'Trung tính; trả lời ngắn はい、すきです hoặc いいえ、あまり….', 'Hay dùng を trong câu hỏi (sai: 日本語をわかりますか).', '["JG-87638f52db","JG-e4333f73fe"]', NULL, 'HOLD', 1, '3c5bc58917e7')
INSERT INTO `jpath_example` (`code`, `owner_type`, `owner_code`, `level`, `sort_order`, `role`, `ja`, `ja_furigana`, `vi`, `audio_path`, `audio_sha256`, `status`, `authored`, `seed_version`) VALUES
('JG-0007a9b1b6-E1', 'GRAMMAR', 'JG-0007a9b1b6', 'N5', 1, 'MAIN', 'このカードはどこでも使うことができます。', 'このカードはどこでも使(つか)うことができます。', 'Thẻ này dùng được ở bất cứ đâu.', 'learning-path/N5/JG-0007a9b1b6-ex1.mp3', '51845643674a9caa02ad455cfca3abdfd370a8d95233b53ea4b0cc530176b685', 'HOLD', 1, '3c5bc58917e7'),
('JG-0007a9b1b6-E2', 'GRAMMAR', 'JG-0007a9b1b6', 'N5', 2, 'EXTRA', '日本のコンビニはどこにでもあります。', '日本(にほん)のコンビニはどこにでもあります。', 'Cửa hàng tiện lợi ở Nhật chỗ nào cũng có.', 'learning-path/N5/JG-0007a9b1b6-ex2.mp3', '573b931f3c6e1887fb3d37ba2d37cf4bab428b6a81ec83047928ecf79266a4fa', 'HOLD', 1, '3c5bc58917e7'),
('JG-0007a9b1b6-E3', 'GRAMMAR', 'JG-0007a9b1b6', 'N5', 3, 'EXTRA', '昼ごはんはどこでもいいですよ。', '昼(ひる)ごはんはどこでもいいですよ。', 'Ăn trưa ở đâu cũng được.', 'learning-path/N5/JG-0007a9b1b6-ex3.mp3', '4d495979e2d93d881b7886d76814d6ddbd6161227987d0431e9fe7a839876410', 'HOLD', 1, '3c5bc58917e7'),
