('JG-13fef2ce63-C06', 'JG-13fef2ce63', 'N5', 'CHECK', 'MEANING', 6, '店から 電話を もらいました。', NULL, '["Cửa hàng không gọi cho tôi.","Tôi nhận được điện thoại từ cửa hàng.","Tôi mua điện thoại ở cửa hàng.","Tôi đã gọi điện cho cửa hàng."]', 1, NULL, NULL, NULL, NULL, 'から nhấn mạnh nguồn.', 'HOLD', 1, '3c5bc58917e7'),
('JG-13fef2ce63-C07', 'JG-13fef2ce63', 'N5', 'CHECK', 'ERROR', 7, 'Câu nào dùng sai mẫu?', NULL, '["母から 手紙を もらいました。","私は 友だちから プレゼントを くれました。","学校から 電話を もらいました。","先生から じしょを もらいました。"]', 1, NULL, NULL, NULL, NULL, 'Tôi nhận từ ai thì dùng もらいました.', 'HOLD', 1, '3c5bc58917e7'),
('JG-13fef2ce63-C08', 'JG-13fef2ce63', 'N5', 'CHECK', 'ERROR', 8, 'Câu nào dùng sai mẫu?', NULL, '["会社から 本を もらいました。","父から お金を もらいました。","姉から かさを もらいました。","私は 兄で 本を もらいました。"]', 3, NULL, NULL, NULL, NULL, 'Nguồn cho đi với から (hoặc に), không dùng で.', 'HOLD', 1, '3c5bc58917e7'),
('JG-13fef2ce63-F01', 'JG-13fef2ce63', 'N5', 'FILL', 'FILL_TEXT', 1, 'きのう 会社＿＿ 電話を もらいました。', NULL, NULL, NULL, NULL, NULL, 'から', NULL, 'Hôm qua tôi nhận được điện thoại từ công ty.', 'HOLD', 1, '3c5bc58917e7'),
('JG-13fef2ce63-F02', 'JG-13fef2ce63', 'N5', 'FILL', 'FILL_TEXT', 2, '私は 学校から 手紙を ＿＿ました。（もらう）', NULL, NULL, NULL, NULL, NULL, 'もらい', NULL, 'Tôi nhận được thư từ trường.', 'HOLD', 1, '3c5bc58917e7'),
('JG-13fef2ce63-O01', 'JG-13fef2ce63', 'N5', 'ORDER', 'ORDER', 1, '私は / とけいを / 父から / もらいました', NULL, NULL, NULL, '["私は","とけいを","父から","もらいました"]', '[0,2,1,3]', NULL, NULL, 'Tôi nhận được đồng hồ từ bố.', 'HOLD', 1, '3c5bc58917e7')
INSERT INTO `jpath_grammar_question` (`code`, `grammar_code`, `level`, `bank`, `question_type`, `sort_order`, `prompt_ja`, `prompt_furigana`, `options_json`, `answer_index`, `pieces_json`, `answer_order_json`, `answer_text`, `accept_json`, `explanation_vi`, `status`, `authored`, `seed_version`) VALUES
('JG-13fef2ce63-O02', 'JG-13fef2ce63', 'N5', 'ORDER', 'ORDER', 2, '本です / これは / もらった / 友だちから', NULL, NULL, NULL, '["本です","これは","もらった","友だちから"]', '[1,3,2,0]', NULL, NULL, 'Đây là cuốn sách tôi nhận từ bạn.', 'HOLD', 1, '3c5bc58917e7'),
('JG-13fef2ce63-X01', 'JG-13fef2ce63', 'N5', 'EXTRA', 'FILL', 1, 'A：その 本は 買いましたか。B：いいえ、先生（　　）もらいました。', NULL, '["から","が","で","を"]', 0, NULL, NULL, NULL, NULL, 'Nhận từ thầy → 先生から もらいました.', 'HOLD', 1, '3c5bc58917e7'),
('JG-13fef2ce63-X02', 'JG-13fef2ce63', 'N5', 'EXTRA', 'MEANING', 2, '私は 日本の 友だちから メールを もらいました。', NULL, '["Người bạn Nhật nhận được email của tôi.","Tôi nhận được email từ người bạn Nhật.","Tôi viết email bằng tiếng Nhật.","Tôi gửi email cho người bạn Nhật."]', 1, NULL, NULL, NULL, NULL, 'から もらいました = nhận từ.', 'HOLD', 1, '3c5bc58917e7'),
('JG-13fef2ce63-X03', 'JG-13fef2ce63', 'N5', 'EXTRA', 'ORDER_STAR', 3, '＿＿ ＿＿ ＿＿ ★ みかんを もらいました。', NULL, '["人","私は","から","となりの"]', 2, NULL, NULL, NULL, NULL, 'Câu đúng: 私はとなりの人からみかんをもらいました。 N から もらいました.', 'HOLD', 1, '3c5bc58917e7'),
('JG-1455934d05-C01', 'JG-1455934d05', 'N5', 'CHECK', 'FILL', 1, 'わたしは くだものが すきです。（　　）、りんごや みかんです。', NULL, '["でも","それから","たとえば","だから"]', 2, NULL, NULL, NULL, NULL, 'Nêu ví dụ cụ thể cho "hoa quả": たとえば.', 'HOLD', 1, '3c5bc58917e7'),
('JG-1455934d05-C02', 'JG-1455934d05', 'N5', 'CHECK', 'FILL', 2, '「どんな ところへ 行きたいですか。」「（　　）、京都や おおさかです。」', NULL, '["ですから","たとえば","それでは","どうして"]', 1, NULL, NULL, NULL, NULL, 'Trả lời bằng ví dụ cụ thể: たとえば.', 'HOLD', 1, '3c5bc58917e7'),
('JG-1455934d05-C03', 'JG-1455934d05', 'N5', 'CHECK', 'ORDER_STAR', 3, '日本の 食べものが すきです。★ ＿＿ ＿＿ ＿＿。', NULL, '["てんぷらです","たとえば","すし","や"]', 1, NULL, NULL, NULL, NULL, 'Thứ tự đúng: 「日本の 食べものが すきです。たとえば すし や てんぷらです。」. たとえば đứng đầu, sau đó là các ví dụ N や N.', 'HOLD', 1, '3c5bc58917e7'),
('JG-1455934d05-C04', 'JG-1455934d05', 'N5', 'CHECK', 'ORDER_STAR', 4, 'わたしは まいにち スポーツを します。＿＿ ＿＿ ★ ＿＿。', NULL, '["サッカーです","たとえば","テニス","や"]', 3, NULL, NULL, NULL, NULL, 'Thứ tự đúng: 「わたしは まいにち スポーツを します。たとえば テニス や サッカーです。」. たとえば + N や N: nêu ví dụ về môn thể thao.', 'HOLD', 1, '3c5bc58917e7'),
('JG-1455934d05-C05', 'JG-1455934d05', 'N5', 'CHECK', 'MEANING', 5, '日本の 町が すきです。たとえば、京都です。', NULL, '["Tôi thích Nhật nhưng không thích Kyoto.","Tôi thích Kyoto vì nó ở Nhật.","Tôi chỉ thích mỗi Kyoto.","Tôi thích các thành phố của Nhật, ví dụ như Kyoto."]', 3, NULL, NULL, NULL, NULL, 'たとえば = ví dụ như; Kyoto là một ví dụ.', 'HOLD', 1, '3c5bc58917e7'),
('JG-1455934d05-C06', 'JG-1455934d05', 'N5', 'CHECK', 'MEANING', 6, 'たとえば、この 本は どうですか。', NULL, '["Cuốn sách này hay nhất.","Ví dụ như cuốn sách này thì sao?","Tại sao lại là cuốn sách này?","Cuốn sách này của ai?"]', 1, NULL, NULL, NULL, NULL, 'たとえば + N は どうですか = ví dụ như N thì sao (gợi ý).', 'HOLD', 1, '3c5bc58917e7'),
('JG-1455934d05-C07', 'JG-1455934d05', 'N5', 'CHECK', 'ERROR', 7, 'Câu nào dùng sai mẫu?', NULL, '["くだものが すきです。たとえば、りんごです。","スポーツを します。たとえば、テニスです。","りんごや みかん、たとえば くだものが すきです。","たとえば、この かばんは どうですか。"]', 2, NULL, NULL, NULL, NULL, 'たとえば đứng trước ví dụ cụ thể, sau phần nói chung; ở đây bị đảo ngược.', 'HOLD', 1, '3c5bc58917e7'),
('JG-1455934d05-C08', 'JG-1455934d05', 'N5', 'CHECK', 'ERROR', 8, 'Câu nào dùng sai mẫu?', NULL, '["のみものは、たとえば コーヒーや こうちゃです。","あついですから、たとえば まどを あけます。","日本語の 本、たとえば この 本が いいです。","たとえば、あしたは どうですか。"]', 1, NULL, NULL, NULL, NULL, 'たとえば dùng để nêu ví dụ, không dùng để nối kết quả như "vì vậy".', 'HOLD', 1, '3c5bc58917e7'),
('JG-1455934d05-F01', 'JG-1455934d05', 'N5', 'FILL', 'FILL_TEXT', 1, 'くだものが すきです。＿＿、バナナです。', NULL, NULL, NULL, NULL, NULL, 'たとえば', NULL, 'Tôi thích hoa quả, ví dụ như chuối.', 'HOLD', 1, '3c5bc58917e7'),
('JG-1455934d05-F02', 'JG-1455934d05', 'N5', 'FILL', 'FILL_TEXT', 2, '「どこが いいですか。」「＿＿、こうえんは どうですか。」', NULL, NULL, NULL, NULL, NULL, 'たとえば', NULL, 'Chỗ nào thì được? - Ví dụ như công viên thì sao?', 'HOLD', 1, '3c5bc58917e7'),
('JG-1455934d05-O01', 'JG-1455934d05', 'N5', 'ORDER', 'ORDER', 1, 'みかんです / たとえば、 / りんごや', NULL, NULL, NULL, '["みかんです","たとえば、","りんごや"]', '[1,2,0]', NULL, NULL, 'Ví dụ như táo, quýt.', 'HOLD', 1, '3c5bc58917e7'),
('JG-1455934d05-O02', 'JG-1455934d05', 'N5', 'ORDER', 'ORDER', 2, 'この / たとえば、 / どうですか / シャツは', NULL, NULL, NULL, '["この","たとえば、","どうですか","シャツは"]', '[1,0,3,2]', NULL, NULL, 'Ví dụ như cái áo sơ mi này thì sao?', 'HOLD', 1, '3c5bc58917e7'),
('JG-1455934d05-X01', 'JG-1455934d05', 'N5', 'EXTRA', 'FILL', 1, 'わたしは のみものは、（　　） コーヒーが すきです。', NULL, '["たとえば","だから","でも","それから"]', 0, NULL, NULL, NULL, NULL, 'Nêu một ví dụ về đồ uống: たとえば.', 'HOLD', 1, '3c5bc58917e7'),
('JG-1455934d05-X02', 'JG-1455934d05', 'N5', 'EXTRA', 'MEANING', 2, 'やさい、たとえば トマトが すきです。', NULL, '["Tôi không thích rau nhưng thích cà chua.","Tôi chỉ thích cà chua.","Tôi thích rau, ví dụ như cà chua.","Tôi thích cà chua hơn rau."]', 2, NULL, NULL, NULL, NULL, 'たとえば nêu cà chua làm ví dụ cho rau.', 'HOLD', 1, '3c5bc58917e7'),
('JG-1455934d05-X03', 'JG-1455934d05', 'N5', 'EXTRA', 'ERROR', 3, 'Câu nào dùng sai mẫu?', NULL, '["日本の 町は、たとえば 東京や おおさかです。","たとえば、この くつは どうですか。","雨ですから、たとえば うちに います。","あまい ものが すきです。たとえば、ケーキです。"]', 2, NULL, NULL, NULL, NULL, 'たとえば không dùng để nêu kết quả; câu này không có ví dụ nào.', 'HOLD', 1, '3c5bc58917e7'),
('JG-14e46cf9f2-C01', 'JG-14e46cf9f2', 'N5', 'CHECK', 'FILL', 1, '私は 先生（　　）じしょを もらいました。', NULL, '["で","を","へ","に"]', 3, NULL, NULL, NULL, NULL, 'Người cho đi với に (hoặc から).', 'HOLD', 1, '3c5bc58917e7'),
('JG-14e46cf9f2-C02', 'JG-14e46cf9f2', 'N5', 'CHECK', 'FILL', 2, '妹は 友だちに 手紙を（　　）。', NULL, '["もらりました","もらいました","もらうました","もらいた"]', 1, NULL, NULL, NULL, NULL, 'もらう → もらいました.', 'HOLD', 1, '3c5bc58917e7'),
('JG-14e46cf9f2-C03', 'JG-14e46cf9f2', 'N5', 'CHECK', 'ORDER_STAR', 3, 'これは ＿＿ ★ ＿＿ ＿＿ です。', NULL, '["から","兄","シャツ","もらった"]', 0, NULL, NULL, NULL, NULL, 'Câu đúng: これは兄からもらったシャツです。 N から もらった + N = N nhận từ ai.', 'HOLD', 1, '3c5bc58917e7'),
('JG-14e46cf9f2-C04', 'JG-14e46cf9f2', 'N5', 'CHECK', 'ORDER_STAR', 4, '姉に ＿＿ ★ ＿＿ ＿＿ です。', NULL, '["とても","もらった","おいしかった","ケーキは"]', 3, NULL, NULL, NULL, NULL, 'Câu đúng: 姉にもらったケーキはとてもおいしかったです。 N に もらった N.', 'HOLD', 1, '3c5bc58917e7'),
('JG-14e46cf9f2-C05', 'JG-14e46cf9f2', 'N5', 'CHECK', 'MEANING', 5, '私は 山田さんに 本を もらいました。', NULL, '["Tôi được anh Yamada cho sách.","Tôi mượn sách của anh Yamada.","Tôi cho anh Yamada sách.","Anh Yamada được tôi cho sách."]', 0, NULL, NULL, NULL, NULL, 'もらう: nhìn từ phía người nhận (私).', 'HOLD', 1, '3c5bc58917e7'),
('JG-14e46cf9f2-C06', 'JG-14e46cf9f2', 'N5', 'CHECK', 'MEANING', 6, 'きのう 田中さんから メールを もらいました。', NULL, '["Hôm qua tôi không nhận được email.","Hôm qua tôi gửi email cho anh Tanaka.","Hôm qua anh Tanaka nhận email của tôi.","Hôm qua tôi nhận được email từ anh Tanaka."]', 3, NULL, NULL, NULL, NULL, 'から もらう = nhận từ.', 'HOLD', 1, '3c5bc58917e7'),
('JG-14e46cf9f2-C07', 'JG-14e46cf9f2', 'N5', 'CHECK', 'ERROR', 7, 'Câu nào dùng sai mẫu?', NULL, '["私は 兄に 本を もらいました。","私は 友だちから 手紙を あげました。","先生に ペンを もらいました。","母から 電話を もらいました。"]', 1, NULL, NULL, NULL, NULL, 'Nhận từ ai dùng もらいました; あげる là cho đi.', 'HOLD', 1, '3c5bc58917e7'),
('JG-14e46cf9f2-C08', 'JG-14e46cf9f2', 'N5', 'CHECK', 'ERROR', 8, 'Câu nào dùng sai mẫu?', NULL, '["私は 母が セーターを もらいました。","弟は 父に ゲームを もらいました。","だれに その かばんを もらいましたか。","私は 会社から 手紙を もらいました。"]', 0, NULL, NULL, NULL, NULL, 'Người cho đi với に/から, không dùng が.', 'HOLD', 1, '3c5bc58917e7'),
('JG-14e46cf9f2-F01', 'JG-14e46cf9f2', 'N5', 'FILL', 'FILL_TEXT', 1, '私は 先生に ペンを ＿＿ました。（もらう）', NULL, NULL, NULL, NULL, NULL, 'もらい', NULL, 'Tôi được thầy cho cây bút.', 'HOLD', 1, '3c5bc58917e7'),
('JG-14e46cf9f2-F02', 'JG-14e46cf9f2', 'N5', 'FILL', 'FILL_TEXT', 2, 'A：その かばん、どう したんですか。B：姉に ＿＿んです。（もらう）', NULL, NULL, NULL, NULL, NULL, 'もらった', NULL, 'A: Cái cặp đó ở đâu ra vậy? B: Tôi được chị cho đấy.', 'HOLD', 1, '3c5bc58917e7'),
('JG-14e46cf9f2-O01', 'JG-14e46cf9f2', 'N5', 'ORDER', 'ORDER', 1, '母から / 私は / 手紙を / もらいました', NULL, NULL, NULL, '["母から","私は","手紙を","もらいました"]', '[1,0,2,3]', NULL, NULL, 'Tôi nhận được thư từ mẹ.', 'HOLD', 1, '3c5bc58917e7'),
('JG-14e46cf9f2-O02', 'JG-14e46cf9f2', 'N5', 'ORDER', 'ORDER', 2, 'もらいましたか / だれに / 花を / その', NULL, NULL, NULL, '["もらいましたか","だれに","花を","その"]', '[1,3,2,0]', NULL, NULL, 'Bạn được ai tặng bó hoa đó?', 'HOLD', 1, '3c5bc58917e7'),
('JG-14e46cf9f2-X01', 'JG-14e46cf9f2', 'N5', 'EXTRA', 'FILL', 1, 'A：すてきな ぼうしですね。B：ありがとう。母（　　）もらいました。', NULL, '["で","に","を","が"]', 1, NULL, NULL, NULL, NULL, 'Người cho đi với に.', 'HOLD', 1, '3c5bc58917e7'),
('JG-14e46cf9f2-X02', 'JG-14e46cf9f2', 'N5', 'EXTRA', 'MEANING', 2, '弟は 父に じてんしゃを もらいました。', NULL, '["Bố được em trai cho xe đạp.","Em trai tôi mua xe đạp cho bố.","Em trai tôi được bố cho xe đạp.","Em trai tôi cho bố xe đạp."]', 2, NULL, NULL, NULL, NULL, 'A は B に N を もらう: A nhận N từ B.', 'HOLD', 1, '3c5bc58917e7'),
('JG-14e46cf9f2-X03', 'JG-14e46cf9f2', 'N5', 'EXTRA', 'ORDER_STAR', 3, '＿＿ ＿＿ ★ ＿＿ もらいました。', NULL, '["私は","りんごを","となりの","人に"]', 3, NULL, NULL, NULL, NULL, 'Câu đúng: 私はとなりの人にりんごをもらいました。 N に N を もらいました.', 'HOLD', 1, '3c5bc58917e7'),
('JG-15239d5b3e-C01', 'JG-15239d5b3e', 'N5', 'CHECK', 'FILL', 1, '私は まだ ひこうきに（　　）ことが ありません。', NULL, '["のりた","のった","のって","のり"]', 1, NULL, NULL, NULL, NULL, 'Chưa từng → Vた ことが ありません.', 'HOLD', 1, '3c5bc58917e7'),
('JG-15239d5b3e-C02', 'JG-15239d5b3e', 'N5', 'CHECK', 'FILL', 2, 'A：ゆきを 見た ことが ありますか。B：いいえ、見た ことが（　　）。', NULL, '["ありません","しません","いません","あります"]', 0, NULL, NULL, NULL, NULL, 'Trả lời phủ định → Vた ことが ありません.', 'HOLD', 1, '3c5bc58917e7'),
('JG-15239d5b3e-C03', 'JG-15239d5b3e', 'N5', 'CHECK', 'ORDER_STAR', 3, '私は ＿＿ ＿＿ ★ ＿＿ ありません。', NULL, '["ことが","日本の","新聞を","読んだ"]', 3, NULL, NULL, NULL, NULL, 'Câu đúng: 私は日本の新聞を読んだことがありません。 Vた ことが ありません = chưa từng.', 'HOLD', 1, '3c5bc58917e7'),
('JG-15239d5b3e-C04', 'JG-15239d5b3e', 'N5', 'CHECK', 'ORDER_STAR', 4, '兄は ＿＿ ★ ＿＿ ＿＿。', NULL, '["ありません","休んだ","学校を","ことが"]', 1, NULL, NULL, NULL, NULL, 'Câu đúng: 兄は学校を休んだことがありません。 休んだ ことが ありません = chưa từng nghỉ.', 'HOLD', 1, '3c5bc58917e7'),
('JG-15239d5b3e-C05', 'JG-15239d5b3e', 'N5', 'CHECK', 'MEANING', 5, '私は 外国へ 行った ことが ありません。', NULL, '["Tôi chưa từng đi nước ngoài.","Tôi đã từng đi nước ngoài.","Tôi sẽ không đi nước ngoài.","Tôi không muốn đi nước ngoài."]', 0, NULL, NULL, NULL, NULL, 'Vた ことが ありません = chưa từng.', 'HOLD', 1, '3c5bc58917e7'),
