('JG-4f77fc0d0b-C01', 'JG-4f77fc0d0b', 'N5', 'CHECK', 'FILL', 1, 'かぜで まどが （　　）。', NULL, '["あけました","あいて","あきました","あけて"]', 2, NULL, NULL, NULL, NULL, 'Tự động từ đi với が: まどが あきました (cửa sổ tự mở).', 'HOLD', 1, '3c5bc58917e7'),
('JG-4f77fc0d0b-C02', 'JG-4f77fc0d0b', 'N5', 'CHECK', 'FILL', 2, 'へやの でんき （　　） きえました。', NULL, '["が","を","で","に"]', 0, NULL, NULL, NULL, NULL, 'Tự động từ きえる đi với が.', 'HOLD', 1, '3c5bc58917e7'),
