('JG-4f77fc0d0b-C05', 'JG-4f77fc0d0b', 'N5', 'CHECK', 'MEANING', 5, 'ドアが しまりました。', NULL, '["Tôi đã đóng cửa.","Hãy đóng cửa lại.","Cánh cửa đã đóng lại.","Cánh cửa vẫn mở."]', 2, NULL, NULL, NULL, NULL, 'しまる là tự động từ: cửa tự đóng, không nói ai đóng.', 'HOLD', 1, '3c5bc58917e7'),
('JG-4f77fc0d0b-C06', 'JG-4f77fc0d0b', 'N5', 'CHECK', 'MEANING', 6, 'でんきが つきました。', NULL, '["Tôi đã bật đèn.","Đèn đã tắt.","Đèn đã sáng lên.","Hãy bật đèn lên."]', 2, NULL, NULL, NULL, NULL, 'つく là tự động từ: đèn sáng lên.', 'HOLD', 1, '3c5bc58917e7'),
('JG-4f77fc0d0b-C07', 'JG-4f77fc0d0b', 'N5', 'CHECK', 'ERROR', 7, 'Câu nào dùng sai mẫu?', NULL, '["まどが あけました。","まどが あきました。","でんきが つきました。","ドアが しまりました。"]', 0, NULL, NULL, NULL, NULL, 'Với が phải dùng tự động từ あきました; あけました là tha động từ đi với を.', 'HOLD', 1, '3c5bc58917e7'),
