('JG-9ce4ca1ba3-C06', 'JG-9ce4ca1ba3', 'N5', 'CHECK', 'MEANING', 6, 'きょうは きのうより さむいです。', NULL, '["Hôm qua lạnh hơn hôm nay.","Hôm nay không lạnh bằng hôm qua.","Hôm nay lạnh hơn hôm qua.","Hôm nay và hôm qua đều lạnh."]', 2, NULL, NULL, NULL, NULL, 'きのうより さむい = lạnh hơn hôm qua.', 'HOLD', 1, '3c5bc58917e7'),
('JG-9ce4ca1ba3-C07', 'JG-9ce4ca1ba3', 'N5', 'CHECK', 'ERROR', 7, 'Câu nào dùng sai mẫu?', NULL, '["わたしは あにより せが ひくいです。","わたしは あにから せが ひくいです。","あには わたしより せが 高いです。","いもうとは わたしより 小さいです。"]', 1, NULL, NULL, NULL, NULL, 'So sánh dùng より, không dùng から.', 'HOLD', 1, '3c5bc58917e7'),
('JG-9ce4ca1ba3-C08', 'JG-9ce4ca1ba3', 'N5', 'CHECK', 'ERROR', 8, 'Câu nào dùng sai mẫu?', NULL, '["ひこうきは 車より はやいです。","ひこうきは 車より はやいの ほうです。","車より ひこうきの ほうが はやいです。","車は ひこうきより おそいです。"]', 1, NULL, NULL, NULL, NULL, 'Mẫu N1 は N2 より A không thêm の ほう sau tính từ.', 'HOLD', 1, '3c5bc58917e7'),
('JG-9ce4ca1ba3-F01', 'JG-9ce4ca1ba3', 'N5', 'FILL', 'FILL_TEXT', 1, 'ベトナムは 日本 ＿＿ あついです。', NULL, NULL, NULL, NULL, NULL, 'より', NULL, 'Việt Nam nóng hơn Nhật Bản.', 'HOLD', 1, '3c5bc58917e7'),
('JG-9ce4ca1ba3-F02', 'JG-9ce4ca1ba3', 'N5', 'FILL', 'FILL_TEXT', 2, 'わたしの へやは あにの へやより ＿＿ です。（rộng）', NULL, NULL, NULL, NULL, NULL, 'ひろい', NULL, 'Phòng của tôi rộng hơn phòng anh trai.', 'HOLD', 1, '3c5bc58917e7'),
('JG-9ce4ca1ba3-O01', 'JG-9ce4ca1ba3', 'N5', 'ORDER', 'ORDER', 1, 'さむいです / ふゆは / なつより', NULL, NULL, NULL, '["さむいです","ふゆは","なつより"]', '[1,2,0]', NULL, NULL, 'Mùa đông lạnh hơn mùa hè.', 'HOLD', 1, '3c5bc58917e7'),
('JG-9ce4ca1ba3-O02', 'JG-9ce4ca1ba3', 'N5', 'ORDER', 'ORDER', 2, 'おもしろいです / この 本は / あの 本より', NULL, NULL, NULL, '["おもしろいです","この 本は","あの 本より"]', '[1,2,0]', NULL, NULL, 'Cuốn sách này hay hơn cuốn kia.', 'HOLD', 1, '3c5bc58917e7')
INSERT INTO `jpath_grammar_question` (`code`, `grammar_code`, `level`, `bank`, `question_type`, `sort_order`, `prompt_ja`, `prompt_furigana`, `options_json`, `answer_index`, `pieces_json`, `answer_order_json`, `answer_text`, `accept_json`, `explanation_vi`, `status`, `authored`, `seed_version`) VALUES
('JG-9ce4ca1ba3-X01', 'JG-9ce4ca1ba3', 'N5', 'EXTRA', 'FILL', 1, 'ちかてつは バス （　　） はやいです。', NULL, '["ほう","より","から","まで"]', 1, NULL, NULL, NULL, NULL, 'So sánh hơn: N2 より.', 'HOLD', 1, '3c5bc58917e7'),
('JG-9ce4ca1ba3-X02', 'JG-9ce4ca1ba3', 'N5', 'EXTRA', 'MEANING', 2, '母は 父より 早く おきます。', NULL, '["Mẹ tôi dậy sớm hơn bố.","Bố tôi dậy sớm hơn mẹ.","Mẹ và bố dậy sớm như nhau.","Mẹ tôi dậy muộn hơn bố."]', 0, NULL, NULL, NULL, NULL, '父より 早く = sớm hơn bố.', 'HOLD', 1, '3c5bc58917e7'),
('JG-9ce4ca1ba3-X03', 'JG-9ce4ca1ba3', 'N5', 'EXTRA', 'ERROR', 3, 'Câu nào dùng sai mẫu?', NULL, '["この みせは あの みせより 安いです。","この みせは あの みせよりを 安いです。","この みせの ほうが 安いです。","あの みせは この みせより 高いです。"]', 1, NULL, NULL, NULL, NULL, 'より không thêm を.', 'HOLD', 1, '3c5bc58917e7'),
('JG-9d12efd7d2-C01', 'JG-9d12efd7d2', 'N5', 'CHECK', 'FILL', 1, '私は田中さんに写真を（　　）もらいました。', NULL, '["とり","とって","とる","とった"]', 1, NULL, NULL, NULL, NULL, 'Được ai làm cho mình: Vて + もらう.', 'HOLD', 1, '3c5bc58917e7'),
('JG-9d12efd7d2-C02', 'JG-9d12efd7d2', 'N5', 'CHECK', 'FILL', 2, '私は友だち（　　）日本語を教えてもらいました。', NULL, '["を","に","で","が"]', 1, NULL, NULL, NULL, NULL, 'Người làm giúp đi với に: 友だちに〜てもらいました.', 'HOLD', 1, '3c5bc58917e7'),
('JG-9d12efd7d2-C03', 'JG-9d12efd7d2', 'N5', 'CHECK', 'ORDER_STAR', 3, '私は ＿＿ ＿＿ ＿＿ ★ もらいました。', NULL, '["に","セーターを","母","作って"]', 3, NULL, NULL, NULL, NULL, 'Câu đúng: 私は母にセーターを作ってもらいました。 Nghĩa: Tôi được mẹ đan áo len cho. 作って + もらいました.', 'HOLD', 1, '3c5bc58917e7'),
('JG-9d12efd7d2-C04', 'JG-9d12efd7d2', 'N5', 'CHECK', 'ORDER_STAR', 4, '私は先生に日本語の手紙を ＿＿ ★ ＿＿ ＿＿。', NULL, '["読んで","よ","ました","もらい"]', 3, NULL, NULL, NULL, NULL, 'Câu đúng: 私は先生に日本語の手紙を読んでもらいましたよ。 Nghĩa: Tôi đã được thầy đọc giúp lá thư tiếng Nhật. 読んで + もらいました.', 'HOLD', 1, '3c5bc58917e7'),
('JG-9d12efd7d2-C05', 'JG-9d12efd7d2', 'N5', 'CHECK', 'MEANING', 5, '私は山田さんにかさを貸してもらいました。', NULL, '["Anh Yamada đã mượn ô của tôi.","Anh Yamada đã cho tôi mượn ô.","Tôi đã cho anh Yamada mượn ô.","Tôi đã mua ô cho anh Yamada."]', 1, NULL, NULL, NULL, NULL, 'Nに〜てもらう = được ai làm cho.', 'HOLD', 1, '3c5bc58917e7'),
('JG-9d12efd7d2-C06', 'JG-9d12efd7d2', 'N5', 'CHECK', 'MEANING', 6, '友だちに駅まで来てもらいました。', NULL, '["Bạn đã nhờ tôi đến ga.","Tôi đã nhờ bạn đến tận ga.","Tôi đã đến ga đón bạn.","Bạn tôi không đến ga."]', 1, NULL, NULL, NULL, NULL, '来てもらう = được (nhờ) ai đến.', 'HOLD', 1, '3c5bc58917e7'),
('JG-9d12efd7d2-C07', 'JG-9d12efd7d2', 'N5', 'CHECK', 'ERROR', 7, 'Câu nào dùng sai mẫu?', NULL, '["私は兄に英語を教えてもらいました。","私は母にお弁当を作ってもらいました。","私は先生に本を貸してもらいました。","私は友だちを写真をとってもらいました。"]', 3, NULL, NULL, NULL, NULL, 'Người làm giúp đi với に: 友だちに.', 'HOLD', 1, '3c5bc58917e7'),
('JG-9d12efd7d2-C08', 'JG-9d12efd7d2', 'N5', 'CHECK', 'ERROR', 8, 'Câu nào dùng sai mẫu?', NULL, '["私は田中さんに地図をかくもらいました。","私は友だちに荷物を持ってもらいました。","私は姉にケーキを買ってもらいました。","私は父に駅まで来てもらいました。"]', 0, NULL, NULL, NULL, NULL, 'Trước もらう dùng thể て: かいてもらいました.', 'HOLD', 1, '3c5bc58917e7'),
('JG-9d12efd7d2-F01', 'JG-9d12efd7d2', 'N5', 'FILL', 'FILL_TEXT', 1, '私は先生に漢字を教え＿＿もらいました。', NULL, NULL, NULL, NULL, NULL, 'て', NULL, 'Tôi được thầy giáo dạy chữ Hán.', 'HOLD', 1, '3c5bc58917e7'),
('JG-9d12efd7d2-F02', 'JG-9d12efd7d2', 'N5', 'FILL', 'FILL_TEXT', 2, '私は田中さんに駅までの道を教えて＿＿。', NULL, NULL, NULL, NULL, NULL, 'もらいました', NULL, 'Tôi được anh Tanaka chỉ đường đến ga.', 'HOLD', 1, '3c5bc58917e7'),
('JG-9d12efd7d2-O01', 'JG-9d12efd7d2', 'N5', 'ORDER', 'ORDER', 1, '時計を / 買ってもらいました / 私 / 父に / は', NULL, NULL, NULL, '["時計を","買ってもらいました","私","父に","は"]', '[2,4,3,0,1]', NULL, NULL, 'Tôi được bố mua cho cái đồng hồ.', 'HOLD', 1, '3c5bc58917e7'),
('JG-9d12efd7d2-O02', 'JG-9d12efd7d2', 'N5', 'ORDER', 'ORDER', 2, '友だち / とって / に / 写真を / もらいました', NULL, NULL, NULL, '["友だち","とって","に","写真を","もらいました"]', '[0,2,3,1,4]', NULL, NULL, 'Tôi được bạn chụp ảnh cho.', 'HOLD', 1, '3c5bc58917e7'),
('JG-9d12efd7d2-X01', 'JG-9d12efd7d2', 'N5', 'EXTRA', 'FILL', 1, 'A：きれいな写真ですね。B：ありがとう。友だちにとって（　　）。', NULL, '["なりました","もらいました","しました","ありました"]', 1, NULL, NULL, NULL, NULL, 'Được bạn chụp cho → とってもらいました.', 'HOLD', 1, '3c5bc58917e7'),
('JG-9d12efd7d2-X02', 'JG-9d12efd7d2', 'N5', 'EXTRA', 'MEANING', 2, '私は母に料理を教えてもらいました。', NULL, '["Tôi được mẹ dạy nấu ăn.","Tôi đã dạy mẹ nấu ăn.","Tôi nấu ăn cho mẹ.","Mẹ tôi đã đi học nấu ăn."]', 0, NULL, NULL, NULL, NULL, 'Vてもらう: mình là người được giúp.', 'HOLD', 1, '3c5bc58917e7'),
('JG-9d12efd7d2-X03', 'JG-9d12efd7d2', 'N5', 'EXTRA', 'ERROR', 3, 'Câu nào dùng sai mẫu?', NULL, '["私は友だちに手紙を読んでもらいました。","私は友だちにペンを貸すてもらいました。","私は友だちに歌を歌ってもらいました。","私は友だちにノートを見せてもらいました。"]', 1, NULL, NULL, NULL, NULL, '貸す → 貸して: 貸してもらいました.', 'HOLD', 1, '3c5bc58917e7'),
('JG-9d6ba97c98-C01', 'JG-9d6ba97c98', 'N5', 'CHECK', 'FILL', 1, 'わたしは 日本語 （　　） できます。', NULL, '["を","で","に","が"]', 3, NULL, NULL, NULL, NULL, 'できます đi với が: N が できます.', 'HOLD', 1, '3c5bc58917e7'),
('JG-9d6ba97c98-C02', 'JG-9d6ba97c98', 'N5', 'CHECK', 'FILL', 2, 'ここで しゃしんを とる （　　） が できません。', NULL, '["こと","もの","ところ","とき"]', 0, NULL, NULL, NULL, NULL, 'Vる + ことが できます/できません.', 'HOLD', 1, '3c5bc58917e7'),
('JG-9d6ba97c98-C03', 'JG-9d6ba97c98', 'N5', 'CHECK', 'ORDER_STAR', 3, 'わたしは ＿＿ ＿＿ ★ ＿＿。', NULL, '["ひく","ことが","できます","ピアノを"]', 1, NULL, NULL, NULL, NULL, 'Thứ tự đúng: 「わたしは ピアノを ひく ことが できます。」. Vる + ことが できます.', 'HOLD', 1, '3c5bc58917e7'),
('JG-9d6ba97c98-C04', 'JG-9d6ba97c98', 'N5', 'CHECK', 'ORDER_STAR', 4, '＿＿ ★ ＿＿ ＿＿。', NULL, '["ことは","およぐ","ここで","できません"]', 1, NULL, NULL, NULL, NULL, 'Thứ tự đúng: 「ここで およぐ ことは できません。」. Thể từ điển (およぐ) đứng trước ことは できません.', 'HOLD', 1, '3c5bc58917e7'),
('JG-9d6ba97c98-C05', 'JG-9d6ba97c98', 'N5', 'CHECK', 'MEANING', 5, 'あには 日本語が できます。', NULL, '["Anh trai tôi đang học tiếng Nhật.","Anh trai tôi không biết tiếng Nhật.","Anh trai tôi biết tiếng Nhật.","Anh trai tôi thích tiếng Nhật."]', 2, NULL, NULL, NULL, NULL, 'N が できます = biết, có khả năng làm N.', 'HOLD', 1, '3c5bc58917e7'),
('JG-9d6ba97c98-C06', 'JG-9d6ba97c98', 'N5', 'CHECK', 'MEANING', 6, 'この へやで たばこを すう ことが できません。', NULL, '["Có thể hút thuốc trong phòng này.","Hãy hút thuốc trong phòng này.","Không được hút thuốc trong phòng này.","Phòng này có nhiều thuốc lá."]', 2, NULL, NULL, NULL, NULL, '〜ことが できません = không thể (không được phép) làm.', 'HOLD', 1, '3c5bc58917e7'),
('JG-9d6ba97c98-C07', 'JG-9d6ba97c98', 'N5', 'CHECK', 'ERROR', 7, 'Câu nào dùng sai mẫu?', NULL, '["わたしは テニスを できます。","わたしは テニスが できます。","母は りょうりが できます。","あには ギターを ひく ことが できます。"]', 0, NULL, NULL, NULL, NULL, 'できます đi với が: テニスが できます.', 'HOLD', 1, '3c5bc58917e7'),
('JG-9d6ba97c98-C08', 'JG-9d6ba97c98', 'N5', 'CHECK', 'ERROR', 8, 'Câu nào dùng sai mẫu?', NULL, '["わたしは かんじを 書きことが できます。","わたしは かんじを 書く ことが できます。","ここで 本を 読む ことが できます。","いもうとは およぐ ことが できます。"]', 0, NULL, NULL, NULL, NULL, 'Trước こと dùng thể từ điển: 書く ことが できます.', 'HOLD', 1, '3c5bc58917e7'),
('JG-9d6ba97c98-F01', 'JG-9d6ba97c98', 'N5', 'FILL', 'FILL_TEXT', 1, 'わたしは スキーが ＿＿。（biết, có thể）', NULL, NULL, NULL, NULL, NULL, 'できます', NULL, 'Tôi biết trượt tuyết.', 'HOLD', 1, '3c5bc58917e7'),
('JG-9d6ba97c98-F02', 'JG-9d6ba97c98', 'N5', 'FILL', 'FILL_TEXT', 2, 'ここで およぐ ＿＿ が できません。', NULL, NULL, NULL, NULL, NULL, 'こと', NULL, 'Ở đây không thể bơi.', 'HOLD', 1, '3c5bc58917e7'),
('JG-9d6ba97c98-O01', 'JG-9d6ba97c98', 'N5', 'ORDER', 'ORDER', 1, 'かんじを / ことが / できます / 書く', NULL, NULL, NULL, '["かんじを","ことが","できます","書く"]', '[0,3,1,2]', NULL, NULL, 'Tôi có thể viết chữ Hán.', 'HOLD', 1, '3c5bc58917e7'),
('JG-9d6ba97c98-O02', 'JG-9d6ba97c98', 'N5', 'ORDER', 'ORDER', 2, 'えいごが / できます / あには', NULL, NULL, NULL, '["えいごが","できます","あには"]', '[2,0,1]', NULL, NULL, 'Anh trai tôi biết tiếng Anh.', 'HOLD', 1, '3c5bc58917e7'),
('JG-9d6ba97c98-X01', 'JG-9d6ba97c98', 'N5', 'EXTRA', 'FILL', 1, '田中さんは ギターを ひく ことが （　　）。', NULL, '["あります","します","なります","できます"]', 3, NULL, NULL, NULL, NULL, '〜ことが できます = có thể làm.', 'HOLD', 1, '3c5bc58917e7'),
('JG-9d6ba97c98-X02', 'JG-9d6ba97c98', 'N5', 'EXTRA', 'MEANING', 2, 'いもうとは まだ 字を 書く ことが できません。', NULL, '["Em gái tôi đã biết viết chữ.","Em gái tôi không thích viết chữ.","Em gái tôi vẫn chưa biết viết chữ.","Em gái tôi đang viết chữ."]', 2, NULL, NULL, NULL, NULL, 'まだ〜できません = vẫn chưa thể.', 'HOLD', 1, '3c5bc58917e7'),
('JG-9d6ba97c98-X03', 'JG-9d6ba97c98', 'N5', 'EXTRA', 'ERROR', 3, 'Câu nào dùng sai mẫu?', NULL, '["わたしは およぐ ことが できます。","母は 日本語が できます。","わたしは およぐが できます。","ここで かいものが できます。"]', 2, NULL, NULL, NULL, NULL, 'Động từ phải thêm こと trước が できます: およぐ ことが できます.', 'HOLD', 1, '3c5bc58917e7'),
('JG-9da239be95-C01', 'JG-9da239be95', 'N5', 'CHECK', 'FILL', 1, 'あの 人は（　　）ですか。—田中さんです。', NULL, '["だれ","どんな","いつ","なに"]', 0, NULL, NULL, NULL, NULL, 'Hỏi người là ai → だれですか.', 'HOLD', 1, '3c5bc58917e7'),
('JG-9da239be95-C02', 'JG-9da239be95', 'N5', 'CHECK', 'FILL', 2, '山田さんは（　　）人ですか。—やさしい 人です。', NULL, '["なに","どう","どんな","だれ"]', 2, NULL, NULL, NULL, NULL, 'Hỏi tính cách → どんな 人ですか.', 'HOLD', 1, '3c5bc58917e7'),
('JG-9da239be95-C03', 'JG-9da239be95', 'N5', 'CHECK', 'ORDER_STAR', 3, 'あそこで ＿＿ ＿＿ ★ ＿＿ だれですか。', NULL, '["人は","いる","本を","読んで"]', 1, NULL, NULL, NULL, NULL, 'Câu đúng: あそこで本を読んでいる人はだれですか。 Mệnh đề + 人は だれですか.', 'HOLD', 1, '3c5bc58917e7'),
('JG-9da239be95-C04', 'JG-9da239be95', 'N5', 'CHECK', 'ORDER_STAR', 4, 'あなたの ＿＿ ★ ＿＿ ＿＿。', NULL, '["ところ","ですか","どんな","大学は"]', 2, NULL, NULL, NULL, NULL, 'Câu đúng: あなたの大学はどんなところですか。 どんな + N ですか.', 'HOLD', 1, '3c5bc58917e7'),
('JG-9da239be95-C05', 'JG-9da239be95', 'N5', 'CHECK', 'MEANING', 5, 'あの めがねの 人は だれですか。', NULL, '["Người đeo kính kia thế nào?","Người kia đeo kính gì?","Người đeo kính kia là ai?","Cái kính đó là của ai?"]', 2, NULL, NULL, NULL, NULL, '〜は だれですか = … là ai.', 'HOLD', 1, '3c5bc58917e7'),
('JG-9da239be95-C06', 'JG-9da239be95', 'N5', 'CHECK', 'MEANING', 6, '田中さんの 会社は どんな 会社ですか。', NULL, '["Công ty anh Tanaka ở đâu?","Công ty anh Tanaka có mấy người?","Ai là giám đốc công ty anh Tanaka?","Công ty của anh Tanaka là công ty như thế nào?"]', 3, NULL, NULL, NULL, NULL, 'どんな + N = N như thế nào.', 'HOLD', 1, '3c5bc58917e7'),
