INSERT INTO `jpath_grammar_question` (`code`, `grammar_code`, `level`, `bank`, `question_type`, `sort_order`, `prompt_ja`, `prompt_furigana`, `options_json`, `answer_index`, `pieces_json`, `answer_order_json`, `answer_text`, `accept_json`, `explanation_vi`, `status`, `authored`, `seed_version`) VALUES
('JG-c2de063a13-S04', 'JG-c2de063a13', 'N5', 'SITU', 'SITUATION', 4, 'Nói bạn thích âm nhạc. ‖ この場面で何と言いますか。', 'Nói bạn thích âm nhạc. ‖ この場面(ばめん)で何(なん)と言(い)いますか。', '["私は音楽が好きです。","私は音楽を好きです。","私は音楽に好きです。","私は音楽へ好きです。"]', 0, NULL, NULL, NULL, NULL, 'Sở thích dùng N + が + 好き. を/に/へ sai.', 'AI_CHECKED', 1, '3c5bc58917e7'),
('JG-c2de063a13-X01', 'JG-c2de063a13', 'N5', 'EXTRA', 'FILL', 1, 'A：何（　　）好きですか。B：音楽が好きです。', NULL, '["が","を","で","に"]', 0, NULL, NULL, NULL, NULL, 'Hỏi sở thích: 何が好きですか.', 'AI_CHECKED', 1, '3c5bc58917e7'),
('JG-c2de063a13-X02', 'JG-c2de063a13', 'N5', 'EXTRA', 'MEANING', 2, '私はあまり肉が好きじゃありません。', NULL, '["Tôi chỉ thích thịt.","Tôi không ăn thịt.","Tôi không thích thịt lắm.","Tôi rất thích thịt."]', 2, NULL, NULL, NULL, NULL, 'あまり好きじゃありません = không thích lắm.', 'AI_CHECKED', 1, '3c5bc58917e7'),
('JG-c2de063a13-X03', 'JG-c2de063a13', 'N5', 'EXTRA', 'ERROR', 3, 'Câu nào dùng sai mẫu?', NULL, '["私はテニスが好きます。","弟はゲームが好きです。","私は日本語が好きです。","母は花が好きです。"]', 0, NULL, NULL, NULL, NULL, '好き là tính từ な, không chia như động từ. Đúng: 好きです。', 'AI_CHECKED', 1, '3c5bc58917e7'),
('JG-c5b9bc987b-C01', 'JG-c5b9bc987b', 'N5', 'CHECK', 'FILL', 1, 'うちから えきまで あるいて 十分 （　　） です。', NULL, '["ぐらい","ごろ","ずつ","など"]', 0, NULL, NULL, NULL, NULL, 'Khoảng (thời lượng, số lượng): ぐらい/くらい.', 'HOLD', 1, '3c5bc58917e7'),
('JG-c5b9bc987b-C02', 'JG-c5b9bc987b', 'N5', 'CHECK', 'FILL', 2, 'まいにち 二時間 （　　） べんきょうします。', NULL, '["くらい","ごろ","など","や"]', 0, NULL, NULL, NULL, NULL, 'Khoảng thời gian dùng くらい; ごろ chỉ dùng cho thời điểm.', 'HOLD', 1, '3c5bc58917e7'),
('JG-c5b9bc987b-C03', 'JG-c5b9bc987b', 'N5', 'CHECK', 'ORDER_STAR', 3, '＿＿ ＿＿ ★ ＿＿。', NULL, '["三千円","この かばんは","ぐらい","でした"]', 2, NULL, NULL, NULL, NULL, 'Thứ tự đúng: 「この かばんは 三千円 ぐらい でした。」. Số lượng + ぐらい = khoảng.', 'HOLD', 1, '3c5bc58917e7'),
('JG-c5b9bc987b-C04', 'JG-c5b9bc987b', 'N5', 'CHECK', 'ORDER_STAR', 4, '＿＿ ＿＿ ★ ＿＿。', NULL, '["バスで","学校まで","くらいです","二十分"]', 3, NULL, NULL, NULL, NULL, 'Thứ tự đúng: 「学校まで バスで 二十分 くらいです。」. Thời lượng + くらいです.', 'HOLD', 1, '3c5bc58917e7'),
('JG-c5b9bc987b-C05', 'JG-c5b9bc987b', 'N5', 'CHECK', 'MEANING', 5, 'へやに 人が 二十人ぐらい います。', NULL, '["Trong phòng có đúng 20 người.","Trong phòng có hơn 20 người.","Trong phòng có ít hơn 20 người.","Trong phòng có khoảng 20 người."]', 3, NULL, NULL, NULL, NULL, 'ぐらい = khoảng.', 'HOLD', 1, '3c5bc58917e7'),
('JG-c5b9bc987b-C06', 'JG-c5b9bc987b', 'N5', 'CHECK', 'MEANING', 6, 'この 本は 千円くらいです。', NULL, '["Cuốn sách này khoảng 1000 yên.","Cuốn sách này đúng 1000 yên.","Cuốn sách này 100 yên.","Cuốn sách này 10.000 yên."]', 0, NULL, NULL, NULL, NULL, '千円くらい = khoảng 1000 yên.', 'HOLD', 1, '3c5bc58917e7'),
('JG-c5b9bc987b-C07', 'JG-c5b9bc987b', 'N5', 'CHECK', 'ERROR', 7, 'Câu nào dùng sai mẫu?', NULL, '["この くつは 五千円ぐらいです。","えきまで 十分ぐらいです。","この くつは 五千円ごろです。","まいばん 一時間くらい テレビを 見ます。"]', 2, NULL, NULL, NULL, NULL, 'Giá tiền ước chừng dùng ぐらい, không dùng ごろ.', 'HOLD', 1, '3c5bc58917e7'),
('JG-c5b9bc987b-C08', 'JG-c5b9bc987b', 'N5', 'CHECK', 'ERROR', 8, 'Câu nào dùng sai mẫu?', NULL, '["日本へ 来て 一年ごろです。","日本へ 来て 一年ぐらいです。","クラスに 学生が 三十人ぐらい います。","ここから えきまで 一キロぐらいです。"]', 0, NULL, NULL, NULL, NULL, 'Khoảng thời gian (một năm) dùng ぐらい; ごろ chỉ dùng cho thời điểm.', 'HOLD', 1, '3c5bc58917e7'),
('JG-c5b9bc987b-F01', 'JG-c5b9bc987b', 'N5', 'FILL', 'FILL_TEXT', 1, 'この シャツは 二千円 ＿＿ です。', NULL, NULL, NULL, NULL, NULL, 'ぐらい', '["くらい"]', 'Cái áo sơ mi này khoảng 2000 yên.', 'HOLD', 1, '3c5bc58917e7'),
('JG-c5b9bc987b-F02', 'JG-c5b9bc987b', 'N5', 'FILL', 'FILL_TEXT', 2, '東京から 大阪まで しんかんせんで 三時間 ＿＿ です。', NULL, NULL, NULL, NULL, NULL, 'くらい', '["ぐらい"]', 'Từ Tokyo đến Osaka đi tàu shinkansen mất khoảng 3 tiếng.', 'HOLD', 1, '3c5bc58917e7'),
('JG-c5b9bc987b-O01', 'JG-c5b9bc987b', 'N5', 'ORDER', 'ORDER', 1, '五分ぐらいです / えきまで / あるいて', NULL, NULL, NULL, '["五分ぐらいです","えきまで","あるいて"]', '[1,2,0]', NULL, NULL, 'Đi bộ đến ga mất khoảng 5 phút.', 'HOLD', 1, '3c5bc58917e7'),
('JG-c5b9bc987b-O02', 'JG-c5b9bc987b', 'N5', 'ORDER', 'ORDER', 2, '日本語を べんきょうします / 一時間ぐらい / まいにち', NULL, NULL, NULL, '["日本語を べんきょうします","一時間ぐらい","まいにち"]', '[2,1,0]', NULL, NULL, 'Mỗi ngày tôi học tiếng Nhật khoảng 1 tiếng.', 'HOLD', 1, '3c5bc58917e7'),
('JG-c5b9bc987b-X01', 'JG-c5b9bc987b', 'N5', 'EXTRA', 'FILL', 1, '日本に 十年 （　　） すんで います。', NULL, '["ごろ","ぐらい","など","ずつ"]', 1, NULL, NULL, NULL, NULL, 'Khoảng thời gian: 十年ぐらい.', 'HOLD', 1, '3c5bc58917e7'),
('JG-c5b9bc987b-X02', 'JG-c5b9bc987b', 'N5', 'EXTRA', 'MEANING', 2, 'この 水は 百円ぐらいです。', NULL, '["Chai nước này đúng 100 yên.","Chai nước này khoảng 100 yên.","Chai nước này 1000 yên.","Chai nước này miễn phí."]', 1, NULL, NULL, NULL, NULL, 'ぐらい = khoảng.', 'HOLD', 1, '3c5bc58917e7'),
('JG-c5b9bc987b-X03', 'JG-c5b9bc987b', 'N5', 'EXTRA', 'ERROR', 3, 'Câu nào dùng sai mẫu?', NULL, '["あの 人は 三十さいぐらいです。","ここから 十分ぐらいです。","この 本は 二千円くらいです。","あの 人は 三十さいごろです。"]', 3, NULL, NULL, NULL, NULL, 'Tuổi ước chừng dùng ぐらい, không dùng ごろ.', 'HOLD', 1, '3c5bc58917e7'),
('JG-c645b96cd3-C01', 'JG-c645b96cd3', 'N5', 'CHECK', 'FILL', 1, 'A：あしたは休み？B：うん、休み（　　）よ。', NULL, '["を","い","だ","く"]', 2, NULL, NULL, NULL, NULL, 'Dạng thường của です sau danh từ là だ: 休みだよ.', 'HOLD', 1, '3c5bc58917e7'),
('JG-c645b96cd3-C02', 'JG-c645b96cd3', 'N5', 'CHECK', 'FILL', 2, 'きょうはいい天気（　　）ね。', NULL, '["い","だ","な","を"]', 1, NULL, NULL, NULL, NULL, 'Nói thân mật: いい天気だね.', 'HOLD', 1, '3c5bc58917e7'),
('JG-c645b96cd3-C03', 'JG-c645b96cd3', 'N5', 'CHECK', 'ORDER_STAR', 3, 'あの人は ＿＿ ＿＿ ＿＿ ★ よ。', NULL, '["だ","先生","私の","日本語の"]', 0, NULL, NULL, NULL, NULL, 'Câu đúng: あの人は私の日本語の先生だよ。 Nghĩa: Người kia là giáo viên tiếng Nhật của tôi đấy. だ đứng sau danh từ.', 'HOLD', 1, '3c5bc58917e7'),
('JG-c645b96cd3-C04', 'JG-c645b96cd3', 'N5', 'CHECK', 'ORDER_STAR', 4, 'A：これ、だれのかばん？B： ＿＿ ★ ＿＿ ＿＿ よ。', NULL, '["かばん","の","山田さん","だ"]', 1, NULL, NULL, NULL, NULL, 'Câu đúng: A：これ、だれのかばん？B：山田さんのかばんだよ。 Nghĩa: Là cặp của anh Yamada đấy. 山田さんのかばん + だ.', 'HOLD', 1, '3c5bc58917e7'),
('JG-c645b96cd3-C05', 'JG-c645b96cd3', 'N5', 'CHECK', 'MEANING', 5, 'あしたは雨だ。', NULL, '["Hôm qua trời mưa.","Ngày mai trời có mưa không?","Ngày mai trời mưa.","Ngày mai trời không mưa."]', 2, NULL, NULL, NULL, NULL, 'だ = です ở dạng thường.', 'HOLD', 1, '3c5bc58917e7'),
('JG-c645b96cd3-C06', 'JG-c645b96cd3', 'N5', 'CHECK', 'MEANING', 6, '父は医者だ。', NULL, '["Bố tôi là bác sĩ.","Bố tôi muốn làm bác sĩ.","Bố tôi không phải bác sĩ.","Bố tôi từng là bác sĩ."]', 0, NULL, NULL, NULL, NULL, 'N1はN2だ = N1 là N2 (dạng thường).', 'HOLD', 1, '3c5bc58917e7'),
('JG-c645b96cd3-C07', 'JG-c645b96cd3', 'N5', 'CHECK', 'ERROR', 7, 'Câu nào dùng sai mẫu?', NULL, '["このかばんは高い。","このかばんは私のだ。","このかばんはきれいだ。","このかばんは高いだ。"]', 3, NULL, NULL, NULL, NULL, 'Tính từ い không thêm だ. Đúng: 高い。', 'HOLD', 1, '3c5bc58917e7'),
('JG-c645b96cd3-C08', 'JG-c645b96cd3', 'N5', 'CHECK', 'ERROR', 8, 'Câu nào dùng sai mẫu?', NULL, '["あしたはテストだね。","あしたは休みだか。","あしたは休みだ。","あしたは日曜日だよ。"]', 1, NULL, NULL, NULL, NULL, 'Câu hỏi thân mật bỏ だ: あしたは休み？', 'HOLD', 1, '3c5bc58917e7'),
('JG-c645b96cd3-F01', 'JG-c645b96cd3', 'N5', 'FILL', 'FILL_TEXT', 1, 'A：これ、何？B：日本のお菓子＿＿よ。', NULL, NULL, NULL, NULL, NULL, 'だ', NULL, 'A: Cái này là gì? B: Là bánh kẹo Nhật đấy.', 'HOLD', 1, '3c5bc58917e7'),
('JG-c645b96cd3-F02', 'JG-c645b96cd3', 'N5', 'FILL', 'FILL_TEXT', 2, 'この町はとても静か＿＿。', NULL, NULL, NULL, NULL, NULL, 'だ', NULL, 'Thị trấn này rất yên tĩnh. (dạng thường)', 'HOLD', 1, '3c5bc58917e7'),
('JG-c645b96cd3-O01', 'JG-c645b96cd3', 'N5', 'ORDER', 'ORDER', 1, 'だ / は / きょう / 私の / 誕生日', NULL, NULL, NULL, '["だ","は","きょう","私の","誕生日"]', '[2,1,3,4,0]', NULL, NULL, 'Hôm nay là sinh nhật tôi.', 'HOLD', 1, '3c5bc58917e7'),
('JG-c645b96cd3-O02', 'JG-c645b96cd3', 'N5', 'ORDER', 'ORDER', 2, 'だよ / は / 山田さん / 人 / あの', NULL, NULL, NULL, '["だよ","は","山田さん","人","あの"]', '[4,3,1,2,0]', NULL, NULL, 'Người kia là anh Yamada đấy.', 'HOLD', 1, '3c5bc58917e7'),
('JG-c645b96cd3-X01', 'JG-c645b96cd3', 'N5', 'EXTRA', 'FILL', 1, 'A：田中さんは学生？B：ううん、会社員（　　）。', NULL, '["いよ","をよ","くよ","だよ"]', 3, NULL, NULL, NULL, NULL, 'Danh từ + だよ trong văn nói thân mật.', 'HOLD', 1, '3c5bc58917e7'),
('JG-c645b96cd3-X02', 'JG-c645b96cd3', 'N5', 'EXTRA', 'MEANING', 2, 'ぼくの好きな食べ物はカレーだ。', NULL, '["Tôi không thích cà ri.","Cà ri có ngon không?","Món tôi thích là cà ri.","Tôi đã ăn cà ri."]', 2, NULL, NULL, NULL, NULL, 'だ kết thúc câu khẳng định thân mật.', 'HOLD', 1, '3c5bc58917e7'),
('JG-c645b96cd3-X03', 'JG-c645b96cd3', 'N5', 'EXTRA', 'ERROR', 3, 'Câu nào dùng sai mẫu?', NULL, '["きょうは寒いね。","きょうは寒いだね。","きょうは休みだね。","きょうは雨だね。"]', 1, NULL, NULL, NULL, NULL, 'Tính từ い không thêm だ: 寒いね.', 'HOLD', 1, '3c5bc58917e7'),
('JG-c6f7a485c1-C01', 'JG-c6f7a485c1', 'N5', 'CHECK', 'FILL', 1, 'しゅくだいは もう しましたか。—いいえ、（　　）です。', NULL, '["まだ","もう","すぐ","もっと"]', 0, NULL, NULL, NULL, NULL, 'Trả lời “chưa” → いいえ、まだです.', 'HOLD', 1, '3c5bc58917e7'),
('JG-c6f7a485c1-C02', 'JG-c6f7a485c1', 'N5', 'CHECK', 'FILL', 2, '田中さんは（　　）来て いません。', NULL, '["すぐ","さっき","もっと","まだ"]', 3, NULL, NULL, NULL, NULL, 'まだ + V-て いません = vẫn chưa….', 'HOLD', 1, '3c5bc58917e7'),
('JG-c6f7a485c1-C03', 'JG-c6f7a485c1', 'N5', 'CHECK', 'ORDER_STAR', 3, 'ばんごはんは ＿＿ ★ ＿＿ ＿＿、いっしょに 食べましょう。', NULL, '["まだ","食べて","から","いません"]', 1, NULL, NULL, NULL, NULL, 'Câu đúng: ばんごはんはまだ食べていませんから、いっしょに食べましょう。 まだ 食べて いません = vẫn chưa ăn.', 'HOLD', 1, '3c5bc58917e7'),
('JG-c6f7a485c1-C04', 'JG-c6f7a485c1', 'N5', 'CHECK', 'ORDER_STAR', 4, '妹は ＿＿ ★ ＿＿ ＿＿、学校へ 行きません。', NULL, '["五さい","です","まだ","から"]', 0, NULL, NULL, NULL, NULL, 'Câu đúng: 妹はまだ五さいですから、学校へ行きません。 まだ + N です = vẫn còn (nhỏ)….', 'HOLD', 1, '3c5bc58917e7'),
('JG-c6f7a485c1-C05', 'JG-c6f7a485c1', 'N5', 'CHECK', 'MEANING', 5, 'まだ ねて いません。', NULL, '["Tôi sắp đi ngủ.","Tôi không ngủ nữa.","Tôi đã ngủ rồi.","Tôi vẫn chưa ngủ."]', 3, NULL, NULL, NULL, NULL, 'まだ + V-て いません = vẫn chưa.', 'HOLD', 1, '3c5bc58917e7'),
('JG-c6f7a485c1-C06', 'JG-c6f7a485c1', 'N5', 'CHECK', 'MEANING', 6, 'かぜは まだ よく なりません。', NULL, '["Bệnh cảm vẫn chưa khỏi.","Bệnh cảm không nặng.","Bệnh cảm sắp khỏi.","Bệnh cảm đã khỏi rồi."]', 0, NULL, NULL, NULL, NULL, 'まだ + phủ định = vẫn chưa.', 'HOLD', 1, '3c5bc58917e7'),
('JG-c6f7a485c1-C07', 'JG-c6f7a485c1', 'N5', 'CHECK', 'ERROR', 7, 'Câu nào dùng sai mẫu?', NULL, '["まだ 昼ごはんを 食べました。","まだ 何も 買って いません。","まだ 時間が ありますよ。","まだ 雨が ふって います。"]', 0, NULL, NULL, NULL, NULL, '“Vẫn chưa ăn” là まだ 食べて いません; まだ không đi với 食べました.', 'HOLD', 1, '3c5bc58917e7'),
('JG-c6f7a485c1-C08', 'JG-c6f7a485c1', 'N5', 'CHECK', 'ERROR', 8, 'Câu nào dùng sai mẫu?', NULL, '["まだ 名前を 書いて いません。","兄は まだ 学生です。","まだ 九時ですよ。","手紙は まだ 書きました。"]', 3, NULL, NULL, NULL, NULL, 'まだ + V-て いません mới là “chưa viết”; まだ 書きました là sai.', 'HOLD', 1, '3c5bc58917e7'),
('JG-c6f7a485c1-F01', 'JG-c6f7a485c1', 'N5', 'FILL', 'FILL_TEXT', 1, 'もう 起きましたか。—いいえ、＿＿ ねて います。', NULL, NULL, NULL, NULL, NULL, 'まだ', NULL, 'Dậy chưa? — Chưa, vẫn đang ngủ.', 'HOLD', 1, '3c5bc58917e7'),
('JG-c6f7a485c1-F02', 'JG-c6f7a485c1', 'N5', 'FILL', 'FILL_TEXT', 2, 'まだ 手紙を 書い＿＿ いません。', NULL, NULL, NULL, NULL, NULL, 'て', NULL, 'Tôi vẫn chưa viết thư.', 'HOLD', 1, '3c5bc58917e7'),
('JG-c6f7a485c1-O01', 'JG-c6f7a485c1', 'N5', 'ORDER', 'ORDER', 1, 'いません / 食べて / まだ / 何も', NULL, NULL, NULL, '["いません","食べて","まだ","何も"]', '[2,3,1,0]', NULL, NULL, 'Tôi vẫn chưa ăn gì cả.', 'HOLD', 1, '3c5bc58917e7'),
('JG-c6f7a485c1-O02', 'JG-c6f7a485c1', 'N5', 'ORDER', 'ORDER', 2, '読んで / その / まだ / 本は / いません', NULL, NULL, NULL, '["読んで","その","まだ","本は","いません"]', '[1,3,2,0,4]', NULL, NULL, 'Cuốn sách đó tôi vẫn chưa đọc.', 'HOLD', 1, '3c5bc58917e7'),
