('JG-db85b4b3fa-O02', 'JG-db85b4b3fa', 'N5', 'ORDER', 'ORDER', 2, 'かばんが / ことが / もつ / おもくて / できません', NULL, NULL, NULL, '["かばんが","ことが","もつ","おもくて","できません"]', '[0,3,2,1,4]', NULL, NULL, 'Cặp nặng quá nên tôi không xách được.', 'HOLD', 1, '3c5bc58917e7'),
('JG-db85b4b3fa-X01', 'JG-db85b4b3fa', 'N5', 'EXTRA', 'FILL', 1, 'この くつは（　　）、歩く ことが できません。', NULL, '["小さくて","小さいて","小さいで","小さくで"]', 0, NULL, NULL, NULL, NULL, '小さい → 小さくて.', 'HOLD', 1, '3c5bc58917e7'),
('JG-db85b4b3fa-X02', 'JG-db85b4b3fa', 'N5', 'EXTRA', 'MEANING', 2, 'テストが むずかしくて、ぜんぜん できませんでした。', NULL, '["Tôi không làm bài kiểm tra.","Bài kiểm tra khó nhưng tôi làm được.","Bài kiểm tra khó quá nên tôi hoàn toàn không làm được.","Bài kiểm tra dễ nên tôi làm được hết."]', 2, NULL, NULL, NULL, NULL, 'Aくて + phủ định = vì… nên không….', 'HOLD', 1, '3c5bc58917e7'),
('JG-db85b4b3fa-X03', 'JG-db85b4b3fa', 'N5', 'EXTRA', 'ORDER_STAR', 3, '目が ＿＿ ＿＿ ★ ＿＿ できません。', NULL, '["本を","いたくて","ことが","読む"]', 3, NULL, NULL, NULL, NULL, 'Câu đúng: 目がいたくて本を読むことができません。 Aくて + ことが できません.', 'HOLD', 1, '3c5bc58917e7'),
('JG-dbad118de2-C01', 'JG-dbad118de2', 'N5', 'CHECK', 'FILL', 1, 'びょういんでは （　　） はなして ください。', NULL, '["しずかな","しずかで","しずかに","しずかだ"]', 2, NULL, NULL, NULL, NULL, 'Tính từ な bổ nghĩa cho động từ dùng 〜に: しずかに はなします.', 'HOLD', 1, '3c5bc58917e7'),
('JG-dbad118de2-C02', 'JG-dbad118de2', 'N5', 'CHECK', 'FILL', 2, '山田さんは えいごを （　　） はなします。', NULL, '["じょうずな","じょうずで","じょうずに","じょうずく"]', 2, NULL, NULL, NULL, NULL, 'じょうず là tính từ な; trước động từ dùng じょうずに.', 'HOLD', 1, '3c5bc58917e7'),
('JG-dbad118de2-C03', 'JG-dbad118de2', 'N5', 'CHECK', 'ORDER_STAR', 3, '＿＿ ＿＿ ★ ＿＿ ください。', NULL, '["字を","書いて","きれいに","もっと"]', 2, NULL, NULL, NULL, NULL, 'Thứ tự đúng: 「字を もっと きれいに 書いて ください。」. きれいに đứng ngay trước động từ 書いて mà nó bổ nghĩa.', 'HOLD', 1, '3c5bc58917e7'),
('JG-dbad118de2-C04', 'JG-dbad118de2', 'N5', 'CHECK', 'ORDER_STAR', 4, '＿＿ ＿＿ ★ ＿＿ ください。', NULL, '["はなして","ここでは","もう すこし","しずかに"]', 3, NULL, NULL, NULL, NULL, 'Thứ tự đúng: 「ここでは もう すこし しずかに はなして ください。」. もう すこし bổ nghĩa cho しずかに, しずかに bổ nghĩa cho はなして.', 'HOLD', 1, '3c5bc58917e7'),
('JG-dbad118de2-C05', 'JG-dbad118de2', 'N5', 'CHECK', 'MEANING', 5, 'あには ギターを じょうずに ひきます。', NULL, '["Anh trai tôi chơi đàn ghi-ta dở.","Anh trai tôi muốn chơi ghi-ta giỏi.","Anh trai tôi không chơi ghi-ta.","Anh trai tôi chơi đàn ghi-ta giỏi."]', 3, NULL, NULL, NULL, NULL, 'じょうずに ひきます = chơi (đàn) giỏi.', 'HOLD', 1, '3c5bc58917e7'),
('JG-dbad118de2-C06', 'JG-dbad118de2', 'N5', 'CHECK', 'MEANING', 6, 'つくえの 上を きれいに して ください。', NULL, '["Hãy dọn mặt bàn cho sạch sẽ.","Mặt bàn sạch quá.","Mặt bàn đã sạch rồi.","Mặt bàn bẩn quá."]', 0, NULL, NULL, NULL, NULL, 'きれいに して ください = hãy làm cho sạch.', 'HOLD', 1, '3c5bc58917e7'),
('JG-dbad118de2-C07', 'JG-dbad118de2', 'N5', 'CHECK', 'ERROR', 7, 'Câu nào dùng sai mẫu?', NULL, '["としょかんで しずかに べんきょうします。","としょかんで しずかな べんきょうします。","へやを きれいに します。","日本語を じょうずに はなします。"]', 1, NULL, NULL, NULL, NULL, 'Trước động từ phải dùng 〜に: しずかに べんきょうします; しずかな chỉ đứng trước danh từ.', 'HOLD', 1, '3c5bc58917e7')
INSERT INTO `jpath_grammar_question` (`code`, `grammar_code`, `level`, `bank`, `question_type`, `sort_order`, `prompt_ja`, `prompt_furigana`, `options_json`, `answer_index`, `pieces_json`, `answer_order_json`, `answer_text`, `accept_json`, `explanation_vi`, `status`, `authored`, `seed_version`) VALUES
('JG-dbad118de2-C08', 'JG-dbad118de2', 'N5', 'CHECK', 'ERROR', 8, 'Câu nào dùng sai mẫu?', NULL, '["子どもが げんきに あそんで います。","子どもが げんきく あそんで います。","字を きれいに 書きます。","みんなで にぎやかに うたいます。"]', 1, NULL, NULL, NULL, NULL, 'げんき là tính từ な nên dùng げんきに, không dùng く.', 'HOLD', 1, '3c5bc58917e7'),
('JG-dbad118de2-F01', 'JG-dbad118de2', 'N5', 'FILL', 'FILL_TEXT', 1, '字を ＿＿ 書いて ください。（きれい）', NULL, NULL, NULL, NULL, NULL, 'きれいに', NULL, 'Hãy viết chữ cho đẹp.', 'HOLD', 1, '3c5bc58917e7'),
('JG-dbad118de2-F02', 'JG-dbad118de2', 'N5', 'FILL', 'FILL_TEXT', 2, 'としょかんでは ＿＿ して ください。（しずか）', NULL, NULL, NULL, NULL, NULL, 'しずかに', NULL, 'Ở thư viện xin hãy giữ yên lặng.', 'HOLD', 1, '3c5bc58917e7'),
('JG-dbad118de2-O01', 'JG-dbad118de2', 'N5', 'ORDER', 'ORDER', 1, 'します / へやを / きれいに', NULL, NULL, NULL, '["します","へやを","きれいに"]', '[1,2,0]', NULL, NULL, 'Tôi dọn căn phòng cho sạch sẽ.', 'HOLD', 1, '3c5bc58917e7'),
('JG-dbad118de2-O02', 'JG-dbad118de2', 'N5', 'ORDER', 'ORDER', 2, 'して / ください / しずかに / もう すこし', NULL, NULL, NULL, '["して","ください","しずかに","もう すこし"]', '[3,2,0,1]', NULL, NULL, 'Hãy giữ yên lặng hơn một chút.', 'HOLD', 1, '3c5bc58917e7'),
('JG-dbad118de2-X01', 'JG-dbad118de2', 'N5', 'EXTRA', 'FILL', 1, '田中さんは りょうりを （　　） つくります。', NULL, '["じょうずに","じょうずな","じょうずだ","じょうずく"]', 0, NULL, NULL, NULL, NULL, 'Bổ nghĩa cho động từ つくります dùng じょうずに.', 'HOLD', 1, '3c5bc58917e7'),
('JG-dbad118de2-X02', 'JG-dbad118de2', 'N5', 'EXTRA', 'MEANING', 2, '子どもたちは げんきに あそんで います。', NULL, '["Bọn trẻ khỏe mạnh nhưng không chơi.","Bọn trẻ đang chơi đùa hăng hái.","Bọn trẻ đang chơi một cách lặng lẽ.","Bọn trẻ muốn chơi đùa."]', 1, NULL, NULL, NULL, NULL, 'げんきに あそんで います = đang chơi một cách hăng hái, khỏe khoắn.', 'HOLD', 1, '3c5bc58917e7'),
('JG-dbad118de2-X03', 'JG-dbad118de2', 'N5', 'EXTRA', 'ERROR', 3, 'Câu nào dùng sai mẫu?', NULL, '["母は へやを きれいに します。","しずかに ドアを しめます。","母は へやを きれく します。","日本語を じょうずに 書きます。"]', 2, NULL, NULL, NULL, NULL, 'きれい là tính từ な, dùng きれいに します.', 'HOLD', 1, '3c5bc58917e7'),
('JG-dbcd98f1dc-C01', 'JG-dbcd98f1dc', 'N5', 'CHECK', 'FILL', 1, 'この 本は （　　）。', NULL, '["おもしろいだです","おもしろです","おもしろいです","おもしろいなです"]', 2, NULL, NULL, NULL, NULL, 'N は Aい です: giữ nguyên い rồi thêm です.', 'HOLD', 1, '3c5bc58917e7'),
('JG-dbcd98f1dc-C02', 'JG-dbcd98f1dc', 'N5', 'CHECK', 'FILL', 2, 'がっこうは （　　） です。', NULL, '["大きいな","大きい","大きく","大き"]', 1, NULL, NULL, NULL, NULL, 'Trước です giữ nguyên tính từ い: 大きいです.', 'HOLD', 1, '3c5bc58917e7'),
('JG-dbcd98f1dc-C03', 'JG-dbcd98f1dc', 'N5', 'CHECK', 'ORDER_STAR', 3, '＿＿ ＿＿ ★ ＿＿。', NULL, '["かばんは","おもいです","とても","わたしの"]', 2, NULL, NULL, NULL, NULL, 'Thứ tự đúng: 「わたしの かばんは とても おもいです。」. とても đứng trước tính từ.', 'HOLD', 1, '3c5bc58917e7'),
('JG-dbcd98f1dc-C04', 'JG-dbcd98f1dc', 'N5', 'CHECK', 'ORDER_STAR', 4, '＿＿ ＿＿ ★ ＿＿。', NULL, '["です","からい","りょうりは","この"]', 1, NULL, NULL, NULL, NULL, 'Thứ tự đúng: 「この りょうりは からい です。」. N は Aい です.', 'HOLD', 1, '3c5bc58917e7'),
('JG-dbcd98f1dc-C05', 'JG-dbcd98f1dc', 'N5', 'CHECK', 'MEANING', 5, 'この へやは あかるいです。', NULL, '["Căn phòng này tối.","Căn phòng này sáng sủa.","Căn phòng này không sáng.","Căn phòng này rộng."]', 1, NULL, NULL, NULL, NULL, 'あかるいです = sáng sủa.', 'HOLD', 1, '3c5bc58917e7'),
('JG-dbcd98f1dc-C06', 'JG-dbcd98f1dc', 'N5', 'CHECK', 'MEANING', 6, 'きょうは さむいです。', NULL, '["Hôm nay trời nóng.","Hôm qua trời lạnh.","Hôm nay trời không lạnh.","Hôm nay trời lạnh."]', 3, NULL, NULL, NULL, NULL, 'さむいです = lạnh.', 'HOLD', 1, '3c5bc58917e7'),
('JG-dbcd98f1dc-C07', 'JG-dbcd98f1dc', 'N5', 'CHECK', 'ERROR', 7, 'Câu nào dùng sai mẫu?', NULL, '["この ケーキは あまいです。","えきは とおいです。","日本語は おもしろいです。","この ケーキは あまいだです。"]', 3, NULL, NULL, NULL, NULL, 'Tính từ い + です, không thêm だ.', 'HOLD', 1, '3c5bc58917e7'),
('JG-dbcd98f1dc-C08', 'JG-dbcd98f1dc', 'N5', 'CHECK', 'ERROR', 8, 'Câu nào dùng sai mẫu?', NULL, '["この 山は 高いなです。","この 山は 高いです。","あの みせは 安いです。","わたしの へやは せまいです。"]', 0, NULL, NULL, NULL, NULL, 'Tính từ い + です, không thêm な.', 'HOLD', 1, '3c5bc58917e7'),
('JG-dbcd98f1dc-F01', 'JG-dbcd98f1dc', 'N5', 'FILL', 'FILL_TEXT', 1, 'この スープは ＿＿ です。（nóng）', NULL, NULL, NULL, NULL, NULL, 'あつい', NULL, 'Món súp này nóng.', 'HOLD', 1, '3c5bc58917e7'),
('JG-dbcd98f1dc-F02', 'JG-dbcd98f1dc', 'N5', 'FILL', 'FILL_TEXT', 2, 'わたしの うちは えきから ＿＿ です。（xa）', NULL, NULL, NULL, NULL, NULL, 'とおい', NULL, 'Nhà tôi xa ga.', 'HOLD', 1, '3c5bc58917e7'),
('JG-dbcd98f1dc-O01', 'JG-dbcd98f1dc', 'N5', 'ORDER', 'ORDER', 1, 'なつは / あついです / 日本の', NULL, NULL, NULL, '["なつは","あついです","日本の"]', '[2,0,1]', NULL, NULL, 'Mùa hè Nhật Bản nóng.', 'HOLD', 1, '3c5bc58917e7'),
('JG-dbcd98f1dc-O02', 'JG-dbcd98f1dc', 'N5', 'ORDER', 'ORDER', 2, 'かるいです / かばんは / この', NULL, NULL, NULL, '["かるいです","かばんは","この"]', '[2,1,0]', NULL, NULL, 'Cái cặp này nhẹ.', 'HOLD', 1, '3c5bc58917e7'),
('JG-dbcd98f1dc-X01', 'JG-dbcd98f1dc', 'N5', 'EXTRA', 'FILL', 1, 'きょうの テストは （　　） です。', NULL, '["むずかしいな","むずかしく","むずかしい","むずかしの"]', 2, NULL, NULL, NULL, NULL, 'N は Aい です: むずかしいです.', 'HOLD', 1, '3c5bc58917e7'),
('JG-dbcd98f1dc-X02', 'JG-dbcd98f1dc', 'N5', 'EXTRA', 'MEANING', 2, 'この くつは 安いです。', NULL, '["Đôi giày này đắt.","Đôi giày này không rẻ.","Đôi giày này mới.","Đôi giày này rẻ."]', 3, NULL, NULL, NULL, NULL, '安いです = rẻ.', 'HOLD', 1, '3c5bc58917e7'),
('JG-dbcd98f1dc-X03', 'JG-dbcd98f1dc', 'N5', 'EXTRA', 'ERROR', 3, 'Câu nào dùng sai mẫu?', NULL, '["この 水は つめたいです。","この へやは ひろいです。","この 水は つめたくです。","あの 人は せが 高いです。"]', 2, NULL, NULL, NULL, NULL, 'Trước です giữ nguyên い: つめたいです.', 'HOLD', 1, '3c5bc58917e7'),
('JG-dc06119c3d-C01', 'JG-dc06119c3d', 'N5', 'CHECK', 'FILL', 1, 'バスより でんしゃ （　　） はやいです。', NULL, '["のが ほう","ほうの","が ほう","の ほうが"]', 3, NULL, NULL, NULL, NULL, 'N1 より N2 の ほうが A.', 'HOLD', 1, '3c5bc58917e7'),
('JG-dc06119c3d-C02', 'JG-dc06119c3d', 'N5', 'CHECK', 'FILL', 2, 'きょねん （　　） ことしの ほうが あついです。', NULL, '["から","まで","より","ほう"]', 2, NULL, NULL, NULL, NULL, 'Vật bị so sánh đi với より.', 'HOLD', 1, '3c5bc58917e7'),
('JG-dc06119c3d-C03', 'JG-dc06119c3d', 'N5', 'CHECK', 'ORDER_STAR', 3, '＿＿ ＿＿ ★ ＿＿。', NULL, '["さかなの","にくより","ほうが","すきです"]', 2, NULL, NULL, NULL, NULL, 'Thứ tự đúng: 「にくより さかなの ほうが すきです。」. N1 より N2 の ほうが すきです.', 'HOLD', 1, '3c5bc58917e7'),
('JG-dc06119c3d-C04', 'JG-dc06119c3d', 'N5', 'CHECK', 'ORDER_STAR', 4, '＿＿ ★ ＿＿ ＿＿。', NULL, '["ほうが","ひろいです","この へやより","あの へやの"]', 3, NULL, NULL, NULL, NULL, 'Thứ tự đúng: 「この へやより あの へやの ほうが ひろいです。」. N2 の ほうが: cái hơn.', 'HOLD', 1, '3c5bc58917e7'),
('JG-dc06119c3d-C05', 'JG-dc06119c3d', 'N5', 'CHECK', 'MEANING', 5, 'でんしゃより バスの ほうが 安いです。', NULL, '["Tàu điện rẻ hơn xe buýt.","Xe buýt và tàu điện giá bằng nhau.","Xe buýt rẻ hơn tàu điện.","Xe buýt đắt hơn tàu điện."]', 2, NULL, NULL, NULL, NULL, 'N の ほうが = N hơn; より = so với.', 'HOLD', 1, '3c5bc58917e7'),
('JG-dc06119c3d-C06', 'JG-dc06119c3d', 'N5', 'CHECK', 'MEANING', 6, 'ひらがなより かんじの ほうが むずかしいです。', NULL, '["Chữ Hán khó hơn chữ hiragana.","Chữ hiragana khó hơn chữ Hán.","Chữ Hán và hiragana đều dễ.","Chữ Hán không khó bằng hiragana."]', 0, NULL, NULL, NULL, NULL, 'かんじの ほうが むずかしい = chữ Hán khó hơn.', 'HOLD', 1, '3c5bc58917e7'),
('JG-dc06119c3d-C07', 'JG-dc06119c3d', 'N5', 'CHECK', 'ERROR', 7, 'Câu nào dùng sai mẫu?', NULL, '["わたしより あにの ほうが 高いです。","あには わたしより 高いです。","わたしより いもうとの ほうが 小さいです。","わたしより あにが ほうが 高いです。"]', 3, NULL, NULL, NULL, NULL, 'ほう là danh từ nên đi sau の: あにの ほうが.', 'HOLD', 1, '3c5bc58917e7'),
('JG-dc06119c3d-C08', 'JG-dc06119c3d', 'N5', 'CHECK', 'ERROR', 8, 'Câu nào dùng sai mẫu?', NULL, '["なつより ふゆの ほうが すきです。","ふゆの ほうが すきです。","なつより ふゆを ほうが すきです。","ふゆは なつより さむいです。"]', 2, NULL, NULL, NULL, NULL, 'Đúng là ふゆの ほうが, không dùng を.', 'HOLD', 1, '3c5bc58917e7'),
('JG-dc06119c3d-F01', 'JG-dc06119c3d', 'N5', 'FILL', 'FILL_TEXT', 1, '犬より ねこ ＿＿ ほうが すきです。', NULL, NULL, NULL, NULL, NULL, 'の', NULL, 'Tôi thích mèo hơn chó.', 'HOLD', 1, '3c5bc58917e7'),
('JG-dc06119c3d-F02', 'JG-dc06119c3d', 'N5', 'FILL', 'FILL_TEXT', 2, 'ことしは きょねん ＿＿ さむいです。', NULL, NULL, NULL, NULL, NULL, 'より', NULL, 'Năm nay lạnh hơn năm ngoái.', 'HOLD', 1, '3c5bc58917e7'),
('JG-dc06119c3d-O01', 'JG-dc06119c3d', 'N5', 'ORDER', 'ORDER', 1, 'ちかてつの / ほうが / はやいです / タクシーより', NULL, NULL, NULL, '["ちかてつの","ほうが","はやいです","タクシーより"]', '[3,0,1,2]', NULL, NULL, 'Tàu điện ngầm nhanh hơn taxi.', 'HOLD', 1, '3c5bc58917e7'),
('JG-dc06119c3d-O02', 'JG-dc06119c3d', 'N5', 'ORDER', 'ORDER', 2, 'くだものの / すきです / ほうが / やさいより', NULL, NULL, NULL, '["くだものの","すきです","ほうが","やさいより"]', '[3,0,2,1]', NULL, NULL, 'Tôi thích hoa quả hơn rau.', 'HOLD', 1, '3c5bc58917e7'),
('JG-dc06119c3d-X01', 'JG-dc06119c3d', 'N5', 'EXTRA', 'FILL', 1, 'あした （　　） あさっての ほうが ひまです。', NULL, '["から","まで","より","の"]', 2, NULL, NULL, NULL, NULL, 'Vật bị so sánh đi với より.', 'HOLD', 1, '3c5bc58917e7'),
