('JG-ffae1ad9ba-O02', 'JG-ffae1ad9ba', 'N5', 'ORDER', 'ORDER', 2, 'わかりますか / かんじが / この', NULL, NULL, NULL, '["わかりますか","かんじが","この"]', '[2,1,0]', NULL, NULL, 'Bạn có hiểu chữ Hán này không?', 'HOLD', 1, '3c5bc58917e7'),
('JG-ffae1ad9ba-X01', 'JG-ffae1ad9ba', 'N5', 'EXTRA', 'FILL', 1, '「この ことばが わかりますか。」「いいえ、（　　）。」', NULL, '["わかります","すきです","わかりました","わかりません"]', 3, NULL, NULL, NULL, NULL, 'いいえ + phủ định: わかりません.', 'HOLD', 1, '3c5bc58917e7'),
('JG-ffae1ad9ba-X02', 'JG-ffae1ad9ba', 'N5', 'EXTRA', 'MEANING', 2, 'フランス語が わかりますか。', NULL, '["Bạn có thích tiếng Pháp không?","Bạn có học tiếng Pháp không?","Bạn có hiểu tiếng Pháp không?","Bạn có đi Pháp không?"]', 2, NULL, NULL, NULL, NULL, 'わかりますか = có hiểu không?', 'HOLD', 1, '3c5bc58917e7'),
('JG-ffae1ad9ba-X03', 'JG-ffae1ad9ba', 'N5', 'EXTRA', 'ERROR', 3, 'Câu nào dùng sai mẫu?', NULL, '["あなたは ねこが すきですか。","この みちが わかりますか。","あなたは ねこに すきですか。","日本の まんがが すきですか。"]', 2, NULL, NULL, NULL, NULL, 'すき đi với が, không đi với に.', 'HOLD', 1, '3c5bc58917e7')
