INSERT INTO `jpath_skill_lesson` (`type_code`, `title_vi`, `goal_vi`, `steps_json`, `traps_json`, `tips_json`, `example_json`, `example_answer_index`, `check_question_vi`, `check_options_json`, `check_answer_index`, `check_explanation_vi`, `example_audio_path`, `example_audio_sha256`, `status`, `authored`, `seed_version`) VALUES
('N5-L-POINT', 'Chiến thuật nghe hiểu điểm chính N5 (ポイント理解)', 'Bắt đúng thông tin chi tiết (thời gian, lý do, địa điểm, phương tiện) được hỏi trong đoạn hội thoại ngắn N5.', '["Bước 1: Tận dụng 10 giây dừng băng trước mỗi câu để đọc nhanh 4 lựa chọn chữ, từ đó đoán trước chủ đề hội thoại.","Bước 2: Nghe kỹ câu hỏi đầu tiên để xác định chính xác từ nghi vấn (どうして, いつ, どうやって, だれと).","Bước 3: Khi nghe băng, tập trung vào câu trả lời trực tiếp cho từ nghi vấn đó, đặc biệt là các vế có 〜から (vì), 〜で (bằng phương tiện/tại nơi).","Bước 4: Chọn đáp án khớp với thông tin đã xác nhận của đúng nhân vật được hỏi."]', '["Bẫy thói quen thông thường và sự việc hôm nay (ví dụ: mọi ngày đi xe đạp nhưng hôm nay trời mưa nên đi xe buýt).","Bẫy các mốc giờ xuất hiện liên tiếp (giờ tàu chạy, giờ bắt đầu phim, giờ hẹn gặp nhau ở nhà ga).","Bẫy phủ định khéo ở cuối câu (〜あまり好きじゃありません)."]', '["Khi 4 lựa chọn đều là giờ giấc hoặc ngày tháng, hãy vừa nghe vừa ghi chú ngắn bên cạnh từng mốc giờ xem đó là giờ của việc gì.","Chú ý phân biệt いつも (luôn luôn) với きょう / きのう / こんど (hôm nay / hôm qua / lần tới)."]', '{"options":["デパートが休みだったからです。","かばんが高くなかったからです。","姉の子どもがうちへ来たからです。","来週の日曜日に仕事があるからです。"],"question_ja":"女の人はどうしてきのう、買い物をしませんでしたか。","script_ja":"質問：女の人はどうしてきのう、買い物をしませんでしたか。\\n男：山田さん、きのうデパートで新しいかばんを買いましたか。\\n女：いいえ。午後からデパートへ行くつもりでしたが、急に姉の子どもがうちへ遊びに来ましたから、どこへも行きませんでした。\\n男：そうですか。じゃあ、来週の日曜日に買いに行きますか。\\n女：ええ、そうします。\\n質問：女の人はどうしてきのう、買い物をしませんでしたか。","translation_vi":"Câu hỏi: Tại sao hôm qua người phụ nữ không đi mua sắm?\\nNam: Chị Yamada này, hôm qua chị đã mua túi xách mới ở trung tâm thương mại chưa?\\nNữ: Chưa. Tôi định chiều mới đi trung tâm thương mại, nhưng vì con của chị gái đột nhiên đến nhà chơi nên tôi đã không đi đâu cả.\\nNam: Vậy à. Thế Chủ nhật tuần sau chị có đi mua không?\\nNữ: Vâng, tôi sẽ đi vào hôm đó.","walkthrough_vi":["Câu hỏi: Tại sao hôm qua người phụ nữ không đi mua sắm (どうしてきのう、買い物をしませんでしたか).","Tập trung nghe lời giải thích của người nữ có chứa từ nối chỉ nguyên nhân 「から」.","Người nữ nói: 「急に姉の子どもがうちへ遊びに来ましたから、どこへも行きませんでした」 (Vì con của chị gái đột nhiên đến nhà chơi nên tôi đã không đi đâu cả).","Đối chiếu với 4 lựa chọn: lựa chọn 3 khớp hoàn toàn."]}', 2, 'Thời gian nghỉ ngắn trước mỗi câu trong phần ポイント理解 N5 nên được tận dụng để làm gì?', '["Nhắm mắt nghỉ ngơi chờ băng đọc xong hội thoại mới nhìn đề.","Đọc trước 4 lựa chọn in trên đề để biết câu hỏi sẽ xoay quanh thời gian, địa điểm hay lý do.","Viết lại toàn bộ câu trước đó.","Đoán đáp án theo độ dài của câu chữ."]', 1, 'Ở phần ポイント理解, 4 lựa chọn được in sẵn trên đề. Đọc trước cả 4 lựa chọn giúp bạn đoán ngay trọng tâm câu hỏi và chủ động bắt từ khóa khi băng phát.', 'learning-path/N5/skills/lesson-N5-L-POINT.mp3', 'f5cdcd138432497dd2bb97ad59dd9b268041d4768f161cf0021f507128a95d01', 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-L-RESPONSE', 'Chiến thuật phản xạ tức thời N5 (即時応答)', 'Chọn ngay câu đáp lại tự nhiên và đúng trọng tâm nhất sau khi nghe một câu nói ngắn duy nhất.', '["Bước 1: Tập trung cao độ ngay từ giây đầu vì câu nói đầu tiên rất ngắn và chỉ đọc 1 lần.","Bước 2: Bắt ngay từ để hỏi (なに, どこ, いつ, だれ, どう, どのぐらい) và đuôi câu (〜ますか, 〜ませんか, 〜ましょう, 〜ね).","Bước 3: Dự đoán nhanh kiểu câu trả lời tương ứng (hỏi ませんか là lời mời -> đáp ええ、いいですね hoặc すみません、ちょっと…).","Bước 4: Nghe 3 phương án và loại các câu trả lời lệch từ nghi vấn hoặc lặp lại từ đồng âm khác nghĩa."]', '["Bẫy câu mời 「〜ませんか」 nhưng đáp án nhiễu lại trả lời như câu hỏi phủ định thông thường.","Bẫy lặp lại một từ có âm giống trong câu hỏi nhưng trả lời sang nội dung hoàn toàn khác.","Bẫy sai thời (câu hỏi ở quá khứ 〜ましたか nhưng câu đáp lại dùng tương lai 〜ましょう)."]', '["Nếu câu đầu kết thúc bằng 「〜ませんか」 với ngữ điệu lên giọng thì đó là lời mời rủ rê, không phải câu hỏi lý do.","Nếu câu đầu là lời xin lỗi hoặc cảm ơn, hãy chọn câu đáp lịch sự tương ứng (いいえ、だいじょうぶですよ / どういたしまして)."]', '{"options":["ええ、きのう見ましたよ。","ええ、いいですね。行きましょう。","いいえ、映画は見ませんから。","はい、映画館の近くです。"],"question_ja":"女の人の誘いに対して、最も適切な返事はどれですか。","script_ja":"女：あした、一緒に映画を見に行きませんか。\\n1. ええ、きのう見ましたよ。\\n2. ええ、いいですね。行きましょう。\\n3. いいえ、映画は見ませんから。","translation_vi":"Nữ: Ngày mai bạn có đi xem phim cùng tôi không?\\n1. Vâng, hôm qua tôi đã xem rồi.\\n2. Vâng, hay quá. Chúng mình cùng đi nhé.\\n3. Không, vì tôi không xem phim.","walkthrough_vi":["Phân tích câu nói đầu: 「あした、一緒に映画を見に行きませんか」 dùng mốc thời gian あした (ngày mai) và mẫu mời rủ 「〜ませんか」.","Lựa chọn 1 sai vì nói về hôm qua (きのう見ましたよ). Lựa chọn 3 không tự nhiên khi từ chối lời mời lịch sự.","Lựa chọn 2 「ええ、いいですね。行きましょう」 (Vâng, hay đấy nhỉ. Chúng mình cùng đi nào) là cách đồng ý lời mời chuẩn xác nhất."]}', 1, 'Trong phần 即時応答 N5, yếu tố nào trong câu nói đầu tiên quyết định trực tiếp cách chọn câu trả lời đúng?', '["Giọng người nói là nam hay nữ.","Từ để hỏi (いつ, どこ, だれ...) và mẫu câu kết thúc ở cuối câu (〜ませんか, 〜ましょうか, 〜ましたか...).","Số lượng chữ Kanji nếu viết câu đó ra giấy.","Tốc độ đọc nhanh hay chậm của người nói."]', 1, 'Từ để hỏi ở giữa câu và mẫu ngữ pháp kết thúc câu quyết định mục đích giao tiếp (hỏi thông tin, mời rủ, đề nghị giúp đỡ hay xác nhận), từ đó xác định câu đáp phù hợp.', 'learning-path/N5/skills/lesson-N5-L-RESPONSE.mp3', 'da466329dce477ffcbee7329800d949c083f57abf9ab2e02adcd29a951469cf5', 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-L-TASK', 'Chiến thuật nghe hiểu nhiệm vụ N5 (課題理解)', 'Xác định đúng hành động tiếp theo mà nhân vật trong hội thoại sẽ thực hiện ngay sau khi nói chuyện.', '["Bước 1: Nghe kỹ câu hỏi đầu bài xem đề hỏi hành động của người nam (男の人) hay người nữ (女の人).","Bước 2: Quan sát nhanh 4 bức tranh hoặc 4 lựa chọn chữ trong lúc băng nghỉ để nhận diện điểm khác nhau (đồ vật, số lượng, vị trí).","Bước 3: Khi nghe hội thoại, tập trung vào các mẫu câu giao việc hoặc chốt quyết định: 〜てください, 〜ましょう, じゃあ、そうします.","Bước 4: Cẩn thận với các câu từ chối hoặc thay đổi ý định như いえ, でも, あ、やっぱり."]', '["Bẫy nhắc đến đồ vật/địa điểm đầu tiên nhưng sau đó phát hiện đã có sẵn hoặc cửa hàng đóng cửa nên đổi sang thứ khác.","Bẫy nhầm việc của người nam sang việc của người nữ.","Bẫy nghe sót số lượng hoặc tính chất (ví dụ mua 3 quả táo to chứ không phải 2 quả táo nhỏ)."]', '["Nếu đề hỏi 「まず何をしますか」 (Đầu tiên sẽ làm gì?), hãy chú ý các từ chỉ trình tự như まず, はじめに, 〜の前に.","Với câu hỏi có tranh, hãy ghi nhanh bằng ký hiệu (○ / ×) lên từng hình ngay khi nghe thấy thông tin được chọn hoặc bị loại."]', '{"image_description_vi":"Bốn bức tranh vẽ đồ uống và đồ ăn trên bàn: (1) Một cốc cà phê nóng, (2) Một cốc nước cam, (3) Một cốc nước cam và bánh quy, (4) Một cốc cà phê và bánh quy.","options":["あたたかいコーヒーだけ","オレンジジュースだけ","オレンジジュースとクッキー","コーヒーとクッキー"],"question_ja":"男の人はこのあと、何を出しますか。","script_ja":"質問：男の人はこのあと、何を出しますか。\\n女：もうすぐ田中さんが来ますね。飲み物は何を出しましょうか。コーヒーにしますか。\\n男：きょうは暑いですから、冷たいオレンジジュースにしましょう。\\n女：そうですね。じゃあ、このクッキーも一緒に出しますか。\\n男：ええ、お願いします。私が準備しますね。\\n質問：男の人はこのあと、何を出しますか。","translation_vi":"Câu hỏi: Sau đây người đàn ông sẽ mang thứ gì ra?\\nNữ: Anh Tanaka sắp đến rồi nhỉ. Chúng ta mang đồ uống gì ra đây? Hay là cà phê nhé?\\nNam: Hôm nay trời nóng nên mình mang nước cam lạnh đi.\\nNữ: Đúng đấy nhỉ. Vậy mình bày cả bánh quy này ra cùng nhé?\\nNam: Vâng, nhờ chị nhé. Để tôi chuẩn bị cho.","walkthrough_vi":["Xác định câu hỏi: Người đàn ông sẽ mang thứ gì ra tiếp khách (男の人はこのあと、何を出しますか).","Người nữ gợi ý cà phê (コーヒーにしますか), nhưng người nam đổi sang nước cam lạnh (冷たいオレンジジュースにしましょう) -> loại lựa chọn 1 và 4.","Người nữ hỏi thêm có mang bánh quy ra cùng không (このクッキーも一緒に出しますか), người nam đồng ý (ええ、お願いします).","Vậy người nam sẽ mang cả nước cam và bánh quy ra -> chọn đáp án 3."]}', 2, 'Trong bài nghe 課題理解 N5, khi nhân vật nói 「あ、やっぱり〜にします」 thì thông tin nào là đáp án đúng?', '["Thông tin được nhắc đến đầu tiên trong hội thoại.","Thông tin được chốt lại ngay sau từ やっぱり.","Thông tin mà người kia đã từ chối.","Bất kỳ danh từ nào được lặp lại 2 lần."]', 1, 'Từ やっぱり trong hội thoại giao việc thường báo hiệu sự thay đổi hoặc chốt lại quyết định cuối cùng, nên thông tin theo sau nó mới là hành động thực sự sẽ làm.', 'learning-path/N5/skills/lesson-N5-L-TASK.mp3', '6a6a24e3d84b6df16b3f0142552429e93dd6f70879710b90b271350d45d847f3', 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-L-UTTERANCE', 'Chiến thuật biểu đạt phát ngôn theo tình huống N5 (発話表現)', 'Chọn câu nói tự nhiên và đúng phép lịch sự nhất cho nhân vật được mũi tên chỉ vào trong bức tranh tình huống.', '["Bước 1: Quan sát kỹ bức tranh: xác định người có mũi tên là ai (người nói), người kia là ai (người nghe), và bối cảnh đang ở đâu.","Bước 2: Nghe lời mô tả tình huống của giọng dẫn để biết mục đích phát ngôn (chào hỏi, xin phép, nhờ vả, xin lỗi hay cảm ơn).","Bước 3: Xác định ai là người thực hiện hành động để chọn đúng câu (mình tự làm: 〜ましょうか / 〜てもいいですか; nhờ người kia làm: 〜てください / 〜をお願いします).","Bước 4: Nghe cả 3 lựa chọn âm thanh rồi chọn câu đúng hoàn cảnh giao tiếp nhất."]', '["Bẫy nhầm câu nói của người thực hiện hành động với câu nói của người tiếp nhận (ví dụ: câu của khách hàng và câu của nhân viên cửa hàng).","Bẫy dùng câu chào trước khi ăn (いただきます) nhầm với câu sau khi ăn xong (ごちそうさまでした) hoặc khi bước vào nhà (おじゃまします) với khi ra về.","Bẫy dùng 〜てください khi muốn xin phép làm việc gì đó cho bản thân (đúng phải là 〜てもいいですか)."]', '["Luôn nhìn hướng mũi tên trong tranh: mũi tên chỉ vào ai thì mình phải đóng vai người đó để nói.","Ôn kỹ các cặp câu giao tiếp cố định theo tình huống: vào phòng, rời chỗ làm trước (お先に失礼します), nhờ chụp ảnh, mượn đồ."]', '{"image_description_vi":"Trong thư viện trường học, một nam sinh đang chỉ vào chiếc ghế trống bên cạnh một nữ sinh đang đọc sách. Mũi tên chỉ vào nam sinh.","options":["すみません、ここに座ってもいいですか。","すみません、ここに座ってください。","すみません、ここに座りましょう。","すみません、そこに座らないでください。"],"question_ja":"女の人に何と言いますか。","script_ja":"図書館で、となりのいすに座りたいです。女の人に何と言いますか。\\n1. すみません、ここに座ってもいいですか。\\n2. すみません、ここに座ってください。\\n3. すみません、ここに座りましょう。","translation_vi":"Ở thư viện, bạn muốn ngồi vào chiếc ghế bên cạnh. Bạn sẽ nói gì với bạn nữ?\\n1. Xin lỗi, tôi ngồi ở đây có được không?\\n2. Xin lỗi, bạn hãy ngồi vào đây đi.\\n3. Xin lỗi, chúng mình cùng ngồi vào đây nhé.","walkthrough_vi":["Xác định tình huống: Trong thư viện, nam sinh (người có mũi tên) muốn ngồi vào chiếc ghế bên cạnh nữ sinh.","Vì người ngồi là bản thân mình nên đây là câu xin phép người bên cạnh -> cần dùng mẫu 「〜てもいいですか」.","Lựa chọn 2 (座ってください) là bảo người kia ngồi; lựa chọn 3 (座りましょう) là rủ cùng ngồi; lựa chọn 1 (ここに座ってもいいですか - Xin lỗi, tôi ngồi ở đây có được không?) là chính xác."]}', 0, 'Khi muốn nhờ người khác làm giúp mình một việc (ví dụ nhờ chụp ảnh giúp), bạn nên chọn mẫu câu nào trong phần 発話表現 N5?', '["シャッターを押してもいいですか (Xin phép tự mình bấm máy).","写真を撮ってください / お願いします (Nhờ người nghe chụp giúp).","写真を撮りましょうか (Đề nghị chụp giúp cho người nghe).","写真を撮りましたか (Hỏi xem đã chụp chưa)."]', 1, 'Khi nhờ người nghe thực hiện hành động cho mình, ở trình độ N5 ta dùng 〜てください hoặc 〜をお願いします; còn 〜ましょうか là khi mình đề nghị làm giúp người kia.', 'learning-path/N5/skills/lesson-N5-L-UTTERANCE.mp3', '37242eb30fccf2b36fc90e6dddc90229cbf1f9022aa81ac483b4989cd4b5a4f5', 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-R-INFO', 'Chiến thuật tìm kiếm thông tin N5 (情報検索)', 'Đọc quét bảng thông báo, lịch mở cửa hoặc bảng giá để tìm đúng thông tin thỏa mãn điều kiện của câu hỏi mà không cần đọc toàn bộ văn bản.', '["Bước 1: Đọc kỹ câu hỏi và liệt kê toàn bộ điều kiện của nhân vật (ai đi, đi thứ mấy, mấy giờ, mang theo bao nhiêu tiền).","Bước 2: Nhìn tiêu đề các cột/dòng trong bảng (時間 - giờ, 休み - ngày nghỉ, 料金/ねだん - giá vé).","Bước 3: Dò từng điều kiện của câu hỏi vào bảng để loại trừ những dòng không thỏa mãn.","Bước 4: Đọc dòng ghi chú nhỏ ở cuối bảng (thường bắt đầu bằng ※ hoặc 休み) trước khi chốt đáp án."]', '["Bẫy ngày nghỉ cố định trong tuần (ví dụ viện bảo tàng nghỉ thứ Hai nhưng câu hỏi cho nhân vật rảnh thứ Hai và thứ Tư).","Bẫy nhầm giá vé người lớn (おとな) với trẻ em (こども) hoặc học sinh (がくせい).","Bẫy khung giờ buổi sáng (ごぜん) và buổi chiều (ごご)."]', '["Tuyệt đối không đọc từ đầu đến cuối bảng thông báo trước; hãy đọc câu hỏi trước để chỉ dò đúng ô dữ liệu cần thiết.","Lấy bút gạch ngay các phương án vi phạm điều kiện thời gian hoặc vượt quá số tiền cho phép."]', '{"options":["200円","400円","600円","800円"],"passage_ja":"【みどり体育館のご案内】\\n場所：みどり駅の北口から歩いて5分\\n開館時間：午前9時〜午後8時（日曜日は午後5時まで）\\n休館日：毎週月曜日\\n利用料金（1時間）：\\n・大人：400円\\n・学生（高校生・大学生）：200円\\n・子ども（中学生以下）：100円\\n※体育館の中で履くきれいな運動ぐつを持ってきてください。","question_ja":"大学生のナムさんは火曜日に2時間、体育館を使います。いくら払いますか。","translation_vi":"[Hướng dẫn Nhà thi đấu Midori]\\nĐịa điểm: Đi bộ 5 phút từ cửa Bắc ga Midori\\nGiờ mở cửa: 9 giờ sáng ~ 8 giờ tối (Chủ nhật mở đến 5 giờ chiều)\\nNgày nghỉ: Thứ Hai hằng tuần\\nPhí sử dụng (1 tiếng):\\n・Người lớn: 400 yên\\n・Học sinh/Sinh viên (cấp 3, đại học): 200 yên\\n・Trẻ em (cấp 2 trở xuống): 100 yên\\n*Vui lòng mang theo giày thể thao sạch để đi trong nhà thi đấu.","walkthrough_vi":["Tóm tắt điều kiện câu hỏi: Nam là sinh viên đại học (大学生 -> thuộc mục 学生), đi vào thứ Ba (火曜日 -> không trùng ngày nghỉ 月曜日), dùng trong 2 tiếng (2時間).","Tra dòng 利用料金（1時間）: mức phí của 学生 là 200円 cho 1 tiếng.","Nhân với thời gian sử dụng 2 tiếng: 200円 × 2 = 400円.","Chọn đáp án 2 (400円). Các đáp án 200円 (quên nhân 2 tiếng) và 800円 (nhầm sang giá 大人) đều là bẫy."]}', 1, 'Khi làm dạng bài Tìm kiếm thông tin (情報検索) N5, bước đầu tiên hiệu quả nhất là gì?', '["Đọc thuộc lòng toàn bộ bảng giá từ dòng đầu tiên đến dòng cuối cùng.","Đọc câu hỏi trước để nắm rõ các điều kiện (đối tượng, ngày giờ, số lượng) rồi mới dò vào bảng.","Chọn con số lớn nhất xuất hiện trong bảng.","Bỏ qua phần ghi chú có dấu ※ ở cuối bảng vì phần đó không bao giờ được hỏi."]', 1, 'Trong dạng 情報検索, đọc câu hỏi trước để xác định điều kiện lọc giúp tiết kiệm thời gian và tránh bị rối bởi những con số không liên quan.', NULL, NULL, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-R-MEDIUM', 'Chiến thuật đọc hiểu đoạn văn trung bình N5 (中文)', 'Theo dõi mạch thời gian và nguyên nhân – kết quả trong đoạn văn 170–320 ký tự để trả lời chính xác 2 câu hỏi đi kèm.', '["Bước 1: Đọc trước cả 2 câu hỏi để biết câu 1 hỏi chi tiết ở nửa đầu bài hay câu 2 hỏi cảm nghĩ ở cuối bài.","Bước 2: Đọc đoạn văn theo từng cụm câu, gạch chân các mốc thời gian (せんしゅう, きのう, つぎの日) và từ nối (それから, でも, から).","Bước 3: Khi trả lời câu hỏi 「どうしてですか」 (Tại sao?), tìm câu có chứa 〜から ở ngay trước hoặc ngay sau câu được hỏi.","Bước 4: Kiểm tra lại tính từ chỉ cảm xúc của người viết ở cuối bài (たのしかったです, ざんねんでした, つかれました) để chốt câu hỏi thứ hai."]', '["Bẫy lấy dự định ban đầu làm kết quả thực tế (ví dụ định đi công viên nhưng trời mưa nên ở nhà đọc sách).","Bẫy đánh tráo lý do của việc A sang việc B trong cùng một đoạn văn.","Bẫy dùng từ gần nghĩa nhưng sai mức độ (như あまり〜ません bị đổi thành ぜんぜん〜ません hoặc よく〜ます)."]', '["Thứ tự 2 câu hỏi trong bài 中文 N5 hầu như luôn thuận theo thứ tự xuất hiện của thông tin từ trên xuống dưới.","Chú ý chữ でも (nhưng): thông tin đứng sau でも mới là sự việc thực sự diễn ra hoặc ý kiến thật của tác giả."]', '{"options":["友だちが来なかったからです。","バスがなかったからです。","朝から強い雨が降ったからです。","図書館で本を読みたかったからです。"],"passage_ja":"きのうは日曜日でした。私は午前中に友だちとバスで海へ行くつもりでしたが、朝から強い雨が降りました。ですから、海へは行きませんでした。午後はうちの近くの新しい図書館へ歩いて行って、日本の歴史や文化の本を三時間ぐらい読みました。図書館の中には人があまりいなくて、とても静かでよかったです。帰りに図書館の前のパン屋で甘いパンを買いました。来週の日曜日は晴れたら、また友だちと海へ行きたいです。","question_ja":"「私」はきのう、どうして海へ行きませんでしたか。","translation_vi":"Hôm qua là Chủ nhật. Buổi sáng tôi đã định đi biển cùng bạn bằng xe buýt, nhưng từ sáng trời đã mưa to. Vì thế tôi đã không đi biển. Buổi chiều tôi đi bộ đến thư viện mới gần nhà và đọc sách lịch sử, văn hóa Nhật Bản khoảng 3 tiếng. Trong thư viện không có mấy người nên rất yên tĩnh và dễ chịu. Lúc về tôi đã mua bánh mì ngọt ở tiệm bánh trước thư viện. Chủ nhật tuần sau nếu trời nắng, tôi lại muốn đi biển cùng bạn.","walkthrough_vi":["Đọc câu hỏi: Hỏi lý do tại sao hôm qua nhân vật \\"tôi\\" không đi biển.","Dò đoạn đầu có từ khóa 海へ行きませんでした: thấy câu trước đó nối bằng 「ですから」.","Đọc mệnh đề ngay trước 「ですから」: 「朝から強い雨が降りました」 (từ sáng đã có mưa to).","Đối chiếu 4 lựa chọn: lựa chọn 3 (Vì từ sáng trời mưa to) khớp hoàn toàn với nguyên nhân trong bài."]}', 2, 'Trong bài đọc trung bình N5, khi đề bài hỏi về việc nhân vật đã thực sự làm trong quá khứ, bạn cần cảnh giác nhất với chi tiết nào?', '["Các câu nêu dự định chưa thực hiện (〜つもりでしたが) đứng trước từ nối でも / が.","Các câu ở cuối đoạn văn.","Các câu có chứa danh từ chỉ địa điểm.","Các câu có số đếm giờ giấc."]', 0, 'Đề rất hay gài bẫy bằng cách đưa dự định ban đầu (〜つもりでしたが...) vào một lựa chọn nhiễu, trong khi hành động thực sự diễn ra lại nằm ở vế sau でも / ですから.', NULL, NULL, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-R-SHORT', 'Chiến thuật đọc hiểu đoạn văn ngắn N5 (短文)', 'Nắm bắt nhanh yêu cầu chính hoặc thông tin cốt lõi trong lời nhắn, bưu thiếp và đoạn văn ngắn 60–130 ký tự chỉ trong 1 lần đọc.', '["Bước 1: Đọc câu hỏi trước để xác định từ để hỏi (いつ, どこ, だれ, なに, どうして).","Bước 2: Nhìn nhanh đầu và cuối đoạn văn (nếu là tin nhắn/thư thì chú ý người gửi ở cuối và người nhận ở đầu).","Bước 3: Tìm câu có chứa từ khóa của câu hỏi hoặc các từ nối chỉ nguyên nhân (から), sự tương phản (でも, が) hay yêu cầu (〜てください).","Bước 4: Đối chiếu câu vừa tìm được với 4 lựa chọn và loại ngay các đáp án sai thời gian, sai địa điểm hoặc ngược phủ định."]', '["Bẫy lặp nguyên từ trong bài nhưng ghép sai động từ hoặc đổi khẳng định thành phủ định (ví dụ bài viết 買いません nhưng đáp án viết 買います).","Bẫy nhầm người thực hiện hành động giữa người viết lời nhắn và người nhận lời nhắn.","Bẫy thông tin xuất hiện ở câu đầu nhưng đã bị thay đổi ở câu sau bởi chữ でも hoặc しかし."]', '["Trong lời nhắn gia đình hoặc văn phòng N5, câu chứa 〜てください hoặc 〜ましょう ở gần cuối bài hầu như luôn là trọng tâm câu hỏi.","Chú ý các trạng từ chỉ thời gian (きのう, きょう, あした, まいにち) để không chọn nhầm việc đã làm với việc sắp làm."]', '{"options":["りんごのケーキを作ります。","冷蔵庫のケーキを食べます。","マイクさんと一緒に帰ります。","お母さんにケーキをあげます。"],"passage_ja":"アンさんへ。冷蔵庫の中にりんごのケーキがあります。けさ母が作りました。私はきょう遅く帰りますから、先に食べてください。マイクより。","question_ja":"アンさんはこのあと、何をしますか。","translation_vi":"Gửi bạn An. Trong tủ lạnh có bánh táo đấy. Sáng nay mẹ tớ đã làm. Hôm nay tớ về muộn nên cậu hãy ăn trước đi nhé. Từ Mike.","walkthrough_vi":["Đọc câu hỏi: Hỏi bạn An sau khi đọc lời nhắn sẽ làm gì (アンさんはこのあと、何をしますか).","Xác định người nhận là An (アンさんへ) và người viết là Mike (マイクより).","Tìm câu yêu cầu ở cuối bài: 「私はきょう遅く帰りますから、先に食べてください」 (Hôm nay tôi về muộn nên bạn hãy ăn trước đi nhé).","Thứ để ăn được nêu ở câu đầu là 「冷蔵庫の中にりんごのケーキがあります」 -> Đáp án đúng là lựa chọn 2 (ăn bánh ngọt trong tủ lạnh)."]}', 1, 'Khi làm bài đọc đoạn văn ngắn N5 dạng lời nhắn (メモ), bạn nên tập trung nhất vào vị trí nào để biết người viết muốn người nhận làm gì?', '["Chỉ đọc tên người gửi ở cuối bài rồi đoán đáp án.","Đọc câu hỏi trước, sau đó tìm câu có mẫu yêu cầu/nhờ vả như 〜てください hoặc câu sau từ nối ở cuối đoạn.","Chọn ngay lựa chọn nào có nhiều chữ Kanji giống câu đầu tiên nhất.","Dịch từng từ một từ đầu đến cuối rồi mới đọc câu hỏi."]', 1, 'Đọc câu hỏi trước giúp định hướng thông tin cần tìm, và trong lời nhắn N5 thì yêu cầu chính dành cho người nhận thường nằm ở câu chứa 〜てください hoặc câu kết luận cuối bài.', NULL, NULL, 'AI_CHECKED', 1, '19d0f58e5bad')
INSERT INTO `jpath_skill_set` (`code`, `type_code`, `level`, `skill`, `sort_order`, `passage_ja`, `passage_vi`, `script_json`, `script_vi`, `image_description_vi`, `new_words_json`, `char_count`, `question_count`, `audio_path`, `audio_sha256`, `audio_seconds`, `status`, `authored`, `seed_version`) VALUES
('N5-R-SHORT-001', 'N5-R-SHORT', 'N5', 'READING', 1, 'リンさんへ。部屋の机の上に図書館で借りた本が二冊あります。きょうの午後五時までに図書館へかえしてください。私は今から病院へ行きますから、午後はうちにいません。気をつけて行ってきてね。母より。', 'Gửi Linh. Trên bàn trong phòng có 2 quyển sách mượn ở thư viện. Con hãy trả lại thư viện trước 5 giờ chiều hôm nay nhé. Bây giờ mẹ đi bệnh viện nên buổi chiều mẹ không có ở nhà. Con đi cẩn thận nhé. Từ mẹ.', NULL, NULL, NULL, '[{"expression":"机","reading":"つくえ","meaning_vi":"bàn học; bàn làm việc"},{"expression":"図書館","reading":"としょかん","meaning_vi":"thư viện"},{"expression":"病院","reading":"びょういん","meaning_vi":"bệnh viện"}]', 95, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-R-SHORT-002', 'N5-R-SHORT', 'N5', 'READING', 2, '山川さん、けさはお電話ありがとうございました。あしたの会議ですが、午前十時からではなくて、午後二時からになりました。会議は会社の三階の広い部屋でします。ノートを持って来てください。', 'Anh Yamakawa, cảm ơn anh sáng nay đã gọi điện. Về cuộc họp ngày mai, không phải từ 10 giờ sáng mà đã đổi sang từ 2 giờ chiều. Cuộc họp sẽ diễn ra ở căn phòng rộng tầng 3 của công ty. Anh hãy mang theo sổ tay nhé.', NULL, NULL, NULL, '[{"expression":"電話","reading":"でんわ","meaning_vi":"gọi điện thoại; điện thoại"},{"expression":"午前","reading":"ごぜん","meaning_vi":"buổi sáng (trước 12 giờ trưa); sáng"},{"expression":"午後","reading":"ごご","meaning_vi":"buổi chiều (sau 12 giờ trưa); chiều"}]', 90, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-R-SHORT-003', 'N5-R-SHORT', 'N5', 'READING', 3, 'きのうの午後、私は駅の近くの新しいカメラ屋へ行きました。小さいカメラがほしかったですが、その店のカメラはとても高かったですから、きのうは買いませんでした。来月、また友だちと見に行きます。', 'Chiều hôm qua, tôi đã đi đến tiệm máy ảnh mới ở gần nhà ga. Tôi muốn mua một chiếc máy ảnh nhỏ, nhưng vì máy ảnh của tiệm đó đắt quá nên hôm qua tôi đã không mua. Tháng sau tôi sẽ lại đi xem cùng bạn.', NULL, NULL, NULL, '[{"expression":"駅","reading":"えき","meaning_vi":"nhà ga; ga"},{"expression":"新しい","reading":"あたらしい","meaning_vi":"mới"},{"expression":"高い","reading":"たかい","meaning_vi":"cao; đắt"}]', 93, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-R-SHORT-004', 'N5-R-SHORT', 'N5', 'READING', 4, 'キムさんへ。台所に冷たい牛乳とおいしい果物があります。テーブルの上の白いパンも朝ごはんに食べてくださいね。私はきょう、会社の仕事がありますから、午後七時ごろにうちへ帰ります。姉より。', 'Gửi Kim. Trong bếp có sữa bò lạnh và hoa quả ngon. Em hãy ăn cả bánh mì trắng ở trên bàn vào bữa sáng nữa nhé. Hôm nay chị có việc ở công ty nên khoảng 7 giờ tối chị sẽ về nhà. Từ chị gái.', NULL, NULL, NULL, '[{"expression":"牛乳","reading":"ぎゅうにゅう","meaning_vi":"sữa bò; sữa"},{"expression":"果物","reading":"くだもの","meaning_vi":"trái cây; hoa quả"},{"expression":"姉","reading":"あね","meaning_vi":"chị gái (tôi)"}]', 91, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-R-SHORT-005', 'N5-R-SHORT', 'N5', 'READING', 5, '私は毎朝六時に起きて、家の近くの広い公園を三十分ぐらい歩きます。それから、うちへ帰って熱いコーヒーを一杯飲みます。朝ごはんにはいつもパンと卵を食べてから、八時に会社へ出かけます。', 'Mỗi sáng tôi thức dậy lúc 6 giờ và đi bộ ở công viên rộng gần nhà khoảng 30 phút. Sau đó tôi về nhà và uống một tách cà phê nóng. Bữa sáng tôi luôn ăn bánh mì và trứng rồi 8 giờ đi làm.', NULL, NULL, NULL, '[{"expression":"毎朝","reading":"まいあさ","meaning_vi":"mỗi sáng; sáng nào cũng"},{"expression":"公園","reading":"こうえん","meaning_vi":"công viên"},{"expression":"卵","reading":"たまご","meaning_vi":"trứng; quả trứng"}]', 89, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-R-SHORT-006', 'N5-R-SHORT', 'N5', 'READING', 6, '先週の土曜日、クラスの友だちと映画館へ映画を見に行きました。映画はとてもおもしろかったです。そのあと、駅の前のレストランでばんごはんを食べて、夜の九時に電車でうちへ帰りました。', 'Thứ Bảy tuần trước, tôi đã đi đến rạp chiếu phim để xem phim cùng bạn cùng lớp. Bộ phim rất thú vị. Sau đó chúng tôi ăn tối ở nhà hàng trước nhà ga rồi về nhà bằng tàu điện lúc 9 giờ tối.', NULL, NULL, NULL, '[{"expression":"土曜日","reading":"どようび","meaning_vi":"thứ bảy"},{"expression":"映画","reading":"えいが","meaning_vi":"bộ phim; phim ảnh"},{"expression":"先週","reading":"せんしゅう","meaning_vi":"tuần trước"}]', 88, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-R-SHORT-007', 'N5-R-SHORT', 'N5', 'READING', 7, '来週の金曜日は母の誕生日です。母はきれいな花が大好きですから、私は金曜日の仕事が終わってから、駅の花屋で花を買って帰ります。妹はうちでおいしいケーキを作って母を待ちます。', 'Thứ Sáu tuần sau là sinh nhật của mẹ tôi. Vì mẹ rất thích hoa đẹp nên sau khi xong việc vào thứ Sáu, tôi sẽ mua hoa ở tiệm hoa nhà ga rồi về. Em gái tôi sẽ làm bánh kem ngon ở nhà và đợi mẹ.', NULL, NULL, NULL, '[{"expression":"来週","reading":"らいしゅう","meaning_vi":"tuần sau"},{"expression":"誕生日","reading":"たんじょうび","meaning_vi":"sinh nhật"},{"expression":"花屋","reading":"はなや","meaning_vi":"cửa hàng bán hoa"}]', 85, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-R-SHORT-008', 'N5-R-SHORT', 'N5', 'READING', 8, '日本語クラスの学生へ。あしたの日本語のテストは午前九時に始まります。教室へ鉛筆を三本とけしゴムを持ってきてください。テストのとき、時計や辞書は使わないでください。先生より。', 'Gửi học sinh lớp tiếng Nhật. Bài kiểm tra tiếng Nhật ngày mai bắt đầu lúc 9 giờ sáng. Các em hãy mang theo 3 cây bút chì và cục tẩy đến phòng học nhé. Khi làm bài kiểm tra, xin đừng sử dụng đồng hồ hay từ điển. Từ thầy giáo.', NULL, NULL, NULL, '[{"expression":"鉛筆","reading":"えんぴつ","meaning_vi":"bút chì"},{"expression":"辞書","reading":"じしょ","meaning_vi":"từ điển; quyển từ điển"},{"expression":"先生","reading":"せんせい","meaning_vi":"người dạy học; thầy (cô) giáo"}]', 86, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-R-SHORT-009', 'N5-R-SHORT', 'N5', 'READING', 9, '私の部屋はアパートの二階にあります。あまり広くありませんが、南に大きい窓が二つありますから、昼はとても明るくてあたたかいです。窓の外には高い山と広い川を見ることができます。', 'Phòng của tôi nằm ở tầng 2 của tòa căn hộ. Phòng không rộng lắm, nhưng vì có 2 cửa sổ lớn ở hướng Nam nên ban ngày rất sáng sủa và ấm áp. Bên ngoài cửa sổ có thể nhìn thấy ngọn núi cao và con sông rộng.', NULL, NULL, NULL, '[{"expression":"部屋","reading":"へや","meaning_vi":"phòng; căn phòng"},{"expression":"窓","reading":"まど","meaning_vi":"cửa sổ"},{"expression":"明るい","reading":"あかるい","meaning_vi":"sáng; sáng sủa; vui tươi (tính cách)"}]', 86, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-R-SHORT-010', 'N5-R-SHORT', 'N5', 'READING', 10, 'マイクさんへ。さっき郵便局の人が来て、あなたの大きい荷物をわたしましたよ。とてもおもかったですから、一階の階段のすぐ近くに今あります。帰ってから二階の部屋へ持って行ってくださいね。', 'Gửi Mike. Lúc nãy nhân viên bưu điện đã đến và giao bưu kiện lớn của bạn đấy. Vì rất nặng nên bây giờ nó đang ở ngay gần cầu thang tầng 1. Sau khi về bạn hãy mang lên phòng ở tầng 2 nhé.', NULL, NULL, NULL, '[{"expression":"郵便局","reading":"ゆうびんきょく","meaning_vi":"bưu điện"},{"expression":"荷物","reading":"にもつ","meaning_vi":"hành lý; kiện hàng; đồ đạc"},{"expression":"階段","reading":"かいだん","meaning_vi":"cầu thang bộ; cầu thang"}]', 90, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-R-SHORT-011', 'N5-R-SHORT', 'N5', 'READING', 11, '私はいつも自転車で会社へ行きます。うちから会社まで自転車で二十分ぐらいかかります。でも、けさは朝からたくさん雨がふりましたから、うちから歩いて駅へ行って電車に乗りました。', 'Tôi luôn đi làm bằng xe đạp. Từ nhà đến công ty đi bằng xe đạp mất khoảng 20 phút. Nhưng sáng nay vì trời mưa nhiều từ sáng nên tôi đã đi bộ từ nhà ra ga rồi lên tàu điện.', NULL, NULL, NULL, '[{"expression":"自転車","reading":"じてんしゃ","meaning_vi":"xe đạp"},{"expression":"会社","reading":"かいしゃ","meaning_vi":"công ty"},{"expression":"電車","reading":"でんしゃ","meaning_vi":"tàu điện"}]', 85, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-R-SHORT-012', 'N5-R-SHORT', 'N5', 'READING', 12, '先週の日曜日、家族と車で山の上の古いお寺へ行きました。その日は天気がとてもよかったですから、お寺に人が多かったです。私たちは広い庭できれいな花の写真をたくさんとりました。', 'Chủ nhật tuần trước, tôi đã đi chùa cổ ở trên núi cùng gia đình bằng ô tô. Hôm đó vì thời tiết rất đẹp nên ở chùa có rất đông người. Chúng tôi đã chụp rất nhiều ảnh hoa đẹp ở trong sân vườn rộng.', NULL, NULL, NULL, '[{"expression":"家族","reading":"かぞく","meaning_vi":"gia đình"},{"expression":"天気","reading":"てんき","meaning_vi":"thời tiết"},{"expression":"写真","reading":"しゃしん","meaning_vi":"tấm ảnh; ảnh chụp; ảnh"}]', 85, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-R-SHORT-013', 'N5-R-SHORT', 'N5', 'READING', 13, 'きのうの夜から少し熱があって、頭が痛いです。けさ近くの病院へ行って白い薬をもらいました。お医者さんは私に「きょうはおふろに入らないで、早く寝てください」と言いました。今夜は早く寝ます。', 'Từ tối hôm qua tôi hơi sốt và đau đầu. Sáng nay tôi đã đi bệnh viện gần nhà và nhận thuốc màu trắng. Bác sĩ đã dặn tôi là "Hôm nay không được tắm bồn mà hãy đi ngủ sớm nhé". Tối nay tôi sẽ ngủ sớm.', NULL, NULL, NULL, '[{"expression":"熱","reading":"ねつ","meaning_vi":"sốt; cơn sốt; nhiệt"},{"expression":"頭","reading":"あたま","meaning_vi":"cái đầu; đầu; trí óc"},{"expression":"薬","reading":"くすり","meaning_vi":"thuốc"}]', 92, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-R-SHORT-014', 'N5-R-SHORT', 'N5', 'READING', 14, '私の兄はサッカーが大好きです。毎週水曜日と土曜日に、学校の広い庭で友だちとサッカーをします。あしたは水曜日ですから、兄はきのう買った新しい白い靴をはいて学校へ行きます。とても楽しそうです。', 'Anh trai tôi rất thích bóng đá. Thứ Tư và thứ Bảy hằng tuần anh ấy đều chơi bóng đá cùng bạn ở sân trường rộng. Ngày mai là thứ Tư nên anh ấy sẽ đi đôi giày trắng mới mua hôm qua đến trường. Trông anh ấy rất hào hứng.', NULL, NULL, NULL, '[{"expression":"兄","reading":"あに","meaning_vi":"anh trai (tôi)"},{"expression":"学校","reading":"がっこう","meaning_vi":"trường học"},{"expression":"靴","reading":"くつ","meaning_vi":"giày; đôi giày"}]', 94, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-R-SHORT-015', 'N5-R-SHORT', 'N5', 'READING', 15, 'タオさんへ。よるごはんのカレーは台所のなべのなかにあります。食べる前に少し温めてくださいね。野菜のサラダとおいしい果物は、台所の白いおさらの上にありますよ。ゆっくり食べてね。母より。', 'Gửi Thảo. Cà ri cho bữa tối có ở trong nồi dưới bếp nhé. Trước khi ăn con hãy hâm nóng một chút nhé. Salad rau và hoa quả ngon thì ở trên chiếc đĩa trắng trong bếp đấy. Con ăn thong thả nhé. Từ mẹ.', NULL, NULL, NULL, '[{"expression":"台所","reading":"だいどころ","meaning_vi":"bếp; nhà bếp"},{"expression":"野菜","reading":"やさい","meaning_vi":"rau; rau củ"},{"expression":"果物","reading":"くだもの","meaning_vi":"trái cây; hoa quả"}]', 91, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-R-SHORT-016', 'N5-R-SHORT', 'N5', 'READING', 16, '先週の日曜日、私はデパートで父の白いシャツを買いました。三千円でした。父は「とてもいいシャツだね。ありがとう」と言いました。来月は母の誕生日にきれいな小さいかばんを買いたいです。', 'Chủ nhật tuần trước, tôi đã mua chiếc áo sơ mi trắng cho bố ở trung tâm thương mại. Giá là 3.000 yên. Bố tôi nói "Chiếc áo sơ mi đẹp quá nhỉ. Cảm ơn con". Tháng sau vào sinh nhật mẹ, tôi muốn mua một chiếc túi xách nhỏ xinh.', NULL, NULL, NULL, '[{"expression":"父","reading":"ちち","meaning_vi":"bố"},{"expression":"白い","reading":"しろい","meaning_vi":"trắng; màu trắng"},{"expression":"来月","reading":"らいげつ","meaning_vi":"tháng sau"}]', 89, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-R-SHORT-017', 'N5-R-SHORT', 'N5', 'READING', 17, 'うちの近くに「さくら」という小さい喫茶店があります。そこのコーヒーはおいしくて安いです。店のなかではいつも静かな音楽を聞くことができますから、私はよくそこで本を読みます。大好きな店です。', 'Ở gần nhà tôi có một quán cà phê nhỏ tên là "Sakura". Cà phê ở đó vừa ngon vừa rẻ. Vì bên trong quán lúc nào cũng có thể nghe nhạc êm dịu nên tôi thường đọc sách ở đó. Đó là quán tôi rất thích.', NULL, NULL, NULL, '[{"expression":"近く","reading":"ちかく","meaning_vi":"gần đây"},{"expression":"喫茶店","reading":"きっさてん","meaning_vi":"quán cà phê; quầy nước; quán giải khát"},{"expression":"音楽","reading":"おんがく","meaning_vi":"âm nhạc"}]', 93, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-R-SHORT-018', 'N5-R-SHORT', 'N5', 'READING', 18, 'あしたはクラスの友だちと海へ泳ぎに行きます。午前八時に駅の西口で友だちと会います。私は冷たい飲み物とお菓子を持っていきます。山川さんは大きい白い傘を持ってきます。あしたはきっといい天気です。', 'Ngày mai tôi sẽ đi bơi ở biển cùng bạn cùng lớp. 8 giờ sáng tôi sẽ gặp bạn ở cửa Tây nhà ga. Tôi mang theo đồ uống lạnh và bánh kẹo. Bạn Yamakawa sẽ mang theo chiếc ô trắng to. Ngày mai chắc chắn thời tiết sẽ đẹp.', NULL, NULL, NULL, '[{"expression":"海","reading":"うみ","meaning_vi":"biển"},{"expression":"泳ぐ","reading":"およぐ","meaning_vi":"bơi"},{"expression":"飲み物","reading":"のみもの","meaning_vi":"đồ uống"}]', 95, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-R-SHORT-019', 'N5-R-SHORT', 'N5', 'READING', 19, '私の趣味は料理を作ることです。月曜日から金曜日までは会社の仕事が忙しいですから、短い時間で料理を作りますが、休みの日曜日には時間をかけて魚や肉の料理をたくさん作ります。家族もいつもよろこびます。', 'Sở thích của tôi là nấu ăn. Từ thứ Hai đến thứ Sáu vì công việc ở công ty bận rộn nên tôi nấu ăn trong thời gian ngắn, nhưng vào ngày nghỉ Chủ nhật tôi dành thời gian nấu rất nhiều món cá và thịt. Gia đình tôi lúc nào cũng rất vui.', NULL, NULL, NULL, '[{"expression":"趣味","reading":"しゅみ","meaning_vi":"sở thích"},{"expression":"料理","reading":"りょうり","meaning_vi":"món ăn; việc nấu ăn"},{"expression":"忙しい","reading":"いそがしい","meaning_vi":"nhiều việc; bận"}]', 97, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-R-SHORT-020', 'N5-R-SHORT', 'N5', 'READING', 20, '山川さん、先週は日本の音楽のCDを貸してくださって、ありがとうございました。とてもいい歌でしたから、うちで毎日聞きました。あしたの昼休みに教室でかえしますね。また学校で話しましょう。ナムより。', 'Bạn Yamakawa ơi, cảm ơn bạn tuần trước đã cho mình mượn đĩa CD nhạc Nhật nhé. Vì là những bài hát rất hay nên ngày nào ở nhà mình cũng nghe. Giờ nghỉ trưa mai ở phòng học mình sẽ trả lại nhé. Hẹn nói chuyện tiếp ở trường nhé. Từ Nam.', NULL, NULL, NULL, '[{"expression":"貸す","reading":"かす","meaning_vi":"cho mượn"},{"expression":"歌","reading":"うた","meaning_vi":"bài hát; việc hát"},{"expression":"毎日","reading":"まいにち","meaning_vi":"hằng ngày"}]', 96, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-R-SHORT-021', 'N5-R-SHORT', 'N5', 'READING', 21, '今日は学校で白い紙を二十枚もらいました。明日、みんなで町の地図を作ります。私は色のペンを持っていますが、はさみがありません。学校の帰りに店ではさみを買って、夜、かばんに入れます。', 'Hôm nay ở trường tôi nhận 20 tờ giấy trắng. Ngày mai cả lớp làm bản đồ thị trấn. Tôi có bút màu nhưng không có kéo. Trên đường về tôi sẽ mua kéo rồi bỏ vào cặp tối nay.', NULL, NULL, NULL, '[]', 89, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-R-SHORT-022', 'N5-R-SHORT', 'N5', 'READING', 22, '田中さんへ。今日の午後、私の家に来てください。でも、三時から四時まで父が部屋で電話をしますから、その間は外で話しましょう。四時になったら家に入って、いっしょにお茶を飲みましょう。リンより。', 'Gửi anh Tanaka. Chiều nay hãy đến nhà tôi. Nhưng từ ba đến bốn giờ bố tôi gọi điện trong phòng nên lúc đó chúng ta nói chuyện bên ngoài. Đến bốn giờ hãy vào nhà cùng uống trà. Linh.', NULL, NULL, NULL, '[]', 94, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-R-SHORT-023', 'N5-R-SHORT', 'N5', 'READING', 23, '私は先月から小さいねこと住んでいます。ねこは朝、窓の近くで寝ますが、昼はいつも私のいすの上にいます。夜は私の部屋ではなく、母の部屋で寝ます。母は毎ばん、ねこに少し水をあげます。', 'Từ tháng trước tôi sống cùng một con mèo nhỏ. Buổi sáng mèo ngủ gần cửa sổ, buổi trưa luôn ở trên ghế của tôi. Buổi tối nó ngủ trong phòng mẹ chứ không phải phòng tôi. Tối nào mẹ cũng cho nó ít nước.', NULL, NULL, NULL, '[]', 88, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-R-SHORT-024', 'N5-R-SHORT', 'N5', 'READING', 24, '明日は学校のみんなで町の大きい川へ行きます。朝九時に学校の前に来てください。川には水が多いですから、水の中には入りません。川のそばで絵をかいて、昼に学校へ帰ります。先生より。', 'Ngày mai cả trường sẽ đến con sông lớn trong thị trấn. Hãy đến trước trường lúc chín giờ sáng. Sông nhiều nước nên không xuống nước. Cả lớp sẽ vẽ tranh bên sông rồi trưa trở về trường. Thầy cô.', NULL, NULL, NULL, '[]', 87, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-R-SHORT-025', 'N5-R-SHORT', 'N5', 'READING', 25, '私は新しいあかいぼうしを持っています。昨日、学校へ持って行きましたが、帰るときにありませんでした。学校の机と家の中を見ましたが、ありません。今日の朝、駅の人に聞きました。ぼうしは駅のいすの上にありました。', 'Tôi có một chiếc mũ đỏ mới. Hôm qua tôi mang đến trường, nhưng lúc về thì không thấy. Tôi tìm ở bàn trường và trong nhà nhưng không có. Sáng nay tôi hỏi người ở ga. Chiếc mũ ở trên ghế trong ga.', NULL, NULL, NULL, '[]', 102, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-R-SHORT-026', 'N5-R-SHORT', 'N5', 'READING', 26, '土曜日に学校で小さいお店をします。私たちのクラスは古い本と絵をうります。山田さんは本を持って来ます。私は家に絵がたくさんありますから、三枚持って行きます。お金は学校にあげます。', 'Thứ Bảy ở trường có một cửa hàng nhỏ. Lớp chúng tôi bán sách cũ và tranh. Yamada mang sách đến. Nhà tôi có nhiều tranh nên tôi sẽ mang ba bức. Tiền sẽ tặng trường.', NULL, NULL, NULL, '[]', 88, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-R-SHORT-027', 'N5-R-SHORT', 'N5', 'READING', 27, 'きのう新しい魚を二ひき買いました。小さいきいろい魚と大きいあおい魚です。二ひきとも元気ですが、きいろい魚はあおい魚よりよく泳ぎます。私は朝とゆうがたに少しずつ食べ物をあげています。', 'Hôm qua tôi mua hai con cá mới: cá vàng nhỏ và cá xanh lớn. Cả hai đều khỏe, nhưng cá vàng bơi nhiều hơn cá xanh. Tôi cho chúng ít thức ăn vào buổi sáng và chiều.', NULL, NULL, NULL, '[]', 90, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-R-SHORT-028', 'N5-R-SHORT', 'N5', 'READING', 28, '佐藤さんは月曜日にあおいかさを学校へ持って来ました。今日は木曜日ですが、そのかさはまだ教室にあります。先生は「金曜日までここにおきます」と言いました。佐藤さんは今、旅行に行っています。', 'Thứ Hai anh Sato mang ô xanh đến trường. Hôm nay là thứ Năm mà chiếc ô vẫn ở trong lớp. Thầy cô nói sẽ để nó ở đây đến thứ Sáu. Sato hiện đang đi du lịch.', NULL, NULL, NULL, '[]', 92, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-R-SHORT-029', 'N5-R-SHORT', 'N5', 'READING', 29, '今日の昼、私は友だちと学校の外で写真をとりました。友だちはカメラを持って来ましたが、私は持っていませんでした。先生が二人の写真をとりました。ゆうがた、友だちがその写真を私に見せました。', 'Trưa nay tôi chụp ảnh cùng bạn ở ngoài trường. Bạn mang máy ảnh còn tôi không mang. Thầy cô chụp ảnh hai chúng tôi. Chiều bạn cho tôi xem bức ảnh đó.', NULL, NULL, NULL, '[]', 92, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-R-SHORT-030', 'N5-R-SHORT', 'N5', 'READING', 30, '私のおばあさんは毎週火曜日に町の小さい店へ行きます。そこで野菜を買ったあとで、店の人と少し話します。今日は火曜日ですが、おばあさんは家にいます。店が休みですから、明日の朝に行きます。', 'Bà tôi đến cửa hàng nhỏ trong thị trấn mỗi thứ Ba. Sau khi mua rau bà nói chuyện một chút với người bán. Hôm nay thứ Ba bà ở nhà vì cửa hàng nghỉ; sáng mai bà mới đi.', NULL, NULL, NULL, '[]', 91, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-R-SHORT-031', 'N5-R-SHORT', 'N5', 'READING', 31, '今日は朝から雨です。母は外に白いシャツを三枚おいていましたが、雨がふってから家の中に入れました。私はあおいズボンをまだ外においていました。昼に見たら、ズボンの上には水がたくさんありました。', 'Hôm nay mưa từ sáng. Mẹ để ba áo sơ mi trắng bên ngoài nhưng khi mưa đã đem vào nhà. Tôi vẫn để quần xanh bên ngoài. Đến trưa nhìn thấy trên quần có nhiều nước.', NULL, NULL, NULL, '[]', 94, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-R-SHORT-032', 'N5-R-SHORT', 'N5', 'READING', 32, '私の町には小さい橋が二つあります。古い橋は学校の近くにありますが、歩く人だけが使います。車に乗るときは、駅の南にある新しい橋を使います。今日は父と車でその新しい橋をわたりました。', 'Thị trấn tôi có hai cây cầu nhỏ. Cầu cũ ở gần trường, chỉ người đi bộ dùng. Khi đi ô tô thì dùng cây cầu mới phía nam ga. Hôm nay tôi cùng bố lái xe qua cây cầu mới ấy.', NULL, NULL, NULL, '[]', 89, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-R-SHORT-033', 'N5-R-SHORT', 'N5', 'READING', 33, '土曜日、学校でみんなと歌を歌います。私は朝、家でその歌を三回歌いました。でも、歌のさいごのところがまだむずかしいです。夜、姉に聞いて、いっしょにもう一度歌います。姉は歌がとても上手です。', 'Thứ Bảy tôi sẽ hát cùng mọi người ở trường. Sáng nay ở nhà tôi hát bài ấy ba lần, nhưng đoạn cuối vẫn khó. Tối tôi sẽ hỏi chị và hát lại cùng chị. Chị hát rất giỏi.', NULL, NULL, NULL, '[]', 93, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-R-SHORT-034', 'N5-R-SHORT', 'N5', 'READING', 34, '学校の食堂では月曜日に魚、火曜日に肉の昼ごはんが出ます。水曜日はうどんです。私は魚があまり好きではありませんから、月曜日には家からパンを持って行きます。今日は月曜日です。', 'Nhà ăn trường phục vụ cá vào thứ Hai, thịt thứ Ba và mì udon thứ Tư. Tôi không thích cá lắm nên thứ Hai mang bánh mì từ nhà. Hôm nay là thứ Hai.', NULL, NULL, NULL, '[]', 85, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-R-SHORT-035', 'N5-R-SHORT', 'N5', 'READING', 35, 'リンさんへ。あなたのあかいセーターは私の家にあります。昨日、ここで着て、そのまま帰りましたね。明日は会えませんから、金曜日に学校へ持って行きます。あなたのあおいぼうしはここにありません。佐藤より。', 'Gửi Linh. Áo len đỏ của bạn ở nhà tôi. Hôm qua bạn mặc ở đây rồi về mà để lại. Ngày mai không gặp được nên thứ Sáu tôi mang đến trường. Mũ xanh của bạn không ở đây. Sato.', NULL, NULL, NULL, '[]', 98, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-R-SHORT-036', 'N5-R-SHORT', 'N5', 'READING', 36, 'きのう、町の新しい店で小さい時計を見ました。くろい時計は五千円で、白い時計は三千円でした。私は白い時計がほしかったですが、お金は二千円だけでした。今日は買わないで、また来週、店へ行きます。', 'Hôm qua tôi xem đồng hồ nhỏ ở cửa hàng mới trong thị trấn. Đồng hồ đen giá 5.000 yên, đồng hồ trắng 3.000 yên. Tôi muốn chiếc trắng nhưng chỉ có 2.000 yên. Hôm nay chưa mua, tuần sau sẽ quay lại cửa hàng.', NULL, NULL, NULL, '[]', 94, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-R-SHORT-037', 'N5-R-SHORT', 'N5', 'READING', 37, '私のおとうとは毎日、朝七時に犬と外へ出ます。でも、今日はおとうとがまだ寝ていましたから、私が犬と歩きました。おとうとは八時に起きて、犬に朝ごはんをあげました。ゆうがたはおとうとがまた犬と外へ行きます。', 'Em trai tôi mỗi sáng bảy giờ ra ngoài cùng chó. Nhưng hôm nay em còn ngủ nên tôi dắt chó đi bộ. Em dậy lúc tám giờ và cho chó ăn sáng. Chiều em lại ra ngoài cùng chó.', NULL, NULL, NULL, '[]', 100, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-R-SHORT-038', 'N5-R-SHORT', 'N5', 'READING', 38, '山田さんへ。来週の火曜日、学校の庭でみんなと写真をとります。白いシャツを着て来てください。雨がふった日は、庭ではなく、学校の一階の大きい部屋でとります。時間は朝十時です。先生より。', 'Gửi Yamada. Thứ Ba tuần sau mọi người sẽ chụp ảnh ở sân trường. Hãy mặc áo sơ mi trắng. Nếu trời mưa thì chụp ở phòng lớn tầng một thay vì sân. Thời gian là 10 giờ sáng. Thầy cô.', NULL, NULL, NULL, '[]', 90, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-R-SHORT-039', 'N5-R-SHORT', 'N5', 'READING', 39, '私の父はまいばん、新聞を読みます。今週の月曜日に新しい新聞が家に来ましたが、父はその日は仕事で遅く帰りました。火曜日の朝はめがねがありませんでしたから、読みませんでした。今夜、新聞を読みます。', 'Bố tôi đọc báo mỗi tối. Thứ Hai tuần này báo mới đến nhà nhưng hôm ấy bố về muộn vì công việc. Sáng thứ Ba không có kính nên ông không đọc. Tối nay bố sẽ đọc báo.', NULL, NULL, NULL, '[]', 96, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-R-SHORT-040', 'N5-R-SHORT', 'N5', 'READING', 40, '今日、私は学校の友だちと教室へ行きました。友だちはあかい花を三つ持って来ました。私はきいろい花を二つ持って来ました。花を教室の机の上において、みんなで見ました。来週はまたべつの花を持って来ます。', 'Hôm nay tôi cùng bạn đến phòng học. Bạn mang ba bông hoa đỏ, tôi mang hai bông hoa vàng. Chúng tôi đặt hoa trên bàn lớp học và cùng ngắm. Tuần sau sẽ mang những bông hoa khác.', NULL, NULL, NULL, '[]', 97, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-R-SHORT-041', 'N5-R-SHORT', 'N5', 'READING', 41, 'りんさんへ。あしたのあさ、えきのきたぐちで八じにあいましょう。バスはおそいですから、でんしゃでいきます。えきのなかの店で水をかってから、そこへきてください。やまだより。', NULL, NULL, NULL, NULL, '[]', 84, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-R-SHORT-042', 'N5-R-SHORT', 'N5', 'READING', 42, '日よう日、わたしは母と大きいスーパーへいきました。母はさかなとやさいをかいました。わたしはパンがほしかったですが、その店にはありませんでした。かえるまえに、えきのちいさい店でパンをかいました。', NULL, NULL, NULL, NULL, '[]', 96, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-R-SHORT-043', 'N5-R-SHORT', 'N5', 'READING', 43, 'たなかさんへ。きょうの日本語のクラスは午後二じからです。いつものへやはそうじをしていますから、一かいのみぎのへやへきてください。ノートとえんぴつをもってきてください。先生より。', NULL, NULL, NULL, NULL, '[]', 88, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-R-SHORT-044', 'N5-R-SHORT', 'N5', 'READING', 44, '先週の土よう日、わたしは友だちとこうえんへいきました。あさは雨でしたが、ひるからいい天気になりました。こうえんで写真をとって、かえりにちかくの店であたたかいパンをたべました。', NULL, NULL, NULL, NULL, '[]', 87, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-R-SHORT-045', 'N5-R-SHORT', 'N5', 'READING', 45, '母へ。きょうは学校のあと、としょかんで本をよみます。五じごろうちにかえりますから、ばんごはんは先にたべてください。わたしのかばんはいすの上です。かえりに牛にゅうをかいます。', NULL, NULL, NULL, NULL, '[]', 86, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-R-SHORT-046', 'N5-R-SHORT', 'N5', 'READING', 46, 'ぼくはまいあさ七じにうちを出ます。学校までバスで二十分です。きょうはバスがきませんでしたから、えきまであるいてでんしゃにのりました。学校についたのはいつもより十分おそい時間でした。', NULL, NULL, NULL, NULL, '[]', 90, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-R-SHORT-047', 'N5-R-SHORT', 'N5', 'READING', 47, 'あねへ。日よう日のひる、うちでカレーをつくります。肉とたまねぎはかいましたが、じゃがいもはまだありません。かえりに店で三つかってきてください。ごはんはわたしがつくります。', NULL, NULL, NULL, NULL, '[]', 85, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-R-SHORT-048', 'N5-R-SHORT', 'N5', 'READING', 48, 'きのう、わたしはあたらしいくつを見に店へいきました。白いくつはきれいでしたが、少し小さかったです。くろいくつは大きさがよかったですが、お金がたりませんでした。来週、もう一ど店へいきます。', NULL, NULL, NULL, NULL, '[]', 93, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-R-SHORT-049', 'N5-R-SHORT', 'N5', 'READING', 49, 'やまださんへ。あしたのテストは午前九じからです。へやには八じ半までにきてください。えんぴつとけしゴムをわすれないでください。テストのあと、みんなで食どうへいきます。先生より。', NULL, NULL, NULL, NULL, '[]', 87, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-R-SHORT-050', 'N5-R-SHORT', 'N5', 'READING', 50, 'わたしの父は日よう日に車でうみへいきます。母とわたしもいっしょです。あさはうちでごはんをたべて、十じに出ます。うみでさかなを見たあと、ちかくの店でひるごはんをたべます。', NULL, NULL, NULL, NULL, '[]', 84, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-R-SHORT-051', 'N5-R-SHORT', 'N5', 'READING', 51, 'りんさんへ。きょうは雨ですから、こうえんへいきません。午後三じにえきのなかの本やであいましょう。本を見たあと、となりの店でお茶をのみませんか。わたしはあおいかばんをもっています。', NULL, NULL, NULL, NULL, '[]', 89, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-R-SHORT-052', 'N5-R-SHORT', 'N5', 'READING', 52, 'わたしは先月日本へきました。月よう日から金よう日まで学校で日本語をべんきょうします。土よう日は友だちとかいものをして、日よう日はうちで本をよみます。今週の日よう日は母に電話をします。', NULL, NULL, NULL, NULL, '[]', 91, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-R-SHORT-053', 'N5-R-SHORT', 'N5', 'READING', 53, 'きょう、おとうとはあさごはんをたべませんでした。時間がありませんでしたから、パンをかばんにいれて学校へいきました。ひる休みに友だちと食どうへいって、パンと牛にゅうをたべました。', NULL, NULL, NULL, NULL, '[]', 88, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-R-SHORT-054', 'N5-R-SHORT', 'N5', 'READING', 54, 'わたしの町にはちいさいこうえんがあります。こうえんのとなりにとしょかんがあり、月よう日は休みです。火よう日から日よう日まではあさ九じから午後六じまでです。土よう日の午後に本をかりにいきます。', NULL, NULL, NULL, NULL, '[]', 95, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-R-SHORT-055', 'N5-R-SHORT', 'N5', 'READING', 55, 'すずきさんへ。きょうの夜、うちで日本語をべんきょうしませんか。七じにきてください。わたしは六じ半にかえります。ごはんはつくりますから、何ももってこなくてもいいです。えきまでむかえにいきます。', NULL, NULL, NULL, NULL, '[]', 95, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-R-SHORT-056', 'N5-R-SHORT', 'N5', 'READING', 56, 'きのう、わたしは母とデパートへいきました。母は白いシャツをかいました。わたしはあかいぼうしがほしかったですが、店にありませんでした。あおいぼうしをかぶってみましたが、かいませんでした。', NULL, NULL, NULL, NULL, '[]', 92, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-R-SHORT-057', 'N5-R-SHORT', 'N5', 'READING', 57, 'あした、クラスのみんなで山へいきます。あさ八じに学校のまえにあつまって、バスで出かけます。水とおべんとうをもってきてください。山の上はさむいですから、あたたかいふくももってきてください。', NULL, NULL, NULL, NULL, '[]', 93, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-R-SHORT-058', 'N5-R-SHORT', 'N5', 'READING', 58, 'わたしは毎週水よう日にえきのちかくの店でパンをかいます。きょうは店が休みでしたから、学校のまえのスーパーへいきました。そこにはパンがありませんでした。ひるごはんはうちからもってきたおにぎりをたべました。', NULL, NULL, NULL, NULL, '[]', 101, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-R-SHORT-059', 'N5-R-SHORT', 'N5', 'READING', 59, '父はまいあさ六じにおきて、しんぶんをよみます。きょうはめがねが見つかりませんでしたから、しんぶんをよみませんでした。あさごはんのあと、母がつくえの上でめがねを見つけました。父はとてもよろこびました。', NULL, NULL, NULL, NULL, '[]', 99, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-R-SHORT-060', 'N5-R-SHORT', 'N5', 'READING', 60, 'わたしは土よう日に友だちとテニスをします。いつもは学校のコートをつかいますが、今週は雨でつかえません。日よう日は父と買いものにいきます。今週の土よう日は公園のちかくのコートであいます。', NULL, NULL, NULL, NULL, '[]', 92, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-R-MEDIUM-001', 'N5-R-MEDIUM', 'N5', 'READING', 1, '先週の日曜日、私は友だちのリンさんと一緒に電車に乗って大きい公園へ行きました。うちから公園まで電車で一時間ぐらいかかりました。公園のなかにはきれいな花や高い木がたくさんありました。私は白い花が一番好きでした。リンさんは高い木が好きだと言いました。昼ごはんは公園の川の近くで、朝うちで作った弁当を二人で食べました。冷たいお茶も飲みました。日曜日は天気もよくて、とても楽しい一日でした。また今年の秋にも二人で遊びに行きたいです。', 'Chủ nhật tuần trước, tôi đã lên tàu điện đi đến một công viên lớn cùng với bạn Linh. Từ nhà đến công viên đi bằng tàu điện mất khoảng 1 tiếng. Trong công viên có rất nhiều hoa đẹp và cây cao. Tôi thích nhất là hoa màu trắng. Bạn Linh thì nói là thích những hàng cây cao. Bữa trưa, hai chúng tôi đã ăn cơm hộp tự làm ở nhà buổi sáng ở gần con sông trong công viên. Chúng tôi cũng uống trà lạnh nữa. Chủ nhật thời tiết cũng đẹp nên là một ngày rất vui. Mùa thu năm nay chúng tôi lại muốn đi chơi cùng nhau tiếp.', NULL, NULL, NULL, '[{"expression":"日曜日","reading":"にちようび","meaning_vi":"chủ nhật"},{"expression":"公園","reading":"こうえん","meaning_vi":"công viên"},{"expression":"弁当","reading":"べんとう","meaning_vi":"cơm hộp"}]', 212, 2, NULL, NULL, NULL, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-R-MEDIUM-002', 'N5-R-MEDIUM', 'N5', 'READING', 2, '私は去年の四月にベトナムから日本へ来ました。四月には日本語があまりわかりませんでしたから、店での買い物や電車に乗ることがとても難しかったです。でも、日本語学校の先生やクラスの友だちが毎日親切に日本語を教えました。今は一人で銀行や病院へ行くことができます。日本での毎日もとても楽しくなりました。今年の夏休みには、一人で速い新幹線に乗って大阪へ三日間旅行に行きたいです。大阪でおいしい料理もたくさん食べたいです。今からとても楽しみです。', 'Tôi đã từ Việt Nam sang Nhật vào tháng 4 năm ngoái. Vào tháng 4 vì chưa hiểu tiếng Nhật mấy nên việc mua sắm ở cửa hàng hay đi tàu điện rất khó khăn. Thế nhưng thầy cô ở trường tiếng Nhật và bạn bè cùng lớp ngày nào cũng tận tình dạy tiếng Nhật. Bây giờ tôi đã có thể tự đi ngân hàng hay bệnh viện một mình. Mỗi ngày ở Nhật cũng trở nên rất vui. Kỳ nghỉ hè năm nay, tôi muốn tự đi tàu Shinkansen nhanh đến Osaka du lịch 3 ngày một mình. Ở Osaka tôi cũng muốn ăn thật nhiều món ngon. Ngay từ bây giờ tôi đã rất háo hức.', NULL, NULL, NULL, '[{"expression":"去年","reading":"きょねん","meaning_vi":"năm ngoái"},{"expression":"難しい","reading":"むずかしい","meaning_vi":"khó"},{"expression":"夏休み","reading":"なつやすみ","meaning_vi":"kỳ nghỉ hè; kì nghỉ hè"}]', 216, 2, NULL, NULL, NULL, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-R-MEDIUM-003', 'N5-R-MEDIUM', 'N5', 'READING', 3, '私の父は料理を作ることがとても上手です。母は土曜日も会社で仕事をしていますから、毎週土曜日のばんごはんは父が作ります。先週の土曜日は、父が魚と野菜の料理をたくさん作りました。とてもおいしかったですから、私はいつもの夜よりたくさんごはんを食べました。母も妹もよろこびました。食事のあとで、私と妹は台所で白いおさらやコップをきれいにあらいました。あしたも土曜日です。父がどんな料理を作るか、今からとても楽しみです。', 'Bố tôi nấu ăn rất giỏi. Vì mẹ tôi ngày thứ Bảy cũng làm việc ở công ty nên bữa tối thứ Bảy hằng tuần đều do bố nấu. Thứ Bảy tuần trước, bố đã nấu rất nhiều món cá và rau. Vì rất ngon nên tôi đã ăn nhiều cơm hơn mọi tối. Cả mẹ và em gái cũng rất vui. Sau bữa ăn, tôi và em gái đã rửa bát đĩa trắng và cốc thật sạch ở trong bếp. Ngày mai lại là thứ Bảy rồi. Ngay từ bây giờ tôi đã rất háo hức xem bố sẽ nấu món gì.', NULL, NULL, NULL, '[{"expression":"上手","reading":"じょうず","meaning_vi":"giỏi; khéo"},{"expression":"妹","reading":"いもうと","meaning_vi":"em gái (tôi)"},{"expression":"仕事","reading":"しごと","meaning_vi":"công việc; nghề; việc làm"}]', 205, 2, NULL, NULL, NULL, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-R-MEDIUM-004', 'N5-R-MEDIUM', 'N5', 'READING', 4, 'きのうの午後、私は駅の近くの大きいデパートへ母の誕生日のプレゼントを買いに行きました。はじめはきれいなハンカチを買いたかったですが、店にいい色がありませんでした。それで、二階のかばん屋を見ました。そこにかるくて小さいかばんがありました。母はいつも荷物が少ないですから、その小さいかばんを三千円で買いました。帰りにデパートの一階の店で、母が好きな果物とお菓子も買ってうちへ帰りました。あした母にわたします。', 'Chiều hôm qua, tôi đã đến trung tâm thương mại lớn gần ga để mua quà sinh nhật cho mẹ. Ban đầu tôi muốn mua một chiếc khăn tay đẹp, nhưng ở tiệm lại không có màu ưng ý. Vì thế tôi đã xem tiệm túi xách ở tầng 2. Ở đó có một chiếc túi vừa nhẹ vừa nhỏ. Vì mẹ tôi lúc nào cũng mang ít đồ nên tôi đã mua chiếc túi nhỏ đó với giá 3.000 yên. Lúc về tôi cũng mua thêm hoa quả và bánh kẹo mà mẹ thích ở tiệm tầng 1 rồi mới về nhà. Ngày mai tôi sẽ tặng mẹ.', NULL, NULL, NULL, '[{"expression":"色","reading":"いろ","meaning_vi":"màu sắc; màu"},{"expression":"少ない","reading":"すくない","meaning_vi":"ít"},{"expression":"お菓子","reading":"おかし","meaning_vi":"bánh kẹo"}]', 202, 2, NULL, NULL, NULL, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-R-MEDIUM-005', 'N5-R-MEDIUM', 'N5', 'READING', 5, '私の一週間はいつもとても忙しいです。月曜日から金曜日までは、午前九時から午後五時まで日本語学校で勉強します。火曜日と木曜日の夜は、駅の近くのレストランで三時間仕事をします。でも、土曜日と日曜日は学校も仕事も休みですから、朝九時ごろまでゆっくり寝ます。土曜日の午後は自分の部屋を掃除したり、洗濯をしたりします。日曜日は友だちと広い公園で楽しくテニスをして、夜はうちで日本の映画を見ます。休みの日が一番好きです。', 'Một tuần của tôi lúc nào cũng rất bận rộn. Từ thứ Hai đến thứ Sáu, tôi học ở trường tiếng Nhật từ 9 giờ sáng đến 5 giờ chiều. Tối thứ Ba và thứ Năm, tôi làm việc 3 tiếng ở nhà hàng gần ga. Nhưng thứ Bảy và Chủ nhật cả trường học lẫn công việc đều nghỉ nên buổi sáng tôi ngủ thoải mái đến khoảng 9 giờ. Chiều thứ Bảy tôi dọn phòng hoặc giặt giũ. Chủ nhật tôi vui vẻ chơi quần vợt với bạn ở công viên rộng và buổi tối thì xem phim Nhật ở nhà. Tôi thích nhất là ngày nghỉ.', NULL, NULL, NULL, '[{"expression":"勉強","reading":"べんきょう","meaning_vi":"việc học"},{"expression":"掃除","reading":"そうじ","meaning_vi":"việc dọn dẹp; dọn dẹp; dọn vệ sinh"},{"expression":"洗濯","reading":"せんたく","meaning_vi":"việc giặt giũ; giặt giũ"}]', 204, 2, NULL, NULL, NULL, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-R-MEDIUM-006', 'N5-R-MEDIUM', 'N5', 'READING', 6, '先月、私は駅の近くの新しいアパートへ来ました。前の部屋は駅から歩いて二十分かかりましたが、今の部屋は駅から歩いて五分ですから、毎日とても便利です。アパートの隣には夜の十時まであいている大きいスーパーがあります。近くには広い図書館や静かな公園もあります。今の部屋は少しせまいですが、新しくてとてもきれいです。今度の日曜日に、クラスの友だちが私の部屋へ来て、みんなで一緒にばんごはんを食べます。今からとても楽しみです。', 'Tháng trước tôi đã chuyển đến tòa căn hộ mới ở gần ga. Phòng trước đây đi bộ từ ga mất 20 phút, nhưng phòng hiện tại đi bộ từ ga chỉ mất 5 phút nên mỗi ngày đều rất tiện lợi. Bên cạnh tòa căn hộ có siêu thị lớn mở cửa đến 10 giờ tối. Ở gần đó cũng có thư viện rộng và công viên yên tĩnh. Căn phòng hiện tại hơi hẹp một chút nhưng mới và rất sạch đẹp. Chủ nhật tới, bạn cùng lớp sẽ đến phòng tôi và mọi người cùng nhau ăn tối. Ngay từ bây giờ tôi đã rất háo hức.', NULL, NULL, NULL, '[{"expression":"隣","reading":"となり","meaning_vi":"bên cạnh"},{"expression":"便利","reading":"べんり","meaning_vi":"tiện lợi; tiện"},{"expression":"静か","reading":"しずか","meaning_vi":"yên tĩnh"}]', 207, 2, NULL, NULL, NULL, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-R-MEDIUM-007', 'N5-R-MEDIUM', 'N5', 'READING', 7, 'きのうは朝から白い雪がたくさんふって、とても寒い一日でした。私はどこへも出かけないで、一日中うちのなかにいました。午前中はあたたかい部屋で静かな音楽を聞いてから、国にいる母に長い手紙を書きました。昼ごはんには、台所で自分で熱い肉うどんを作って食べました。とてもおいしかったです。午後は日本の古い映画を二本見ました。外はとても寒かったですが、うちのなかでゆっくり休むことができて本当によかったです。', 'Hôm qua tuyết trắng rơi nhiều từ sáng nên là một ngày rất lạnh. Tôi không đi đâu cả mà ở trong nhà suốt cả ngày. Buổi sáng sau khi nghe nhạc êm dịu trong căn phòng ấm áp, tôi đã viết một bức thư dài cho mẹ ở quê nhà. Bữa trưa tôi tự nấu mì udon thịt nóng ở trong bếp để ăn. Món mì rất ngon. Buổi chiều tôi xem 2 bộ phim cũ của Nhật. Bên ngoài tuy rất lạnh nhưng tôi đã có thể nghỉ ngơi thong thả ở trong nhà nên thực sự rất tốt.', NULL, NULL, NULL, '[{"expression":"雪","reading":"ゆき","meaning_vi":"tuyết"},{"expression":"寒い","reading":"さむい","meaning_vi":"lạnh (thời tiết)"},{"expression":"手紙","reading":"てがみ","meaning_vi":"lá thư; thư (viết tay)"}]', 198, 2, NULL, NULL, NULL, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-R-MEDIUM-008', 'N5-R-MEDIUM', 'N5', 'READING', 8, '私のうちには小さい白い犬がいます。名前は「シロ」です。三年前に兄の友だちからもらいました。シロは外を歩くのが大好きですから、私は毎日学校から帰ってから、近くの川のそばを三十分ぐらいシロと一緒に歩きます。雨の日は外へ行くことができませんから、うちの広い部屋のなかで小さいボールを使って一緒に遊びます。シロは毎日とても元気です。シロは家族みんなと遊ぶのが好きですが、うちのなかで一番好きな人は私の母です。', 'Ở nhà tôi có một chú chó nhỏ màu trắng. Tên của nó là "Shiro". Cách đây 3 năm chúng tôi nhận nuôi từ một người bạn của anh trai. Vì Shiro rất thích đi dạo bên ngoài nên mỗi ngày sau khi đi học về, tôi đều đi bộ cùng Shiro khoảng 30 phút ở bờ sông gần nhà. Ngày mưa không ra ngoài được nên chúng tôi cùng chơi bằng quả bóng nhỏ ở trong căn phòng rộng ở nhà. Shiro ngày nào cũng rất khỏe mạnh. Shiro thích chơi với cả nhà, nhưng người nó thích nhất trong nhà là mẹ tôi.', NULL, NULL, NULL, '[{"expression":"犬","reading":"いぬ","meaning_vi":"con chó; chó"},{"expression":"名前","reading":"なまえ","meaning_vi":"tên"},{"expression":"川","reading":"かわ","meaning_vi":"sông"}]', 200, 2, NULL, NULL, NULL, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-R-MEDIUM-009', 'N5-R-MEDIUM', 'N5', 'READING', 9, '先週の金曜日、会社の同僚と五人で駅の近くの新しいレストランへ行きました。その店は魚の料理が有名です。私たちは魚料理と野菜のサラダを食べました。魚料理はとてもおいしかったです。野菜のサラダもたくさんありました。店の人もみんなとても親切でした。でも、金曜日の夜でしたから、店のなかに人がたくさんいて、少しにぎやかでした。今度は月曜日から木曜日までの静かな昼の時間に、またその店へ魚料理を食べに行きたいです。', 'Thứ Sáu tuần trước, tôi đã đi cùng đồng nghiệp công ty tổng cộng 5 người đến một nhà hàng mới ở gần ga. Quán đó nổi tiếng về các món cá. Chúng tôi đã ăn món cá và salad rau. Món cá rất ngon. Salad rau cũng có rất nhiều. Nhân viên quán ai cũng rất thân thiện. Tuy nhiên, vì là tối thứ Sáu nên trong quán đông người và hơi nhộn nhịp. Lần tới tôi muốn lại đến quán đó ăn món cá vào khung giờ buổi trưa yên tĩnh từ thứ Hai đến thứ Năm.', NULL, NULL, NULL, '[{"expression":"金曜日","reading":"きんようび","meaning_vi":"thứ sáu"},{"expression":"有名","reading":"ゆうめい","meaning_vi":"nổi tiếng"},{"expression":"魚","reading":"さかな","meaning_vi":"cá"}]', 201, 2, NULL, NULL, NULL, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-R-MEDIUM-010', 'N5-R-MEDIUM', 'N5', 'READING', 10, '私は先月から毎週水曜日に会社の近くで英語を習っています。先生は外国から来たブラウン先生です。ブラウン先生は日本語も上手ですが、教室の授業ではいつも英語しか話しません。水曜日の授業では先生の話が速くて、はじめは少ししかわかりませんでした。でも、毎日うちで三十分ぐらい英語のCDを聞いて勉強しましたから、今は先生の話がよくわかります。英語の歌も好きになりました。英語で友だちと話すのは本当に楽しいです。', 'Từ tháng trước, thứ Tư hằng tuần tôi đều học tiếng Anh ở gần công ty. Giáo viên là thầy Brown đến từ nước ngoài. Thầy Brown cũng giỏi tiếng Nhật, nhưng trong giờ học ở lớp thầy luôn chỉ nói tiếng Anh thôi. Trong giờ học thứ Tư thầy nói nhanh nên ban đầu tôi chỉ hiểu được một chút. Nhưng nhờ mỗi ngày đều nghe CD tiếng Anh học khoảng 30 phút ở nhà nên bây giờ tôi đã hiểu rõ lời thầy nói. Tôi cũng trở nên thích các bài hát tiếng Anh. Nói chuyện bằng tiếng Anh với bạn bè thực sự rất vui.', NULL, NULL, NULL, '[{"expression":"水曜日","reading":"すいようび","meaning_vi":"thứ tư"},{"expression":"英語","reading":"えいご","meaning_vi":"tiếng Anh"},{"expression":"授業","reading":"じゅぎょう","meaning_vi":"buổi học; tiết học; giờ học"}]', 199, 2, NULL, NULL, NULL, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-R-MEDIUM-011', 'N5-R-MEDIUM', 'N5', 'READING', 11, 'きのうの夜、私は電車のなかに新しい大きい傘をわすれました。その傘は先週の誕生日に姉にもらったきれいな白い傘でした。私はすぐ駅の事務所へ行って、駅の人に傘のことを話しました。駅の人はとても親切で、いろいろな駅に電話をして傘を聞きました。三十分あとで、駅の人は「隣の駅にありますよ」と言いました。私はすぐ電車に乗って隣の駅へ行って、その白い傘をもらいました。駅の人に「ありがとうございます」と言いました。本当によかったです。', 'Tối hôm qua tôi đã quên chiếc ô to mới ở trên tàu điện. Chiếc ô đó là chiếc ô trắng đẹp mà tôi nhận từ chị gái vào sinh nhật tuần trước. Tôi lập tức đến văn phòng nhà ga và nói chuyện chiếc ô với nhân viên nhà ga. Nhân viên ga rất tận tình, đã gọi điện hỏi nhiều ga khác nhau về chiếc ô. 30 phút sau, nhân viên ga nói "Có ở ga bên cạnh đấy". Tôi liền lên tàu sang ga bên cạnh và nhận lại chiếc ô trắng đó. Tôi đã nói "Xin cảm ơn" với nhân viên nhà ga. Thật là may quá.', NULL, NULL, NULL, '[{"expression":"傘","reading":"かさ","meaning_vi":"ô; dù; cái ô"},{"expression":"聞く","reading":"きく","meaning_vi":"nghe; hỏi"},{"expression":"隣","reading":"となり","meaning_vi":"bên cạnh"}]', 210, 2, NULL, NULL, NULL, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-R-MEDIUM-012', 'N5-R-MEDIUM', 'N5', 'READING', 12, '私の町には大きい図書館が一つあります。うちから自転車で十分ぐらいかかります。私は毎週土曜日の午後にその図書館へ行きます。一階には新しい新聞や雑誌がたくさんあります。二階には外国語の本や辞書があります。また、二階には静かに勉強する広い部屋もあります。その部屋には大きい机がたくさんあります。私はいつも二階の静かな部屋で二時間ぐらい日本語の勉強をしてから、日本の本を一冊借りてうちへ帰ります。来週の土曜日もまた行きます。', 'Ở thị trấn của tôi có một thư viện lớn. Từ nhà đi bằng xe đạp mất khoảng 10 phút. Chiều thứ Bảy hằng tuần tôi đều đến thư viện đó. Ở tầng 1 có rất nhiều báo và tạp chí mới. Ở tầng 2 có sách ngoại ngữ và từ điển. Ngoài ra, ở tầng 2 còn có căn phòng rộng để học bài yên tĩnh. Trong phòng đó có rất nhiều bàn lớn. Tôi luôn học tiếng Nhật khoảng 2 tiếng ở căn phòng yên tĩnh trên tầng 2 xong rồi mượn một cuốn sách tiếng Nhật mang về nhà. Thứ Bảy tuần sau tôi cũng sẽ lại đi.', NULL, NULL, NULL, '[{"expression":"町","reading":"まち","meaning_vi":"thị trấn; phố; khu phố"},{"expression":"雑誌","reading":"ざっし","meaning_vi":"tạp chí"},{"expression":"借りる","reading":"かりる","meaning_vi":"mượn"}]', 208, 2, NULL, NULL, NULL, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-R-MEDIUM-013', 'N5-R-MEDIUM', 'N5', 'READING', 13, '今年の春休みに、私は家族と一緒に飛行機で北の町へ旅行に行きました。私たちの町はもうあたたかかったですが、北の町はまだとても寒くて、白い雪がたくさん残っていました。私たちは三日間、いろいろな所を見ました。夜に高い山の上から見た町の明かりがいちばんきれいでした。私と妹は写真をたくさんとりました。また、温かい牛乳や魚料理もとてもおいしかったです。父も母も毎日元気でとても楽しそうでした。また今年の冬にも家族で行きたいです。', 'Vào kỳ nghỉ xuân năm nay, tôi đã đi du lịch tới thị trấn phương Bắc cùng gia đình bằng máy bay. Thị trấn của chúng tôi lúc đó đã ấm áp rồi, nhưng thị trấn phương Bắc vẫn còn rất lạnh và tuyết trắng vẫn còn đọng lại rất nhiều. Trong 3 ngày, chúng tôi đã tham quan nhiều nơi khác nhau. Ánh đèn phố thị nhìn từ trên đỉnh núi cao vào ban đêm là đẹp nhất. Tôi và em gái đã chụp rất nhiều ảnh. Hơn nữa, sữa bò ấm và món cá cũng rất ngon. Cả bố và mẹ tôi ngày nào cũng khỏe và rất vui vẻ. Mùa đông năm nay tôi lại muốn đi cùng gia đình tiếp.', NULL, NULL, NULL, '[{"expression":"春","reading":"はる","meaning_vi":"mùa xuân"},{"expression":"飛行機","reading":"ひこうき","meaning_vi":"máy bay"},{"expression":"山","reading":"やま","meaning_vi":"núi"}]', 209, 2, NULL, NULL, NULL, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-R-MEDIUM-014', 'N5-R-MEDIUM', 'N5', 'READING', 14, '私はお菓子が大好きで、毎日たくさん食べていました。でも、先週の月曜日の夜から口の中が痛くなりましたから、火曜日に会社の近くの病院へ行きました。病院はとてもきれいでした。お医者さんは私に「今週はお菓子を食べないでください。それから、毎日寝る前にゆっくり口の中をきれいにあらってください」と言いました。今週はお菓子を食べないで、おいしい果物を少しだけ食べています。今はもうぜんぜん痛くありません。本当によかったです。', 'Tôi rất thích bánh kẹo nên ngày nào cũng ăn rất nhiều. Nhưng từ tối thứ Hai tuần trước trong miệng/răng tôi bắt đầu bị đau, nên thứ Ba tôi đã đến bệnh viện gần công ty. Bệnh viện rất sạch đẹp. Bác sĩ dặn tôi: "Tuần này đừng ăn bánh kẹo nhé. Ngoài ra, mỗi ngày trước khi đi ngủ hãy vệ sinh răng miệng kỹ nhé". Tuần này tôi không ăn bánh kẹo nữa mà chỉ ăn một chút hoa quả ngon thôi. Bây giờ tôi hoàn toàn không còn đau nữa. Thật là may quá.', NULL, NULL, NULL, '[{"expression":"痛い","reading":"いたい","meaning_vi":"đau"},{"expression":"火曜日","reading":"かようび","meaning_vi":"thứ ba"},{"expression":"医者","reading":"いしゃ","meaning_vi":"bác sĩ"}]', 206, 2, NULL, NULL, NULL, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-R-MEDIUM-015', 'N5-R-MEDIUM', 'N5', 'READING', 15, 'きのうは私の誕生日でした。夜、日本語クラスの友だちが私のアパートへ遊びに来ました。マイクさんは駅の前の店で大きいケーキを買って持ってきました。リンさんとタオさんは私の台所でベトナムの料理をたくさん作りました。どの料理もとてもおいしかったです。みんなで料理とケーキを食べてから、ギターをひいて日本の歌を楽しく歌いました。友だちは午後十時に電車で帰りました。とてもにぎやかで楽しい誕生日でした。また来年もみんなで会いたいです。', 'Hôm qua là sinh nhật của tôi. Buổi tối, bạn bè cùng lớp tiếng Nhật đã đến căn hộ của tôi chơi. Bạn Mike đã mua một chiếc bánh kem lớn ở tiệm trước nhà ga mang đến. Bạn Linh và bạn Thảo thì nấu rất nhiều món ăn Việt Nam ở trong bếp của tôi. Món nào cũng rất ngon. Sau khi mọi người cùng ăn món ăn và bánh kem xong, chúng tôi đàn ghi-ta và vui vẻ hát các bài hát tiếng Nhật. Bạn bè ra về bằng tàu điện lúc 10 giờ tối. Đó là một ngày sinh nhật thật nhộn nhịp và vui vẻ. Năm sau tôi cũng muốn mọi người lại gặp nhau.', NULL, NULL, NULL, '[{"expression":"誕生日","reading":"たんじょうび","meaning_vi":"sinh nhật"},{"expression":"歌う","reading":"うたう","meaning_vi":"hát"},{"expression":"楽しい","reading":"たのしい","meaning_vi":"vui; vui vẻ"}]', 211, 2, NULL, NULL, NULL, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-R-MEDIUM-016', 'N5-R-MEDIUM', 'N5', 'READING', 16, '私は毎朝七時二十分のバスに乗って学校へ行きます。バスのりばはうちのすぐ前にありますから、雨の日もとても便利です。でも、けさは七時十分ごろに起きたので、いつものバスに乗ることができませんでした。次のバスは八時ですから、学校の授業に遅れます。それで、私はうちから駅まで十五分はしって、速い電車に乗って学校へ行きました。とてもつかれましたが、午前九時の授業の前に学校へ着くことができました。あしたはもっと早く起きます。', 'Mỗi sáng tôi đều lên chuyến xe buýt lúc 7 giờ 20 phút để đi học. Điểm đón xe buýt nằm ngay trước nhà nên những ngày mưa cũng rất tiện. Thế nhưng sáng nay vì khoảng 7 giờ 10 phút mới dậy nên tôi không thể lên chuyến xe buýt mọi khi. Chuyến buýt tiếp theo tận 8 giờ mới có nên sẽ bị muộn giờ học ở trường. Vì vậy tôi đã chạy bộ 15 phút từ nhà ra ga rồi đi tàu điện nhanh tới trường. Tuy rất mệt nhưng tôi đã có thể đến trường trước giờ học lúc 9 giờ sáng. Ngày mai tôi sẽ dậy sớm hơn nữa.', NULL, NULL, NULL, '[{"expression":"起きる","reading":"おきる","meaning_vi":"thức dậy; thức; xảy ra"},{"expression":"乗る","reading":"のる","meaning_vi":"lên xe; lên tàu; lên"},{"expression":"着く","reading":"つく","meaning_vi":"tới nơi; đến (ga; nhà...)"}]', 206, 2, NULL, NULL, NULL, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-R-MEDIUM-017', 'N5-R-MEDIUM', 'N5', 'READING', 17, '私の姉は今、東京の大きい病院で看護師の仕事をしています。姉は三年前に大学の勉強が終わってから、一人で東京へ行きました。病院の仕事は毎日忙しくて、夜遅く帰ることも多いですが、姉は「今の仕事が大好きだ」と言っています。休みの日には、友だちと美術館へ行ったり、うちでおいしいお菓子を作ったりしています。来月、姉は一週間休みをとって、新幹線で私たちの町へ帰ってきます。私は姉に会うのがとても楽しみです。家族みんなで姉を待っています。', 'Chị gái tôi hiện đang làm công việc điều dưỡng tại một bệnh viện lớn ở Tokyo. Cách đây 3 năm, sau khi học xong ở đại học, chị ấy đã lên Tokyo một mình. Công việc ở bệnh viện ngày nào cũng bận rộn, nhiều hôm phải về muộn vào ban đêm, nhưng chị tôi nói rằng "Chị rất yêu công việc hiện tại". Vào ngày nghỉ, chị thường đi bảo tàng mỹ thuật với bạn hoặc làm bánh kẹo ngon ở nhà. Tháng sau, chị sẽ nghỉ phép 1 tuần để về thăm quê chúng tôi bằng tàu Shinkansen. Tôi rất háo hức được gặp chị. Cả gia đình đang mong đợi chị về.', NULL, NULL, NULL, '[{"expression":"看護師","reading":"かんごし","meaning_vi":"y tá; điều dưỡng"},{"expression":"仕事","reading":"しごと","meaning_vi":"công việc; nghề; việc làm"},{"expression":"美術館","reading":"びじゅつかん","meaning_vi":"viện bảo tàng mỹ thuật; phòng tranh"}]', 212, 2, NULL, NULL, NULL, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-R-MEDIUM-018', 'N5-R-MEDIUM', 'N5', 'READING', 18, '先週の土曜日、私は駅の前の店へ新しい時計を買いに行きました。私の部屋の古い時計がこわれたからです。店にはいろいろな時計がありました。大きい時計もありましたが、私は勉強の机の上で使いたかったですから、小さい白い時計を買いました。時計は二千円でした。その新しい時計は毎朝六時にきれいな音楽がなりますから、今は毎朝六時に楽しく起きることができます。部屋も明るくなりました。とてもいい時計を買いました。', 'Thứ Bảy tuần trước, tôi đã đến cửa hàng trước ga để mua một chiếc đồng hồ mới. Đó là vì chiếc đồng hồ cũ trong phòng tôi đã bị hỏng. Trong tiệm có rất nhiều loại đồng hồ. Cũng có cả đồng hồ cỡ lớn, nhưng vì tôi muốn dùng ở trên bàn học nên đã mua một chiếc đồng hồ nhỏ màu trắng. Chiếc đồng hồ giá 2.000 yên. Chiếc đồng hồ mới đó mỗi sáng lúc 6 giờ đều vang lên bản nhạc hay, nên giờ đây mỗi sáng tôi có thể thức dậy lúc 6 giờ một cách vui vẻ. Căn phòng cũng trở nên sáng sủa hơn. Tôi đã mua được một chiếc đồng hồ rất tốt.', NULL, NULL, NULL, '[{"expression":"時計","reading":"とけい","meaning_vi":"đồng hồ; cái đồng hồ"},{"expression":"古い","reading":"ふるい","meaning_vi":"cũ"},{"expression":"小さい","reading":"ちいさい","meaning_vi":"nhỏ; bé"}]', 197, 2, NULL, NULL, NULL, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-R-MEDIUM-019', 'N5-R-MEDIUM', 'N5', 'READING', 19, '私は去年の秋から写真を習っています。毎週日曜日の午前中に、写真の先生や友だちと一緒にいろいろな所へ写真をとりにいきます。先週の日曜日は、山の近くの広い公園へ行きました。木の上のとりやきれいな花の写真をとりました。とりはすぐ空へ飛びますから、写真をとるのがとても難しかったです。でも、先生が上手なとりかたを親切に教えましたから、いい写真を二枚とることができました。家族にもその写真を見せました。とてもうれしかったです。', 'Tôi học chụp ảnh từ mùa thu năm ngoái. Sáng Chủ nhật hằng tuần, tôi đều đi chụp ảnh ở nhiều nơi khác nhau cùng với thầy giáo và bạn bè. Chủ nhật tuần trước, chúng tôi đã đến một công viên rộng ở gần núi. Tôi đã chụp ảnh chim trên cây và hoa đẹp. Vì chim bay lên trời ngay nên việc chụp ảnh rất khó. Tuy nhiên, nhờ thầy giáo tận tình chỉ cho cách chụp khéo léo nên tôi đã có thể chụp được 2 bức ảnh đẹp. Tôi cũng đã cho gia đình xem những bức ảnh đó. Tôi đã rất vui.', NULL, NULL, NULL, '[{"expression":"秋","reading":"あき","meaning_vi":"mùa thu"},{"expression":"花","reading":"はな","meaning_vi":"hoa"},{"expression":"空","reading":"そら","meaning_vi":"bầu trời; trời (trên cao)"}]', 208, 2, NULL, NULL, NULL, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-R-MEDIUM-020', 'N5-R-MEDIUM', 'N5', 'READING', 20, '私の母は花や木が大好きです。うちの庭には、母が作った花がいつもきれいにたくさんあります。春にはあかい花やきいろい花がたくさんあります。夏には庭のうしろでトマトなどの野菜も作ります。母は毎朝六時に起きて、庭の花や野菜に水をあげます。私も日曜日の朝は早く起きて、母の仕事を手伝います。けさは庭でとったあかいトマトを朝ごはんに食べました。とてもおいしかったですから、あしたの朝もまた家族みんなで食べたいです。', 'Mẹ tôi rất thích hoa và cây cối. Ở sân vườn nhà tôi lúc nào cũng có rất nhiều hoa đẹp do mẹ trồng. Vào mùa xuân có rất nhiều hoa đỏ và hoa vàng. Vào mùa hè mẹ còn trồng cả rau củ như cà chua ở phía sau vườn. Mỗi sáng mẹ đều dậy lúc 6 giờ để tưới nước cho hoa và rau trong vườn. Sáng Chủ nhật tôi cũng dậy sớm để phụ giúp công việc của mẹ. Sáng nay tôi đã ăn cà chua đỏ hái trong vườn vào bữa sáng. Vì rất ngon nên sáng mai tôi lại muốn cả nhà cùng ăn tiếp.', NULL, NULL, NULL, '[{"expression":"庭","reading":"にわ","meaning_vi":"sân vườn; vườn"},{"expression":"夏","reading":"なつ","meaning_vi":"mùa hè"},{"expression":"水","reading":"みず","meaning_vi":"nước; nước uống"}]', 201, 2, NULL, NULL, NULL, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-R-MEDIUM-021', 'N5-R-MEDIUM', 'N5', 'READING', 21, '私の学校では、毎週月曜日の朝、学生が教室をそうじします。先週は私と山田さんがまどをそうじし、田中さんがいすをそうじしました。私ははじめ、まどのそばのつくえもそうじしたかったです。でも、先生が『つくえはもうきれいです。こくばんをおねがいします』と言いました。それで、私はこくばんをきれいにしました。そうじが終わってから、みんなでお茶を飲みました。きれいな教室で勉強すると、気持ちがいいです。来週も早く学校へ行きたいです。', 'Ở trường tôi, sáng thứ Hai hằng tuần học sinh dọn lớp. Tuần trước tôi và Yamada dọn cửa sổ, còn Tanaka dọn ghế. Ban đầu tôi muốn dọn cả bàn gần cửa sổ. Nhưng giáo viên nói: \'Bàn đã sạch rồi. Em lau bảng nhé.\' Vì thế tôi làm sạch bảng. Dọn xong, mọi người cùng uống trà. Học trong lớp sạch sẽ khiến tôi thấy dễ chịu. Tuần sau tôi cũng muốn đến trường sớm.', NULL, NULL, NULL, '[]', 209, 2, NULL, NULL, NULL, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-R-MEDIUM-022', 'N5-R-MEDIUM', 'N5', 'READING', 22, 'きのうの朝、母はベランダにシャツとズボンを出しました。朝はよくはれていましたが、昼から空がくらくなりました。私は学校から帰って、そのシャツを見ました。まだそこにありました。でも、雨がふるとおもいましたから、シャツとズボンを家の中へ入れました。十分あとで、強い雨がふりました。母は仕事から帰って『ありがとう。ふくは家の中にありますね』と言いました。夜、母といっしょにふくをへやにおきました。あしたははれてほしいです。', 'Sáng qua, mẹ đem áo sơ mi và quần ra ban công. Buổi sáng trời nắng nhưng từ trưa bầu trời tối lại. Tôi đi học về và nhìn những chiếc áo, thấy quần áo vẫn còn ở đó. Tuy nhiên, vì tôi nghĩ trời sẽ mưa, tôi mang áo và quần vào nhà. Mười phút sau mưa rất to. Mẹ đi làm về và nói: \'Cảm ơn con. Quần áo đã ở trong nhà rồi nhỉ.\' Buổi tối, tôi cùng mẹ đặt quần áo vào phòng. Tôi mong ngày mai trời nắng.', NULL, NULL, NULL, '[]', 207, 2, NULL, NULL, NULL, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-R-MEDIUM-023', 'N5-R-MEDIUM', 'N5', 'READING', 23, '土曜日に、私はおとうとと町の小さい店へ行きました。おとうとはあおいノートがほしいと言いましたが、店にはあかいノートしかありませんでした。おとうとははじめ、何も買わないで帰りたいと言いました。私は『となりの店にもノートがありますよ』と言いました。二人でとなりの店へ行くと、あおいノートが三つありました。おとうとは一つ買い、私は日本語の本を一さつ買いました。帰るとき、おとうとはとてもうれしかったです。家で新しいノートに友だちの名前を書いていました。', 'Thứ Bảy, tôi cùng em trai đến một cửa hàng nhỏ trong thị trấn. Em muốn một quyển vở màu xanh, nhưng cửa hàng chỉ có vở đỏ. Lúc đầu em muốn về mà không mua gì. Tôi nói: \'Cửa hàng bên cạnh cũng có vở đấy.\' Chúng tôi sang đó và thấy ba quyển vở xanh. Em mua một quyển, còn tôi mua một cuốn sách tiếng Nhật. Lúc về, em có vẻ rất vui. Ở nhà, em viết tên bạn bè vào quyển vở mới.', NULL, NULL, NULL, '[]', 223, 2, NULL, NULL, NULL, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-R-MEDIUM-024', 'N5-R-MEDIUM', 'N5', 'READING', 24, '私の父は毎朝六時に起きます。でも、日曜日は仕事がありませんから、七時までねます。先週の日曜日は、父と私で朝ごはんを作りました。父はパンをあたたかくし、私はくだものを切りました。母はまだねていましたから、二人でしずかに作りました。八時に母が起きて、三人で食べました。母は『パンがあたたかくて、おいしいですね』と言いました。そのあと、父は新聞を読み、私は母と台所をそうじしました。来週は私がパンもやきたいです。', 'Bố tôi dậy lúc sáu giờ mỗi sáng. Nhưng Chủ nhật không phải đi làm nên bố ngủ đến bảy giờ. Chủ nhật tuần trước, bố và tôi cùng làm bữa sáng. Bố làm nóng bánh mì, còn tôi cắt trái cây. Vì mẹ vẫn đang ngủ nên hai bố con làm thật yên lặng. Tám giờ mẹ dậy và cả ba người ăn cùng nhau. Mẹ nói: \'Bánh mì nóng và ngon quá.\' Sau đó bố đọc báo, còn tôi dọn bếp với mẹ. Tuần sau tôi muốn tự làm nóng cả bánh mì.', NULL, NULL, NULL, '[]', 203, 2, NULL, NULL, NULL, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-R-MEDIUM-025', 'N5-R-MEDIUM', 'N5', 'READING', 25, '私は毎週火曜日に学校の近くでピアノを習っています。先生の部屋にはピアノが二つあります。一つは大きくてくろいピアノ、もう一つは小さくて白いピアノです。先週はくろいピアノを使いましたが、きょうは白いピアノを使いました。きょうの歌は少しむずかしかったです。先生は『家でも音楽のれんしゅうをしてください』と言いました。家にはピアノがありませんが、学校の音楽の部屋にあります。あした、学校が終わってからそこへ行きます。', 'Tôi học đàn piano gần trường vào mỗi thứ Ba. Trong phòng của giáo viên có hai cây đàn: một cây lớn màu đen và một cây nhỏ màu trắng. Tuần trước tôi dùng đàn đen, hôm nay dùng đàn trắng. Bài hát hôm nay hơi khó. Giáo viên nói: \'Ở nhà cũng hãy tập nhạc nhé.\' Nhà tôi không có đàn, nhưng phòng nhạc ở trường có. Ngày mai sau giờ học, tôi sẽ tới đó.', NULL, NULL, NULL, '[]', 204, 2, NULL, NULL, NULL, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-R-MEDIUM-026', 'N5-R-MEDIUM', 'N5', 'READING', 26, '私の家の近くに小さいパン屋があります。毎朝七時に店があきます。私は水曜日の朝によく行きます。きょうは七時半に行きました。いつものあまいパンはまだありませんでしたが、たまごのパンがありました。店の人は『あまいパンは八時にできます』と言いました。でも、私は八時前に学校へ行きますから、たまごのパンを二つ買いました。一つは自分で食べ、もう一つは学校で友だちにあげました。友だちはそのパンが大好きだと言いました。', 'Gần nhà tôi có một tiệm bánh nhỏ, mở cửa lúc bảy giờ mỗi sáng. Tôi thường đến vào sáng thứ Tư. Hôm nay tôi đến lúc bảy giờ rưỡi. Loại bánh ngọt tôi vẫn mua chưa có, nhưng đã có bánh trứng. Nhân viên nói: \'Tám giờ bánh ngọt mới xong.\' Tuy nhiên, tôi phải đến trường trước tám giờ nên mua hai bánh trứng. Tôi ăn một chiếc, chiếc còn lại đưa cho bạn ở trường. Bạn ấy nói rất thích chiếc bánh đó.', NULL, NULL, NULL, '[]', 202, 2, NULL, NULL, NULL, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-R-MEDIUM-027', 'N5-R-MEDIUM', 'N5', 'READING', 27, '先週、学校で小さいサッカーのしあいがありました。私のクラスは朝のしあいに出ました。私はサッカーが上手ではありませんから、はじめは見ていました。でも、友だちがつかれましたから、先生は私に『いっしょにやってください』と言いました。私は十分ぐらいサッカーをしました。ボールは一回もけることができませんでしたが、とても楽しかったです。しあいのあと、みんなで水を飲みました。来月のしあいの前には、友だちと少しれんしゅうしたいです。', 'Tuần trước, trường có một trận bóng đá nhỏ. Lớp tôi tham gia trận buổi sáng. Tôi đá không giỏi nên lúc đầu chỉ đứng xem. Nhưng một bạn mệt, giáo viên bảo tôi tham gia. Tôi chơi bóng đá khoảng mười phút. Tôi không đá được quả bóng lần nào, nhưng rất vui. Sau trận, cả lớp cùng uống nước. Trước trận tháng sau, tôi muốn tập một chút với bạn bè.', NULL, NULL, NULL, '[]', 210, 2, NULL, NULL, NULL, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-R-MEDIUM-028', 'N5-R-MEDIUM', 'N5', 'READING', 28, '私は夜、毎日ノートにその日のことを書きます。きのうは何もおもしろいことがないとおもいました。でも、ノートを見て、朝にとなりのおばあさんからみかんをもらったことをおもい出しました。昼には学校で友だちの新しいかばんを見ました。夜には父とテレビで古い映画を見ました。私はそれをぜんぶノートに書きました。書くことはたくさんありました。これからも毎ばん少しずつ書きたいです。あとで読むと、その日のことがまたわかります。', 'Mỗi tối tôi viết vào vở những việc xảy ra trong ngày. Hôm qua tôi tưởng không có gì thú vị. Nhưng khi nhìn vào vở, tôi nhớ ra buổi sáng được bà hàng xóm cho quýt, buổi trưa thấy chiếc túi mới của bạn ở trường, và buổi tối xem phim cũ trên TV với bố. Tôi viết hết những việc đó vào vở. Hóa ra có rất nhiều điều để viết. Tôi muốn tiếp tục viết một chút mỗi tối. Khi đọc lại sau này, tôi có thể nhớ lại ngày đó.', NULL, NULL, NULL, '[]', 204, 2, NULL, NULL, NULL, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-R-MEDIUM-029', 'N5-R-MEDIUM', 'N5', 'READING', 29, '私の妹は絵をかくのが大好きです。毎週土曜日の午後、家で紙にいろいろな絵をかきます。先週は家族の絵をかきました。父はあおいシャツ、母はあかいシャツ、私は白いシャツを着ていました。妹は自分を一番大きくかきました。私は『どうしてあなたが一番大きいの』と聞きました。妹は『この絵は私の絵だから』と言いました。母はその絵をへやのかべにかけました。今は家族みんなが毎日その絵を見ます。', 'Em gái tôi rất thích vẽ. Chiều thứ Bảy hằng tuần, em vẽ nhiều bức trên giấy ở nhà. Tuần trước, em vẽ gia đình. Bố mặc áo xanh, mẹ mặc áo đỏ, còn tôi mặc áo trắng. Em vẽ mình lớn nhất. Tôi hỏi: \'Sao em lại lớn nhất?\' Em nói: \'Vì đây là tranh của em.\' Mẹ treo bức tranh lên tường phòng. Bây giờ cả nhà nhìn bức tranh ấy mỗi ngày.', NULL, NULL, NULL, '[]', 186, 2, NULL, NULL, NULL, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-R-MEDIUM-030', 'N5-R-MEDIUM', 'N5', 'READING', 30, 'きのう、私は友だちの佐藤さんと学校の近くの川まで歩きました。佐藤さんは魚を見たいと言いました。朝は川の水がきれいで、小さい魚がたくさん見えました。私は写真をとりたかったですが、カメラを家にわすれました。佐藤さんのカメラで魚の写真を三まいとりました。昼から雨がふりましたから、二人で近くの店に入りました。そこであたたかいお茶を飲み、雨のあいだ話しました。帰るとき、佐藤さんは写真を私に見せました。', 'Hôm qua, tôi đi bộ cùng Sato tới con sông gần trường. Sato muốn xem cá. Buổi sáng nước sông trong, nhìn thấy nhiều cá nhỏ. Tôi muốn chụp ảnh nhưng bỏ quên máy ảnh ở nhà. Tôi dùng máy của Sato chụp ba tấm ảnh cá. Từ trưa trời mưa nên chúng tôi vào một cửa hàng gần đó, uống trà nóng và trò chuyện trong lúc trời mưa. Lúc về, Sato cho tôi xem những tấm ảnh.', NULL, NULL, NULL, '[]', 197, 2, NULL, NULL, NULL, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-R-MEDIUM-031', 'N5-R-MEDIUM', 'N5', 'READING', 31, '今週の月曜日、日本語の先生は新しい本をクラスに持ってきました。その本には短い話が十こあります。私は毎日一つ読みます。月曜日には一つめの話を読みました。少し知らない言葉がありましたから、友だちのリンさんに聞きました。火曜日には二つめの話を読みました。話はおもしろかったですが、漢字が多かったです。水曜日には学校のあとでリンさんといっしょに二つの話を読みました。今は四つ読みました。来週、ぜんぶ読みたいです。', 'Thứ Hai tuần này, giáo viên tiếng Nhật mang một cuốn sách mới đến lớp. Sách có mười câu chuyện ngắn. Tôi đọc mỗi ngày một câu chuyện. Thứ Hai tôi đọc chuyện thứ nhất; có vài từ chưa biết nên hỏi bạn Linh. Thứ Ba tôi đọc chuyện thứ hai; nội dung thú vị nhưng có nhiều chữ Hán. Thứ Tư sau giờ học tôi đọc hai chuyện cùng Linh. Đến giờ tôi đã đọc bốn chuyện. Tôi muốn đọc hết vào tuần sau.', NULL, NULL, NULL, '[]', 202, 2, NULL, NULL, NULL, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-R-MEDIUM-032', 'N5-R-MEDIUM', 'N5', 'READING', 32, '私の兄は毎日自転車で会社へ行きます。先週の木曜日の朝は雨でしたから、バスで行きました。兄は七時のバスに乗りたかったですが、家を出たときはもう七時五分でした。それで、七時半のバスに乗りました。会社には八時十五分につきました。いつもより少しおそかったですが、仕事は九時からですから、だいじょうぶでした。帰りには雨はもうふっていませんでした。兄はバスで家まで帰り、夜、自転車を見ました。自転車は家の前にありました。', 'Anh trai tôi hằng ngày đi làm bằng xe đạp. Sáng thứ Năm tuần trước trời mưa nên anh đi xe buýt. Anh muốn lên chuyến bảy giờ nhưng khi ra khỏi nhà đã là bảy giờ năm. Vì thế anh lên chuyến bảy giờ rưỡi và đến công ty lúc tám giờ mười lăm. Muộn hơn mọi ngày một chút nhưng công việc bắt đầu lúc chín giờ nên không sao. Lúc về mưa đã tạnh. Anh đi xe buýt về nhà; tối đến anh nhìn chiếc xe đạp. Xe vẫn ở trước nhà.', NULL, NULL, NULL, '[]', 204, 2, NULL, NULL, NULL, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-R-MEDIUM-033', 'N5-R-MEDIUM', 'N5', 'READING', 33, 'きょうはおばあさんが私の家に来ました。おばあさんの家から私の家まで電車で二時間かかります。私は駅までむかえに行きました。おばあさんは大きいかばんを持っていましたが、中はふくではなく、私の好きなりんごでした。おばあさんは『朝、店で買いました』と言いました。家に帰ってから、二人でりんごを洗いました。母はりんごを切って、おさらに入れました。三人でお茶を飲みました。それから、おばあさんの家の近くの話を聞きました。おばあさんは日曜日まで私たちの家にいます。', 'Hôm nay bà đến nhà tôi. Đi tàu từ nhà bà đến nhà tôi mất hai tiếng. Tôi ra ga đón bà. Bà cầm chiếc túi lớn, nhưng bên trong không phải quần áo mà là táo tôi thích. Bà bảo đã mua ở cửa hàng buổi sáng. Về nhà, hai bà cháu rửa táo. Mẹ cắt táo và cho lên đĩa. Ba người uống trà. Sau đó, chúng tôi nghe bà kể chuyện vùng gần nhà bà. Bà sẽ ở nhà chúng tôi đến Chủ nhật.', NULL, NULL, NULL, '[]', 225, 2, NULL, NULL, NULL, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-R-MEDIUM-034', 'N5-R-MEDIUM', 'N5', 'READING', 34, '新しい学生の鈴木さんは、今月私のクラスに来ました。鈴木さんは学校まで歩いて二十分かかります。私は自転車で十分です。月曜日、鈴木さんは教室がわかりませんでしたから、私が学校の前からいっしょに行きました。火曜日には鈴木さんが一人で教室に来ました。水曜日の昼休みに、私は鈴木さんに学校の中の小さい店を見せました。そこではパンと牛乳を買うことができます。鈴木さんは牛乳を一つ買い、『この学校はいいですね』と言いました。', 'Suzuki là học sinh mới đến lớp tôi trong tháng này. Từ nhà đến trường Suzuki đi bộ mất hai mươi phút, còn tôi đi xe đạp mười phút. Thứ Hai, Suzuki không biết lớp ở đâu nên tôi dẫn bạn từ trước cổng trường. Thứ Ba bạn tự đến lớp. Giờ nghỉ trưa thứ Tư, tôi cho Suzuki xem cửa hàng nhỏ trong trường, nơi có thể mua bánh mì và sữa. Suzuki mua một hộp sữa và nói: \'Trường này tốt quá nhỉ.\'', NULL, NULL, NULL, '[]', 205, 2, NULL, NULL, NULL, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-R-MEDIUM-035', 'N5-R-MEDIUM', 'N5', 'READING', 35, '先月、私は父と駅の近くのくつ屋へ行きました。私の古いくつは小さくなりましたから、新しいくつがほしかったです。店には白いくつとくろいくつがありました。白いくつはとてもきれいでしたが、少し大きかったです。くろいくつは大きくも小さくもありませんでしたから、そちらを買いました。父は自分のくつを買いませんでしたが、私のくつと同じ店でくつ下を三そく買いました。家に帰って、新しいくつで家の前を少し歩きました。とてもよかったです。', 'Tháng trước, tôi đi cùng bố đến cửa hàng giày gần ga. Giày cũ của tôi đã chật nên tôi muốn mua giày mới. Cửa hàng có giày trắng và giày đen. Giày trắng rất đẹp nhưng hơi rộng; giày đen vừa chân nên tôi mua đôi đó. Bố không mua giày cho mình mà mua ba đôi tất ở cùng cửa hàng. Về nhà, tôi đi thử đôi giày mới trước nhà một lúc. Đôi giày rất tốt.', NULL, NULL, NULL, '[]', 209, 2, NULL, NULL, NULL, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-R-MEDIUM-036', 'N5-R-MEDIUM', 'N5', 'READING', 36, 'きょう、私はおとうとと学校のプールへ行きました。おとうとは水が好きですが、私はまだ上手に泳げません。プールに入る前、先生は『はじめにここで少し歩いてください』と言いました。私はおとうとといっしょに水の中を歩きました。そのあと、おとうとは一人でむこうまで泳ぎました。私は先生といっしょに少しだけ泳ぎました。お昼にはプールの外で持ってきたパンを食べました。おとうとは午後も泳ぎたかったですが、私はつかれましたから、二人で家へ帰りました。', 'Hôm nay tôi cùng em trai đến bể bơi của trường. Em thích nước, còn tôi vẫn bơi chưa giỏi. Trước khi xuống bể, giáo viên bảo: \'Đầu tiên hãy đi bộ trong nước ở đây một chút.\' Tôi đi trong nước cùng em. Sau đó em tự bơi sang phía bên kia; tôi bơi một chút cùng giáo viên. Buổi trưa, chúng tôi ăn bánh mì mang theo ở ngoài bể. Em muốn bơi tiếp buổi chiều, nhưng tôi đã mệt nên cả hai về nhà.', NULL, NULL, NULL, '[]', 216, 2, NULL, NULL, NULL, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-R-MEDIUM-037', 'N5-R-MEDIUM', 'N5', 'READING', 37, '私たちのクラスは学校の前に花を作っています。四月に先生と学生であかい花と白い花を一つずつ買いました。私は毎朝学校へ来てから、その花に水をあげます。火曜日は雨でしたから、水をあげませんでした。水曜日に見ると、白い花は元気でしたが、あかい花は少し元気がありませんでした。先生は『あかい花はもっと水がいりますね』と言いました。それから、私はあかい花に少し多く水をあげています。きょうはあかい花もきれいです。', 'Lớp tôi trồng hoa trước trường. Tháng Tư, giáo viên và học sinh cùng mua một cây hoa đỏ và một cây hoa trắng. Mỗi sáng sau khi đến trường tôi tưới nước cho hoa. Thứ Ba trời mưa nên tôi không tưới. Thứ Tư nhìn lại, cây hoa trắng vẫn khỏe nhưng cây đỏ hơi yếu. Giáo viên nói cây đỏ cần thêm nước. Từ đó tôi tưới cây đỏ nhiều nước hơn một chút. Hôm nay hoa đỏ cũng đẹp trở lại.', NULL, NULL, NULL, '[]', 200, 2, NULL, NULL, NULL, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-R-MEDIUM-038', 'N5-R-MEDIUM', 'N5', 'READING', 38, '私の家では、金曜日の夜に家族でゲームをします。父はいつも早く帰りますが、先週の金曜日は仕事が多くておそくなりました。母とおとうとと私は八時まで待ちました。父が帰ったとき、おとうとはもうねむかったですから、ゲームは一回だけしました。父が一番になり、おとうとは二番でした。私はさいごでしたが、みんなといっしょに遊べて楽しかったです。来週は父の仕事が少ない日です。おとうとは『次は二回したい』と言っています。', 'Gia đình tôi chơi trò chơi vào tối thứ Sáu. Bố thường về sớm, nhưng thứ Sáu tuần trước công việc nhiều nên bố về muộn. Mẹ, em trai và tôi đợi đến tám giờ. Khi bố về, em buồn ngủ nên cả nhà chỉ chơi một lượt. Bố đứng đầu, em đứng thứ hai, còn tôi về cuối. Dù vậy tôi vẫn vui vì được chơi cùng mọi người. Tuần sau bố ít việc. Em nói lần sau muốn chơi hai lượt.', NULL, NULL, NULL, '[]', 201, 2, NULL, NULL, NULL, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-R-MEDIUM-039', 'N5-R-MEDIUM', 'N5', 'READING', 39, '私は電車に乗るとき、よく本を読みます。でも、けさは電車の中に人が多くて、たっていました。本を読むことができませんでしたから、まどの外を見ました。空はあおくて、遠くに山が見えました。次の駅でたくさんの人が電車をおりました。私はいすにすわって、本を読みました。学校の駅まであと四つありましたから、短い話を一つ読みました。学校に着いたとき、その話を友だちに話したくなりました。友だちは本が好きです。', 'Tôi thường đọc sách khi đi tàu. Nhưng sáng nay tàu đông người nên tôi phải đứng và không thể đọc sách. Tôi nhìn ra cửa sổ: trời xanh và xa xa có núi. Ở ga tiếp theo, nhiều người xuống tàu. Tôi ngồi vào ghế và bắt đầu đọc sách. Còn bốn ga nữa mới đến ga trường nên tôi đọc xong một chuyện ngắn. Đến trường, tôi muốn kể chuyện ấy cho bạn mình vì bạn cũng thích sách.', NULL, NULL, NULL, '[]', 196, 2, NULL, NULL, NULL, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-R-MEDIUM-040', 'N5-R-MEDIUM', 'N5', 'READING', 40, '私のおじいさんは遠い町に住んでいます。私は毎月、おじいさんに手紙を書きます。今月は学校のことを書きました。はじめに新しい先生のこと、次に友だちと見た映画のことを書きました。手紙といっしょに、学校の前でとった写真も入れました。きのうの午後、郵便局へ行きましたが、家に手紙をわすれました。それで、また家へ帰りました。今日は手紙をかばんに入れてから、郵便局へ行きました。今度はちゃんと出すことができました。おじいさんからの手紙を待っています。', 'Ông tôi sống ở một thị trấn xa. Mỗi tháng tôi viết thư cho ông. Tháng này tôi viết về trường học: trước tiên là giáo viên mới, rồi đến bộ phim xem cùng bạn. Tôi cũng bỏ vào phong thư một bức ảnh chụp trước trường. Chiều qua tôi đến bưu điện nhưng bỏ quên thư ở nhà nên phải quay lại. Hôm nay, sau khi cho thư vào túi, tôi đến bưu điện và gửi được thư. Tôi đang chờ thư của ông.', NULL, NULL, NULL, '[]', 218, 2, NULL, NULL, NULL, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-R-MEDIUM-041', 'N5-R-MEDIUM', 'N5', 'READING', 41, '日曜日、私は友だちのやまださんと町の公園へ行きました。やまださんはサッカーをしたことがありませんでしたが、私は学校で少しれんしゅうしました。はじめに二人でサッカーをしました。やまださんは何回もまちがえましたから、私はゆっくり教えました。一時間のあと、やまださんも少し上手になりました。帰る前に水を飲んで休み、来週もいっしょに行くことにしました。', 'Chủ nhật, tôi đến công viên trong thị trấn với bạn Yamada. Bạn chưa chơi bóng đá bao giờ, còn tôi đã tập một chút ở trường. Chúng tôi cùng chơi. Bạn mắc lỗi vài lần nên tôi chỉ dẫn chậm rãi. Sau một giờ, bạn chơi khá hơn. Trước khi về, chúng tôi uống nước, nghỉ một chút và hẹn tuần sau cùng đi nữa.', NULL, NULL, NULL, '[]', 172, 2, NULL, NULL, NULL, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-R-MEDIUM-042', 'N5-R-MEDIUM', 'N5', 'READING', 42, '先週の土曜日、私は母と家の近くのいちばへ行きました。母は魚を買い、私はかごを持ちました。いちばの中は人が多かったので母のそばを歩きました。母は魚の店のあとで、たまごと牛乳も買いました。私はくだものがほしかったですが、家にまだりんごがありましたから買いませんでした。家に帰ると、母は魚を使ってばんごはんを作りました。いちばを出るとき、母は家の人の分の牛乳も買いました。', 'Thứ bảy tuần trước, tôi đi chợ gần nhà với mẹ. Mẹ mua cá, trứng và sữa; tôi xách giỏ bên cạnh mẹ vì chợ đông. Tôi muốn mua trái cây nhưng ở nhà vẫn còn táo nên không mua. Về nhà, mẹ dùng cá làm bữa tối.', NULL, NULL, NULL, '[]', 183, 2, NULL, NULL, NULL, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-R-MEDIUM-043', 'N5-R-MEDIUM', 'N5', 'READING', 43, '毎朝、私は六時半に起きます。かおをあらってから、台所でパンとたまごを食べます。母は七時に家を出ますが、私は学校へ行く前に本を読みたいので、母よりあとに出ます。きょうは本を読んでいたら時間がなくなりました。いつもより早く歩いて、八時前に学校に着きました。あしたは本を読む時間を少し短くするつもりです。学校に着いてから、友だちは私がはやく来たことに気がつきました。', 'Mỗi sáng tôi thức dậy lúc sáu giờ rưỡi, rửa mặt rồi ăn bánh mì và trứng. Mẹ ra khỏi nhà lúc bảy giờ. Tôi muốn đọc sách trước khi đến trường nên thường đi sau mẹ. Hôm nay tôi đọc lâu nên ra khỏi nhà muộn, phải đi nhanh mới đến trường trước tám giờ. Ngày mai tôi định đọc sách ít thời gian hơn.', NULL, NULL, NULL, '[]', 180, 2, NULL, NULL, NULL, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-R-MEDIUM-044', 'N5-R-MEDIUM', 'N5', 'READING', 44, 'きのう、私は新しい自転車で公園へ行きました。公園の入口で、前のタイヤの空気が少ないことに気がつきました。空気を入れる物を持って来ませんでしたから、近くの店へ行きました。店の人はタイヤに空気を入れてくれました。私はお金をはらって、もう一度自転車に乗りました。帰りはゆっくりはしり、家に着いてから自転車を中に入れました。店の人は、空気が少なくなったらまた来てくださいと言いました。', 'Hôm qua tôi đạp xe mới đến công viên. Ở cổng, tôi thấy lốp trước thiếu hơi. Tôi không mang đồ bơm nên đến cửa hàng gần đó. Nhân viên bơm lốp giúp tôi. Tôi trả tiền rồi lại đạp xe. Trên đường về tôi đi chậm và cất xe vào nhà khi đến nơi.', NULL, NULL, NULL, '[]', 188, 2, NULL, NULL, NULL, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-R-MEDIUM-045', 'N5-R-MEDIUM', 'N5', 'READING', 45, '今月、私の町に小さい音楽の会がありました。私は歌が好きなので、友だちのリンさんと行きました。会は午後二時からでしたが、私たちは一時半に着きました。入口の近くに人がたくさんいたので、外で少し待ちました。中に入ると前のいすはいっぱいでしたから、後ろにすわりました。歌はとても楽しく、帰りに好きな歌の話をしました。会のあと、私たちは駅まで歩いて帰りました。', 'Tháng này thị trấn tôi có buổi biểu diễn âm nhạc nhỏ. Tôi thích ca hát nên đi cùng Linh. Buổi diễn bắt đầu lúc hai giờ, nhưng chúng tôi đến từ một rưỡi. Cửa vào đông người nên chúng tôi chờ bên ngoài. Khi vào trong, ghế phía trước đã kín, vì vậy chúng tôi ngồi phía sau. Buổi hát rất vui; trên đường về chúng tôi nói về bài hát yêu thích.', NULL, NULL, NULL, '[]', 175, 2, NULL, NULL, NULL, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-R-MEDIUM-046', 'N5-R-MEDIUM', 'N5', 'READING', 46, '先週、私は父といっしょに家の近くの山へ行きました。朝早く家を出て、バスに乗りました。山の下で水を買ってから、ゆっくり上りました。父は山の上でおべんとうを食べたいと言いましたが、雨がふりそうでしたから木の下で食べました。食べたあと少し休んで、山を下りました。家に帰ったときはつかれていましたが、また行きたいとおもいました。父は家に帰ってから、次はべつの山へ行こうと言いました。', 'Tuần trước, tôi cùng bố đến ngọn núi gần nhà. Chúng tôi đi xe buýt từ sáng sớm, mua nước dưới chân núi rồi đi lên từ từ. Bố muốn ăn cơm hộp trên đỉnh nhưng trời có vẻ sắp mưa nên chúng tôi ăn dưới gốc cây. Sau đó chúng tôi nghỉ rồi xuống núi. Tôi mệt khi về nhà nhưng vẫn muốn đi lần nữa.', NULL, NULL, NULL, '[]', 187, 2, NULL, NULL, NULL, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-R-MEDIUM-047', 'N5-R-MEDIUM', 'N5', 'READING', 47, '土曜日の午後、私は妹と家でカードのゲームをしました。妹はやりかたを知りませんでしたから、はじめにカードの使いかたを話しました。一回め、妹はまちがえてカードを出しました。でも、すぐにやりかたがわかりました。二回めは妹がかちました。妹はとてもよろこんで、もう一度したいと言いました。私はばんごはんのあとで、またいっしょに遊ぶことにしました。妹はカードをはこに入れました。', 'Chiều thứ bảy, tôi chơi trò chơi bài ở nhà với em gái. Em chưa biết cách chơi nên đầu tiên tôi giải thích cách dùng các lá bài. Em đánh nhầm ở lượt đầu nhưng nhanh chóng hiểu cách chơi. Em thắng ở lượt thứ hai và vui lắm, còn muốn chơi thêm. Tôi hẹn chơi cùng em sau bữa tối.', NULL, NULL, NULL, '[]', 183, 2, NULL, NULL, NULL, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-R-MEDIUM-048', 'N5-R-MEDIUM', 'N5', 'READING', 48, 'きょう、私は父のへやをそうじしました。父は仕事で朝から家にいませんでした。私はまどをあけて、つくえの上の本を本だなに入れました。それからゆかをそうじしました。つくえの下に父の古い時計がありましたから、なくさないようつくえの上におきました。父が帰ると、へやがきれいになったと言いました。私は父に時計も見つけたと話しました。父は時計を見て、とてもよろこびました。', 'Hôm nay tôi dọn phòng của bố. Bố đi làm từ sáng. Tôi mở cửa sổ, xếp sách trên bàn vào kệ rồi lau sàn. Tôi tìm thấy chiếc đồng hồ cũ của bố dưới bàn nên đặt lên bàn để khỏi làm mất. Khi bố về, bố nói phòng đã sạch. Tôi kể rằng mình cũng tìm thấy đồng hồ.', NULL, NULL, NULL, '[]', 179, 2, NULL, NULL, NULL, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-R-MEDIUM-049', 'N5-R-MEDIUM', 'N5', 'READING', 49, '先週、私は友だちの家へ行って、いっしょにカレーを作りました。友だちは野菜を切り、私はなべに水を入れました。カレーを作るのは時間がかかりましたが、二人で話して待ちました。食べると、とてもからかったです。私は水をたくさん飲みました。友だちは、次はからくないカレーを作ると言いました。私は家に帰ってから、母に作りかたを話しました。次の日、友だちは残ったカレーを昼ごはんに食べました。', 'Tuần trước tôi đến nhà bạn và cùng nấu cà ri. Bạn cắt rau, còn tôi đổ nước vào nồi. Nấu khá lâu nhưng chúng tôi vừa trò chuyện vừa đợi. Món cà ri rất cay nên tôi uống nhiều nước. Bạn nói lần tới sẽ nấu món cà ri không cay. Về nhà, tôi kể cách nấu cho mẹ nghe.', NULL, NULL, NULL, '[]', 188, 2, NULL, NULL, NULL, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-R-MEDIUM-050', 'N5-R-MEDIUM', 'N5', 'READING', 50, '先月、私は新しいめがねを作りました。前のめがねは小さくて、長い時間かけるとめがいたくなりました。母と店へ行き、店の人にかおを見てもらいました。私は大きいめがねをえらびましたが、母はもう少し小さいものがいいと言いました。それで二つをかけてから、母がいいと言っためがねを買いました。今は本を読むときもめがいたくありません。母は古いめがねを店の人に見てもらいました。', 'Tháng trước tôi làm một cặp kính mới. Cặp cũ nhỏ, đeo lâu thì mắt đau. Tôi đến cửa hàng với mẹ và nhờ nhân viên xem mặt. Tôi chọn cặp lớn nhưng mẹ nói cặp nhỏ hơn sẽ tốt. Sau khi thử cả hai, tôi mua cặp mẹ chọn. Bây giờ đọc sách lâu mắt cũng không đau.', NULL, NULL, NULL, '[]', 180, 2, NULL, NULL, NULL, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-R-MEDIUM-051', 'N5-R-MEDIUM', 'N5', 'READING', 51, 'きのうの夜、私の家にいとこが来ました。いとこは町の外に住んでいるので、家に来るのはひさしぶりでした。母はばんごはんに肉と野菜を作りました。食べたあと、私たちは子どものときの写真を見ました。いとこは写真の私を見て、今よりかみが長いと言いました。夜おそくなったので、いとこは家に帰らず、私のへやでねました。朝、いとこは母といっしょに朝ごはんを食べました。', 'Tối qua người em họ sống ở thị trấn khác đến nhà tôi. Mẹ nấu thịt và rau cho bữa tối. Sau khi ăn, chúng tôi xem ảnh hồi nhỏ. Em họ nói tóc tôi trong ảnh dài hơn bây giờ. Vì đã khuya nên em không về nhà mà ngủ ở phòng tôi.', NULL, NULL, NULL, '[]', 175, 2, NULL, NULL, NULL, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-R-MEDIUM-052', 'N5-R-MEDIUM', 'N5', 'READING', 52, '私は毎月一回、父と家の車をそうじします。今月は日曜日の朝にしました。父は車の外を水であらい、私は中のごみをとりました。車の中に小さい紙がたくさんあったので、時間がかかりました。そうじのあと、父は車でスーパーへ行こうと言いました。私はきれいな車に乗れてうれしかったです。帰りに父はアイスクリームを買ってくれました。父は車の中を見て、きれいになったと言いました。', 'Mỗi tháng một lần tôi rửa xe cùng bố. Tháng này chúng tôi làm vào sáng Chủ nhật. Bố rửa bên ngoài, còn tôi lấy rác bên trong. Có nhiều mẩu giấy nhỏ nên mất thời gian. Sau khi dọn xong, bố rủ tôi lái xe đến siêu thị. Tôi vui vì được ngồi trong chiếc xe sạch. Trên đường về bố mua kem cho tôi.', NULL, NULL, NULL, '[]', 179, 2, NULL, NULL, NULL, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-R-MEDIUM-053', 'N5-R-MEDIUM', 'N5', 'READING', 53, '学校の休み時間に、私は友だちのさとうさんと中庭へ行きました。さとうさんは花を見たいと言いましたが、そこには花がありませんでした。かわりに小さいとりが木の上にいました。私たちは大きな声を出さないで、少し見ていました。とりはすぐに空へ行きました。さとうさんは写真をとりたかったと言いましたが、とりが早く行ったので、とれませんでした。休み時間が終わると、私たちは教室へ帰りました。', 'Giờ nghỉ ở trường, tôi đến sân trong với Sato. Bạn muốn xem hoa nhưng ở đó không có hoa. Thay vào đó có một con chim nhỏ trên cây. Chúng tôi im lặng ngắm một lúc. Chim bay đi rất nhanh. Sato muốn chụp ảnh nhưng không kịp vì chim đã bay mất.', NULL, NULL, NULL, '[]', 187, 2, NULL, NULL, NULL, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-R-MEDIUM-054', 'N5-R-MEDIUM', 'N5', 'READING', 54, '先週、私は家の近くの店で小さいラジオを買いました。毎朝、朝ごはんを食べるときにニュースを聞きたかったからです。店には大きいラジオもありましたが、私のへやは小さいので小さいものにしました。家に帰って、母といっしょに使いかたを読みました。今は朝、ラジオをつけてからパンを食べます。ニュースで天気を聞いて、かさを持つかどうかきめます。ラジオの天気の話は、毎朝少しずつちがいます。', 'Tuần trước tôi mua chiếc radio nhỏ ở cửa hàng gần nhà vì muốn nghe tin tức lúc ăn sáng. Cửa hàng cũng có radio lớn, nhưng phòng tôi nhỏ nên tôi chọn chiếc nhỏ. Về nhà tôi đọc hướng dẫn với mẹ. Bây giờ tôi bật radio rồi ăn bánh mì. Tôi nghe dự báo thời tiết để quyết định có mang ô theo không.', NULL, NULL, NULL, '[]', 186, 2, NULL, NULL, NULL, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-R-MEDIUM-055', 'N5-R-MEDIUM', 'N5', 'READING', 55, '今週の金曜日、私は学校の友だちと海へ行くよていでした。でも、木曜日の夜から雨がふりました。朝になっても雨はやみませんでしたから、海へ行くのをやめました。友だちは少しざんねんそうでしたが、私の家に来ました。三人で古い映画を見て、昼ごはんにうどんを作りました。雨は午後にやみましたが、私たちは家でゆっくりしました。友だちは映画がおもしろかったと言いました。', 'Tuần này tôi định đi biển với bạn cùng trường vào thứ Sáu. Nhưng từ tối thứ Năm trời đã mưa, sáng hôm sau vẫn chưa tạnh nên chúng tôi hủy chuyến đi. Bạn hơi tiếc nhưng đến nhà tôi. Ba chúng tôi xem phim cũ và nấu mì udon cho bữa trưa. Mưa tạnh vào buổi chiều nhưng chúng tôi vẫn ở nhà nghỉ ngơi.', NULL, NULL, NULL, '[]', 176, 2, NULL, NULL, NULL, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-R-MEDIUM-056', 'N5-R-MEDIUM', 'N5', 'READING', 56, '私は今週、学校のノートを新しくしました。前のノートは使うところがなくなったので、駅の近くの店で一さつ買いました。家に帰って、前のノートから大切な紙を出しました。紙には友だちの電話の番ごうと先生の話が書いてありました。新しいノートのはじめに、その紙を入れました。あしたから学校で新しいノートを使います。前のノートは家においておきます。先生は新しいノートを見て、いいですねと言いました。', 'Tuần này tôi bắt đầu dùng quyển vở mới vì quyển cũ đã hết chỗ viết. Tôi mua quyển mới ở cửa hàng gần ga. Về nhà, tôi lấy tờ giấy quan trọng trong quyển cũ ra. Trên đó có số điện thoại của bạn và lời thầy giáo dặn. Tôi kẹp giấy vào đầu quyển mới. Ngày mai tôi sẽ dùng vở mới ở trường.', NULL, NULL, NULL, '[]', 191, 2, NULL, NULL, NULL, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-R-MEDIUM-057', 'N5-R-MEDIUM', 'N5', 'READING', 57, '日曜日、私は父と新しいテレビを見ました。テレビは先週家に来ましたが、使いかたがよくわかりませんでした。父がせつめいの紙を読み、私はテレビのうしろにあるボタンを見ました。二人でいろいろなボタンをおして、やっとニュースを見ることができました。父は音が大きいと言ったので、私は音を小さくしました。そのあと、二人で天気の話を聞きました。父はニュースのあと、明日の天気について話しました。', 'Chủ nhật tôi xem ti vi mới cùng bố. Ti vi được mang đến tuần trước nhưng chúng tôi chưa biết cách dùng. Bố đọc tờ hướng dẫn còn tôi xem các nút phía sau. Chúng tôi thử nhiều nút rồi cuối cùng xem được tin tức. Bố nói âm thanh lớn quá nên tôi giảm âm lượng. Sau đó chúng tôi nghe dự báo thời tiết.', NULL, NULL, NULL, '[]', 189, 2, NULL, NULL, NULL, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-R-MEDIUM-058', 'N5-R-MEDIUM', 'N5', 'READING', 58, '先月、私は友だちと町の小さい店でお茶を飲みました。友だちははじめてその店に来ました。私はよくここで本を読みますが、友だちはお茶とケーキを食べたいと言いました。店の人に聞くと、ケーキは午後三時からでした。私たちは二時に店に着いたので、先にお茶を飲みました。三時になってからケーキを一つ買い、二人で半分ずつ食べました。私は友だちに、またこの店へ来たいと言いました。', 'Tháng trước tôi uống trà ở một quán nhỏ trong thị trấn với bạn. Bạn đến đó lần đầu. Tôi thường đọc sách ở quán, còn bạn muốn ăn bánh. Nhân viên nói bánh chỉ bán từ ba giờ. Chúng tôi đến lúc hai giờ nên uống trà trước. Đến ba giờ, chúng tôi mua một chiếc bánh và chia đôi.', NULL, NULL, NULL, '[]', 180, 2, NULL, NULL, NULL, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-R-MEDIUM-059', 'N5-R-MEDIUM', 'N5', 'READING', 59, '毎週月曜日、私は家の近くの公園をそうじします。今週は友だちのリンさんも来ました。私たちは手ぶくろをして、道におとちている紙や小さいごみをひろいました。公園の人は、ここにごみをすてないでくださいと言いました。そうじのあと、リンさんは近くの水を飲みました。私は家から持って来たお茶を飲みました。公園は前よりきれいになりました。来週もリンさんといっしょにそうじをするつもりです。', 'Mỗi thứ Hai tôi dọn công viên gần nhà. Tuần này Linh cũng đến. Chúng tôi đeo găng và nhặt giấy cùng rác nhỏ trên đường. Nhân viên công viên nhắc mọi người đừng vứt rác ở đây. Sau khi dọn xong, Linh uống nước gần đó, còn tôi uống trà mang từ nhà. Công viên sạch hơn trước.', NULL, NULL, NULL, '[]', 186, 2, NULL, NULL, NULL, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-R-MEDIUM-060', 'N5-R-MEDIUM', 'N5', 'READING', 60, 'きょう、私は母といっしょに写真を見ました。写真は去年の夏に、母の友だちの家でとったものです。写真の中で母はあかいふくを着て、私は白いぼうしをかぶっていました。母はこの写真が好きですが、私は少しはずかしいです。母は写真を一まいえらんで、へやのつくえの上におきました。私は写真を見て、去年の夏のことをおもい出しました。母は写真を見て、私のぼうしが大きかったと言いました。', 'Hôm nay tôi xem ảnh với mẹ. Ảnh được chụp mùa hè năm ngoái ở nhà bạn của mẹ. Trong ảnh mẹ mặc áo đỏ còn tôi đội mũ trắng. Mẹ thích ảnh nhưng tôi hơi ngượng. Mẹ chọn một tấm rồi đặt lên bàn trong phòng. Nhìn ảnh, tôi nhớ lại mùa hè năm ngoái.', NULL, NULL, NULL, '[]', 183, 2, NULL, NULL, NULL, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-R-INFO-001', 'N5-R-INFO', 'N5', 'READING', 1, '【さくら図書館のお知らせ】\nあいている時間：\n・火曜日〜金曜日：午前9時00分〜午後7時00分\n・土曜日・日曜日：午前10時00分〜午後5時00分\n休みの日：毎週月曜日\n本を借りる人へ：一人で5冊まで、2週間借りることができます。\n※新しい雑誌や新聞は図書館のなかで読んでください。うちへ持って帰ることはできません。', '[Thông báo của Thư viện Sakura]\nGiờ mở cửa:\n・Thứ Ba ~ Thứ Sáu: 9:00 sáng ~ 7:00 tối\n・Thứ Bảy, Chủ nhật: 10:00 sáng ~ 5:00 chiều\nNgày nghỉ: Thứ Hai hằng tuần\nGửi người mượn sách: Mỗi người được mượn tối đa 5 quyển trong 2 tuần.\n*Tạp chí mới và báo vui lòng đọc trong thư viện, không được mang về nhà.', NULL, NULL, NULL, '[{"expression":"火曜日","reading":"かようび","meaning_vi":"thứ ba"},{"expression":"月曜日","reading":"げつようび","meaning_vi":"thứ hai"},{"expression":"図書館","reading":"としょかん","meaning_vi":"thư viện"}]', 152, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-R-INFO-002', 'N5-R-INFO', 'N5', 'READING', 2, '【山川病院・病院のあいている時間】\n・午前：午前9時00分〜午前12時00分（月曜日〜土曜日）\n・午後：午後2時00分〜午後6時00分（月曜日・火曜日・水曜日・金曜日）\n休みの日：木曜日の午後、土曜日の午後、日曜日\n※この病院へはじめて来る人は、一階の受付で白い紙に名前と住所と電話を書いてください。', '[Bệnh viện Yamakawa - Giờ mở cửa của bệnh viện]\n・Buổi sáng: 9:00 sáng ~ 12:00 trưa (Thứ Hai ~ Thứ Bảy)\n・Buổi chiều: 2:00 chiều ~ 6:00 chiều (Thứ Hai, Thứ Ba, Thứ Tư, Thứ Sáu)\nNgày nghỉ: Chiều thứ Năm, chiều thứ Bảy, cả ngày Chủ nhật\n*Người đến bệnh viện này lần đầu vui lòng viết tên, địa chỉ và điện thoại vào tờ giấy trắng ở quầy tiếp nhận tầng 1.', NULL, NULL, NULL, '[{"expression":"木曜日","reading":"もくようび","meaning_vi":"thứ năm"},{"expression":"休み","reading":"やすみ","meaning_vi":"ngày nghỉ; giờ nghỉ"},{"expression":"電話","reading":"でんわ","meaning_vi":"gọi điện thoại; điện thoại"}]', 146, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-R-INFO-003', 'N5-R-INFO', 'N5', 'READING', 3, '【あおい美術館のお知らせ】\nあいている時間：午前9時30分〜午後5時00分（月曜日は休みです）\n美術館に入るお金：\n・大人：一人 800円\n・大学生・高校生：一人 500円\n・中学生・小学生：一人 200円\n・6歳より小さい子ども：お金はいりません（0円）\n※毎週土曜日は、中学生と小学生もお金はいりません（0円）。', '[Thông báo của Bảo tàng Mỹ thuật Aoi]\nGiờ mở cửa: 9:30 sáng ~ 5:00 chiều (nghỉ Thứ Hai)\nTiền vé vào bảo tàng:\n・Người lớn: 800 yên/người\n・Sinh viên đại học, học sinh cấp 3: 500 yên/người\n・Học sinh cấp 2, tiểu học: 200 yên/người\n・Trẻ em dưới 6 tuổi: Không mất tiền (0 yên)\n*Thứ Bảy hằng tuần, học sinh cấp 2 và tiểu học cũng không mất tiền (0 yên).', NULL, NULL, NULL, '[{"expression":"大人","reading":"おとな","meaning_vi":"người lớn"},{"expression":"子ども","reading":"こども","meaning_vi":"trẻ con; con; trẻ em"},{"expression":"土曜日","reading":"どようび","meaning_vi":"thứ bảy"}]', 148, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-R-INFO-004', 'N5-R-INFO', 'N5', 'READING', 4, '【レストラン「はるか」・昼のメニュー（午前11時〜午後2時）】\n・Aセット：魚の料理・しろいごはん・温かいスープ（850円）\n・Bセット：肉の料理・パンまたはしろいごはん・野菜サラダ（950円）\n・Cセット：野菜カレー・小さいサラダ・おいしい果物（750円）\n※プラス100円で、食後にコーヒーまたは温かいお茶を飲むことができます。', '[Nhà hàng "Haruka" - Thực đơn bữa trưa (11:00 sáng ~ 2:00 chiều)]\n・Set A: Món cá, cơm trắng, súp ấm (850 yên)\n・Set B: Món thịt, bánh mì hoặc cơm trắng, salad rau (950 yên)\n・Set C: Cà ri rau củ, salad nhỏ, hoa quả ngon (750 yên)\n*Thêm 100 yên có thể uống cà phê hoặc trà ấm sau bữa ăn.', NULL, NULL, NULL, '[{"expression":"昼","reading":"ひる","meaning_vi":"buổi trưa"},{"expression":"肉","reading":"にく","meaning_vi":"thịt"},{"expression":"お茶","reading":"おちゃ","meaning_vi":"trà"}]', 162, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-R-INFO-005', 'N5-R-INFO', 'N5', 'READING', 5, '【みどりデパート・買い物のフロア】\n・4階：本屋・ノートや鉛筆やボールペンの店・家族のレストラン\n・3階：男の人のシャツ・スポーツの靴・大きい旅行のかばん\n・2階：女の人のスカート・子どものシャツ・新しい時計\n・1階：白い靴・長い傘・きれいな花屋\n・地下1階：魚・肉・野菜・おいしい果物・温かい弁当\n※デパートは午前10時から午後8時までです。', '[Trung tâm thương mại Midori - Các tầng mua sắm]\n・Tầng 4: Hiệu sách, tiệm vở/bút chì/bút bi, nhà hàng gia đình\n・Tầng 3: Áo sơ mi nam, giày thể thao, túi du lịch lớn\n・Tầng 2: Chân váy nữ, áo trẻ em, đồng hồ mới\n・Tầng 1: Giày trắng, ô dài, tiệm hoa đẹp\n・Tầng hầm B1: Cá, thịt, rau, hoa quả ngon, cơm hộp ấm\n*Trung tâm thương mại mở cửa từ 10 giờ sáng đến 8 giờ tối.', NULL, NULL, NULL, '[{"expression":"本屋","reading":"ほんや","meaning_vi":"hiệu sách"},{"expression":"鉛筆","reading":"えんぴつ","meaning_vi":"bút chì"},{"expression":"果物","reading":"くだもの","meaning_vi":"trái cây; hoa quả"}]', 166, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-R-INFO-006', 'N5-R-INFO', 'N5', 'READING', 6, '【日本語学校・バス旅行のお知らせ】\n旅行の日：5月15日（金曜日）\n行く所：みどり山の広い公園\n会う時間と所：午前8時30分に学校の大きい門の前\n持ってくるもの：昼の弁当、冷たい飲み物、雨の傘\nバスのお金：一人 600円\n※バスのお金は5月14日（木曜日）の午後4時までに、教室で先生にわたししてください。', '[Trường tiếng Nhật - Thông báo chuyến du lịch bằng xe buýt]\nNgày đi: Ngày 15 tháng 5 (Thứ Sáu)\nNơi đến: Công viên rộng ở núi Midori\nGiờ và nơi gặp mặt: 8:30 sáng tại trước cổng lớn của trường\nĐồ mang theo: Cơm hộp bữa trưa, đồ uống lạnh, ô che mưa\nTiền xe buýt: 600 yên/người\n*Tiền xe buýt vui lòng nộp cho giáo viên tại phòng học trước 4 giờ chiều ngày 14 tháng 5 (Thứ Năm).', NULL, NULL, NULL, '[{"expression":"旅行","reading":"りょこう","meaning_vi":"du lịch; chuyến đi"},{"expression":"門","reading":"もん","meaning_vi":"cổng"},{"expression":"お金","reading":"おかね","meaning_vi":"tiền"}]', 146, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-R-INFO-007', 'N5-R-INFO', 'N5', 'READING', 7, '【東京駅から山川駅までのバスと電車の時間】\n1. バス：午前9時00分に出ます → 午前10時30分に着きます（1,200円）\n2. しろい電車：午前9時15分に出ます → 午前10時15分に着きます（1,500円）\n3. 速い電車：午前9時20分に出ます → 午前9時55分に着きます（2,400円）\n※雨の日には、バスは15分ぐらい遅く着くことがあります。', '[Giờ xe buýt và tàu điện từ ga Tokyo đến ga Yamakawa]\n1. Xe buýt: Khởi hành 9:00 sáng → Đến nơi 10:30 sáng (1.200 yên)\n2. Tàu điện trắng: Khởi hành 9:15 sáng → Đến nơi 10:15 sáng (1.500 yên)\n3. Tàu điện nhanh: Khởi hành 9:20 sáng → Đến nơi 9:55 sáng (2.400 yên)\n*Vào ngày mưa, xe buýt có lúc đến muộn khoảng 15 phút.', NULL, NULL, NULL, '[{"expression":"速い","reading":"はやい","meaning_vi":"nhanh (tốc độ)"},{"expression":"電車","reading":"でんしゃ","meaning_vi":"tàu điện"},{"expression":"着く","reading":"つく","meaning_vi":"tới nơi; đến (ga; nhà...)"}]', 167, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-R-INFO-008', 'N5-R-INFO', 'N5', 'READING', 8, '【東映画館・土曜日の映画が始まる時間】\n・映画A「夏の海」：午前10時00分 ／ 午後1時30分 ／ 午後5時00分\n・映画B「山の家族」：午前11時00分 ／ 午後2時30分 ／ 午後6時30分\n・映画C「白い犬」：午後12時00分 ／ 午後3時30分 ／ 午後7時00分\nお金：大人 1,800円、学生 1,200円（どの映画も2時間ぐらいです）', '[Rạp chiếu phim Higashi - Giờ bắt đầu chiếu phim thứ Bảy]\n・Phim A "Biển mùa hè": 10:00 sáng / 1:30 chiều / 5:00 chiều\n・Phim B "Gia đình trên núi": 11:00 sáng / 2:30 chiều / 6:30 tối\n・Phim C "Chú chó trắng": 12:00 trưa / 3:30 chiều / 7:00 tối\nGiá vé: Người lớn 1.800 yên, Học sinh/Sinh viên 1.200 yên (phim nào cũng dài khoảng 2 tiếng)', NULL, NULL, NULL, '[{"expression":"映画館","reading":"えいがかん","meaning_vi":"rạp chiếu phim"},{"expression":"学生","reading":"がくせい","meaning_vi":"học sinh; sinh viên"},{"expression":"始まる","reading":"はじまる","meaning_vi":"bắt đầu"}]', 157, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-R-INFO-009', 'N5-R-INFO', 'N5', 'READING', 9, '【みなみスポーツ教室のお知らせ（1か月のお金）】\n・テニス教室：毎週土曜日 午前9時〜午前11時（4,000円）\n・水泳教室：毎週水曜日 午後7時〜午後8時30分（3,500円）\n・ダンス教室：毎週金曜日 午後6時30分〜午後8時（3,000円）\n※一人で2つの教室に入る人は、1か月のお金が全部で500円安くなります。', '[Thông báo Lớp thể thao Minami (Học phí 1 tháng)]\n・Lớp quần vợt: Thứ Bảy hằng tuần 9:00 sáng ~ 11:00 sáng (4.000 yên)\n・Lớp bơi lội: Thứ Tư hằng tuần 7:00 tối ~ 8:30 tối (3.500 yên)\n・Lớp khiêu vũ: Thứ Sáu hằng tuần 6:30 tối ~ 8:00 tối (3.000 yên)\n*Người đăng ký học 2 lớp cùng lúc sẽ được giảm 500 yên trên tổng học phí 1 tháng.', NULL, NULL, NULL, '[{"expression":"水泳","reading":"すいえい","meaning_vi":"môn bơi; việc bơi lội"},{"expression":"毎週","reading":"まいしゅう","meaning_vi":"mỗi tuần"},{"expression":"安い","reading":"やすい","meaning_vi":"rẻ"}]', 153, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-R-INFO-010', 'N5-R-INFO', 'N5', 'READING', 10, '【さくらホテル・部屋のお金（一日・一人）】\n・一人部屋（朝ごはんなし）：6,000円\n・一人部屋（朝ごはんつき）：7,000円\n・二人部屋（朝ごはんなし）：一人 5,000円\n・二人部屋（朝ごはんつき）：一人 6,000円\n※部屋へ入る時間は午後3時からです。次の日の午前10時までに部屋を出てください。', '[Khách sạn Sakura - Giá phòng nghỉ (1 ngày / 1 người)]\n・Phòng đơn (không ăn sáng): 6.000 yên\n・Phòng đơn (có ăn sáng): 7.000 yên\n・Phòng đôi (không ăn sáng): 5.000 yên/người\n・Phòng đôi (có ăn sáng): 6.000 yên/người\n*Giờ nhận phòng là từ 3 giờ chiều. Vui lòng trả phòng trước 10 giờ sáng ngày hôm sau.', NULL, NULL, NULL, '[{"expression":"ホテル","reading":"ほてる","meaning_vi":"khách sạn"},{"expression":"一人","reading":"ひとり","meaning_vi":"một người; một mình"},{"expression":"二人","reading":"ふたり","meaning_vi":"hai người"}]', 145, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-R-INFO-011', 'N5-R-INFO', 'N5', 'READING', 11, '【花山公園へ行くバスのお知らせ】\n花山駅の東口から大きい公園へ行くバスが出ています。\n・1番のりば：公園の北門へ行くバス（月曜日〜日曜日・午前9時〜午後4時・15分ごと）\n・2番のりば：公園の南門へ行くバス（土曜日と日曜日だけ・午前9時〜午後3時・30分ごと）\nバスのお金：大人 220円、子ども 110円', '[Thông báo xe buýt đi Công viên Hanayama]\nTừ cửa Đông ga Hanayama có xe buýt đi công viên lớn.\n・Bến số 1: Xe buýt đi cổng Bắc công viên (Thứ Hai ~ Chủ nhật, 9:00 sáng ~ 4:00 chiều, 15 phút/chuyến)\n・Bến số 2: Xe buýt đi cổng Nam công viên (chỉ chạy Thứ Bảy và Chủ nhật, 9:00 sáng ~ 3:00 chiều, 30 phút/chuyến)\nGiá vé xe buýt: Người lớn 220 yên, Trẻ em 110 yên', NULL, NULL, NULL, '[{"expression":"東","reading":"ひがし","meaning_vi":"hướng đông; phía đông"},{"expression":"北","reading":"きた","meaning_vi":"bắc"},{"expression":"南","reading":"みなみ","meaning_vi":"nam; phía nam"}]', 147, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-R-INFO-012', 'N5-R-INFO', 'N5', 'READING', 12, '【パン屋「アンデル」・今週のやすいパンのお知らせ】\n店の時間：午前7時30分〜午後7時00分（毎週水曜日は店が休みです）\n・月曜日・火曜日：白いパンがいつもより 50円安くなります。\n・木曜日・金曜日：果物のパンがいつもより 30円安くなります。\n・土曜日・日曜日：午後5時から、店にあるパンが全部 40円安くなります。', '[Tiệm bánh mì "Anderu" - Thông báo bánh mì giảm giá tuần này]\nGiờ mở cửa: 7:30 sáng ~ 7:00 tối (Cửa hàng nghỉ Thứ Tư hằng tuần)\n・Thứ Hai, Thứ Ba: Bánh mì trắng giảm 50 yên so với mọi khi.\n・Thứ Năm, Thứ Sáu: Bánh mì hoa quả giảm 30 yên so với mọi khi.\n・Thứ Bảy, Chủ nhật: Từ 5 giờ chiều, toàn bộ bánh mì trong tiệm giảm 40 yên.', NULL, NULL, NULL, '[{"expression":"パン屋","reading":"パンや","meaning_vi":"cửa hàng bán bánh mì"},{"expression":"今週","reading":"こんしゅう","meaning_vi":"tuần này"},{"expression":"時間","reading":"じかん","meaning_vi":"thời gian"}]', 153, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-R-INFO-013', 'N5-R-INFO', 'N5', 'READING', 13, '【学生アパート「ひまわり」・掃除の日のお知らせ】\n・1階の部屋の人：毎週火曜日の夜8時〜9時（台所と広い食堂）\n・2階の部屋の人：毎週木曜日の夜8時〜9時（一階のドアの前と階段）\n・3階の部屋の人：毎週土曜日の朝9時〜10時（外の庭とゴミを出す所）\n※掃除の日に来ることができない人は、前の日までに先生に言ってください。', '[Căn hộ sinh viên "Himawari" - Thông báo ngày trực nhật dọn vệ sinh]\n・Người ở phòng tầng 1: Tối thứ Ba hằng tuần 8:00 ~ 9:00 (nhà bếp và nhà ăn rộng)\n・Người ở phòng tầng 2: Tối thứ Năm hằng tuần 8:00 ~ 9:00 (trước cửa tầng 1 và cầu thang)\n・Người ở phòng tầng 3: Sáng thứ Bảy hằng tuần 9:00 ~ 10:00 (sân vườn bên ngoài và nơi để rác)\n*Người không thể tham gia vào ngày trực nhật vui lòng báo cho thầy giáo muộn nhất là hôm trước đó.', NULL, NULL, NULL, '[{"expression":"食堂","reading":"しょくどう","meaning_vi":"nhà ăn; căn tin"},{"expression":"階段","reading":"かいだん","meaning_vi":"cầu thang bộ; cầu thang"},{"expression":"掃除","reading":"そうじ","meaning_vi":"việc dọn dẹp; dọn dẹp; dọn vệ sinh"}]', 156, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-R-INFO-014', 'N5-R-INFO', 'N5', 'READING', 14, '【山川カメラ店・写真のお金と時間】\n・小さい写真（1枚）：30円（20枚から上は、1枚 25円になります）\n・大きい写真（1枚）：100円\n写真ができる時間：\n・1枚〜20枚まで：30分ぐらいかかります。\n・21枚から上：1時間ぐらいかかります。\n※カメラ店の休みは毎週火曜日です。午前9時から午後7時まであいています。', '[Tiệm máy ảnh Yamakawa - Bảng giá và thời gian in ảnh]\n・Ảnh cỡ nhỏ (1 tấm): 30 yên (từ 20 tấm trở lên giá 25 yên/tấm)\n・Ảnh cỡ lớn (1 tấm): 100 yên\nThời gian làm xong ảnh:\n・Từ 1 đến 20 tấm: mất khoảng 30 phút.\n・Từ 21 tấm trở lên: mất khoảng 1 tiếng.\n*Tiệm máy ảnh nghỉ Thứ Ba hằng tuần. Mở cửa từ 9 giờ sáng đến 7 giờ tối.', NULL, NULL, NULL, '[{"expression":"写真","reading":"しゃしん","meaning_vi":"tấm ảnh; ảnh chụp; ảnh"},{"expression":"大きい","reading":"おおきい","meaning_vi":"to; lớn"},{"expression":"店","reading":"みせ","meaning_vi":"cửa hàng; quán"}]', 153, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-R-INFO-015', 'N5-R-INFO', 'N5', 'READING', 15, '【町の日本語クラスのお知らせ】\n・朝のクラス（毎週火曜日・木曜日）：午前10時〜午前11時30分（3階の301教室）\n・夜のクラス（毎週水曜日・金曜日）：午後6時30分〜午後8時（2階の204教室）\n・土曜日のクラス（毎週土曜日）：午後1時30分〜午後3時（4階の402教室）\nお金：どのクラスも 1か月 1,000円（本のお金がほかに 1,500円いります）', '[Thông báo Lớp tiếng Nhật của thị trấn]\n・Lớp buổi sáng (Thứ Ba, Thứ Năm hằng tuần): 10:00 ~ 11:30 sáng (Phòng 301 tầng 3)\n・Lớp buổi tối (Thứ Tư, Thứ Sáu hằng tuần): 6:30 ~ 8:00 tối (Phòng 204 tầng 2)\n・Lớp thứ Bảy (Thứ Bảy hằng tuần): 1:30 ~ 3:00 chiều (Phòng 402 tầng 4)\nHọc phí: Lớp nào cũng 1.000 yên/tháng (cần thêm 1.500 yên tiền sách)', NULL, NULL, NULL, '[{"expression":"教室","reading":"きょうしつ","meaning_vi":"phòng học; lớp học"},{"expression":"夜","reading":"よる","meaning_vi":"buổi tối"},{"expression":"本","reading":"ほん","meaning_vi":"sách; quyển sách"}]', 173, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-R-INFO-016', 'N5-R-INFO', 'N5', 'READING', 16, '【みどり公園・貸し自転車のお知らせ】\n自転車を借りる時間：午前9時00分〜午後4時30分\nお金（1台・2時間まで）：\n・大人の自転車：300円\n・子どもの自転車：150円\n・電気の自転車（大人だけ）：600円\n※雨がふる日と、かぜがとても強い日は自転車を借りることができません。公園の事務所で聞いてください。', '[Công viên Midori - Thông báo cho thuê xe đạp]\nGiờ mượn xe đạp: 9:00 sáng ~ 4:30 chiều\nGiá thuê (1 chiếc / tối đa 2 tiếng):\n・Xe đạp người lớn: 300 yên\n・Xe đạp trẻ em: 150 yên\n・Xe đạp điện (chỉ dành cho người lớn): 600 yên\n*Không thể mượn xe đạp vào ngày trời mưa và ngày gió rất to. Vui lòng hỏi tại văn phòng công viên.', NULL, NULL, NULL, '[{"expression":"雨","reading":"あめ","meaning_vi":"mưa"},{"expression":"強い","reading":"つよい","meaning_vi":"mạnh; khỏe"},{"expression":"自転車","reading":"じてんしゃ","meaning_vi":"xe đạp"}]', 148, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-R-INFO-017', 'N5-R-INFO', 'N5', 'READING', 17, '【喫茶店「モカ」・朝のセット（午前7時〜午前10時30分）】\n・Aセット（温かいパン・卵・飲み物1つ）：450円\n・Bセット（野菜のサンドイッチ・おいしい果物・飲み物1つ）：550円\n飲み物：コーヒー、温かいお茶、オレンジジュース、冷たい牛乳のなかから1つえらんでください。\n※午前10時30分からは昼のごはんのメニューになります。', '[Quán cà phê "Moka" - Set ăn sáng (7:00 sáng ~ 10:30 sáng)]\n・Set A (bánh mì ấm, trứng, 1 đồ uống): 450 yên\n・Set B (bánh mì kẹp rau, hoa quả ngon, 1 đồ uống): 550 yên\nĐồ uống: Vui lòng chọn 1 món trong cà phê, trà ấm, nước cam, sữa bò lạnh.\n*Từ 10:30 sáng chuyển sang thực đơn bữa trưa.', NULL, NULL, NULL, '[{"expression":"朝","reading":"あさ","meaning_vi":"buổi sáng"},{"expression":"牛乳","reading":"ぎゅうにゅう","meaning_vi":"sữa bò; sữa"},{"expression":"飲む","reading":"のむ","meaning_vi":"uống"}]', 162, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-R-INFO-018', 'N5-R-INFO', 'N5', 'READING', 18, '【さくら郵便局・窓口の時間】\n・切手やはがきを買う窓口：月曜日〜金曜日 午前9時〜午後5時\n・荷物を送る窓口：月曜日〜金曜日 午前9時〜午後7時、土曜日 午前9時〜午後3時\n郵便局の休み：毎週日曜日\n※郵便局のなかで銀行のカードを使ってお金を出す所は、毎日午前8時から午後9時まであいています。', '[Bưu điện Sakura - Giờ mở quầy]\n・Quầy mua tem và bưu thiếp: Thứ Hai ~ Thứ Sáu 9:00 sáng ~ 5:00 chiều\n・Quầy gửi bưu kiện: Thứ Hai ~ Thứ Sáu 9:00 sáng ~ 7:00 tối, Thứ Bảy 9:00 sáng ~ 3:00 chiều\nNgày nghỉ của bưu điện: Chủ nhật hằng tuần\n*Nơi dùng thẻ ngân hàng rút tiền bên trong bưu điện mở cửa mỗi ngày từ 8:00 sáng đến 9:00 tối.', NULL, NULL, NULL, '[{"expression":"切手","reading":"きって","meaning_vi":"tem thư"},{"expression":"はがき","reading":"はがき","meaning_vi":"bưu thiếp"},{"expression":"送る","reading":"おくる","meaning_vi":"gửi; tiễn; tặng (quà)"}]', 140, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-R-INFO-019', 'N5-R-INFO', 'N5', 'READING', 19, '【秋の音楽会のお知らせ】\n日にち：11月23日（日曜日）\n音楽会の所：さくら会館（さくら駅の南口から歩いて3分）\n時間：午後1時30分に大きいドアがあきます。午後2時00分に音楽が始まります。\nチケットのお金：大人 2,000円、学生 1,000円\n※会館の部屋のなかで食べ物を食べたり、カメラで写真をとったりしないでください。', '[Thông báo Buổi hòa nhạc mùa thu]\nNgày: Ngày 23 tháng 11 (Chủ nhật)\nĐịa điểm hòa nhạc: Hội quán Sakura (đi bộ 3 phút từ cửa Nam ga Sakura)\nThời gian: 1:30 chiều mở cửa lớn. 2:00 chiều âm nhạc bắt đầu.\nGiá vé: Người lớn 2.000 yên, Học sinh/Sinh viên 1.000 yên\n*Vui lòng không ăn đồ ăn hay chụp ảnh bằng máy ảnh bên trong phòng hội quán.', NULL, NULL, NULL, '[{"expression":"歩く","reading":"あるく","meaning_vi":"đi bộ"},{"expression":"音楽","reading":"おんがく","meaning_vi":"âm nhạc"},{"expression":"食べ物","reading":"たべもの","meaning_vi":"đồ ăn"}]', 157, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-R-INFO-020', 'N5-R-INFO', 'N5', 'READING', 20, '【みどりアパート・ゴミを出す日と時間】\n・台所のゴミや紙のゴミ：毎週火曜日と金曜日の朝8時00分まで\n・ペットボトルや古い新聞：毎週水曜日の朝8時00分まで\n・飲み物のびんやかん：毎週木曜日の朝8時00分まで\n※ゴミは前の日の夜に出さないでください。ゴミの日の朝6時から朝8時までの間に、一階の外へ出してください。', '[Căn hộ Midori - Ngày và giờ đổ rác]\n・Rác nhà bếp và rác giấy: Trước 8:00 sáng Thứ Ba và Thứ Sáu hằng tuần\n・Chai nhựa PET và báo cũ: Trước 8:00 sáng Thứ Tư hằng tuần\n・Chai lọ thủy tinh và lon đồ uống: Trước 8:00 sáng Thứ Năm hằng tuần\n*Vui lòng không mang rác ra từ tối hôm trước. Hãy mang ra bên ngoài tầng 1 trong khoảng từ 6 giờ sáng đến 8 giờ sáng đúng ngày đổ rác.', NULL, NULL, NULL, '[{"expression":"紙","reading":"かみ","meaning_vi":"giấy; tờ giấy"},{"expression":"金曜日","reading":"きんようび","meaning_vi":"thứ sáu"},{"expression":"出す","reading":"だす","meaning_vi":"gửi (thư); nộp; đưa ra"}]', 153, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-R-INFO-021', 'N5-R-INFO', 'N5', 'READING', 21, '【学校の食堂】月曜日から金曜日まで、昼ごはんは午前11時30分から午後2時までです。月・水・金曜日はカレーが500円、火・木曜日は魚とごはんが550円です。毎日、うどんは400円です。飲み物はどれも100円です。午後1時30分をすぎると、カレーと魚は買うことができません。食堂は土曜日と日曜日は休みです。', '【Nhà ăn trường học】Từ thứ Hai đến thứ Sáu, bữa trưa phục vụ từ 11:30 đến 14:00. Thứ Hai, Tư, Sáu có cà ri giá 500 yên; thứ Ba, Năm có cá và cơm giá 550 yên. Mỗi ngày đều có udon giá 400 yên. Đồ uống đồng giá 100 yên. Sau 13:30 không thể mua cà ri và cá. Nhà ăn nghỉ thứ Bảy và Chủ nhật.', NULL, NULL, NULL, '[]', 152, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-R-INFO-022', 'N5-R-INFO', 'N5', 'READING', 22, '【テニスのコート】公園のコートは火曜日から日曜日まで使えます。午前9時から午後12時までは1時間600円、午後1時から午後5時までは1時間800円です。月曜日は休みです。水は一本200円で買うことができます。雨の日はコートを使うことができません。お金はコートの前の小さい店ではらってください。', '【Sân quần vợt】Có thể dùng sân trong công viên từ thứ Ba đến Chủ nhật. Từ 9:00 đến 12:00 giá 600 yên mỗi giờ, từ 13:00 đến 17:00 giá 800 yên mỗi giờ. Thứ Hai nghỉ. Có thể mua một chai nước giá 200 yên. Ngày mưa không thể dùng sân. Hãy trả tiền tại cửa hàng nhỏ trước sân.', NULL, NULL, NULL, '[]', 146, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-R-INFO-023', 'N5-R-INFO', 'N5', 'READING', 23, '【川のふね】駅の近くの川から、公園までふねで行くことができます。火曜日から金曜日は午前10時と午後2時、土曜日と日曜日は午前10時、午後1時、午後4時に出ます。月曜日はふねが出ません。大人は一人700円、子どもは一人300円です。雨の日はふねが出ません。ふねに乗る人は、出る15分前までに来てください。', '【Thuyền trên sông】Có thể đi thuyền từ con sông gần ga đến công viên. Thứ Ba đến thứ Sáu thuyền chạy lúc 10:00 và 14:00; thứ Bảy, Chủ nhật chạy lúc 10:00, 13:00, 16:00. Thứ Hai nghỉ. Người lớn 700 yên, trẻ em 300 yên. Ngày mưa thuyền không chạy. Người đi thuyền hãy đến trước giờ xuất phát 15 phút.', NULL, NULL, NULL, '[]', 151, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-R-INFO-024', 'N5-R-INFO', 'N5', 'READING', 24, '【町のプール】プールは水曜日から日曜日まで、午前9時から午後6時までです。月曜日と火曜日は休みです。大人は一回500円、小学生は一回200円です。午前9時から午前11時までは小さい子どもも入ることができます。午後4時から午後6時までは小学生は大人と一緒に来てください。タオルは自分で持って来てください。', '【Hồ bơi thị trấn】Hồ bơi mở từ thứ Tư đến Chủ nhật, 9:00–18:00. Thứ Hai và Ba nghỉ. Người lớn 500 yên một lần, học sinh tiểu học 200 yên một lần. Từ 9:00 đến 11:00 trẻ nhỏ cũng có thể vào. Từ 16:00 đến 18:00 học sinh tiểu học hãy đến cùng người lớn. Hãy tự mang khăn.', NULL, NULL, NULL, '[]', 151, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-R-INFO-025', 'N5-R-INFO', 'N5', 'READING', 25, '【花の店】月曜日から土曜日まで、午前10時から午後7時まであいています。あかい花は一本150円、白い花は一本100円です。花を五本買う人には、小さいカードを一枚あげます。カードに名前を書くことができます。日曜日は店が休みです。午後6時30分をすぎると、花を家まで持って行くことはできません。店で買うことはできます。', '【Cửa hàng hoa】Mở từ thứ Hai đến thứ Bảy, 10:00–19:00. Hoa đỏ 150 yên một cành, hoa trắng 100 yên một cành. Người mua năm cành hoa được tặng một tấm thiệp nhỏ. Có thể viết tên lên thiệp. Chủ nhật cửa hàng nghỉ. Sau 18:30 không thể nhờ mang hoa đến nhà, nhưng vẫn có thể mua tại cửa hàng.', NULL, NULL, NULL, '[]', 157, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-R-INFO-026', 'N5-R-INFO', 'N5', 'READING', 26, '【学校のパソコンのへや】月・水・金曜日は午前8時から午後5時まで、火・木曜日は午前8時から午後7時まで使うことができます。土曜日は午前10時から午後2時までです。日曜日は休みです。一人で一日2時間まで使えます。へやの中では食べないでください。飲まないでください。使う前に、先生に学生のカードを見せてください。', '【Phòng máy tính của trường】Thứ Hai, Tư, Sáu dùng được từ 8:00 đến 17:00; thứ Ba, Năm từ 8:00 đến 19:00. Thứ Bảy từ 10:00 đến 14:00. Chủ nhật nghỉ. Mỗi người dùng tối đa hai giờ mỗi ngày. Đừng ăn trong phòng. Đừng uống trong phòng. Trước khi dùng hãy cho giáo viên xem thẻ học sinh.', NULL, NULL, NULL, '[]', 154, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-R-INFO-027', 'N5-R-INFO', 'N5', 'READING', 27, '【くだものをとる日】日曜日に山の近くの庭で、りんごをとることができます。午前9時から午後12時までです。大人は一人1200円、子どもは一人600円です。とったりんごを家に持って帰る人は、一つ200円はらいます。庭では水を買うことができません。水とぼうしを持って来てください。雨の日はありません。', '【Ngày hái trái cây】Chủ nhật có thể hái táo ở khu vườn gần núi, từ 9:00 đến 12:00. Người lớn 1200 yên, trẻ em 600 yên. Ai mang táo đã hái về nhà trả thêm 200 yên cho mỗi quả. Không thể mua nước ở khu vườn. Hãy mang nước và mũ. Ngày mưa hoạt động không diễn ra.', NULL, NULL, NULL, '[]', 147, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-R-INFO-028', 'N5-R-INFO', 'N5', 'READING', 28, '【くつの店】くつをなおす人は、店の一階へ来てください。月曜日から金曜日は午前10時から午後6時まで、土曜日は午前10時から午後3時までです。日曜日にはくつをなおしません。くつをなおすお金は500円です。朝にくつを持って来てください。午後5時にできます。土曜日に持って来たくつは、月曜日にできます。二階では新しいくつを買えます。', '【Cửa hàng giày】Người cần sửa giày hãy đến tầng một. Thứ Hai đến thứ Sáu mở 10:00–18:00, thứ Bảy 10:00–15:00. Chủ nhật nghỉ. Sửa giày giá 500 yên. Hãy mang giày đến vào buổi sáng. Giày sẽ xong lúc 17:00. Giày mang đến vào thứ Bảy sẽ xong thứ Hai. Tầng hai bán giày mới.', NULL, NULL, NULL, '[]', 163, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-R-INFO-029', 'N5-R-INFO', 'N5', 'READING', 29, '【町の店】月曜日と木曜日はみかんが一つ200円、火曜日と金曜日はバナナが三本で150円です。水曜日と土曜日はりんごが五つで300円です。毎日、トマトは一つ100円です。店は午前9時から午後6時まで、日曜日は休みです。午後5時からは、その日のものを50円安く買えます。トマトのお金はかわりません。', '【Cửa hàng trong thị trấn】Thứ Hai và Năm quýt giá 200 yên một cái; thứ Ba và Sáu chuối giá 150 yên ba củ; thứ Tư và Bảy táo giá 300 yên năm củ. Mỗi ngày cà chua giá 100 yên một quả. Cửa hàng mở 9:00–18:00, Chủ nhật nghỉ. Từ 17:00, mặt hàng của ngày hôm đó rẻ hơn 50 yên. Giá cà chua không đổi.', NULL, NULL, NULL, '[]', 147, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-R-INFO-030', 'N5-R-INFO', 'N5', 'READING', 30, '【ふくをあらう店】店は毎日、午前7時から午後10時まであいています。シャツを一枚あらうお金は300円、ズボンは一枚500円です。ふくを店に持って来る人は、午後9時30分までに来てください。午後9時30分からは新しいふくをあらうことができません。あらったふくをとりに来る人は午後10時までに来てください。日曜日も同じ時間です。', '【Tiệm giặt quần áo】Tiệm mở mỗi ngày từ 7:00 đến 22:00. Giặt một chiếc áo sơ mi giá 300 yên, một chiếc quần giá 500 yên. Người mang quần áo đến giặt hãy đến trước 21:30. Từ 21:30 không thể nhận giặt thêm đồ mới. Người đến lấy đồ đã giặt hãy đến trước 22:00. Chủ nhật cũng cùng giờ.', NULL, NULL, NULL, '[]', 162, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-R-INFO-031', 'N5-R-INFO', 'N5', 'READING', 31, '【自転車をとめる所】駅の前に自転車をとめる所が二つあります。北の所は午前6時から午後8時まで、1日100円です。南の所は毎日いつでも使えて、1日200円です。北の所は日曜日に休みます。南の所には自転車だけでなく、バイクもとめられます。バイクは1日400円です。お金は出るときに、入り口ではらってください。', '【Chỗ để xe đạp】Trước ga có hai chỗ để xe đạp. Bãi phía bắc mở 6:00–20:00, 100 yên một ngày. Bãi phía nam dùng được mọi lúc, 200 yên một ngày. Bãi phía bắc nghỉ Chủ nhật. Bãi phía nam nhận cả xe đạp và xe máy. Xe máy giá 400 yên một ngày. Trả tiền ở lối vào khi ra về.', NULL, NULL, NULL, '[]', 152, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-R-INFO-032', 'N5-R-INFO', 'N5', 'READING', 32, '【子どものへや】町の子どものへやは、火曜日から土曜日まで午前9時から午後5時までです。日曜日は午前10時から午後3時までです。月曜日は休みます。三歳より小さい子どもは、午前中だけ入ることができます。小学生は午後も入れます。小さい子どもは大人と一緒に来てください。へやの中では、くつをぬいでください。お金はいりません。', '【Phòng trẻ em】Phòng trẻ em của thị trấn mở thứ Ba đến thứ Bảy từ 9:00 đến 17:00. Chủ nhật mở 10:00–15:00. Thứ Hai nghỉ. Trẻ dưới ba tuổi chỉ có thể vào buổi sáng. Học sinh tiểu học cũng có thể vào buổi chiều. Trẻ nhỏ hãy đến cùng người lớn. Hãy cởi giày trong phòng. Không mất tiền.', NULL, NULL, NULL, '[]', 158, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-R-INFO-033', 'N5-R-INFO', 'N5', 'READING', 33, '【駅のかばんのはこ】駅の一階には小さいはこ、二階には大きいはこがあります。かばんを入れることができます。小さいはこは一日300円、大きいはこは一日500円です。大きいかばんは小さいはこには入りません。はこは毎日午前5時から午後11時まで使えます。午後11時までにかばんを出してください。お金を100円ずつ入れてください。', '【Hộp giữ túi ở ga】Tầng một của ga có hộp nhỏ, tầng hai có hộp lớn để gửi túi. Hộp nhỏ giá 300 yên một ngày, hộp lớn 500 yên một ngày. Túi lớn không vừa hộp nhỏ. Có thể dùng hộp mỗi ngày từ 5:00 đến 23:00. Hãy lấy túi ra trước 23:00. Hãy dùng đồng 100 yên để trả tiền.', NULL, NULL, NULL, '[]', 160, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-R-INFO-034', 'N5-R-INFO', 'N5', 'READING', 34, '【犬とねこの店】店は火曜日から日曜日まで、午前9時から午後5時までです。犬にごはんをあげる時間は午前10時と午後3時、ねこは午前11時と午後2時です。店の犬とねこを見ることができますが、自分でごはんをあげないでください。午後1時から午後2時まで、犬のへやはそうじをします。月曜日には店に入れません。店に入るお金はいりません。', '【Cửa hàng chó mèo】Cửa hàng mở từ thứ Ba đến Chủ nhật, 9:00–17:00. Chó được cho ăn lúc 10:00 và 15:00, mèo lúc 11:00 và 14:00. Có thể xem chó mèo trong cửa hàng, nhưng đừng tự cho chúng ăn. Từ 13:00 đến 14:00 phòng chó được dọn dẹp. Thứ Hai không thể vào cửa hàng. Vào cửa không mất tiền.', NULL, NULL, NULL, '[]', 162, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-R-INFO-035', 'N5-R-INFO', 'N5', 'READING', 35, '【町の本の店】今週の土曜日、本の店で古い本をうります。午前10時から午後4時までです。小さい本は一冊100円、大きい本は一冊300円です。三冊買う人は、全部で50円安くなります。ノートは一冊200円ですが、ノートは三冊の本の中には入りません。日曜日は古い本をうりません。新しい本は毎日買うことができます。', '【Hiệu sách thị trấn】Thứ Bảy tuần này, hiệu sách bán sách cũ từ 10:00 đến 16:00. Sách nhỏ 100 yên một cuốn, sách lớn 300 yên một cuốn. Người mua ba cuốn sách được giảm 50 yên trên tổng tiền. Vở giá 200 yên một cuốn nhưng không được tính trong ba cuốn sách. Chủ nhật không bán sách cũ. Sách mới có thể mua mỗi ngày.', NULL, NULL, NULL, '[]', 152, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-R-INFO-036', 'N5-R-INFO', 'N5', 'READING', 36, '【アパートのおゆ】来週の火曜日、アパートの一階と二階では、午前9時から午前11時までおゆが出ません。三階と四階では、午後1時から午後3時までおゆが出ません。水はどのへやでも一日中使えます。おふろを使う人は、この時間を見てください。月曜日と水曜日はいつもと同じです。わからない人は、一階の小さいへやに来てください。', '【Nước nóng trong chung cư】Thứ Ba tuần sau, tầng một và hai không có nước nóng từ 9:00 đến 11:00. Tầng ba và bốn không có nước nóng từ 13:00 đến 15:00. Nước lạnh dùng được cả ngày ở mọi phòng. Ai muốn tắm hãy chú ý thời gian này. Thứ Hai và Tư vẫn như thường lệ. Ai chưa rõ hãy đến phòng nhỏ ở tầng một.', NULL, NULL, NULL, '[]', 156, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-R-INFO-037', 'N5-R-INFO', 'N5', 'READING', 37, '【朝のパンの店】朝のパンは毎日午前6時から午前10時まで買うことができます。パンは一つ250円、サンドイッチは一つ350円、卵のパンは一つ200円です。午前8時までに二つ買う人には、牛乳を一つ100円でうります。午前8時をすぎると牛乳は150円です。日曜日だけは午前9時で店がしまります。あたたかいお茶は毎日100円です。', '【Tiệm bánh buổi sáng】Bánh sáng bán mỗi ngày từ 6:00 đến 10:00. Bánh mì 250 yên một chiếc, sandwich 350 yên, bánh nhân trứng 200 yên. Người mua hai chiếc trước 8:00 có thể mua sữa với giá 100 yên. Sau 8:00 sữa giá 150 yên. Riêng Chủ nhật cửa hàng đóng lúc 9:00. Trà nóng giá 100 yên mỗi ngày.', NULL, NULL, NULL, '[]', 161, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-R-INFO-038', 'N5-R-INFO', 'N5', 'READING', 38, '【町のダンスの会】ダンスの会は木曜日の午後6時から午後7時まで、土曜日の午前10時から午前11時までです。木曜日は学校の二階、土曜日は公園の近くの大きいへやでします。大人は一回300円、学生は一回100円です。はじめて来る人も同じお金です。木曜日はくつを持って来てください。土曜日は水を持って来てください。', '【Buổi khiêu vũ của thị trấn】Buổi khiêu vũ diễn ra thứ Năm 18:00–19:00 và thứ Bảy 10:00–11:00. Thứ Năm ở tầng hai của trường, thứ Bảy ở phòng lớn gần công viên. Người lớn 300 yên một buổi, học sinh 100 yên một buổi. Người đến lần đầu trả cùng mức giá. Thứ Năm hãy mang giày; thứ Bảy hãy mang nước.', NULL, NULL, NULL, '[]', 153, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-R-INFO-039', 'N5-R-INFO', 'N5', 'READING', 39, '【学校のそうじ】今週の金曜日、学校をそうじします。一階の学生は午前9時から午前10時まで教室をそうじします。二階の学生は午前10時から午前11時までろうかをそうじします。三階の学生は午前11時から午後12時までまどをそうじします。そうじに使うものは学校にあります。そうじのあとに手をあらってください。金曜日は授業がありません。', '【Dọn vệ sinh trường học】Thứ Sáu tuần này sẽ dọn trường. Học sinh tầng một dọn lớp từ 9:00 đến 10:00. Học sinh tầng hai dọn hành lang từ 10:00 đến 11:00. Học sinh tầng ba lau cửa sổ từ 11:00 đến 12:00. Trường có sẵn dụng cụ dọn dẹp. Hãy rửa tay sau khi dọn. Thứ Sáu không có giờ học.', NULL, NULL, NULL, '[]', 163, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-R-INFO-040', 'N5-R-INFO', 'N5', 'READING', 40, '【町のバスのカード】バスに乗る人は、店でカードを買うことができます。大人のカードは1000円で、バスに五回乗れます。子どものカードは500円で、五回乗れます。カードは月曜日から土曜日まで、午前9時から午後6時まで買えます。店では日曜日にカードを買えません。カードを持っていない人は、バスの中で一回250円はらってください。カードは家族で一緒に使えません。', '【Thẻ xe buýt thị trấn】Người đi xe buýt có thể mua thẻ tại cửa hàng. Thẻ người lớn giá 1000 yên dùng được năm lượt, thẻ trẻ em giá 500 yên dùng được năm lượt. Có thể mua thẻ từ thứ Hai đến thứ Bảy, 9:00–18:00. Chủ nhật không thể mua thẻ ở cửa hàng. Người không có thẻ trả 250 yên một lượt trên xe. Các thành viên gia đình không được dùng chung một thẻ.', NULL, NULL, NULL, '[]', 177, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-R-INFO-041', 'N5-R-INFO', 'N5', 'READING', 41, '【さくらプールのお知らせ】あいている時間は火曜日から金曜日まで午前10時から午後8時までです。土曜日と日曜日は午前9時から午後6時までです。毎週月曜日に休みます。。おとなは一回500円、学生は一回300円です。小学生より小さい子どもはお金がいりません。水着とタオルを持って来てください。土曜日の午後2時から3時までは子どもの水泳の時間です。', '[Thông báo hồ bơi Sakura] Thứ Ba–Thứ Sáu mở 10:00–20:00; Thứ Bảy và Chủ nhật mở 9:00–18:00; Thứ Hai nghỉ. Người lớn 500 yên/lượt, học sinh 300 yên, trẻ nhỏ hơn học sinh tiểu học miễn phí. Mang đồ bơi và khăn. Thứ Bảy 14:00–15:00 là giờ bơi của trẻ em.', NULL, NULL, NULL, '[]', 170, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-R-INFO-042', 'N5-R-INFO', 'N5', 'READING', 42, '【山の町へ行く電車】駅を出る時間と町に着く時間、きっぷのお金を書きます。Aの電車は午前8時に出て、9時30分に着きます。お金は900円です。Bの電車は午前8時30分に出て、9時に着きます。お金は1,200円です。Cの電車は午前9時に出て、10時に着きます。お金は700円です。学生はどの電車も100円安くなります。', '[Tàu đến thị trấn trên núi] Tàu A đi 8:00, đến 9:30, vé 900 yên. Tàu B đi 8:30, đến 9:00, vé 1.200 yên. Tàu C đi 9:00, đến 10:00, vé 700 yên. Học sinh được giảm 100 yên trên mọi chuyến.', NULL, NULL, NULL, '[]', 157, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-R-INFO-043', 'N5-R-INFO', 'N5', 'READING', 43, '【まちの子ども公園】公園は毎日午前9時から午後5時まであいています。入るお金はいりません。大きいすべり台は6さいから12さいまでの子どもが使うことができます。小さい子どものへやは午前10時から午後3時までです。水曜日は公園のそうじをしますから、へやは使うことができません。食べ物はへやの中で食べないでください。', '[Công viên trẻ em của thành phố] Mở hằng ngày 9:00–17:00, miễn phí. Cầu trượt lớn dành cho trẻ 6–12 tuổi. Phòng trẻ nhỏ mở 10:00–15:00; thứ Tư đóng phòng để dọn vệ sinh. Không ăn trong phòng.', NULL, NULL, NULL, '[]', 155, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-R-INFO-044', 'N5-R-INFO', 'N5', 'READING', 44, '【ももや】月曜日から金曜日まで、店は午前9時から午後6時までです。土曜日は午前10時から午後4時までです。日曜日には店があいていません。りんごは一つ100円、みかんは一つ80円です。午後4時のあとで、りんごを5つ買うと、もう一つもらうことができます。みかんにはこのサービスがありません。店の前に小さい自転車をとめるばしょがあります。', '[Cửa hàng Momoya] Thứ Hai–Thứ Sáu mở 9:00–18:00, Thứ Bảy 10:00–16:00, Chủ nhật nghỉ. Táo 100 yên/quả, quýt 80 yên/quả. Sau 16:00, mua 5 táo được tặng thêm 1; quýt không có ưu đãi. Có chỗ để xe đạp nhỏ trước cửa.', NULL, NULL, NULL, '[]', 166, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-R-INFO-045', 'N5-R-INFO', 'N5', 'READING', 45, '【日本語学校の一日】学校の門は午前8時にあきます。午前9時から日本語のクラスが始まります。12時から1時まで昼ごはんです。午後1時から3時までは日本語の本を読みます。金曜日だけ、午後2時から音楽の時間があります。その日は本を読む時間が1時間です。学生は自分の昼ごはんを持って来てください。', '[Một ngày ở trường tiếng Nhật] Cổng trường mở lúc 8:00. Lớp tiếng Nhật bắt đầu 9:00. Ăn trưa từ 12:00 đến 13:00. Đọc sách tiếng Nhật từ 13:00 đến 15:00. Riêng thứ Sáu có giờ âm nhạc từ 14:00; hôm đó chỉ đọc sách một tiếng. Học sinh tự mang bữa trưa.', NULL, NULL, NULL, '[]', 144, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-R-INFO-046', 'N5-R-INFO', 'N5', 'READING', 46, '【小さなどうぶつ園】あいている時間は午前9時から午後4時30分までです。火曜日は休みです。おとなは600円、小学生は300円です。6さいより小さい子どもはむりょうです。土曜日は小学生もむりょうになります。どうぶつに食べ物をあげないでください。どうぶつの写真はとることができますが、フラッシュを使わないでください。入口で地図をもらうことができます。', '[Vườn thú nhỏ] Mở 9:00–16:30, nghỉ thứ Ba. Người lớn 600 yên, học sinh tiểu học 300 yên, trẻ dưới 6 tuổi miễn phí. Thứ Bảy học sinh tiểu học cũng được miễn phí. Không cho động vật ăn; được chụp ảnh nhưng không dùng đèn flash. Có thể lấy bản đồ ở cửa vào.', NULL, NULL, NULL, '[]', 173, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-R-INFO-047', 'N5-R-INFO', 'N5', 'READING', 47, '【町の映画館】映画は一日に三回あります。午前の映画は10時に始まり、11時40分に終わります。午後の一回めは1時に始まり、2時40分に終わります。午後の二回めは4時に始まり、5時40分に終わります。おとなのきっぷは1,500円、学生は1,000円です。水曜日は学生のきっぷが800円です。食べ物を映画のへやに持って入ることはできません。', '[Rạp phim thị trấn] Có ba suất mỗi ngày: 10:00–11:40, 13:00–14:40, 16:00–17:40. Vé người lớn 1.500 yên, học sinh 1.000 yên. Thứ Tư vé học sinh 800 yên. Không mang thức ăn vào phòng chiếu.', NULL, NULL, NULL, '[]', 168, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-R-INFO-048', 'N5-R-INFO', 'N5', 'READING', 48, '【まちの日本語クラス】クラスは毎週火曜日と木曜日の午後6時から7時30分までです。ばしょはまちの大きいへやです。お金は一か月2,000円です。学生は1,000円です。はじめて来る人は、名前と電話のばんごうを紙に書いてください。クラスの本は学校にありますから、買わなくてもいいです。今月は木曜日が休みです。来週の火曜日からクラスを始めます。', '[Lớp tiếng Nhật thành phố] Học thứ Ba và thứ Năm 18:00–19:30 tại phòng lớn của thành phố. Học phí tháng 2.000 yên, học sinh 1.000 yên. Người mới ghi tên và số điện thoại; sách có sẵn. Tháng này nghỉ thứ Năm, lớp bắt đầu lại từ thứ Ba tuần tới.', NULL, NULL, NULL, '[]', 169, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-R-INFO-049', 'N5-R-INFO', 'N5', 'READING', 49, '【カフェひなたの朝ごはん】朝のメニューは午前7時から11時までです。パンとたまごのセットは500円です。ごはんと魚のセットは650円です。コーヒーは一杯200円、お茶は一杯150円です。セットといっしょに飲み物を買うと、飲み物は100円になります。日曜日は朝のメニューがありません。店の中でたばこをすわないでください。子どものいすもあります。', '[Bữa sáng quán Hinata] Phục vụ 7:00–11:00. Set bánh mì và trứng 500 yên; set cơm và cá 650 yên. Cà phê 200 yên, trà 150 yên; mua kèm set thì đồ uống còn 100 yên. Chủ nhật không có thực đơn sáng. Có ghế trẻ em; không hút thuốc trong quán.', NULL, NULL, NULL, '[]', 171, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-R-INFO-050', 'N5-R-INFO', 'N5', 'READING', 50, '【ごみを出す日】この町では、月曜日と木曜日に生ごみを出します。火曜日は紙と本の日です。金曜日はびんとペットボトルの日です。ごみは朝8時までに家の前に出してください。夜に出してはいけません。大きいテーブルやいすを出す時は、先に町の人に電話をしてください。日曜日はごみを出すことができません。', '[Ngày đổ rác] Thứ Hai và thứ Năm đổ rác thức ăn; thứ Ba là giấy và sách; thứ Sáu là chai thủy tinh và chai nhựa. Đem rác ra trước nhà trước 8:00 sáng, không đem ra ban đêm. Muốn bỏ bàn/ghế lớn phải gọi trước cho cán bộ khu phố. Chủ nhật không đổ rác.', NULL, NULL, NULL, '[]', 144, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-R-INFO-051', 'N5-R-INFO', 'N5', 'READING', 51, '【さくらクリニック】月曜日から金曜日は午前9時から12時まで、午後2時から6時までです。土曜日は午前9時から午後1時までです。日曜日とやすみの日は休みです。水曜日の午後は先生がいません。はじめて来る人は、入口で名前と住所を書いてください。子どものへやは二階にあります。電話で時間を聞くこともできます。', '[Phòng khám Sakura] Thứ Hai–Thứ Sáu mở 9:00–12:00 và 14:00–18:00; thứ Bảy 9:00–13:00; Chủ nhật và ngày lễ nghỉ. Thứ Tư buổi chiều bác sĩ không có mặt. Người khám lần đầu ghi tên và địa chỉ ở cửa vào. Phòng trẻ em ở tầng hai; có thể gọi hỏi giờ.', NULL, NULL, NULL, '[]', 150, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-R-INFO-052', 'N5-R-INFO', 'N5', 'READING', 52, '【あおい店のばしょ】店は午前10時から午後7時までです。月曜日は店をしめます。一階にはくつと雨のかさがあります。二階にはシャツとズボンがあります。三階には本とノートとえんぴつがあります。四階はレストランです。エレベーターは店の右にあります。日曜日は人が多いですから、午前中に来てください。店の中で写真をとらないでください。', '[Các tầng cửa hàng Aoi] Mở 10:00–19:00, nghỉ thứ Hai. Tầng 1 bán giày và ô; tầng 2 áo và quần; tầng 3 sách, vở, bút chì; tầng 4 là nhà hàng. Thang máy bên phải cửa hàng. Chủ nhật đông khách nên hãy đến buổi sáng; không chụp ảnh trong cửa hàng.', NULL, NULL, NULL, '[]', 161, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-R-INFO-053', 'N5-R-INFO', 'N5', 'READING', 53, '【学校の山のバス】バスは6月12日土曜日に出ます。朝7時に学校の前に来てください。山の公園には9時に着きます。帰りのバスは午後4時に公園を出て、6時に学校に着きます。バスのお金は一人800円です。昼ごはんと水を持って来てください。雨の日もバスは出ます。お金は6月10日までに先生にわたしてください。', '[Xe buýt đi núi của trường] Khởi hành thứ Bảy 12/6. Có mặt trước trường lúc 7:00, đến công viên núi lúc 9:00. Xe về rời công viên 16:00 và đến trường 18:00. Vé 800 yên/người. Mang cơm trưa và nước. Xe vẫn chạy khi mưa; nộp tiền cho giáo viên trước 10/6.', NULL, NULL, NULL, '[]', 149, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-R-INFO-054', 'N5-R-INFO', 'N5', 'READING', 54, '【はな公園の花】公園は毎日午前8時から午後5時まであいています。入る時にお金をはらいません。花を見ることができる時間は午前9時から午後4時までです。土曜日の午前10時には花の話があります。日曜日の午後1時には子どもの絵の時間があります。公園の中で花をとらないでください。雨の日は花の話と絵の時間はありません。水は公園の入口で買うことができます。', '[Hoa ở công viên Hana] Công viên mở 8:00–17:00, miễn phí; thời gian ngắm hoa 9:00–16:00. Thứ Bảy 10:00 có buổi nói chuyện về hoa; Chủ nhật 13:00 có giờ vẽ cho trẻ. Không hái hoa. Nếu mưa, hai hoạt động không diễn ra. Có thể mua nước ở cổng.', NULL, NULL, NULL, '[]', 172, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-R-INFO-055', 'N5-R-INFO', 'N5', 'READING', 55, '【まちのせんたく店】店は火曜日から日曜日まで午前8時から午後7時までです。月曜日は店をやすみます。シャツをあらうお金は一枚300円です。ズボンは一枚500円です。朝10時までにふくを出すと、その日の午後6時にできあがります。10時のあとに出すと、次の日にできあがります。日曜日に出したふくは火曜日にできます。大きいふとんは店であらうことができません。', '[Tiệm giặt Machi] Mở thứ Ba–Chủ nhật 8:00–19:00, nghỉ thứ Hai. Giặt áo 300 yên, quần 500 yên. Gửi trước 10:00 thì nhận lúc 18:00 cùng ngày; gửi sau 10:00 nhận ngày hôm sau. Đồ gửi Chủ nhật nhận vào thứ Ba. Không giặt chăn lớn.', NULL, NULL, NULL, '[]', 175, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-R-INFO-056', 'N5-R-INFO', 'N5', 'READING', 56, '【子どもの水泳クラス】クラスは水曜日と土曜日にあります。水曜日は午後4時から5時まで、土曜日は午前10時から11時までです。5さいから10さいまでの子どもが入ることができます。一か月のお金は2,000円です。水着とタオルをわすれないでください。はじめての日は、クラスが始まる15分前に来てください。日曜日はクラスがありません。', '[Lớp bơi trẻ em] Học thứ Tư 16:00–17:00 và thứ Bảy 10:00–11:00, dành cho trẻ 5–10 tuổi. Học phí tháng 2.000 yên. Mang đồ bơi và khăn. Ngày đầu đến sớm 15 phút. Chủ nhật không có lớp.', NULL, NULL, NULL, '[]', 163, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-R-INFO-057', 'N5-R-INFO', 'N5', 'READING', 57, '【レストラン山】店は午前11時から午後8時までです。火曜日に店はあいていません。テーブルは電話でよやくすることができます。昼の魚のセットは900円、肉のセットは1,000円です。午後5時からは夜のメニューです。夜は魚のセットが1,100円、肉のセットが1,200円です。子どものいすは二つあります。よやくの時間に10分おくれる時は、店に電話してください。', '[Nhà hàng Yama] Mở 11:00–20:00, nghỉ thứ Ba. Có thể đặt bàn qua điện thoại. Set cá buổi trưa 900 yên, set thịt 1.000 yên. Sau 17:00 là thực đơn tối: set cá 1.100 yên, set thịt 1.200 yên. Có hai ghế trẻ em. Nếu đến trễ 10 phút so với giờ đặt, hãy gọi báo quán.', NULL, NULL, NULL, '[]', 177, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-R-INFO-058', 'N5-R-INFO', 'N5', 'READING', 58, '【まんなか郵便局】月曜日から金曜日は午前9時から午後5時までです。土曜日は午前9時から12時までです。日曜日としゅくじつは休みです。手紙を出すお金は日本の中なら110円、外国なら300円です。小さいはこを送る時は、はこの大きさでお金がかわります。手紙の紙とふうとうは入口の店で買うことができます。午後4時のあとに出した手紙は、次の日に行きます。', '[Bưu điện Chuo] Thứ Hai–Thứ Sáu mở 9:00–17:00; thứ Bảy 9:00–12:00; Chủ nhật và ngày lễ nghỉ. Gửi thư trong nước 110 yên, ra nước ngoài 300 yên. Phí gửi hộp nhỏ tùy kích thước. Có thể mua giấy và phong bì ở quầy cửa vào. Thư gửi sau 16:00 sẽ đi vào ngày hôm sau.', NULL, NULL, NULL, '[]', 172, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-R-INFO-059', 'N5-R-INFO', 'N5', 'READING', 59, '【町のことば図書館】あいている時間は月曜日から金曜日まで午前9時から午後6時までです。土曜日は午後4時までです。日曜日は図書館をあけません。本は一人で4さつまで、2週間借りることができます。シーディーは一人で2まいまで、一週間です。新しい本は図書館の中で読んでください。かえす日がおくれる時は、電話で話してください。', '[Thư viện Kotoba] Thứ Hai–Thứ Sáu mở 9:00–18:00; thứ Bảy đến 16:00; Chủ nhật nghỉ. Mỗi người được mượn tối đa 4 sách trong 2 tuần và 2 シーディー trong 1 tuần. Sách mới chỉ đọc tại thư viện. Nếu trả trễ, hãy gọi điện.', NULL, NULL, NULL, '[]', 158, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-R-INFO-060', 'N5-R-INFO', 'N5', 'READING', 60, '【さくらマンションのお知らせ】ごみを出す時間は朝7時から8時までです。月曜日と木曜日は生ごみ、火曜日は紙、金曜日はびんを出してください。水曜日はごみを出すことができません。自転車はたてものの後ろにとめてください。入口の前に自転車をおかないでください。日曜日の午前10時から12時まで、みんなでへやと入口をそうじします。', '[Thông báo chung cư Sakura] Giờ đổ rác 7:00–8:00 sáng. Thứ Hai và thứ Năm đổ rác thức ăn; thứ Ba giấy; thứ Sáu chai thủy tinh; thứ Tư không đổ rác. Để xe đạp phía sau tòa nhà, không để trước cửa vào. Chủ nhật 10:00–12:00 mọi người cùng dọn phòng và lối vào.', NULL, NULL, NULL, '[]', 159, 1, NULL, NULL, NULL, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-L-TASK-001', 'N5-L-TASK', 'N5', 'LISTENING', 1, NULL, NULL, '[{"speaker":"N","ja":"男の人は果物をいくつ買いますか。"},{"speaker":"F","ja":"あなた、帰りにスーパーでりんごを買ってきてください。"},{"speaker":"M","ja":"いいよ。りんごを三つ買うね。"},{"speaker":"F","ja":"あ、あした母が来ますから、五つお願いします。"},{"speaker":"M","ja":"わかった。五つだね。"},{"speaker":"F","ja":"みかんはまだありますから、買わないでね。"},{"speaker":"M","ja":"うん、りんごだけ買って帰るよ。"},{"speaker":"N","ja":"男の人は果物をいくつ買いますか。"}]', 'Người dẫn: Người đàn ông sẽ mua mấy quả?\nNữ: Anh ơi, lúc về anh ghé siêu thị mua táo về nhé.\nNam: Được chứ. Anh mua 3 quả táo nhé.\nNữ: À, ngày mai mẹ sẽ đến nên nhờ anh mua 5 quả nhé.\nNam: Anh hiểu rồi. 5 quả nhỉ.\nNữ: Vẫn còn quýt nên anh đừng mua nhé.\nNam: Ừ, anh chỉ mua táo rồi về.\nNgười dẫn: Người đàn ông sẽ mua mấy quả?', 'Bốn ô hình: (1) 5 quả táo; (2) 3 quả táo; (3) 3 quả quýt; (4) 5 quả quýt.', '[{"expression":"果物","reading":"くだもの","meaning_vi":"trái cây; hoa quả"},{"expression":"三つ","reading":"みっつ","meaning_vi":"ba cái"},{"expression":"五つ","reading":"いつつ","meaning_vi":"năm cái"}]', 139, 1, 'learning-path/N5/skills/N5-L-TASK-001.mp3', '788e8e719dc07988287a22ed834f62f4a7b4ecaf095a391650442b744b888272', 33, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-L-TASK-002', 'N5-L-TASK', 'N5', 'LISTENING', 2, NULL, NULL, '[{"speaker":"N","ja":"学生は机の上に何を出しますか。"},{"speaker":"F","ja":"みなさん、これからテストを始めます。机の上には鉛筆と消しゴムだけ出してください。"},{"speaker":"M","ja":"先生、辞書も出していいですか。"},{"speaker":"F","ja":"いいえ、きょうのテストでは辞書は使いません。かばんの中に入れてください。"},{"speaker":"M","ja":"本もかばんに入れますか。"},{"speaker":"F","ja":"ええ、机の上に本も置かないでください。"},{"speaker":"N","ja":"学生は机の上に何を出しますか。"}]', 'Người dẫn: Học sinh sẽ để thứ gì lên trên bàn?\nNữ: Các em, bây giờ chúng ta bắt đầu kiểm tra. Trên bàn chỉ để bút chì và cục tẩy thôi nhé.\nNam: Thưa cô, có được để từ điển ra không ạ?\nNữ: Không, bài kiểm tra hôm nay không dùng từ điển. Em hãy cất vào trong cặp nhé.\nNam: Sách cũng cất vào cặp ạ?\nNữ: Đúng. Cũng đừng để sách trên bàn.\nNgười dẫn: Học sinh sẽ để thứ gì lên trên bàn?', 'Bốn ô hình: (1) Sách và bút chì; (2) Chỉ bút chì và tẩy; (3) Bút chì, tẩy và từ điển; (4) Chỉ từ điển.', '[{"expression":"机","reading":"つくえ","meaning_vi":"bàn học; bàn làm việc"},{"expression":"鉛筆","reading":"えんぴつ","meaning_vi":"bút chì"},{"expression":"辞書","reading":"じしょ","meaning_vi":"từ điển; quyển từ điển"}]', 152, 1, 'learning-path/N5/skills/N5-L-TASK-002.mp3', '4dac3c1ae7ccb2baeeed98cd20ef9f1c1cade88a431c8391c3d78013caa98692', 35, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-L-TASK-003', 'N5-L-TASK', 'N5', 'LISTENING', 3, NULL, NULL, '[{"speaker":"N","ja":"二人はあした、どこで会いますか。"},{"speaker":"M","ja":"リンさん、あしたは駅の東口で会いましょうか。"},{"speaker":"F","ja":"東口は人が多くてわかりにくいですよ。西口はどうですか。"},{"speaker":"M","ja":"そうですね、じゃあ、西口の本屋の前で会いましょう。"},{"speaker":"F","ja":"はい、わかりました。"},{"speaker":"M","ja":"花屋の前ではありませんね。"},{"speaker":"F","ja":"ええ、本屋です。十時に会いましょう。"},{"speaker":"N","ja":"二人はあした、どこで会いますか。"}]', 'Người dẫn: Ngày mai hai người sẽ gặp nhau ở đâu?\nNam: Linh ơi, ngày mai mình gặp nhau ở cửa Đông nhà ga nhé?\nNữ: Cửa Đông đông người nên khó tìm nhau lắm. Cửa Tây thì sao?\nNam: Đúng nhỉ. Vậy mình gặp nhau ở trước hiệu sách cửa Tây nhé.\nNữ: Vâng, mình hiểu rồi.\nNam: Không phải trước tiệm hoa nhỉ?\nNữ: Đúng, hiệu sách. Gặp nhau lúc 10 giờ nhé.\nNgười dẫn: Ngày mai hai người sẽ gặp nhau ở đâu?', 'Bốn ô hình: (1) Trước tiệm hoa ở cửa đông ga; (2) Trước hiệu sách ở cửa đông ga; (3) Trước hiệu sách ở cửa tây ga; (4) Trước tiệm hoa ở cửa tây ga.', '[{"expression":"東","reading":"ひがし","meaning_vi":"hướng đông; phía đông"},{"expression":"西","reading":"にし","meaning_vi":"hướng tây; phía tây"},{"expression":"本屋","reading":"ほんや","meaning_vi":"hiệu sách"}]', 147, 1, 'learning-path/N5/skills/N5-L-TASK-003.mp3', '3d8f68d28167f2d7c1914f1cc840d072a39a2e9aeb0972cc691116722847a2d9', 35, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-L-TASK-004', 'N5-L-TASK', 'N5', 'LISTENING', 4, NULL, NULL, '[{"speaker":"N","ja":"女の人はこれから、何をしますか。"},{"speaker":"F","ja":"お父さん、お皿を洗いましょうか。"},{"speaker":"M","ja":"ありがとう、でも、お皿は私が洗うから、テーブルの上をふいてください。"},{"speaker":"F","ja":"はい、テーブルの上をふきます。"},{"speaker":"M","ja":"ふくものは台所にありますよ。"},{"speaker":"F","ja":"じゃあ、それを使ってテーブルをきれいにします。"},{"speaker":"N","ja":"女の人はこれから、何をしますか。"}]', 'Người dẫn: Sau đây người phụ nữ sẽ làm gì?\nNữ: Bố ơi, để con rửa bát đĩa nhé?\nNam: Cảm ơn con. Nhưng bát đĩa để bố rửa cho, con hãy lau mặt bàn nhé.\nNữ: Vâng, con lau mặt bàn.\nNam: Khăn lau ở trong bếp đấy.\nNữ: Vậy con dùng nó lau sạch bàn.\nNgười dẫn: Sau đây người phụ nữ sẽ làm gì?', 'Bốn ô hình: (1) Rửa bát; (2) Dọn phòng; (3) Đi mua trái cây; (4) Lau mặt bàn.', '[{"expression":"上","reading":"うえ","meaning_vi":"phía trên; bên trên"},{"expression":"父","reading":"ちち","meaning_vi":"bố"}]', 134, 1, 'learning-path/N5/skills/N5-L-TASK-004.mp3', 'c0b4368108d1b517bf9112708c350fd916eb68d0e0744351eb7ac1a0e5bddde4', 30, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-L-TASK-005', 'N5-L-TASK', 'N5', 'LISTENING', 5, NULL, NULL, '[{"speaker":"N","ja":"男の人は何を注文しますか。"},{"speaker":"F","ja":"いらっしゃいませ。何にしますか。"},{"speaker":"M","ja":"ええと、カレーライスをお願いします。あ、すみません、きょうは寒いですから、やっぱり熱いうどんにします。"},{"speaker":"F","ja":"はい、熱いうどんですね。お飲み物はどうしますか。"},{"speaker":"M","ja":"オレンジジュースをください。"},{"speaker":"F","ja":"お茶はいりませんか。"},{"speaker":"M","ja":"ええ、ジュースだけでいいです。"},{"speaker":"N","ja":"男の人は何を注文しますか。"}]', 'Người dẫn: Người đàn ông sẽ gọi món gì?\nNữ: Xin kính chào quý khách. Quý khách dùng gì ạ?\nNam: Ừm, cho tôi cơm cà ri nhé. À, xin lỗi, hôm nay trời lạnh nên thôi tôi đổi sang mì udon nóng.\nNữ: Vâng, mì udon nóng ạ. Còn đồ uống thì sao ạ?\nNam: Cho tôi nước cam nhé.\nNữ: Anh không cần trà ạ?\nNam: Vâng, chỉ nước cam thôi.\nNgười dẫn: Người đàn ông sẽ gọi món gì?', 'Bốn ô hình: (1) Udon nóng và nước cam; (2) Cơm cà ri và trà lạnh; (3) Udon nóng và trà nóng; (4) Bánh mì và cà phê.', '[{"expression":"寒い","reading":"さむい","meaning_vi":"lạnh (thời tiết)"},{"expression":"飲み物","reading":"のみもの","meaning_vi":"đồ uống"}]', 156, 1, 'learning-path/N5/skills/N5-L-TASK-005.mp3', '0ef685fa887c5feed7422e96990bfc20a5b7f9e444c9823e5ef6db52748404dd', 37, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-L-TASK-006', 'N5-L-TASK', 'N5', 'LISTENING', 6, NULL, NULL, '[{"speaker":"N","ja":"女の人は何で病院へ行きますか。"},{"speaker":"F","ja":"すみません、病院へ行きたいです。電車で行きますか。"},{"speaker":"M","ja":"病院の近くに駅がありませんから、駅の前の三番のバスに乗ってください。"},{"speaker":"F","ja":"三番のバスですね。ありがとうございます。"},{"speaker":"M","ja":"五番のバスは病院へ行きませんよ。"},{"speaker":"F","ja":"では、三番を待ちます。"},{"speaker":"N","ja":"女の人は何で病院へ行きますか。"}]', 'Người dẫn: Người phụ nữ sẽ đi đến Bệnh viện Thành phố bằng gì?\nNữ: Xin lỗi, tôi muốn đến bệnh viện. Tôi đi bằng tàu điện phải không ạ?\nNam: Vì gần bệnh viện không có ga nên chị hãy lên xe buýt số 3 trước ga.\nNữ: Xe buýt số 3 ạ. Tôi cảm ơn nhiều.\nNam: Xe số 5 không đi bệnh viện đâu.\nNữ: Vậy tôi đợi xe số 3.\nNgười dẫn: Người phụ nữ sẽ đi đến Bệnh viện Thành phố bằng gì?', 'Bốn ô hình: (1) Đi tàu điện; (2) Đi xe buýt số 3; (3) Đi xe đạp; (4) Đi bộ.', '[{"expression":"病院","reading":"びょういん","meaning_vi":"bệnh viện"},{"expression":"電車","reading":"でんしゃ","meaning_vi":"tàu điện"},{"expression":"乗る","reading":"のる","meaning_vi":"lên xe; lên tàu; lên"}]', 136, 1, 'learning-path/N5/skills/N5-L-TASK-006.mp3', '3e2b91be5a509f18a3b549464bfe8878f1f48d891b0938d205975bd6cb5e0cb5', 33, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-L-TASK-007', 'N5-L-TASK', 'N5', 'LISTENING', 7, NULL, NULL, '[{"speaker":"N","ja":"男の人は花をどこに置きますか。"},{"speaker":"M","ja":"きれいな花ですね。窓の近くの机の上に置きましょうか。"},{"speaker":"F","ja":"そこは風が強いですから、ドアのよこの小さいテーブルの上に置いてください。"},{"speaker":"M","ja":"はい、花はドアのそばですね。"},{"speaker":"F","ja":"テレビの上には置かないでくださいね。"},{"speaker":"M","ja":"ええ、小さいテーブルに置きます。"},{"speaker":"N","ja":"男の人は花をどこに置きますか。"}]', 'Người dẫn: Người đàn ông sẽ đặt hoa ở đâu?\nNam: Hoa đẹp quá nhỉ. Tôi đặt lên chiếc bàn ở gần cửa sổ nhé?\nNữ: Chỗ đó gió mạnh lắm, anh hãy đặt lên chiếc bàn nhỏ ở bên cạnh cửa ra vào nhé.\nNam: Vâng, hoa đặt cạnh cửa nhỉ.\nNữ: Đừng đặt lên tivi nhé.\nNam: Vâng, tôi đặt lên bàn nhỏ.\nNgười dẫn: Người đàn ông sẽ đặt hoa ở đâu?', 'Bốn ô hình: (1) Trên bàn gần cửa sổ; (2) Trên tivi; (3) Trên bàn nhỏ cạnh cửa ra vào; (4) Dưới ghế.', '[{"expression":"花","reading":"はな","meaning_vi":"hoa"},{"expression":"窓","reading":"まど","meaning_vi":"cửa sổ"}]', 140, 1, 'learning-path/N5/skills/N5-L-TASK-007.mp3', '6e6305b60f0d3aad6bafb343f7e81152b0244427e2749cd7a837be19959e909c', 32, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-L-TASK-008', 'N5-L-TASK', 'N5', 'LISTENING', 8, NULL, NULL, '[{"speaker":"N","ja":"男の人はどのシャツを買いますか。"},{"speaker":"M","ja":"すみません、その白いシャツを見せてください。"},{"speaker":"F","ja":"はい、どうぞ。同じ形で青いシャツもありますよ。"},{"speaker":"M","ja":"ああ、青もいいですね。でも、会社で着ますから、この白いのにします。これから涼しくなりますから、ながそでのほうをください。"},{"speaker":"F","ja":"白いシャツも、そでが短いのと長いのがあります。"},{"speaker":"M","ja":"長いのを一枚ください。短いのはいりません。"},{"speaker":"N","ja":"男の人はどのシャツを買いますか。"}]', 'Người dẫn: Người đàn ông sẽ mua chiếc áo sơ mi nào?\nNam: Xin lỗi, cho tôi xem chiếc áo sơ mi trắng kia.\nNữ: Vâng, xin mời anh. Cùng kiểu dáng còn có cả áo màu xanh nữa đấy ạ.\nNam: Ồ, màu xanh cũng đẹp nhỉ. Nhưng vì mặc ở công ty nên tôi lấy chiếc màu trắng này. Sắp tới trời sẽ mát mẻ nên cho tôi loại dài tay nhé.\nNữ: Áo trắng cũng có tay ngắn và tay dài.\nNam: Cho tôi một chiếc tay dài. Tôi không cần tay ngắn.\nNgười dẫn: Người đàn ông sẽ mua chiếc áo sơ mi nào?', 'Bốn ô hình: (1) Áo sơ mi trắng tay ngắn; (2) Áo sơ mi xanh tay ngắn; (3) Áo sơ mi xanh tay dài; (4) Áo sơ mi trắng tay dài.', '[{"expression":"白い","reading":"しろい","meaning_vi":"trắng; màu trắng"},{"expression":"青い","reading":"あおい","meaning_vi":"xanh (như da trời hoặc biển); màu xanh"},{"expression":"長い","reading":"ながい","meaning_vi":"dài; lâu"}]', 181, 1, 'learning-path/N5/skills/N5-L-TASK-008.mp3', 'c6d755a366c7df08064d87d08a613ca4038f8c79b8093422eaed4d159c0db4d8', 40, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-L-TASK-009', 'N5-L-TASK', 'N5', 'LISTENING', 9, NULL, NULL, '[{"speaker":"N","ja":"二人は何時に映画館の前で会いますか。"},{"speaker":"F","ja":"あしたの映画は夜七時からですね。六時半に映画館の前で会いましょうか。"},{"speaker":"M","ja":"映画を見る前に少し晩ごはんを食べませんか。"},{"speaker":"F","ja":"いいですね、じゃあ、六時に会いましょう。"},{"speaker":"M","ja":"はい、そうしましょう。"},{"speaker":"F","ja":"食事のあとで映画館に入りますね。"},{"speaker":"M","ja":"ええ、映画は七時ですから、時間はあります。"},{"speaker":"N","ja":"二人は何時に映画館の前で会いますか。"}]', 'Người dẫn: Hai người sẽ gặp nhau trước rạp chiếu phim lúc mấy giờ?\nNữ: Phim ngày mai bắt đầu từ 7 giờ tối nhỉ. Mình gặp nhau trước rạp lúc 6 giờ rưỡi nhé?\nNam: Trước khi xem phim mình ăn tối một chút không?\nNữ: Hay đấy. Vậy mình gặp nhau lúc 6 giờ nhé.\nNam: Vâng, mình làm thế đi.\nNữ: Ăn xong rồi vào rạp nhỉ?\nNam: Ừ, phim lúc 7 giờ nên còn thời gian.\nNgười dẫn: Hai người sẽ gặp nhau trước rạp chiếu phim lúc mấy giờ?', 'Bốn ô hình: (1) 6 giờ; (2) 5 giờ 30; (3) 6 giờ 30; (4) 7 giờ.', '[{"expression":"映画","reading":"えいが","meaning_vi":"bộ phim; phim ảnh"},{"expression":"晩ご飯","reading":"ばんごはん","meaning_vi":"bữa tối"}]', 159, 1, 'learning-path/N5/skills/N5-L-TASK-009.mp3', 'd83551885bed0ea56deeb466ea43d6819882cea09704e88fa49393a3c5429474', 36, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-L-TASK-010', 'N5-L-TASK', 'N5', 'LISTENING', 10, NULL, NULL, '[{"speaker":"N","ja":"女の人はこのあと、何をしますか。"},{"speaker":"M","ja":"タオさん、きょうの授業は終わりましたから、部屋の電気を消しましょう。"},{"speaker":"F","ja":"はい、あ、窓がまだあいていますよ。私が閉めますね。"},{"speaker":"M","ja":"ありがとう、電気は私が消します。"},{"speaker":"F","ja":"ドアも閉めますか。"},{"speaker":"M","ja":"ドアはまだ閉めないでください。先生が来ます。"},{"speaker":"N","ja":"女の人はこのあと、何をしますか。"}]', 'Người dẫn: Sau đây người phụ nữ sẽ làm gì?\nNam: Bạn Thảo ơi, giờ học hôm nay kết thúc rồi nên mình tắt đèn phòng học nhé.\nNữ: Vâng. À, cửa sổ vẫn còn đang mở kìa. Để mình đóng lại nhé.\nNam: Cảm ơn bạn. Đèn thì để mình tắt cho.\nNữ: Tôi đóng cả cửa ra vào nhé?\nNam: Đừng đóng cửa ra vào vội. Giáo viên sắp đến.\nNgười dẫn: Sau đây người phụ nữ sẽ làm gì?', 'Bốn ô hình: (1) Tắt đèn; (2) Đóng cửa sổ; (3) Xếp ghế; (4) Lau bảng.', '[{"expression":"授業","reading":"じゅぎょう","meaning_vi":"buổi học; tiết học; giờ học"},{"expression":"電気","reading":"でんき","meaning_vi":"điện; đèn (trong nhà)"}]', 138, 1, 'learning-path/N5/skills/N5-L-TASK-010.mp3', '5672ad7a26a96ca3aaffb3a4cb912eb5370ec7090d0e91321774eeb4f43c0f2c', 33, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-L-TASK-011', 'N5-L-TASK', 'N5', 'LISTENING', 11, NULL, NULL, '[{"speaker":"N","ja":"男の人は郵便局で何を買いますか。"},{"speaker":"M","ja":"すみません、八十円の切手を二枚ください。"},{"speaker":"F","ja":"はい、八十円の切手が二枚ですね。はがきはよろしいですか。"},{"speaker":"M","ja":"あ、そうですね、切手はやっぱり三枚にしてください。はがきはうちにまだありますから、けっこうです。"},{"speaker":"F","ja":"では、切手は全部で二百四十円です。"},{"speaker":"M","ja":"はい、三枚ともこの手紙に使います。"},{"speaker":"N","ja":"男の人は郵便局で何を買いますか。"}]', 'Người dẫn: Người đàn ông sẽ mua gì ở bưu điện?\nNam: Xin lỗi, bán cho tôi 2 con tem 80 yên.\nNữ: Vâng, 2 con tem 80 yên ạ. Anh có lấy thêm bưu thiếp không ạ?\nNam: À, phải rồi. Tem thì cho tôi đổi thành 3 con nhé. Bưu thiếp ở nhà tôi vẫn còn nên không cần đâu ạ.\nNữ: Vậy tiền tem tổng cộng là 240 yên.\nNam: Vâng, tôi dùng cả ba tem cho lá thư này.\nNgười dẫn: Người đàn ông sẽ mua gì ở bưu điện?', 'Bốn ô hình: (1) Hai tem 80 yên; (2) Hai bưu thiếp; (3) Ba tem 80 yên; (4) Ba bưu thiếp và một tem.', '[{"expression":"郵便局","reading":"ゆうびんきょく","meaning_vi":"bưu điện"},{"expression":"切手","reading":"きって","meaning_vi":"tem thư"}]', 162, 1, 'learning-path/N5/skills/N5-L-TASK-011.mp3', '6e580aab9039eb0f4e73b8d2bab0e65b4c08d4fc13de76f80553f870e630701b', 38, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-L-TASK-012', 'N5-L-TASK', 'N5', 'LISTENING', 12, NULL, NULL, '[{"speaker":"N","ja":"男の人はこれから、何階へ行きますか。"},{"speaker":"M","ja":"すみません、日本の新聞を読みたいんですが、二階にありますか。"},{"speaker":"F","ja":"二階は外国語の本だけです。新聞と雑誌は三階の部屋にありますよ。"},{"speaker":"M","ja":"そうですか、じゃあ、三階へ行きます。"},{"speaker":"F","ja":"三階にはいすもありますから、そこで読んでください。"},{"speaker":"M","ja":"ありがとうございます、本の部屋には行きません。"},{"speaker":"N","ja":"男の人はこれから、何階へ行きますか。"}]', 'Người dẫn: Sau đây người đàn ông sẽ đi lên tầng mấy?\nNam: Xin lỗi, tôi muốn đọc báo tiếng Nhật, có ở tầng 2 không ạ?\nNữ: Tầng 2 chỉ có sách ngoại ngữ thôi ạ. Báo và tạp chí thì có ở phòng trên tầng 3 đấy ạ.\nNam: Vậy ạ. Thế thì tôi sẽ lên tầng 3.\nNữ: Tầng ba có ghế nên anh hãy đọc ở đó.\nNam: Cảm ơn. Tôi không đến phòng sách nữa.\nNgười dẫn: Sau đây người đàn ông sẽ đi lên tầng mấy?', 'Bốn ô hình: (1) Đi tầng 1; (2) Đi tầng 2; (3) Đi tầng 4; (4) Đi tầng 3.', '[{"expression":"雑誌","reading":"ざっし","meaning_vi":"tạp chí"}]', 163, 1, 'learning-path/N5/skills/N5-L-TASK-012.mp3', 'b87dc0fef08e1ed0ee2642727f265568c578c785f56f4e7a32840c14f9bfd163', 36, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-L-TASK-013', 'N5-L-TASK', 'N5', 'LISTENING', 13, NULL, NULL, '[{"speaker":"N","ja":"二人は山田さんに何を買いますか。"},{"speaker":"F","ja":"来週、山田さんの誕生日ですね。お菓子を買いませんか。"},{"speaker":"M","ja":"山田さんは今、甘いものを食べていませんよ。きれいなコップはどうですか。"},{"speaker":"F","ja":"コップは先月もべつの人からもらっていましたよ。じゃあ、この木の箸にしましょう。"},{"speaker":"M","ja":"いいですね、その箸を買いましょう。"},{"speaker":"F","ja":"お菓子は買いませんね。"},{"speaker":"M","ja":"ええ、この箸を山田さんにあげましょう。"},{"speaker":"N","ja":"二人は山田さんに何を買いますか。"}]', 'Người dẫn: Hai người sẽ mua gì tặng bạn Yamada?\nNữ: Tuần sau là sinh nhật của bạn Yamada nhỉ. Mình mua bánh kẹo nhé?\nNam: Bạn Yamada hiện đang kiêng đồ ngọt đấy. Một chiếc cốc đẹp thì sao?\nNữ: Cốc thì tháng trước bạn ấy cũng nhận được từ người khác rồi. Vậy mình chọn đôi đũa gỗ này đi.\nNam: Hay đấy, mua đôi đũa đó nhé.\nNữ: Không mua bánh kẹo nhỉ?\nNam: Ừ, tặng đôi đũa này cho Yamada nhé.\nNgười dẫn: Hai người sẽ mua gì tặng bạn Yamada?', 'Bốn ô hình: (1) Mua đũa gỗ; (2) Mua bánh kẹo; (3) Mua cốc trắng; (4) Mua trái cây.', '[{"expression":"甘い","reading":"あまい","meaning_vi":"ngọt; dễ dãi; nuông chiều"},{"expression":"先月","reading":"せんげつ","meaning_vi":"tháng trước"},{"expression":"木","reading":"き","meaning_vi":"cái cây; cây"}]', 179, 1, 'learning-path/N5/skills/N5-L-TASK-013.mp3', 'd63e401a0165de485e67fb3e73b0200d3d00db6ffe9cf8555ea98453a6b7feb3', 40, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-L-TASK-014', 'N5-L-TASK', 'N5', 'LISTENING', 14, NULL, NULL, '[{"speaker":"N","ja":"女の人は紙に何を書きますか。"},{"speaker":"M","ja":"図書館のカードを作りますから、この紙に名前と電話番号を書いてください。"},{"speaker":"F","ja":"はい、うちの住所も書きますか。"},{"speaker":"M","ja":"いいえ、住所は書かなくてもいいですよ。"},{"speaker":"F","ja":"電話番号はうちの番号でいいですか。"},{"speaker":"M","ja":"はい、名前と一緒にここに書いてください。"},{"speaker":"N","ja":"女の人は紙に何を書きますか。"}]', 'Người dẫn: Người phụ nữ sẽ viết gì vào tờ giấy?\nNam: Vì làm thẻ thư viện nên chị hãy viết tên và số điện thoại vào tờ giấy này nhé.\nNữ: Vâng. Có viết cả địa chỉ nhà không ạ?\nNam: Không, địa chỉ thì không cần viết đâu ạ.\nNữ: Ghi số điện thoại nhà được không?\nNam: Được. Ghi ở đây cùng tên nhé.\nNgười dẫn: Người phụ nữ sẽ viết gì vào tờ giấy?', 'Bốn ô hình: (1) Chỉ ghi tên; (2) Ghi tên và số điện thoại; (3) Ghi tên và địa chỉ; (4) Chỉ ghi số điện thoại.', '[{"expression":"紙","reading":"かみ","meaning_vi":"giấy; tờ giấy"},{"expression":"名前","reading":"なまえ","meaning_vi":"tên"},{"expression":"書く","reading":"かく","meaning_vi":"viết; vẽ"}]', 134, 1, 'learning-path/N5/skills/N5-L-TASK-014.mp3', 'd93598453e276127091b8e119e0eae0e01f54c750b5bd3f68925c9c16542bddb', 31, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-L-TASK-015', 'N5-L-TASK', 'N5', 'LISTENING', 15, NULL, NULL, '[{"speaker":"N","ja":"男の人はあした、何を持っていきますか。"},{"speaker":"M","ja":"あしたは山の公園へ行きますね。お弁当と飲み物を持っていきますか。"},{"speaker":"F","ja":"お弁当は山のレストランで食べますから、いりませんよ。お茶と、それから雨が多い所ですから傘を持ってきてください。"},{"speaker":"M","ja":"わかりました、お茶と傘ですね。"},{"speaker":"F","ja":"カメラは私が持っていきますね。"},{"speaker":"M","ja":"では、私はお茶と傘を持っていきます。"},{"speaker":"N","ja":"男の人はあした、何を持っていきますか。"}]', 'Người dẫn: Ngày mai người đàn ông sẽ mang theo thứ gì?\nNam: Ngày mai mình đi công viên trên núi nhỉ. Có mang theo cơm hộp và đồ uống không?\nNữ: Bữa trưa mình sẽ ăn ở nhà hàng trên núi nên không cần cơm hộp đâu. Bạn hãy mang theo trà, và vì chỗ đó hay mưa nên mang cả ô nữa nhé.\nNam: Mình hiểu rồi. Trà và ô nhỉ.\nNữ: Tôi sẽ mang máy ảnh nhé.\nNam: Vậy tôi mang trà và ô.\nNgười dẫn: Ngày mai người đàn ông sẽ mang theo thứ gì?', 'Bốn ô hình: (1) Cơm hộp và trà; (2) Cơm hộp và ô; (3) Trà và ô; (4) Máy ảnh và ô.', '[{"expression":"山","reading":"やま","meaning_vi":"núi"},{"expression":"お茶","reading":"おちゃ","meaning_vi":"trà"},{"expression":"傘","reading":"かさ","meaning_vi":"ô; dù; cái ô"}]', 173, 1, 'learning-path/N5/skills/N5-L-TASK-015.mp3', '1acee06b408de627bd992ce21e1da619851cd68e24ecbbabf829f1bf281f8adc', 37, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-L-TASK-016', 'N5-L-TASK', 'N5', 'LISTENING', 16, NULL, NULL, '[{"speaker":"N","ja":"女の人はまず、どこへ行きますか。"},{"speaker":"M","ja":"リンさん、昼休みに銀行へ行きますね。この手紙も郵便局で出してください。"},{"speaker":"F","ja":"はい、いいですよ。銀行でお金を下ろしてから、郵便局へ行きますね。"},{"speaker":"M","ja":"あ、すみません、この手紙は早く出したいですから、銀行の前に郵便局へ行ってください。"},{"speaker":"F","ja":"わかりました、じゃあ、すぐ行ってきます。"},{"speaker":"M","ja":"銀行はそのあとでいいですよ。"},{"speaker":"F","ja":"はい、この手紙を先に出します。"},{"speaker":"N","ja":"女の人はまず、どこへ行きますか。"}]', 'Người dẫn: Đầu tiên người phụ nữ sẽ đi đâu?\nNam: Linh, giờ nghỉ trưa bạn đến ngân hàng nhỉ. Hãy gửi giúp cả lá thư này ở bưu điện nhé.\nNữ: Vâng, được chứ ạ. Tôi rút tiền ở ngân hàng xong rồi sẽ qua bưu điện nhé.\nNam: À, xin lỗi. Tôi muốn gửi thư sớm nên bạn hãy đến bưu điện trước ngân hàng.\nNữ: Vâng, tôi hiểu rồi. Vậy tôi đi ngay đây ạ.\nNam: Ngân hàng thì đến sau cũng được.\nNữ: Vâng, tôi gửi thư trước.\nNgười dẫn: Đầu tiên người phụ nữ sẽ đi đâu?', 'Bốn ô hình: (1) Đi ngân hàng; (2) Đi siêu thị; (3) Đi nhà hàng; (4) Đi bưu điện.', '[{"expression":"昼休み","reading":"ひるやすみ","meaning_vi":"giờ nghỉ trưa; nghỉ trưa"},{"expression":"銀行","reading":"ぎんこう","meaning_vi":"ngân hàng"},{"expression":"手紙","reading":"てがみ","meaning_vi":"lá thư; thư (viết tay)"}]', 189, 1, 'learning-path/N5/skills/N5-L-TASK-016.mp3', '72a01e86d536edd0bb4e1b628162345459fdf210bad2a0a2f84b66df56ae39a4', 42, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-L-TASK-017', 'N5-L-TASK', 'N5', 'LISTENING', 17, NULL, NULL, '[{"speaker":"N","ja":"男の人はいすをいくつ持ってきますか。"},{"speaker":"F","ja":"午後からの会議には十人来ますね。この部屋にいすはいくつありますか。"},{"speaker":"M","ja":"ええと、一つ、二つ…八つあります。二つ足りませんね。"},{"speaker":"F","ja":"じゃあ、隣の部屋からいすを二つ持ってきてください。"},{"speaker":"M","ja":"はい、すぐ持ってきます。"},{"speaker":"F","ja":"隣の部屋のいすは使ってもいいですよ。"},{"speaker":"M","ja":"では、足りない二つを持ってきます。"},{"speaker":"N","ja":"男の人はいすをいくつ持ってきますか。"}]', 'Người dẫn: Người đàn ông sẽ mang thêm mấy chiếc ghế?\nNữ: Cuộc họp chiều nay có 10 người đến nhỉ. Trong phòng này có mấy chiếc ghế?\nNam: Để xem, 1, 2... có 8 chiếc. Thiếu 2 chiếc rồi.\nNữ: Vậy anh hãy mang 2 chiếc ghế từ phòng bên cạnh sang nhé.\nNam: Vâng, tôi mang sang ngay đây.\nNữ: Có thể dùng ghế phòng bên cạnh.\nNam: Vậy tôi mang sang hai chiếc còn thiếu.\nNgười dẫn: Người đàn ông sẽ mang thêm mấy chiếc ghế?', 'Bốn ô hình: (1) Mang hai ghế; (2) Mang ba ghế; (3) Mang tám ghế; (4) Mang mười ghế.', '[{"expression":"八つ","reading":"やっつ","meaning_vi":"tám cái"},{"expression":"二つ","reading":"ふたつ","meaning_vi":"hai cái"}]', 167, 1, 'learning-path/N5/skills/N5-L-TASK-017.mp3', 'a704595933d992eead125b16759a92f260dd52017b72ae524b5078014e776acb', 38, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-L-TASK-018', 'N5-L-TASK', 'N5', 'LISTENING', 18, NULL, NULL, '[{"speaker":"N","ja":"女の人はスーパーで何を買いますか。"},{"speaker":"F","ja":"今晩はカレーを作りましょう。じゃがいもとにんじんを買いますね。"},{"speaker":"M","ja":"じゃがいもはうちの台所にまだたくさんありますよ。"},{"speaker":"F","ja":"本当ですか。じゃあ、にんじんだけ買いますね。"},{"speaker":"M","ja":"トマトもありますから、いりませんよ。"},{"speaker":"F","ja":"はい、きょう買うのはにんじんだけですね。"},{"speaker":"N","ja":"女の人はスーパーで何を買いますか。"}]', 'Người dẫn: Người phụ nữ sẽ mua gì ở siêu thị?\nNữ: Tối nay mình nấu món cà ri nhé. Em sẽ mua khoai tây và cà rốt nhé.\nNam: Khoai tây ở trong bếp nhà mình vẫn còn nhiều lắm đấy.\nNữ: Thật thế à. Vậy em chỉ mua cà rốt thôi nhé.\nNam: Cà chua cũng còn nên không cần mua.\nNữ: Vâng, hôm nay chỉ mua cà rốt nhỉ.\nNgười dẫn: Người phụ nữ sẽ mua gì ở siêu thị?', 'Bốn ô hình: (1) Cà chua và khoai tây; (2) Chỉ cà rốt; (3) Khoai tây và cà rốt; (4) Chỉ khoai tây.', '[{"expression":"今晩","reading":"こんばん","meaning_vi":"tối nay"},{"expression":"台所","reading":"だいどころ","meaning_vi":"bếp; nhà bếp"},{"expression":"たくさん","reading":"たくさん","meaning_vi":"nhiều"}]', 149, 1, 'learning-path/N5/skills/N5-L-TASK-018.mp3', 'd64dbbcd60879703c6bc8f2d128c28fc47e52f728dfe3717b572a3df95963d37', 32, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-L-TASK-019', 'N5-L-TASK', 'N5', 'LISTENING', 19, NULL, NULL, '[{"speaker":"N","ja":"二人はどこで写真をとりますか。"},{"speaker":"F","ja":"いい天気ですね。あの大きい花の木の下で写真をとりましょうか。"},{"speaker":"M","ja":"あそこは人がたくさんいますから、むこうの白い橋の上でとりませんか。川もきれいに見えますよ。"},{"speaker":"F","ja":"そうですね、じゃあ、橋の上へ行きましょう。"},{"speaker":"M","ja":"橋の上は今、人が少ないですね。"},{"speaker":"F","ja":"ええ、あそこで二人の写真をとりましょう。"},{"speaker":"N","ja":"二人はどこで写真をとりますか。"}]', 'Người dẫn: Hai người sẽ chụp ảnh ở đâu?\nNữ: Thời tiết đẹp quá nhỉ. Mình chụp ảnh ở dưới gốc cây hoa lớn đằng kia nhé?\nNam: Chỗ đó đông người lắm, mình chụp ở trên cây cầu trắng phía kia đi. Nhìn thấy cả dòng sông đẹp nữa đấy.\nNữ: Đúng nhỉ. Vậy mình ra trên cầu đi.\nNam: Bây giờ trên cầu ít người nhỉ.\nNữ: Ừ, chụp ảnh hai chúng ta ở đó nhé.\nNgười dẫn: Hai người sẽ chụp ảnh ở đâu?', 'Bốn ô hình: (1) Dưới cây hoa lớn; (2) Trước cổng công viên; (3) Trên cầu trắng; (4) Bên cạnh ghế.', '[{"expression":"天気","reading":"てんき","meaning_vi":"thời tiết"},{"expression":"写真","reading":"しゃしん","meaning_vi":"tấm ảnh; ảnh chụp; ảnh"},{"expression":"橋","reading":"はし","meaning_vi":"cây cầu"}]', 161, 1, 'learning-path/N5/skills/N5-L-TASK-019.mp3', 'ed7f9c5f72dd2315077d0592baf871a19017bbdebcedd6675d8cc2b8c293da9e', 35, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-L-TASK-020', 'N5-L-TASK', 'N5', 'LISTENING', 20, NULL, NULL, '[{"speaker":"N","ja":"男の人は昼ごはんのあとで、薬をどう飲みますか。"},{"speaker":"F","ja":"山田さん、これが風邪の薬です。白い薬は朝と昼と夜、ごはんを食べたあとで二つ飲んでください。"},{"speaker":"M","ja":"はい、ごはんのあとで二つですね。この青い薬も昼に飲みますか。"},{"speaker":"F","ja":"いいえ、青い薬は夜、寝る前に一つだけ飲んでください。"},{"speaker":"M","ja":"じゃあ、昼は青い薬はいりませんね。"},{"speaker":"F","ja":"はい、昼ごはんのあとは白い薬だけです。"},{"speaker":"N","ja":"男の人は昼ごはんのあとで、薬をどう飲みますか。"}]', 'Người dẫn: Sau bữa trưa, người đàn ông sẽ uống thuốc như thế nào?\nNữ: Anh Yamada, đây là thuốc cảm của anh. Thuốc màu trắng thì sáng, trưa, tối, sau khi ăn cơm xong anh hãy uống mỗi lần 2 viên nhé.\nNam: Vâng, sau bữa cơm 2 viên nhỉ. Thế thuốc màu xanh này buổi trưa cũng uống ạ?\nNữ: Không, thuốc màu xanh chỉ uống 1 viên trước khi đi ngủ vào buổi tối thôi ạ.\nNam: Vậy buổi trưa không cần thuốc xanh nhỉ?\nNữ: Đúng. Sau bữa trưa chỉ uống thuốc trắng.\nNgười dẫn: Sau bữa trưa, người đàn ông sẽ uống thuốc như thế nào?', 'Bốn ô hình: (1) Uống một viên thuốc trắng; (2) Uống một viên thuốc xanh; (3) Uống thuốc trắng và thuốc xanh; (4) Uống hai viên thuốc trắng.', '[{"expression":"薬","reading":"くすり","meaning_vi":"thuốc"},{"expression":"昼ご飯","reading":"ひるごはん","meaning_vi":"bữa trưa"},{"expression":"寝る","reading":"ねる","meaning_vi":"ngủ; đi ngủ"}]', 183, 1, 'learning-path/N5/skills/N5-L-TASK-020.mp3', '05cac5c5c60b81a0c0a0eba5d9fcee6dd0406dad06d82f257f65502a5d936ceb', 41, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-L-TASK-021', 'N5-L-TASK', 'N5', 'LISTENING', 21, NULL, NULL, '[{"speaker":"N","ja":"女の人は大きい辞書をどこに置きますか。"},{"speaker":"F","ja":"先生、この日本語の本と大きい辞書は本棚の上に置きましょうか。"},{"speaker":"M","ja":"日本語の本は上の段に置いてください。でも、辞書は重くて危ないですから、一番下の段に入れてください。"},{"speaker":"F","ja":"はい、辞書は一番下ですね。"},{"speaker":"M","ja":"机の上にも置かないでくださいね。"},{"speaker":"F","ja":"はい、本棚の下に入れます。"},{"speaker":"N","ja":"女の人は大きい辞書をどこに置きますか。"}]', 'Người dẫn: Người phụ nữ sẽ đặt cuốn từ điển lớn ở đâu?\nNữ: Thưa thầy, quyển sách tiếng Nhật này và cuốn từ điển lớn em để lên trên giá sách nhé ạ?\nNam: Sách tiếng Nhật thì em để ở ngăn trên nhé. Nhưng từ điển nặng và nguy hiểm nên em hãy xếp vào ngăn dưới cùng nhé.\nNữ: Vâng, từ điển ở ngăn dưới cùng nhỉ.\nNam: Cũng đừng để lên bàn nhé.\nNữ: Vâng, em để vào ngăn dưới giá sách.\nNgười dẫn: Người phụ nữ sẽ đặt cuốn từ điển lớn ở đâu?', 'Bốn ô hình: (1) Ngăn dưới cùng giá sách; (2) Ngăn trên giá sách; (3) Trên bàn; (4) Dưới ghế.', '[{"expression":"重い","reading":"おもい","meaning_vi":"nặng"},{"expression":"危ない","reading":"あぶない","meaning_vi":"nguy hiểm; không an toàn"},{"expression":"下","reading":"した","meaning_vi":"phía dưới; bên dưới"}]', 159, 1, 'learning-path/N5/skills/N5-L-TASK-021.mp3', 'd46ede9e379ef11e38fa529520e04fc15022a01549f7b9a58beb2edbeac44eb9', 36, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-L-TASK-022', 'N5-L-TASK', 'N5', 'LISTENING', 22, NULL, NULL, '[{"speaker":"N","ja":"二人はこれから、何をしますか。"},{"speaker":"M","ja":"アンさん、今から公園へテニスをしに行きませんか。"},{"speaker":"F","ja":"あ、外を見てください。雨がふっていますよ。"},{"speaker":"M","ja":"本当ですね。じゃあ、テニスはやめて、私のうちで新しい映画のDVDを見ませんか。"},{"speaker":"F","ja":"ええ、いいですね。そうしましょう。"},{"speaker":"M","ja":"映画のDVDはうちにあります。買いませんよ。"},{"speaker":"F","ja":"じゃあ、あなたのうちへ行きましょう。"},{"speaker":"N","ja":"二人はこれから、何をしますか。"}]', 'Người dẫn: Sau đây hai người sẽ làm gì?\nNam: Bạn An ơi, bây giờ mình ra công viên chơi quần vợt không?\nNữ: À, bạn nhìn ra ngoài kìa. Trời đang mưa rồi đấy.\nNam: Thật thế nhỉ. Vậy mình thôi không chơi quần vợt nữa, về nhà mình xem đĩa DVD phim mới nhé?\nNữ: Vâng, hay quá. Mình làm thế đi.\nNam: Nhà tôi có DVD phim rồi. Không mua đâu.\nNữ: Vậy đến nhà bạn nhé.\nNgười dẫn: Sau đây hai người sẽ làm gì?', 'Bốn ô hình: (1) Chơi quần vợt ở công viên; (2) Xem DVD phim ở nhà người nam; (3) Đi đọc sách ở thư viện; (4) Đi mua ô ở cửa hàng bách hóa.', '[{"expression":"外","reading":"そと","meaning_vi":"bên ngoài; phía ngoài"},{"expression":"雨","reading":"あめ","meaning_vi":"mưa"},{"expression":"見る","reading":"みる","meaning_vi":"xem; trông; nhìn ngắm"}]', 171, 1, 'learning-path/N5/skills/N5-L-TASK-022.mp3', 'c355266eb61628256ce0f7fee987eb11fde4899b6c8d1b8bb21e4b3fa4bcdd4c', 40, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-L-TASK-023', 'N5-L-TASK', 'N5', 'LISTENING', 23, NULL, NULL, '[{"speaker":"N","ja":"男の人はいくらの切符を何枚買いますか。"},{"speaker":"M","ja":"みどり駅まで二人ですね。切符は一枚二百円ですか。"},{"speaker":"F","ja":"いいえ、二百円は隣の駅までですよ。みどり駅までは一枚二百八十円です。"},{"speaker":"M","ja":"あ、そうですね、じゃあ、二百八十円の切符を二枚買いますね。"},{"speaker":"F","ja":"二枚ですから、全部で五百六十円ですね。"},{"speaker":"M","ja":"はい、二百円の切符では行くことができませんね。"},{"speaker":"N","ja":"男の人はいくらの切符を何枚買いますか。"}]', 'Người dẫn: Người đàn ông sẽ mua mấy tấm vé giá bao nhiêu tiền?\nNam: Đi đến ga Midori 2 người nhỉ. Vé là 200 yên một tấm phải không?\nNữ: Không, 200 yên là đến ga bên cạnh thôi. Đến ga Midori là 280 yên một tấm.\nNam: À, đúng rồi. Vậy tôi mua 2 tấm vé 280 yên nhé.\nNữ: Hai vé nên tổng cộng 560 yên nhỉ.\nNam: Ừ, không thể đi bằng vé 200 yên nhỉ.\nNgười dẫn: Người đàn ông sẽ mua mấy tấm vé giá bao nhiêu tiền?', 'Bốn ô hình: (1) Một vé 200 yên; (2) Hai vé 200 yên; (3) Hai vé 280 yên; (4) Một vé 280 yên.', '[{"expression":"二人","reading":"ふたり","meaning_vi":"hai người"},{"expression":"隣","reading":"となり","meaning_vi":"bên cạnh"},{"expression":"買う","reading":"かう","meaning_vi":"mua"}]', 167, 1, 'learning-path/N5/skills/N5-L-TASK-023.mp3', '504ff3915f37360fe69eddc5015733fc3e7258d3846ae5f3049c77dcd60ee98f', 39, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-L-TASK-024', 'N5-L-TASK', 'N5', 'LISTENING', 24, NULL, NULL, '[{"speaker":"N","ja":"女の人は何でこの紙を書きますか。"},{"speaker":"F","ja":"すみません、この紙は鉛筆で書いてもいいですか。"},{"speaker":"M","ja":"いいえ、大切な書類ですから、黒のボールペンで書いてください。赤や青のペンも使わないでください。"},{"speaker":"F","ja":"わかりました、黒のボールペンですね。"},{"speaker":"M","ja":"黒のボールペンはこの机にありますよ。"},{"speaker":"F","ja":"ありがとうございます、これを使います。"},{"speaker":"N","ja":"女の人は何でこの紙を書きますか。"}]', 'Người dẫn: Người phụ nữ sẽ viết tờ giấy này bằng bút gì?\nNữ: Xin lỗi, tờ giấy này tôi viết bằng bút chì có được không ạ?\nNam: Không, vì là giấy tờ quan trọng nên chị hãy viết bằng bút bi đen nhé. Xin đừng dùng bút đỏ hay bút xanh.\nNữ: Vâng, tôi hiểu rồi. Bút bi đen ạ.\nNam: Bút bi đen ở trên bàn này.\nNữ: Cảm ơn. Tôi dùng chiếc này.\nNgười dẫn: Người phụ nữ sẽ viết tờ giấy này bằng bút gì?', 'Bốn ô hình: (1) Viết bằng bút chì; (2) Viết bằng bút đỏ; (3) Viết bằng bút xanh; (4) Viết bằng bút bi đen.', '[{"expression":"黒い","reading":"くろい","meaning_vi":"đen; màu đen"},{"expression":"赤い","reading":"あかい","meaning_vi":"đỏ; màu đỏ"}]', 157, 1, 'learning-path/N5/skills/N5-L-TASK-024.mp3', '5ec02bef827fe32cf18836d35850f7fed08a8bd0476eaaa9c211e4e801b6e2b9', 34, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-L-TASK-025', 'N5-L-TASK', 'N5', 'LISTENING', 25, NULL, NULL, '[{"speaker":"N","ja":"男の人は台所から何を持ってきますか。"},{"speaker":"F","ja":"晩ごはんができましたよ。大きいお皿はもうならべましたから、台所から小さいお茶わんと箸を二人分持ってきてください。"},{"speaker":"M","ja":"はい、コップも持ってきましょうか。"},{"speaker":"F","ja":"コップはもうテーブルの上にありますよ。"},{"speaker":"M","ja":"あ、そうですね、じゃあ、お茶わんと箸を持ってきます。"},{"speaker":"F","ja":"小さいお皿はいりませんよ。"},{"speaker":"M","ja":"はい、お茶わんと箸だけ持ってきます。"},{"speaker":"N","ja":"男の人は台所から何を持ってきますか。"}]', 'Người dẫn: Người đàn ông sẽ mang thứ gì từ nhà bếp ra?\nNữ: Cơm tối xong rồi đây. Đĩa lớn em đã bày ra rồi, anh vào bếp lấy giúp em bát ăn cơm nhỏ và đũa cho 2 người nhé.\nNam: Ừ. Anh lấy cả cốc ra nữa nhé?\nNữ: Cốc thì đã có ở trên bàn rồi mà.\nNam: À, đúng nhỉ. Vậy anh đi lấy bát ăn cơm và đũa đây.\nNữ: Không cần đĩa nhỏ đâu.\nNam: Vâng, con chỉ mang bát và đũa.\nNgười dẫn: Người đàn ông sẽ mang thứ gì từ nhà bếp ra?', 'Bốn ô hình: (1) Bát cơm nhỏ và đũa; (2) Đĩa lớn; (3) Cốc và đĩa; (4) Thìa và dĩa.', '[{"expression":"小さい","reading":"ちいさい","meaning_vi":"nhỏ; bé"},{"expression":"上","reading":"うえ","meaning_vi":"phía trên; bên trên"},{"expression":"台所","reading":"だいどころ","meaning_vi":"bếp; nhà bếp"}]', 185, 1, 'learning-path/N5/skills/N5-L-TASK-025.mp3', 'ec0b3a0674f6c23fc074a262cce4e8a70ee271d5b0b088987b56ab9049846746', 41, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-L-TASK-026', 'N5-L-TASK', 'N5', 'LISTENING', 26, NULL, NULL, '[{"speaker":"N","ja":"女の人は何日にホテルを予約しますか。"},{"speaker":"M","ja":"来月の大阪旅行ですが、六月十日の火曜日に泊まりますか。"},{"speaker":"F","ja":"火曜日はまだ仕事がありますよ。十二日の木曜日にしましょう。"},{"speaker":"M","ja":"あ、木曜日はそのホテルが休みです。次の日の十三日はどうですか。"},{"speaker":"F","ja":"いいですね、じゃあ、十三日の金曜日に予約しますね。"},{"speaker":"M","ja":"土曜日はもう帰りますね。"},{"speaker":"F","ja":"はい、金曜日の夜だけ泊まります。"},{"speaker":"N","ja":"女の人は何日にホテルを予約しますか。"}]', 'Người dẫn: Người phụ nữ sẽ đặt khách sạn vào ngày mấy?\nNam: Về chuyến du lịch Osaka tháng sau, mình sẽ nghỉ đêm vào thứ Ba ngày 10 tháng 6 à?\nNữ: Thứ Ba vẫn còn công việc mà. Mình đi vào thứ Năm ngày 12 nhé.\nNam: À, thứ Năm khách sạn đó nghỉ đấy. Ngày hôm sau là ngày 13 thì sao?\nNữ: Được đấy. Vậy tôi sẽ đặt vào thứ Sáu ngày 13 nhé.\nNam: Thứ bảy mình về rồi nhỉ?\nNữ: Vâng, chỉ ở tối thứ sáu.\nNgười dẫn: Người phụ nữ sẽ đặt khách sạn vào ngày mấy?', 'Bốn ô hình: (1) Thứ ba ngày 10; (2) Thứ sáu ngày 13; (3) Thứ năm ngày 12; (4) Thứ bảy ngày 14.', '[{"expression":"旅行","reading":"りょこう","meaning_vi":"du lịch; chuyến đi"},{"expression":"金曜日","reading":"きんようび","meaning_vi":"thứ sáu"}]', 176, 1, 'learning-path/N5/skills/N5-L-TASK-026.mp3', '96b232094491eb9f12008ef5cfc352046134c6e57c2efaaf7cf381749a6bfe26', 41, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-L-TASK-027', 'N5-L-TASK', 'N5', 'LISTENING', 27, NULL, NULL, '[{"speaker":"N","ja":"男の人はこれからまず、何をしますか。"},{"speaker":"M","ja":"ただいま、ああ、きょうはたくさん歩いて疲れた。すぐおふろに入るよ。"},{"speaker":"F","ja":"お帰りなさい、おふろはまだおゆが熱くないですよ。晩ごはんがもうできていますから、先に食べてください。"},{"speaker":"M","ja":"そうか。じゃあ、先に晩ごはんを食べるね。"},{"speaker":"F","ja":"食事のあとでおふろに入ってね。"},{"speaker":"M","ja":"うん、おふろより先にごはんだね。"},{"speaker":"N","ja":"男の人はこれからまず、何をしますか。"}]', 'Người dẫn: Sau đây, đầu tiên người đàn ông sẽ làm gì?\nNam: Anh về rồi đây. Ôi, hôm nay đi bộ nhiều mệt quá. Anh đi tắm bồn ngay đây.\nNữ: Mừng anh đã về. Bồn tắm nước vẫn chưa nóng đâu anh. Cơm tối đã nấu xong rồi nên anh hãy ăn trước đi nhé.\nNam: Thế à. Vậy anh ăn cơm tối trước nhé.\nNữ: Ăn xong rồi tắm nhé.\nNam: Ừ, ăn trước khi tắm nhỉ.\nNgười dẫn: Sau đây, đầu tiên người đàn ông sẽ làm gì?', 'Bốn ô hình: (1) Đọc báo; (2) Tắm bồn; (3) Ăn tối; (4) Đi ngủ sớm.', '[{"expression":"歩く","reading":"あるく","meaning_vi":"đi bộ"},{"expression":"入る","reading":"はいる","meaning_vi":"vào"},{"expression":"食べる","reading":"たべる","meaning_vi":"ăn"}]', 170, 1, 'learning-path/N5/skills/N5-L-TASK-027.mp3', 'e4a3a7360ee7c4ce3af8687cea81da49d58b59d0e68c97edfabeaec766bcdb4b', 38, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-L-TASK-028', 'N5-L-TASK', 'N5', 'LISTENING', 28, NULL, NULL, '[{"speaker":"N","ja":"学生はあしたまでに、どの宿題をしますか。"},{"speaker":"F","ja":"みなさん、きょうは教科書の二十四ページまで勉強しましたね。あしたの宿題は、その次の二十五ページの問題です。"},{"speaker":"M","ja":"先生、練習帳の十二ページもしますか。"},{"speaker":"F","ja":"いいえ、練習帳は金曜日までですから、あしたはしなくてもいいですよ。"},{"speaker":"M","ja":"教科書の二十四ページはもうしませんね。"},{"speaker":"F","ja":"ええ、あしたは二十五ページを見ます。"},{"speaker":"N","ja":"学生はあしたまでに、どの宿題をしますか。"}]', 'Người dẫn: Học sinh sẽ làm bài tập nào cho đến ngày mai?\nNữ: Các em, hôm nay chúng ta đã học đến trang 24 của sách giáo khoa rồi nhỉ. Bài tập cho ngày mai là phần câu hỏi ở trang tiếp theo, trang 25.\nNam: Thưa cô, có làm cả trang 12 của quyển vở luyện tập không ạ?\nNữ: Không, quyển luyện tập hạn đến thứ Sáu nên ngày mai chưa làm cũng được nhé.\nNam: Không làm lại trang 24 sách giáo khoa nữa nhỉ?\nNữ: Đúng, ngày mai xem trang 25.\nNgười dẫn: Học sinh sẽ làm bài tập nào cho đến ngày mai?', 'Bốn ô hình: (1) Trang 24 sách giáo khoa; (2) Trang 12 vở bài tập; (3) Trang 15 vở bài tập; (4) Trang 25 sách giáo khoa.', '[{"expression":"勉強","reading":"べんきょう","meaning_vi":"việc học"},{"expression":"金曜日","reading":"きんようび","meaning_vi":"thứ sáu"}]', 181, 1, 'learning-path/N5/skills/N5-L-TASK-028.mp3', 'd7d792e1b11112fe843798e38a7645397833191f57ecd9500f381537873f1080', 39, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-L-TASK-029', 'N5-L-TASK', 'N5', 'LISTENING', 29, NULL, NULL, '[{"speaker":"N","ja":"女の人はこれからスーパーで何を買いますか。"},{"speaker":"F","ja":"あしたの朝のパンと牛乳を買いに行きますね。卵も買いましょうか。"},{"speaker":"M","ja":"パンはさっき駅の上のパン屋で買ってきましたよ。でも、牛乳と卵はもうありませんから、買ってきてください。"},{"speaker":"F","ja":"わかりました、牛乳と卵ですね。"},{"speaker":"M","ja":"卵は六つ買ってください。牛乳は一本です。"},{"speaker":"F","ja":"はい、パンはもうあるんですね。"},{"speaker":"N","ja":"女の人はこれからスーパーで何を買いますか。"}]', 'Người dẫn: Sau đây người phụ nữ sẽ mua gì ở siêu thị?\nNữ: Em đi mua bánh mì và sữa bò cho bữa sáng mai nhé. Có mua thêm trứng không anh?\nNam: Bánh mì thì lúc nãy anh đã mua ở tiệm bánh trên ga về rồi. Nhưng sữa bò và trứng đã hết rồi nên em mua về nhé.\nNữ: Vâng, em hiểu rồi. Sữa bò và trứng nhỉ.\nNam: Mua sáu quả trứng nhé. Sữa thì một hộp.\nNữ: Vâng, bánh mì đã có rồi nhỉ.\nNgười dẫn: Sau đây người phụ nữ sẽ mua gì ở siêu thị?', 'Bốn ô hình: (1) Sữa và trứng; (2) Chỉ sữa; (3) Bánh mì và sữa; (4) Trứng và bánh mì.', '[{"expression":"牛乳","reading":"ぎゅうにゅう","meaning_vi":"sữa bò; sữa"},{"expression":"卵","reading":"たまご","meaning_vi":"trứng; quả trứng"},{"expression":"朝","reading":"あさ","meaning_vi":"buổi sáng"}]', 174, 1, 'learning-path/N5/skills/N5-L-TASK-029.mp3', 'b8ff10edcdc9231d0419015f608daefcf6afa2f0e77427fcd35cd50eff88d936', 38, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-L-TASK-030', 'N5-L-TASK', 'N5', 'LISTENING', 30, NULL, NULL, '[{"speaker":"N","ja":"男の人は傘をどこに置きますか。"},{"speaker":"M","ja":"すみません、このぬれた傘は教室の中へ持って入ってもいいですか。"},{"speaker":"F","ja":"いいえ、教室の中へは持って入らないでください。入口の右に大きい傘立てがありますから、そこに入れてください。左の小さい箱はゴミ箱ですよ。"},{"speaker":"M","ja":"はい、入口の右ですね、ありがとうございます。"},{"speaker":"F","ja":"小さい箱には傘を入れないでください。"},{"speaker":"M","ja":"はい、大きい傘立てを使います。"},{"speaker":"N","ja":"男の人は傘をどこに置きますか。"}]', 'Người dẫn: Người đàn ông sẽ để chiếc ô ở đâu?\nNam: Xin lỗi, chiếc ô ướt này tôi mang vào trong phòng học có được không ạ?\nNữ: Không, xin đừng mang vào trong phòng học. Ở bên phải lối vào có giá để ô lớn, bạn hãy để vào đó nhé. Chiếc thùng nhỏ bên trái là thùng rác đấy.\nNam: Vâng, bên phải lối vào nhỉ. Tôi cảm ơn ạ.\nNữ: Đừng bỏ ô vào hộp nhỏ.\nNam: Vâng, tôi dùng giá để ô lớn.\nNgười dẫn: Người đàn ông sẽ để chiếc ô ở đâu?', 'Bốn ô hình: (1) Hộp bên trái cửa vào; (2) Giá để ô bên phải cửa vào; (3) Trong lớp học; (4) Dưới bàn.', '[{"expression":"教室","reading":"きょうしつ","meaning_vi":"phòng học; lớp học"},{"expression":"右","reading":"みぎ","meaning_vi":"bên phải; phải"},{"expression":"左","reading":"ひだり","meaning_vi":"bên trái; trái"}]', 183, 1, 'learning-path/N5/skills/N5-L-TASK-030.mp3', '6ab008905ee429a448f2d48564f3f5771885537cf60197e085ffd609139f5205', 41, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-L-TASK-031', 'N5-L-TASK', 'N5', 'LISTENING', 31, NULL, NULL, '[{"speaker":"N","ja":"リンさんは図書館へ何を持って行きますか。"},{"speaker":"M","ja":"明日は図書館で本を読みますね。"},{"speaker":"F","ja":"はい。私の本とノートを持って行きます。"},{"speaker":"M","ja":"ノートは図書館にありますよ。"},{"speaker":"F","ja":"そうですか。では、本だけ持って行きます。"},{"speaker":"M","ja":"ペンもありますから、いりません。"},{"speaker":"F","ja":"わかりました。"},{"speaker":"N","ja":"リンさんは図書館へ何を持って行きますか。"}]', 'Người dẫn: Linh mang gì đến thư viện?\nNam: Mai chúng ta đọc sách ở thư viện nhỉ.\nNữ: Vâng. Tôi sẽ mang sách và vở của mình.\nNam: Ở thư viện có vở rồi.\nNữ: Vậy à. Thế tôi chỉ mang sách.\nNam: Bút cũng có sẵn nên không cần.\nNữ: Tôi hiểu rồi.\nNgười dẫn: Linh mang gì đến thư viện?', 'Bốn ô hình: (1) Một quyển sách; (2) Một quyển vở; (3) Một cây bút; (4) Một chiếc cặp.', '[]', 131, 1, 'learning-path/N5/skills/N5-L-TASK-031.mp3', '6fc61a9869cc7e4b9c95a9579429cb2258c5a58aa76c75c0406c8b43bfe3dd9d', 32, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-L-TASK-032', 'N5-L-TASK', 'N5', 'LISTENING', 32, NULL, NULL, '[{"speaker":"N","ja":"男の人はへやのどこをそうじしますか。"},{"speaker":"F","ja":"おきゃくさんが来る前に、へやをそうじしましょう。"},{"speaker":"M","ja":"テーブルとまどをきれいにしますね。"},{"speaker":"F","ja":"テーブルは私がします。まどをおねがいします。"},{"speaker":"M","ja":"わかりました。まどをふきます。"},{"speaker":"F","ja":"ゆかは昨日そうじしました。"},{"speaker":"M","ja":"では、まどだけですね。"},{"speaker":"N","ja":"男の人はへやのどこをそうじしますか。"}]', 'Người dẫn: Người nam dọn chỗ nào trong phòng?\nNữ: Hãy dọn phòng trước khi khách đến.\nNam: Tôi sẽ lau bàn và cửa sổ.\nNữ: Bàn để tôi. Nhờ anh lau cửa sổ.\nNam: Được. Tôi sẽ lau cửa sổ.\nNữ: Sàn đã dọn hôm qua.\nNam: Vậy chỉ cửa sổ thôi nhỉ.\nNgười dẫn: Người nam dọn chỗ nào trong phòng?', 'Bốn ô hình: (1) Cái bàn; (2) Cửa sổ; (3) Sàn nhà; (4) Cửa ra vào.', '[]', 138, 1, 'learning-path/N5/skills/N5-L-TASK-032.mp3', '40eb421e65564650037d62d1949908174003c692005ddc161e42c8df45679736', 32, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-L-TASK-033', 'N5-L-TASK', 'N5', 'LISTENING', 33, NULL, NULL, '[{"speaker":"N","ja":"女の人はどのコップを使いますか。"},{"speaker":"M","ja":"お茶を飲みましょう。大きいコップを使いますか。"},{"speaker":"F","ja":"大きいのは水が入っています。小さいコップはありますか。"},{"speaker":"M","ja":"あおい小さいコップがあります。あかいのはまだあらっていません。"},{"speaker":"F","ja":"では、あおい小さいコップを使います。"},{"speaker":"M","ja":"お茶は熱いですから、気をつけてください。"},{"speaker":"F","ja":"はい、ありがとうございます。"},{"speaker":"N","ja":"女の人はどのコップを使いますか。"}]', 'Người dẫn: Người nữ dùng chiếc cốc nào?\nNam: Uống trà nhé. Chị dùng cốc lớn không?\nNữ: Cốc lớn có nước. Có cốc nhỏ không?\nNam: Có cốc nhỏ màu xanh. Cốc đỏ chưa rửa.\nNữ: Vậy tôi dùng cốc nhỏ màu xanh.\nNam: Trà nóng, hãy cẩn thận.\nNữ: Vâng, cảm ơn.\nNgười dẫn: Người nữ dùng chiếc cốc nào?', 'Bốn ô hình: (1) Cốc đỏ nhỏ; (2) Cốc xanh lớn; (3) Cốc xanh nhỏ; (4) Cốc đỏ lớn.', '[]', 165, 1, 'learning-path/N5/skills/N5-L-TASK-033.mp3', '519ca16817323da117b8cd71fe4790726f262e7dc506f319a789da7d1591e664', 36, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-L-TASK-034', 'N5-L-TASK', 'N5', 'LISTENING', 34, NULL, NULL, '[{"speaker":"N","ja":"男の人はだれに電話しますか。"},{"speaker":"F","ja":"山田さんに今日の時間を聞きたいです。"},{"speaker":"M","ja":"山田さんは今、仕事をしていますよ。"},{"speaker":"F","ja":"では、佐藤さんに聞きますか。"},{"speaker":"M","ja":"佐藤さんの電話ばんごうは知りません。田中さんは会社にいます。"},{"speaker":"F","ja":"わかりました。田中さんに電話します。"},{"speaker":"M","ja":"電話ばんごうはこの紙にあります。"},{"speaker":"N","ja":"男の人はだれに電話しますか。"}]', 'Người dẫn: Người nam gọi điện cho ai?\nNữ: Tôi muốn hỏi Yamada giờ hôm nay.\nNam: Yamada đang làm việc.\nNữ: Vậy hỏi Sato nhé?\nNam: Tôi không biết số điện thoại của Sato. Tanaka đang ở công ty.\nNữ: Tôi hiểu rồi. Tôi sẽ gọi Tanaka.\nNam: Số điện thoại ở trên tờ giấy này.\nNgười dẫn: Người nam gọi điện cho ai?', 'Bốn ô hình: (1) Ảnh Linh; (2) Ảnh Yamada; (3) Ảnh Sato; (4) Ảnh Tanaka.', '[]', 141, 1, 'learning-path/N5/skills/N5-L-TASK-034.mp3', 'f397be31b37d1f3765cf9f95df740596b730f43eb10b0891c5b9037803b3e647', 34, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-L-TASK-035', 'N5-L-TASK', 'N5', 'LISTENING', 35, NULL, NULL, '[{"speaker":"N","ja":"女の人はどのバスに乗りますか。"},{"speaker":"M","ja":"駅へ行くバスは何番ですか。"},{"speaker":"F","ja":"三番です。でも、今は来ません。"},{"speaker":"M","ja":"二番のバスは駅へ行きますか。"},{"speaker":"F","ja":"はい、行きますが、遠い道をとおります。一番はすぐ来ます。"},{"speaker":"M","ja":"一番も駅へ行きますか。"},{"speaker":"F","ja":"はい。では、一番に乗りますね。"},{"speaker":"N","ja":"女の人はどのバスに乗りますか。"}]', 'Người dẫn: Người nữ đi xe buýt số mấy?\nNam: Xe buýt số mấy đi đến ga?\nNữ: Số ba. Nhưng bây giờ không có.\nNam: Xe số hai có đến ga không?\nNữ: Có, nhưng đi đường xa. Số một sắp tới.\nNam: Số một cũng đến ga à?\nNữ: Vâng. Vậy tôi đi xe số một.\nNgười dẫn: Người nữ đi xe buýt số mấy?', 'Bốn ô hình: (1) Xe buýt số 1; (2) Xe buýt số 2; (3) Xe buýt số 3; (4) Xe buýt số 4.', '[]', 126, 1, 'learning-path/N5/skills/N5-L-TASK-035.mp3', 'ea3d28fb1cf493a9ca1d26409d6328914d19b49af03f4ef7c7f5721c1043bfc0', 33, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-L-TASK-036', 'N5-L-TASK', 'N5', 'LISTENING', 36, NULL, NULL, '[{"speaker":"N","ja":"男の人はどのかさを持って帰りますか。"},{"speaker":"F","ja":"あなたのかさはどれですか。"},{"speaker":"M","ja":"くろいかさです。あ、ここに二本ありますね。"},{"speaker":"F","ja":"大きいほうは私のです。小さいほうがあなたのですよ。"},{"speaker":"M","ja":"そうでした。小さいくろいかさですね。"},{"speaker":"F","ja":"白いかさは田中さんのです。"},{"speaker":"M","ja":"はい、自分のだけ持って帰ります。"},{"speaker":"N","ja":"男の人はどのかさを持って帰りますか。"}]', 'Người dẫn: Người nam mang chiếc ô nào về?\nNữ: Ô của anh là cái nào?\nNam: Ô đen. A, ở đây có hai cái.\nNữ: Cái lớn là của tôi. Cái nhỏ là của anh.\nNam: Đúng rồi. Ô đen nhỏ nhỉ.\nNữ: Ô trắng là của Tanaka.\nNam: Vâng, tôi chỉ mang ô của mình.\nNgười dẫn: Người nam mang chiếc ô nào về?', 'Bốn ô hình: (1) Ô đen lớn; (2) Ô đen nhỏ; (3) Ô trắng lớn; (4) Ô trắng nhỏ.', '[]', 142, 1, 'learning-path/N5/skills/N5-L-TASK-036.mp3', '1cc80e97b02ed5b36d86e2910950d21209de54448d68fe61a7fd32081993a65a', 35, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-L-TASK-037', 'N5-L-TASK', 'N5', 'LISTENING', 37, NULL, NULL, '[{"speaker":"N","ja":"女の人はまず何を洗いますか。"},{"speaker":"M","ja":"食べたあとで、おさらを洗いましょう。"},{"speaker":"F","ja":"はい。コップもありますね。"},{"speaker":"M","ja":"コップはあとで私が洗います。おさらを先におねがいします。"},{"speaker":"F","ja":"わかりました。おさらから洗います。"},{"speaker":"M","ja":"そのあとでテーブルもふいてください。"},{"speaker":"F","ja":"はい、そうします。"},{"speaker":"N","ja":"女の人はまず何を洗いますか。"}]', 'Người dẫn: Người nữ rửa gì trước?\nNam: Ăn xong thì rửa bát đĩa nhé.\nNữ: Vâng. Còn cả cốc nữa.\nNam: Cốc lát nữa để tôi rửa. Nhờ chị rửa đĩa trước.\nNữ: Được. Tôi rửa đĩa trước.\nNam: Sau đó lau bàn nữa nhé.\nNữ: Vâng, tôi sẽ làm.\nNgười dẫn: Người nữ rửa gì trước?', 'Bốn ô hình: (1) Rửa cốc; (2) Lau bàn; (3) Rửa đĩa; (4) Rửa nồi.', '[]', 131, 1, 'learning-path/N5/skills/N5-L-TASK-037.mp3', 'f9b2f3f3bfec07edf1fd267d2cc474a3bcc879e536810511e96cbbe10bb90902', 33, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-L-TASK-038', 'N5-L-TASK', 'N5', 'LISTENING', 38, NULL, NULL, '[{"speaker":"N","ja":"男の人はどのぼうしをかいますか。"},{"speaker":"F","ja":"この白いぼうしはどうですか。"},{"speaker":"M","ja":"いいですが、少し小さいです。"},{"speaker":"F","ja":"こちらのあおいぼうしは大きいですよ。"},{"speaker":"M","ja":"あおは好きですが、もっと安いのはありますか。"},{"speaker":"F","ja":"同じ大きさでくろいのがあります。あおより安いです。"},{"speaker":"M","ja":"では、くろいのをください。"},{"speaker":"N","ja":"男の人はどのぼうしをかいますか。"}]', 'Người dẫn: Người nam mua chiếc mũ nào?\nNữ: Chiếc mũ trắng này thế nào?\nNam: Đẹp, nhưng hơi nhỏ.\nNữ: Mũ xanh này lớn hơn.\nNam: Tôi thích xanh nhưng có cái nào rẻ hơn không?\nNữ: Có mũ đen cùng cỡ, rẻ hơn mũ xanh.\nNam: Vậy cho tôi mũ đen.\nNgười dẫn: Người nam mua chiếc mũ nào?', 'Bốn ô hình: (1) Mũ trắng nhỏ; (2) Mũ xanh lớn; (3) Mũ đen nhỏ; (4) Mũ đen lớn.', '[]', 138, 1, 'learning-path/N5/skills/N5-L-TASK-038.mp3', '7c0d5d6af0ec1868c312ff28008cbd471eadc4750ad3d8d33bcb91412cf2f8c7', 32, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-L-TASK-039', 'N5-L-TASK', 'N5', 'LISTENING', 39, NULL, NULL, '[{"speaker":"N","ja":"女の人はどの食べ物を作りますか。"},{"speaker":"M","ja":"明日はみんなで食べます。ケーキを作りますか。"},{"speaker":"F","ja":"ケーキは田中さんが持って来ます。"},{"speaker":"M","ja":"では、パンを作りましょうか。"},{"speaker":"F","ja":"パンもありますよ。おにぎりを作ってください。"},{"speaker":"M","ja":"わかりました。私はおにぎりを作ります。"},{"speaker":"F","ja":"ごはんはここにあります。"},{"speaker":"N","ja":"女の人はどの食べ物を作りますか。"}]', 'Người dẫn: Người nữ làm món ăn nào?\nNam: Mai mọi người sẽ ăn cùng nhau. Làm bánh kem nhé?\nNữ: Tanaka sẽ mang bánh kem đến.\nNam: Thế tôi làm bánh mì?\nNữ: Bánh mì cũng có rồi. Hãy làm cơm nắm.\nNam: Được. Tôi sẽ làm cơm nắm.\nNữ: Cơm ở đây rồi.\nNgười dẫn: Người nữ làm món ăn nào?', 'Bốn ô hình: (1) Cơm nắm; (2) Súp; (3) Bánh kem; (4) Bánh mì.', '[]', 137, 1, 'learning-path/N5/skills/N5-L-TASK-039.mp3', 'e252299a3198f71ae0fb5d29601e5bb4b5e81fa6ac2cefbdde99d16094dfb0eb', 34, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-L-TASK-040', 'N5-L-TASK', 'N5', 'LISTENING', 40, NULL, NULL, '[{"speaker":"N","ja":"男の人はどのへやへ行きますか。"},{"speaker":"F","ja":"先生は今、どこにいますか。"},{"speaker":"M","ja":"二階の小さいへやにいました。"},{"speaker":"F","ja":"今もそこですか。"},{"speaker":"M","ja":"いいえ、三階の大きいへやへ行きました。"},{"speaker":"F","ja":"三階の小さいへやではありませんね。"},{"speaker":"M","ja":"はい。大きいへやへ行ってください。"},{"speaker":"N","ja":"男の人はどのへやへ行きますか。"}]', 'Người dẫn: Người nam đến phòng nào?\nNữ: Giáo viên bây giờ ở đâu?\nNam: Lúc nãy ở phòng nhỏ tầng hai.\nNữ: Bây giờ vẫn ở đó à?\nNam: Không, đã sang phòng lớn tầng ba.\nNữ: Không phải phòng nhỏ tầng ba nhỉ?\nNam: Đúng. Hãy đến phòng lớn.\nNgười dẫn: Người nam đến phòng nào?', 'Bốn ô hình: (1) Phòng nhỏ tầng 3; (2) Phòng lớn tầng 3; (3) Phòng nhỏ tầng 2; (4) Phòng lớn tầng 2.', '[]', 118, 1, 'learning-path/N5/skills/N5-L-TASK-040.mp3', '0cb02e500bc7fceed9fba1817de7276500f47f644d8fa013b78480481a425fa1', 29, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-L-TASK-041', 'N5-L-TASK', 'N5', 'LISTENING', 41, NULL, NULL, '[{"speaker":"N","ja":"リンさんは何色のノートを買いますか。"},{"speaker":"M","ja":"新しいノートを買いに行きましょう。"},{"speaker":"F","ja":"あかいノートが好きです。"},{"speaker":"M","ja":"あかいのは大きいのだけです。あおい小さいのもあります。"},{"speaker":"F","ja":"小さいのがほしいです。あおいのにします。"},{"speaker":"M","ja":"きいろいのは少し高いです。"},{"speaker":"F","ja":"では、あおいノートを買います。"},{"speaker":"N","ja":"リンさんは何色のノートを買いますか。"}]', 'Người dẫn: Linh mua vở màu gì?\nNam: Đi mua vở mới nhé.\nNữ: Tôi thích vở đỏ.\nNam: Vở đỏ chỉ có loại lớn. Còn vở xanh nhỏ.\nNữ: Tôi muốn loại nhỏ. Chọn xanh.\nNam: Vở vàng hơi đắt.\nNữ: Vậy tôi mua vở xanh.\nNgười dẫn: Linh mua vở màu gì?', 'Bốn ô hình: (1) Vở trắng; (2) Vở đỏ; (3) Vở xanh; (4) Vở vàng.', '[]', 140, 1, 'learning-path/N5/skills/N5-L-TASK-041.mp3', 'c3c8b3b07f6e9fe2dfd23521414a5ca3883619c257321bd42524000b5112d816', 32, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-L-TASK-042', 'N5-L-TASK', 'N5', 'LISTENING', 42, NULL, NULL, '[{"speaker":"N","ja":"男の人は何を先生にわたしますか。"},{"speaker":"F","ja":"先生にこの紙を持って行ってください。"},{"speaker":"M","ja":"テストの紙ですか。"},{"speaker":"F","ja":"いいえ、それは私が持って行きます。あなたはこの手紙を。"},{"speaker":"M","ja":"手紙ですね。ノートもいりますか。"},{"speaker":"F","ja":"ノートはいりません。"},{"speaker":"M","ja":"わかりました。手紙だけわたします。"},{"speaker":"N","ja":"男の人は何を先生にわたしますか。"}]', 'Người dẫn: Người nam đưa gì cho giáo viên?\nNữ: Hãy mang giấy này cho giáo viên.\nNam: Giấy kiểm tra à?\nNữ: Không, tôi mang cái đó. Anh mang thư này.\nNam: Lá thư nhỉ. Có cần vở không?\nNữ: Không cần vở.\nNam: Tôi hiểu rồi. Tôi chỉ đưa thư.\nNgười dẫn: Người nam đưa gì cho giáo viên?', 'Bốn ô hình: (1) Quyển sách; (2) Tờ kiểm tra; (3) Quyển vở; (4) Lá thư.', '[]', 129, 1, 'learning-path/N5/skills/N5-L-TASK-042.mp3', '11ccf81bcd6a1a518f665821228af6ebe23a935878a8bcc0bda785707f29b0e1', 33, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-L-TASK-043', 'N5-L-TASK', 'N5', 'LISTENING', 43, NULL, NULL, '[{"speaker":"N","ja":"女の人は何曜日にプールへ行きますか。"},{"speaker":"M","ja":"プールには土曜日に行きますか。"},{"speaker":"F","ja":"土曜日は仕事です。日曜日は行きます。"},{"speaker":"M","ja":"日曜日は午後から雨ですよ。"},{"speaker":"F","ja":"では、金曜日はどうですか。"},{"speaker":"M","ja":"金曜日はいい天気です。"},{"speaker":"F","ja":"わかりました。金曜日に行きます。"},{"speaker":"N","ja":"女の人は何曜日にプールへ行きますか。"}]', 'Người dẫn: Người nữ đến bể bơi vào thứ mấy?\nNam: Thứ Bảy đi bể bơi nhé?\nNữ: Thứ Bảy tôi làm việc. Chủ nhật thì được.\nNam: Chủ nhật chiều có mưa.\nNữ: Vậy thứ Sáu thì sao?\nNam: Thứ Sáu thời tiết đẹp.\nNữ: Được. Tôi đi thứ Sáu.\nNgười dẫn: Người nữ đến bể bơi vào thứ mấy?', 'Bốn ô hình: (1) Lịch thứ Sáu; (2) Lịch thứ Bảy; (3) Lịch Chủ nhật; (4) Lịch thứ Hai.', '[]', 122, 1, 'learning-path/N5/skills/N5-L-TASK-043.mp3', 'fce14fb6516a84b4c51140ae49bdf075ece46a6f8465ede74055f50b60a82af2', 32, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-L-TASK-044', 'N5-L-TASK', 'N5', 'LISTENING', 44, NULL, NULL, '[{"speaker":"N","ja":"男の人はどのいすにすわりますか。"},{"speaker":"F","ja":"こちらにすわってください。"},{"speaker":"M","ja":"まどの近くのいすですか。"},{"speaker":"F","ja":"そこは田中さんのです。ドアの近くはどうですか。"},{"speaker":"M","ja":"ドアの近くのあかいいすですね。"},{"speaker":"F","ja":"あかいのはリンさんのです。あおいのにどうぞ。"},{"speaker":"M","ja":"はい、あおいいすにすわります。"},{"speaker":"N","ja":"男の人はどのいすにすわりますか。"}]', 'Người dẫn: Người nam ngồi ghế nào?\nNữ: Hãy ngồi ở đây.\nNam: Ghế gần cửa sổ à?\nNữ: Ghế đó của Tanaka. Gần cửa ra vào thì sao?\nNam: Ghế đỏ gần cửa ra vào nhỉ.\nNữ: Ghế đỏ là của Linh. Mời ngồi ghế xanh.\nNam: Vâng, tôi ngồi ghế xanh.\nNgười dẫn: Người nam ngồi ghế nào?', 'Bốn ô hình: (1) Ghế đỏ gần cửa ra vào; (2) Ghế xanh gần cửa ra vào; (3) Ghế đỏ gần cửa sổ; (4) Ghế xanh gần cửa sổ.', '[]', 132, 1, 'learning-path/N5/skills/N5-L-TASK-044.mp3', '3714868c4fd07d89e757da23d2507b0e0eace4a83393328c69c8ccfdcfcc3bc6', 32, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-L-TASK-045', 'N5-L-TASK', 'N5', 'LISTENING', 45, NULL, NULL, '[{"speaker":"N","ja":"女の人は何をれいぞうこに入れますか。"},{"speaker":"M","ja":"食べ物をれいぞうこに入れてください。"},{"speaker":"F","ja":"パンと魚がありますね。"},{"speaker":"M","ja":"パンはテーブルにおいてください。魚を入れてください。"},{"speaker":"F","ja":"牛乳も入れますか。"},{"speaker":"M","ja":"牛乳はもう中にあります。"},{"speaker":"F","ja":"では、魚だけ入れます。"},{"speaker":"N","ja":"女の人は何をれいぞうこに入れますか。"}]', 'Người dẫn: Người nữ cho gì vào tủ lạnh?\nNam: Hãy cho thức ăn vào tủ lạnh.\nNữ: Có bánh mì và cá.\nNam: Bánh mì để trên bàn. Hãy cho cá vào.\nNữ: Có cho sữa vào nữa không?\nNam: Sữa đã ở trong đó.\nNữ: Vậy tôi chỉ cho cá vào.\nNgười dẫn: Người nữ cho gì vào tủ lạnh?', 'Bốn ô hình: (1) Bánh mì; (2) Hộp sữa; (3) Con cá; (4) Chai trà.', '[]', 123, 1, 'learning-path/N5/skills/N5-L-TASK-045.mp3', 'e841a779f2d6fc0d003f98cae56dabc976c1b41f3566e16ff68121e7f302539f', 30, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-L-TASK-046', 'N5-L-TASK', 'N5', 'LISTENING', 46, NULL, NULL, '[{"speaker":"N","ja":"男の人はどの写真を見せますか。"},{"speaker":"F","ja":"旅行の写真を見せてください。"},{"speaker":"M","ja":"五枚あります。全部見ますか。"},{"speaker":"F","ja":"今日は時間がありません。二枚だけおねがいします。"},{"speaker":"M","ja":"この三枚は山の写真です。二枚は海です。"},{"speaker":"F","ja":"海の写真が見たいです。"},{"speaker":"M","ja":"わかりました。海の二枚を見せます。"},{"speaker":"N","ja":"男の人はどの写真を見せますか。"}]', 'Người dẫn: Người nam cho xem ảnh nào?\nNữ: Cho tôi xem ảnh chuyến đi.\nNam: Có năm tấm. Xem hết không?\nNữ: Hôm nay không có thời gian. Hai tấm thôi.\nNam: Ba tấm này chụp núi, hai tấm chụp biển.\nNữ: Tôi muốn xem ảnh biển.\nNam: Được. Tôi cho xem hai ảnh biển.\nNgười dẫn: Người nam cho xem ảnh nào?', 'Bốn ô hình: (1) Ba ảnh biển; (2) Hai ảnh núi; (3) Ba ảnh núi; (4) Hai ảnh biển.', '[]', 129, 1, 'learning-path/N5/skills/N5-L-TASK-046.mp3', '00e9b71c70dfc276757681fbf7c07aebc81f2602dc97f4aa0aacd37b2d29f576', 34, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-L-TASK-047', 'N5-L-TASK', 'N5', 'LISTENING', 47, NULL, NULL, '[{"speaker":"N","ja":"女の人はどのくだものを食べますか。"},{"speaker":"M","ja":"デザートにバナナを食べますか。"},{"speaker":"F","ja":"バナナは朝食べました。"},{"speaker":"M","ja":"りんごもありますよ。"},{"speaker":"F","ja":"りんごは大きいです。みかんはありますか。"},{"speaker":"M","ja":"はい、小さいみかんがあります。"},{"speaker":"F","ja":"では、みかんを一つ食べます。"},{"speaker":"N","ja":"女の人はどのくだものを食べますか。"}]', 'Người dẫn: Người nữ ăn loại quả nào?\nNam: Ăn chuối tráng miệng không?\nNữ: Sáng tôi ăn chuối rồi.\nNam: Có cả táo.\nNữ: Táo lớn quá. Có quýt không?\nNam: Có quýt nhỏ.\nNữ: Vậy tôi ăn một quả quýt.\nNgười dẫn: Người nữ ăn loại quả nào?', 'Bốn ô hình: (1) Quả quýt; (2) Chuối và táo; (3) Quả chuối; (4) Quả táo.', '[]', 119, 1, 'learning-path/N5/skills/N5-L-TASK-047.mp3', '223d39d658d153577bc2b14b5c871b3347aa3ddc704d9cd562f0c84ae510bf97', 29, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-L-TASK-048', 'N5-L-TASK', 'N5', 'LISTENING', 48, NULL, NULL, '[{"speaker":"N","ja":"男の人はどこにくつをおきますか。"},{"speaker":"F","ja":"そのくつをここにおかないでください。"},{"speaker":"M","ja":"ドアの右ですか。"},{"speaker":"F","ja":"右にはかさがあります。左のたなにおいてください。"},{"speaker":"M","ja":"左の上ですか、下ですか。"},{"speaker":"F","ja":"下にはくつがあります。上においてください。"},{"speaker":"M","ja":"はい、ドアの左の上ですね。"},{"speaker":"N","ja":"男の人はどこにくつをおきますか。"}]', 'Người dẫn: Người nam đặt giày ở đâu?\nNữ: Đừng để giày ở đây.\nNam: Bên phải cửa à?\nNữ: Bên phải có ô. Hãy để lên kệ bên trái.\nNam: Bên trái ở trên hay dưới?\nNữ: Bên dưới đã có giày. Hãy để phía trên.\nNam: Vâng, phía trên bên trái cửa.\nNgười dẫn: Người nam đặt giày ở đâu?', 'Bốn ô hình: (1) Dưới kệ bên phải cửa; (2) Trên kệ bên trái cửa; (3) Dưới kệ bên trái cửa; (4) Trên kệ bên phải cửa.', '[]', 128, 1, 'learning-path/N5/skills/N5-L-TASK-048.mp3', 'e37beb10ec9094ef0c2bae27edebd17c82b160efe148a013715baecfd4c5c3b6', 33, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-L-TASK-049', 'N5-L-TASK', 'N5', 'LISTENING', 49, NULL, NULL, '[{"speaker":"N","ja":"男の人は何を買ってから帰りますか。"},{"speaker":"F","ja":"帰りに何か買いますか。"},{"speaker":"M","ja":"水と新聞を買います。"},{"speaker":"F","ja":"新聞は家にありますよ。水はもうありません。"},{"speaker":"M","ja":"では、水を買います。お茶もいりますか。"},{"speaker":"F","ja":"お茶はまだあります。"},{"speaker":"M","ja":"わかりました。水だけ買います。"},{"speaker":"N","ja":"男の人は何を買ってから帰りますか。"}]', 'Người dẫn: Người nam mua gì rồi về?\nNữ: Lúc về anh mua gì không?\nNam: Tôi định mua nước và báo.\nNữ: Báo có ở nhà. Nước hết rồi.\nNam: Vậy tôi mua nước. Có cần trà không?\nNữ: Trà vẫn còn.\nNam: Tôi hiểu rồi. Chỉ mua nước.\nNgười dẫn: Người nam mua gì rồi về?', 'Bốn ô hình: (1) Chai trà; (2) Cốc cà phê; (3) Chai nước; (4) Tờ báo.', '[]', 120, 1, 'learning-path/N5/skills/N5-L-TASK-049.mp3', 'ea97e926f3faca7ac91e684e6969c7d7e2301b8517cb930fd7cc53caa0cfffce', 32, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-L-TASK-050', 'N5-L-TASK', 'N5', 'LISTENING', 50, NULL, NULL, '[{"speaker":"N","ja":"女の人は何時に家を出ますか。"},{"speaker":"M","ja":"明日の電車は八時半ですね。"},{"speaker":"F","ja":"はい。駅まで三十分かかります。"},{"speaker":"M","ja":"七時に家を出ますか。"},{"speaker":"F","ja":"七時だと少し早いです。七時半に出ましょう。"},{"speaker":"M","ja":"朝ごはんは七時までに食べてください。"},{"speaker":"F","ja":"はい、七時半に出ます。"},{"speaker":"N","ja":"女の人は何時に家を出ますか。"}]', 'Người dẫn: Người nữ ra khỏi nhà lúc mấy giờ?\nNam: Tàu ngày mai lúc tám giờ rưỡi nhỉ.\nNữ: Vâng. Đến ga mất ba mươi phút.\nNam: Ra khỏi nhà lúc bảy giờ nhé?\nNữ: Bảy giờ hơi sớm. Đi lúc bảy rưỡi.\nNam: Hãy ăn sáng xong trước bảy giờ.\nNữ: Vâng, tôi đi lúc bảy rưỡi.\nNgười dẫn: Người nữ ra khỏi nhà lúc mấy giờ?', 'Bốn ô hình: (1) Đồng hồ 8 giờ; (2) Đồng hồ 8 giờ 30; (3) Đồng hồ 7 giờ; (4) Đồng hồ 7 giờ 30.', '[]', 116, 1, 'learning-path/N5/skills/N5-L-TASK-050.mp3', 'be51bb1741be7af92639d7953808d50ef81399b8ce9274ed4596d6b89679479d', 32, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-L-TASK-051', 'N5-L-TASK', 'N5', 'LISTENING', 51, NULL, NULL, '[{"speaker":"N","ja":"男の人は何をかべにかけますか。"},{"speaker":"F","ja":"へやのかべがさびしいですね。"},{"speaker":"M","ja":"大きい写真をかけましょうか。"},{"speaker":"F","ja":"写真はテーブルの上がいいです。"},{"speaker":"M","ja":"では、この時計をかけますか。"},{"speaker":"F","ja":"時計はドアの近くにあります。ここには絵をおねがいします。"},{"speaker":"M","ja":"はい、絵をかけます。"},{"speaker":"N","ja":"男の人は何をかべにかけますか。"}]', 'Người dẫn: Người nam treo gì lên tường?\nNữ: Tường phòng trống quá nhỉ.\nNam: Treo ảnh lớn nhé?\nNữ: Ảnh để trên bàn thì hay hơn.\nNam: Vậy treo đồng hồ này?\nNữ: Đồng hồ ở gần cửa rồi. Nhờ anh treo tranh ở đây.\nNam: Vâng, tôi treo tranh.\nNgười dẫn: Người nam treo gì lên tường?', 'Bốn ô hình: (1) Bức tranh; (2) Gương; (3) Ảnh; (4) Đồng hồ.', '[]', 125, 1, 'learning-path/N5/skills/N5-L-TASK-051.mp3', '7d99aaf2553982951b75a6d63009de834e930ba794fca750e4ae5fc09e3ae158', 31, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-L-TASK-052', 'N5-L-TASK', 'N5', 'LISTENING', 52, NULL, NULL, '[{"speaker":"N","ja":"女の人はこれから何をかばんに入れますか。"},{"speaker":"M","ja":"海に行きます。かばんに本を入れましたか。"},{"speaker":"F","ja":"はい。水も入れました。"},{"speaker":"M","ja":"サンドイッチはどうですか。"},{"speaker":"F","ja":"まだです。今入れます。"},{"speaker":"M","ja":"ぼうしはかぶってくださいね。"},{"speaker":"F","ja":"はい。サンドイッチをかばんに入れます。"},{"speaker":"N","ja":"女の人はこれから何をかばんに入れますか。"}]', 'Người dẫn: Người nữ sắp cho gì vào túi?\nNam: Đi biển nhé. Chị đã cho sách vào túi chưa?\nNữ: Rồi. Tôi cũng cho nước vào.\nNam: Còn sandwich?\nNữ: Chưa. Tôi cho vào ngay.\nNam: Nhớ đội mũ nhé.\nNữ: Vâng. Tôi cho sandwich vào túi.\nNgười dẫn: Người nữ sắp cho gì vào túi?', 'Bốn ô hình: (1) Chai nước; (2) Sandwich; (3) Mũ; (4) Sách.', '[]', 128, 1, 'learning-path/N5/skills/N5-L-TASK-052.mp3', '937c292b2feeed72ed6c18a85f03701b7603fcf1c43ac3b2efb44effb60b8242', 33, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-L-TASK-053', 'N5-L-TASK', 'N5', 'LISTENING', 53, NULL, NULL, '[{"speaker":"N","ja":"男の人は何色の本を読みますか。"},{"speaker":"F","ja":"このあかい本はどうですか。"},{"speaker":"M","ja":"それは先週読みました。"},{"speaker":"F","ja":"あおい本は新しいですよ。"},{"speaker":"M","ja":"あおいのは大きいです。小さい本がいいです。"},{"speaker":"F","ja":"こちらのみどりの本は小さいです。"},{"speaker":"M","ja":"では、みどりの本を読みます。"},{"speaker":"N","ja":"男の人は何色の本を読みますか。"}]', 'Người dẫn: Người nam đọc sách màu gì?\nNữ: Cuốn sách đỏ này thế nào?\nNam: Tôi đọc tuần trước rồi.\nNữ: Cuốn xanh mới đấy.\nNam: Cuốn xanh to. Tôi muốn sách nhỏ.\nNữ: Cuốn xanh lá này nhỏ.\nNam: Vậy tôi đọc sách xanh lá.\nNgười dẫn: Người nam đọc sách màu gì?', 'Bốn ô hình: (1) Sách đỏ; (2) Sách xanh lam; (3) Sách xanh lá; (4) Sách trắng.', '[]', 117, 1, 'learning-path/N5/skills/N5-L-TASK-053.mp3', 'd1ea9b02fb781db40dcd46263f84e0256af2c703481889d9fc3a0edbedfd812e', 31, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-L-TASK-054', 'N5-L-TASK', 'N5', 'LISTENING', 54, NULL, NULL, '[{"speaker":"N","ja":"女の人は何を先に作りますか。"},{"speaker":"M","ja":"今夜はごはんとスープを作ります。"},{"speaker":"F","ja":"ごはんを先に作りましょうか。"},{"speaker":"M","ja":"ごはんはもうあります。スープをおねがいします。"},{"speaker":"F","ja":"スープの中に肉を入れますか。"},{"speaker":"M","ja":"肉はありません。やさいを入れてください。"},{"speaker":"F","ja":"わかりました。スープから作ります。"},{"speaker":"N","ja":"女の人は何を先に作りますか。"}]', 'Người dẫn: Người nữ nấu gì trước?\nNam: Tối nay làm cơm và súp.\nNữ: Tôi làm cơm trước nhé?\nNam: Cơm có rồi. Nhờ chị làm súp.\nNữ: Cho thịt vào súp à?\nNam: Không có thịt. Hãy cho rau.\nNữ: Tôi hiểu. Tôi làm súp trước.\nNgười dẫn: Người nữ nấu gì trước?', 'Bốn ô hình: (1) Đĩa thịt; (2) Đĩa salad; (3) Nồi cơm; (4) Bát súp.', '[]', 132, 1, 'learning-path/N5/skills/N5-L-TASK-054.mp3', '14fd385ca8c9f3605f92d61ef8dd22a5497305ca3c68a7b8ccc0d66c930d1d8f', 33, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-L-TASK-055', 'N5-L-TASK', 'N5', 'LISTENING', 55, NULL, NULL, '[{"speaker":"N","ja":"男の人はどのえんぴつを使いますか。"},{"speaker":"F","ja":"テストにこのえんぴつを使ってください。"},{"speaker":"M","ja":"あかいえんぴつですか。"},{"speaker":"F","ja":"いいえ、あかいのは先生のです。あおいのを。"},{"speaker":"M","ja":"あおいのは短いですが、いいですか。"},{"speaker":"F","ja":"長いあおいのもありますよ。"},{"speaker":"M","ja":"では、長いあおいえんぴつを使います。"},{"speaker":"N","ja":"男の人はどのえんぴつを使いますか。"}]', 'Người dẫn: Người nam dùng cây bút chì nào?\nNữ: Hãy dùng bút chì này để làm bài.\nNam: Bút chì đỏ ạ?\nNữ: Không, bút đỏ của giáo viên. Dùng bút xanh.\nNam: Bút xanh ngắn, được không?\nNữ: Có cả bút xanh dài.\nNam: Vậy tôi dùng bút xanh dài.\nNgười dẫn: Người nam dùng cây bút chì nào?', 'Bốn ô hình: (1) Bút chì xanh dài; (2) Bút chì đỏ dài; (3) Bút chì đỏ ngắn; (4) Bút chì xanh ngắn.', '[]', 133, 1, 'learning-path/N5/skills/N5-L-TASK-055.mp3', '6332dbf1d2e303a1a3ddba804a4544d4a4465698f3d4437b50f918d69e33cb65', 32, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-L-TASK-056', 'N5-L-TASK', 'N5', 'LISTENING', 56, NULL, NULL, '[{"speaker":"N","ja":"女の人はどこで昼ごはんを食べますか。"},{"speaker":"M","ja":"今日は学校の食堂で食べますか。"},{"speaker":"F","ja":"食堂はお休みです。"},{"speaker":"M","ja":"駅のレストランはどうですか。"},{"speaker":"F","ja":"駅は遠いです。学校の近くの店がいいです。"},{"speaker":"M","ja":"あのパンの店ですか。"},{"speaker":"F","ja":"はい、そこで食べます。"},{"speaker":"N","ja":"女の人はどこで昼ごはんを食べますか。"}]', 'Người dẫn: Người nữ ăn trưa ở đâu?\nNam: Hôm nay ăn ở nhà ăn trường nhé?\nNữ: Nhà ăn nghỉ.\nNam: Nhà hàng ở ga thì sao?\nNữ: Ga xa. Tôi thích quán gần trường.\nNam: Quán bánh mì kia à?\nNữ: Vâng, tôi ăn ở đó.\nNgười dẫn: Người nữ ăn trưa ở đâu?', 'Bốn ô hình: (1) Nhà hàng ở ga; (2) Tiệm bánh gần trường; (3) Ngôi nhà; (4) Nhà ăn trường.', '[]', 115, 1, 'learning-path/N5/skills/N5-L-TASK-056.mp3', '367db78dbfc2148193643e648fdf3949583f9936ea130120473207e43f8df8c3', 30, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-L-TASK-057', 'N5-L-TASK', 'N5', 'LISTENING', 57, NULL, NULL, '[{"speaker":"N","ja":"男の人はどのどうぶつにごはんをあげますか。"},{"speaker":"F","ja":"どうぶつにごはんをあげてください。"},{"speaker":"M","ja":"犬とねこ、どちらですか。"},{"speaker":"F","ja":"犬はもう食べました。ねこはまだです。"},{"speaker":"M","ja":"魚もここにいますね。"},{"speaker":"F","ja":"魚には私があげます。"},{"speaker":"M","ja":"では、ねこにあげます。"},{"speaker":"N","ja":"男の人はどのどうぶつにごはんをあげますか。"}]', 'Người dẫn: Người nam cho con vật nào ăn?\nNữ: Hãy cho con vật ăn.\nNam: Chó hay mèo?\nNữ: Chó ăn rồi. Mèo chưa.\nNam: Ở đây còn có cá.\nNữ: Cá để tôi cho ăn.\nNam: Vậy tôi cho mèo ăn.\nNgười dẫn: Người nam cho con vật nào ăn?', 'Bốn ô hình: (1) Chó và mèo; (2) Con chó; (3) Con mèo; (4) Con cá.', '[]', 120, 1, 'learning-path/N5/skills/N5-L-TASK-057.mp3', '5b525ac06a09cde42d6d1cf10e301785eea9e6979bdc5faea2dc5deaadb338af', 31, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-L-TASK-058', 'N5-L-TASK', 'N5', 'LISTENING', 58, NULL, NULL, '[{"speaker":"N","ja":"女の人はどのはこを持って行きますか。"},{"speaker":"M","ja":"このはこを田中さんに持って行ってください。"},{"speaker":"F","ja":"白い大きいはこですか。"},{"speaker":"M","ja":"それはおもいです。あおい小さいはこです。"},{"speaker":"F","ja":"あおい大きいのもありますね。"},{"speaker":"M","ja":"大きいのではありません。小さいほうです。"},{"speaker":"F","ja":"わかりました。あおい小さいはこですね。"},{"speaker":"N","ja":"女の人はどのはこを持って行きますか。"}]', 'Người dẫn: Người nữ mang chiếc hộp nào đi?\nNam: Hãy mang hộp này cho Tanaka.\nNữ: Hộp trắng lớn à?\nNam: Nó nặng. Hộp xanh nhỏ.\nNữ: Có cả hộp xanh lớn.\nNam: Không phải hộp lớn. Loại nhỏ.\nNữ: Vâng, hộp xanh nhỏ.\nNgười dẫn: Người nữ mang chiếc hộp nào đi?', 'Bốn ô hình: (1) Hộp trắng lớn; (2) Hộp trắng nhỏ; (3) Hộp xanh lớn; (4) Hộp xanh nhỏ.', '[]', 141, 1, 'learning-path/N5/skills/N5-L-TASK-058.mp3', '2ef4fee1ce17c5b0450fd02a2d37fad7109f609211d1b9a441adff0b22525064', 33, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-L-TASK-059', 'N5-L-TASK', 'N5', 'LISTENING', 59, NULL, NULL, '[{"speaker":"N","ja":"男の人は何を先にかえしますか。"},{"speaker":"F","ja":"友だちに借りたものをかえしましょう。"},{"speaker":"M","ja":"本とカメラを借りました。"},{"speaker":"F","ja":"本は今日いりますから、先にカメラをかえしてください。"},{"speaker":"M","ja":"カメラはこのかばんの中ですね。"},{"speaker":"F","ja":"はい。本はあしたでいいです。"},{"speaker":"M","ja":"では、まずカメラをかえします。"},{"speaker":"N","ja":"男の人は何を先にかえしますか。"}]', 'Người dẫn: Người nam trả gì trước?\nNữ: Hãy trả đồ đã mượn bạn.\nNam: Tôi mượn sách và máy ảnh.\nNữ: Sách hôm nay còn cần, hãy trả máy ảnh trước.\nNam: Máy ảnh trong túi này nhỉ.\nNữ: Vâng. Sách ngày mai trả cũng được.\nNam: Vậy trước tiên tôi trả máy ảnh.\nNgười dẫn: Người nam trả gì trước?', 'Bốn ô hình: (1) Máy ảnh; (2) Chiếc túi; (3) Quyển vở; (4) Quyển sách.', '[]', 130, 1, 'learning-path/N5/skills/N5-L-TASK-059.mp3', '4c8feffd82c9d067c5ad8b728073ae9d285b90d1050ef6095a59966dd32d17b7', 31, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-L-TASK-060', 'N5-L-TASK', 'N5', 'LISTENING', 60, NULL, NULL, '[{"speaker":"N","ja":"女の人はどのケーキを食べますか。"},{"speaker":"M","ja":"チョコレートのケーキを食べますか。"},{"speaker":"F","ja":"今日はチョコレートは食べません。"},{"speaker":"M","ja":"白いケーキはどうですか。"},{"speaker":"F","ja":"白いのは大きいですね。小さいのがありますか。"},{"speaker":"M","ja":"小さいきいろいケーキがあります。"},{"speaker":"F","ja":"では、きいろいのを食べます。"},{"speaker":"N","ja":"女の人はどのケーキを食べますか。"}]', 'Người dẫn: Người nữ ăn chiếc bánh nào?\nNam: Ăn bánh kem sô cô la nhé?\nNữ: Hôm nay tôi không ăn sô cô la.\nNam: Bánh trắng thì sao?\nNữ: Bánh trắng to quá. Có bánh nhỏ không?\nNam: Có bánh nhỏ màu vàng.\nNữ: Vậy tôi ăn bánh vàng.\nNgười dẫn: Người nữ ăn chiếc bánh nào?', 'Bốn ô hình: (1) Bánh vàng lớn; (2) Bánh vàng nhỏ; (3) Bánh trắng lớn; (4) Bánh trắng nhỏ.', '[]', 129, 1, 'learning-path/N5/skills/N5-L-TASK-060.mp3', '110c5dd38648e16f6e051dc1b0652243f5895bc04c2fef4f95ddc13f5eb5637f', 30, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-L-TASK-061', 'N5-L-TASK', 'N5', 'LISTENING', 61, NULL, NULL, '[{"speaker":"N","ja":"女の人は何を持って行きますか。"},{"speaker":"M","ja":"あした、学校で日本語の会があります。"},{"speaker":"F","ja":"じゃあ、ノートを持って行きます。"},{"speaker":"M","ja":"ノートはありますか。"},{"speaker":"F","ja":"はい。でも、えんぴつもいりますね。"},{"speaker":"M","ja":"えんぴつはぼくが持って行きます。"},{"speaker":"F","ja":"では、わたしはノートを持って行きます。"},{"speaker":"N","ja":"女の人は何を持って行きますか。"}]', 'Người dẫn hỏi người nữ mang gì. Hai người bàn về buổi gặp tiếng Nhật ở trường; nữ mang vở, nam mang bút chì.', 'Bốn ô hình: (1) Quyển vở; (2) Bút chì; (3) Cục tẩy; (4) Quyển sách.', '[]', 126, 1, 'learning-path/N5/skills/N5-L-TASK-061.mp3', 'ba7be5636f5d39b397d4901d6d13a9f987a7f9e79b86c5e168dae17f4dad9b00', 30, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-L-TASK-062', 'N5-L-TASK', 'N5', 'LISTENING', 62, NULL, NULL, '[{"speaker":"N","ja":"男の人はこれから何をしますか。"},{"speaker":"F","ja":"駅までいっしょに行きましょう。"},{"speaker":"M","ja":"いいですね。バスで行きますか。"},{"speaker":"F","ja":"雨ですから、タクシーにしましょう。"},{"speaker":"M","ja":"でも、タクシーは高いですよ。"},{"speaker":"F","ja":"駅は近いですから、歩きましょう。"},{"speaker":"M","ja":"そうですね。かさを持って歩きます。"},{"speaker":"N","ja":"男の人はこれから何をしますか。"}]', 'Hai người định đi ga. Trời mưa nên cân nhắc taxi, nhưng ga gần; cuối cùng họ đi bộ và mang ô.', 'Bốn ô hình: (1) Người đi bộ cầm ô; (2) Người đi xe buýt; (3) Người đi taxi; (4) Người đi xe đạp.', '[]', 124, 1, 'learning-path/N5/skills/N5-L-TASK-062.mp3', '26ee98d07a7917e419f3bf5e6cd2281fe1351c76d3521d355e32cdc1cb1ea9bc', 31, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-L-TASK-063', 'N5-L-TASK', 'N5', 'LISTENING', 63, NULL, NULL, '[{"speaker":"N","ja":"女の人はこれから何をしますか。"},{"speaker":"M","ja":"このへや、ちょっと寒いですね。"},{"speaker":"F","ja":"まどがあいていますよ。"},{"speaker":"M","ja":"そうですね。わたしがまどをしめましょうか。"},{"speaker":"F","ja":"おねがいします。そのあと、エアコンをつけてください。"},{"speaker":"M","ja":"はい。まどをしめて、エアコンをつけます。"},{"speaker":"F","ja":"ありがとう。わたしはお茶を持って来ます。"},{"speaker":"N","ja":"女の人はこれから何をしますか。"}]', 'Phòng hơi lạnh. Người nam đóng cửa sổ và bật máy lạnh; người nữ mang trà đến.', 'Bốn ô hình: (1) Người nữ mang trà; (2) Người nữ đóng cửa sổ; (3) Người nữ bật máy lạnh; (4) Người nữ mở cửa sổ.', '[]', 143, 1, 'learning-path/N5/skills/N5-L-TASK-063.mp3', 'b222789bf45d11cb9151ac87683c05639b108e42ca09e0b0adc55e260996027e', 35, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-L-TASK-064', 'N5-L-TASK', 'N5', 'LISTENING', 64, NULL, NULL, '[{"speaker":"N","ja":"男の人は何を買いますか。"},{"speaker":"F","ja":"スーパーで牛乳を買って来てください。"},{"speaker":"M","ja":"牛乳ですね。パンも買いますか。"},{"speaker":"F","ja":"パンは家にあります。たまごがありません。"},{"speaker":"M","ja":"じゃあ、牛乳とたまごを買います。"},{"speaker":"F","ja":"牛乳は大きいものをおねがいします。"},{"speaker":"M","ja":"わかりました。大きい牛乳とたまごですね。"},{"speaker":"N","ja":"男の人は何を買いますか。"}]', 'Người nữ nhờ mua sữa hộp lớn và trứng; bánh mì đã có ở nhà.', 'Bốn ô hình: (1) Sữa lớn và bánh mì; (2) Sữa lớn và trứng; (3) Sữa nhỏ và trứng; (4) Sữa nhỏ và bánh mì.', '[]', 130, 1, 'learning-path/N5/skills/N5-L-TASK-064.mp3', 'efe2bd9db9907372ab0a4c7825483dde310ca0235b9c6565df5aaeab603ee627', 33, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-L-TASK-065', 'N5-L-TASK', 'N5', 'LISTENING', 65, NULL, NULL, '[{"speaker":"N","ja":"二人はこれから何をしますか。"},{"speaker":"M","ja":"図書館で本を読みませんか。"},{"speaker":"F","ja":"いいですね。でも、先に昼ごはんを食べたいです。"},{"speaker":"M","ja":"では、駅の前でごはんを食べましょう。"},{"speaker":"F","ja":"その店は今日は休みですよ。"},{"speaker":"M","ja":"そうですか。じゃあ、駅の中の店に行きましょう。"},{"speaker":"F","ja":"はい。ごはんのあとで図書館へ行きます。"},{"speaker":"N","ja":"二人はこれから何をしますか。"}]', 'Hai người sẽ ăn trưa ở quán trong ga trước, rồi đến thư viện. Quán trước ga đang nghỉ.', 'Bốn ô hình: (1) Hai người đi thư viện ngay; (2) Hai người ăn ở quán trước ga; (3) Hai người ăn ở quán trong ga; (4) Hai người về nhà ăn.', '[]', 137, 1, 'learning-path/N5/skills/N5-L-TASK-065.mp3', '15c226abffbcaed7064f051162abfbff9bb674fc6eca62cb343c65fc16844643', 34, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-L-TASK-066', 'N5-L-TASK', 'N5', 'LISTENING', 66, NULL, NULL, '[{"speaker":"N","ja":"女の人は何時の電車に乗りますか。"},{"speaker":"F","ja":"駅に着きました。電車は何時ですか。"},{"speaker":"M","ja":"三時の電車はもう行きました。"},{"speaker":"F","ja":"次は三時半ですね。"},{"speaker":"M","ja":"はい。でも、四時の電車もありますよ。"},{"speaker":"F","ja":"三時半でいいです。きっぷを買って来ます。"},{"speaker":"M","ja":"では、ここで待っています。"},{"speaker":"N","ja":"女の人は何時の電車に乗りますか。"}]', 'Chuyến ba giờ đã đi; người nữ chọn chuyến ba giờ rưỡi và đi mua vé.', 'Bốn ô hình: (1) Tàu 3:00; (2) Tàu 4:00; (3) Tàu 4:30; (4) Tàu 3:30.', '[]', 123, 1, 'learning-path/N5/skills/N5-L-TASK-066.mp3', 'd887954a17a2033d2be5fc98d5d97e101536f862ab74e0ab6bbb9f57a7996e4f', 33, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-L-TASK-067', 'N5-L-TASK', 'N5', 'LISTENING', 67, NULL, NULL, '[{"speaker":"N","ja":"男の人は何を先にしますか。"},{"speaker":"F","ja":"出かける前に、へやをそうじしてください。"},{"speaker":"M","ja":"そうじの前に、せんたくをしてもいいですか。"},{"speaker":"F","ja":"せんたくはあとでいいですよ。"},{"speaker":"M","ja":"じゃあ、まずつくえの上をきれいにします。"},{"speaker":"F","ja":"本は本だなの中に入れてください。"},{"speaker":"M","ja":"わかりました。本をしまってから、そうじします。"},{"speaker":"N","ja":"男の人は何を先にしますか。"}]', 'Người nam sẽ dọn bàn và cất sách trước; giặt đồ để sau.', 'Bốn ô hình: (1) Người nam dọn bàn; (2) Người nam giặt đồ; (3) Người nam đi ra ngoài; (4) Người nam đọc sách.', '[]', 140, 1, 'learning-path/N5/skills/N5-L-TASK-067.mp3', '5a1c385e404e05f43b5d87d60f263305dc7899a347cd52e8d3e633d44977a951', 33, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-L-TASK-068', 'N5-L-TASK', 'N5', 'LISTENING', 68, NULL, NULL, '[{"speaker":"N","ja":"女の人は何を食べますか。"},{"speaker":"M","ja":"昼ごはんにカレーを食べませんか。"},{"speaker":"F","ja":"いいですね。でも、からいものは少しにがてです。"},{"speaker":"M","ja":"この店にはカレーと魚があります。"},{"speaker":"F","ja":"魚はどうですか。"},{"speaker":"M","ja":"魚はからくないですよ。ごはんもつきます。"},{"speaker":"F","ja":"では、魚とごはんをください。"},{"speaker":"N","ja":"女の人は何を食べますか。"}]', 'Người nữ không thích đồ cay nên chọn cá và cơm thay vì cà ri.', 'Bốn ô hình: (1) Cà ri; (2) Cá và cơm; (3) Cá và bánh mì; (4) Cơm và cà ri.', '[]', 121, 1, 'learning-path/N5/skills/N5-L-TASK-068.mp3', '432aca92ac685df55aa613dd2f317007200288d88faa5c94d8c60de43b10fa8a', 31, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-L-TASK-069', 'N5-L-TASK', 'N5', 'LISTENING', 69, NULL, NULL, '[{"speaker":"N","ja":"男の人はこれからどこへ行きますか。"},{"speaker":"F","ja":"郵便局へ行きたいです。"},{"speaker":"M","ja":"駅の前の郵便局ですか。"},{"speaker":"F","ja":"いいえ、そこは今日休みです。"},{"speaker":"M","ja":"じゃあ、銀行のとなりの郵便局はどうですか。"},{"speaker":"F","ja":"そこはあいています。手紙を出したいです。"},{"speaker":"M","ja":"わかりました。銀行のとなりへ行きましょう。"},{"speaker":"N","ja":"男の人はこれからどこへ行きますか。"}]', 'Bưu điện trước ga nghỉ hôm nay; họ đến bưu điện cạnh ngân hàng để gửi thư.', 'Bốn ô hình: (1) Bưu điện trước ga; (2) Ngân hàng; (3) Bưu điện cạnh ngân hàng; (4) Nhà ga.', '[]', 132, 1, 'learning-path/N5/skills/N5-L-TASK-069.mp3', '3c339b38f3b320d3df488ed810cfec29e6246e641bbac189fb496a8026845d1f', 33, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-L-TASK-070', 'N5-L-TASK', 'N5', 'LISTENING', 70, NULL, NULL, '[{"speaker":"N","ja":"女の人は何を買いますか。"},{"speaker":"M","ja":"花を買いましょうか。"},{"speaker":"F","ja":"はい。母のたん生日ですから。"},{"speaker":"M","ja":"あかい花と白い花があります。"},{"speaker":"F","ja":"母は白い花が好きです。"},{"speaker":"M","ja":"小さい花もありますよ。"},{"speaker":"F","ja":"では、白い花を買います。"},{"speaker":"N","ja":"女の人は何を買いますか。"}]', 'Người nữ mua hoa trắng làm quà sinh nhật mẹ; có hoa đỏ và hoa trắng.', 'Bốn ô hình: (1) Hoa trắng; (2) Hoa đỏ; (3) Hoa vàng; (4) Hoa xanh.', '[]', 96, 1, 'learning-path/N5/skills/N5-L-TASK-070.mp3', '51ad836b4e93b87de5112afa31bb356488eb3f2149e903194cfeef4a1b494280', 27, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-L-TASK-071', 'N5-L-TASK', 'N5', 'LISTENING', 71, NULL, NULL, '[{"speaker":"N","ja":"二人は何をしますか。"},{"speaker":"F","ja":"日曜日に海へ行きませんか。"},{"speaker":"M","ja":"いいですね。何時に出ますか。"},{"speaker":"F","ja":"朝は少し早いですね。"},{"speaker":"M","ja":"では、九時に駅で会いましょう。"},{"speaker":"F","ja":"駅までバスで行きますか。"},{"speaker":"M","ja":"はい。バスで駅へ行きます。"},{"speaker":"N","ja":"二人は何をしますか。"}]', 'Hai người hẹn gặp ở ga lúc 9 giờ Chủ nhật rồi đi biển bằng xe buýt.', 'Bốn ô hình: (1) (2) Hai người đi tàu ra biển; (2) (1) Hai người đi xe buýt ra ga; (3) (3) Hai người đi bộ tới trường; (4) (4) Hai người đi taxi tới biển.', '[]', 97, 1, 'learning-path/N5/skills/N5-L-TASK-071.mp3', '6b9a66beb2ceb3c1ee352e676d1cc229d1d7364625bc4268f2ad44c259c4801c', 27, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-L-TASK-072', 'N5-L-TASK', 'N5', 'LISTENING', 72, NULL, NULL, '[{"speaker":"N","ja":"男の人は何をしますか。"},{"speaker":"M","ja":"先生にこの本をかえします。"},{"speaker":"F","ja":"先生は今、教室にいますか。"},{"speaker":"M","ja":"いいえ、教室にはいません。"},{"speaker":"F","ja":"図書館にいるとおもいますよ。"},{"speaker":"M","ja":"そうですか。図書館へ行って来ます。"},{"speaker":"F","ja":"本をわすれないでくださいね。"},{"speaker":"N","ja":"男の人は何をしますか。"}]', 'Người nam cần trả sách cho giáo viên. Thầy không ở lớp, nên anh đến thư viện tìm thầy.', 'Bốn ô hình: (1) (3) Nam đi nhà ga; (2) (2) Nam vào lớp; (3) (1) Nam đi thư viện cầm sách; (4) (4) Nam về nhà.', '[]', 106, 1, 'learning-path/N5/skills/N5-L-TASK-072.mp3', '7947ce0b4e1692ccd0c57ac6333e18237d026d1c46544d06f302639905e5fe4b', 29, 'AI_CHECKED', 1, '19d0f58e5bad'),
('N5-L-TASK-073', 'N5-L-TASK', 'N5', 'LISTENING', 73, NULL, NULL, '[{"speaker":"N","ja":"女の人はどのかばんを使いますか。"},{"speaker":"M","ja":"旅行のかばんはどれにしますか。"},{"speaker":"F","ja":"このくろいかばんはどうですか。"},{"speaker":"M","ja":"少し小さいですね。"},{"speaker":"F","ja":"じゃあ、あの大きいかばんにします。"},{"speaker":"M","ja":"あおいかばんとあかいかばんがありますよ。"},{"speaker":"F","ja":"あおいほうを使います。"},{"speaker":"N","ja":"女の人はどのかばんを使いますか。"}]', 'Người nữ chọn chiếc túi lớn màu xanh cho chuyến đi; chiếc đen hơi nhỏ.', 'Bốn ô hình: (1) (4) Túi xanh nhỏ.; (2) (2) Túi đỏ lớn; (3) (3) Túi đen nhỏ; (4) (1) Túi xanh lớn', '[]', 119, 1, 'learning-path/N5/skills/N5-L-TASK-073.mp3', 'ae8daae1cd48e20193b8db519e2233b31b7c7b624faf0d9ef5be547b56c1bc44', 28, 'AI_CHECKED', 1, '19d0f58e5bad'),
